local drainBootStart = os.clock()
local drainLastStage = "start"

local function drainBootLog(stage)
    stage = drainScrub(stage)
    drainLastStage = stage
    local elapsed = os.clock() - drainBootStart
    local text = string.format("drain boot: %s (%.1fs)", stage, elapsed)
    print(text)
    drainBootDump(text)
end

local function drainWaitPlayerGui(timeout)
    local player = game:GetService("Players").LocalPlayer
    if not player then return nil end
    local existing = player:FindFirstChildOfClass("PlayerGui")
    if existing then return existing end
    return player:WaitForChild("PlayerGui", timeout or 10)
end

drainBootLog("start")

if not game:IsLoaded() then
    drainBootLog("waiting for game.Loaded")
    local deadline = os.clock() + 20
    repeat task.wait(0.1) until game:IsLoaded() or os.clock() > deadline
end

drainBootLog("game loaded")

-- // bs
do
    getgenv().drain_guard = { Done = false, Patched = 0, Hits = { count = 0 } }

    local ok, err = pcall(function()
        local guard = getgenv().drain_guard

        if getgenv().drain_skip_guard then
            drainBootLog("guard skipped by flag")
            return
        end

        if type(getgc) ~= "function" then
            drainBootLog("guard skipped: no memory access")
            return
        end

        local objects = getgc(true)
        local total = #objects
        drainBootLog("guard scanning " .. tostring(total))

        -- // ничего не нашел
        local function calm() return false end
        local function park()
            guard.Hits.count += 1
            return task.wait(9e9)
        end

        local slice = 0.006
        local sliceStart = os.clock()
        local deadline = sliceStart + 12
        local patched = 0
        local stoppedAt = 0

        for index = 1, total do
            local item = objects[index]

            if typeof(item) == "table"
                and (rawget(item, "indexInstance")
                    or rawget(item, "newindexInstance")
                    or rawget(item, "newIndexInstance")) then
                local written = pcall(function()
                    -- // узнаем по форме записи
                    for _, entry in pairs(item) do
                        if type(entry) == "table"
                            and type(entry[1]) == "string"
                            and type(entry[2]) == "function" then
                            entry[2] = calm
                        end
                    end

                    item.hbx = { "kick", park }
                end)
                if written then patched += 1 end
            end

            if index % 512 == 0 then
                local now = os.clock()
                if now >= deadline then
                    stoppedAt = index
                    break
                end
                if now - sliceStart >= slice then
                    task.wait()
                    sliceStart = os.clock()
                end
            end
        end

        objects = nil
        guard.Patched = patched
        guard.Done = true

        if stoppedAt > 0 then
            drainBootLog(string.format("guard hit the time cap at %d of %d, patched %d",
                stoppedAt, total, patched))
        else
            drainBootLog(string.format("guard patched %d of %d", patched, total))
        end

        -- // если патчнуть не получилось не грузим фичи с метаметодом
        if patched == 0 then
            drainBootLog("guard found nothing, avoid features that need metamethod hooks")
        end
    end)

    if not ok then
        drainReportFail("guard", err)
    end
end

drainBootLog("entering main")

