-- // NoCollect для готовых строк
function library2:Translate(text2, noCollect)
    if type(text2) ~= 'string' or text2 == '' then
        return text2;
    end;

    if not noCollect and not library2.SeenStrings[text2] and string.find(text2, '%a') then
        library2.SeenStrings[text2] = true;
        if library2.OnNewString then
            library2.OnNewString();
        end;
    end;

    return library2.Strings[text2] or text2;
end;

function library2:TranslateFormat(template2, ...)
    local translated2 = library2:Translate(template2);

    if translated2 ~= template2 then
        -- // если что то сломано используем дефолт
        local ok3, result2 = pcall(string.format, translated2, ...);
        if ok3 then
            return result2;
        end;
    end;

    return string.format(template2, ...);
end;

