function library2:GetViewportSize()
    local camera2 = workspace2.CurrentCamera;
    return camera2 and camera2.ViewportSize or Vector2.new(1920, 1080);
end;

function library2:RefreshDeviceClass()
    if not library2.IsMobile then
        library2.DeviceClass = 'Desktop';
        return library2.DeviceClass;
    end;

    local viewport2 = library2:GetViewportSize();
    local shortSide = math.min(viewport2.X, viewport2.Y);
    local longSide = math.max(viewport2.X, viewport2.Y);
    local aspectRatio = longSide / math.max(shortSide, 1);
    library2.DeviceClass = (shortSide <= 760 or aspectRatio >= 1.75) and 'Phone' or 'Tablet';
    return library2.DeviceClass;
end;

function library2:RegisterCustomBackgroundPanel(object2)
    if typeof(object2) ~= 'Instance' or not object2:IsA('GuiObject') then
        return;
    end;

    if library2.CustomBackgroundPanels[object2] == nil then
        library2.CustomBackgroundPanels[object2] = object2.BackgroundTransparency;
    end;

    object2.BackgroundTransparency = library2.CustomBackgroundEnabled
        and library2.CustomBackgroundPanelTransparency
        or library2.CustomBackgroundPanels[object2];
end;

function library2:RefreshCustomBackground()
    local backgroundImage = library2.CustomBackgroundImage;
    local hasAsset = type(library2.CustomBackgroundAsset) == 'string'
        and library2.CustomBackgroundAsset ~= '';

    if backgroundImage and backgroundImage.Parent then
        backgroundImage.Image = hasAsset and library2.CustomBackgroundAsset or '';
        backgroundImage.ImageTransparency = math.clamp(library2.CustomBackgroundTransparency or 0.35, 0, 1);
        backgroundImage.ScaleType = Enum.ScaleType[library2.CustomBackgroundScaleType] or Enum.ScaleType.Crop;
        backgroundImage.Visible = library2.CustomBackgroundEnabled and hasAsset;
    end;

    for object2, originalTransparency in pairs(library2.CustomBackgroundPanels) do
        if object2 and object2.Parent then
            object2.BackgroundTransparency = library2.CustomBackgroundEnabled and hasAsset
                and math.clamp(library2.CustomBackgroundPanelTransparency or 0.2, 0, 1)
                or originalTransparency;
        else
            library2.CustomBackgroundPanels[object2] = nil;
        end;
    end;
end;

function library2:SetCustomBackgroundAsset(asset2)
    library2.CustomBackgroundAsset = type(asset2) == 'string' and asset2 or '';
    library2:RefreshCustomBackground();
end;

function library2:SetCustomBackgroundEnabled(state2)
    library2.CustomBackgroundEnabled = state2 == true;
    library2:RefreshCustomBackground();
end;

function library2:SetCustomBackgroundTransparency(value2)
    library2.CustomBackgroundTransparency = math.clamp(tonumber(value2) or 0.35, 0, 1);
    library2:RefreshCustomBackground();
end;

function library2:SetCustomBackgroundPanelTransparency(value2)
    library2.CustomBackgroundPanelTransparency = math.clamp(tonumber(value2) or 0.2, 0, 1);
    library2:RefreshCustomBackground();
end;

function library2:SetCustomBackgroundScaleType(value2)
    library2.CustomBackgroundScaleType = Enum.ScaleType[tostring(value2)] and tostring(value2) or 'Crop';
    library2:RefreshCustomBackground();
end;

function library2:IsPrimaryInput(input2)
    if not input2 then return false; end;

    return input2.UserInputType == Enum.UserInputType.MouseButton1
        or (library2.IsTouchDevice and input2.UserInputType == Enum.UserInputType.Touch);
end;

function library2:GetRawPointerPosition(input2)
    if input2 and input2.UserInputType == Enum.UserInputType.Touch and input2.Position then
        return Vector2.new(input2.Position.X, input2.Position.Y);
    end;

    return inputService2:GetMouseLocation();
end;

function library2:GetInputPosition(input2)
    local position2 = library2:GetRawPointerPosition(input2);
    if input2 and input2.UserInputType == Enum.UserInputType.Touch then
        return position2;
    end;

    if not screenGui2.IgnoreGuiInset then
        local topLeftInset = game:GetService('GuiService'):GetGuiInset();
        position2 = position2 - Vector2.new(topLeftInset.X, topLeftInset.Y);
    end;

    return position2;
end;

function library2:IsInputActive(input2)
    if not input2 then return false; end;

    if input2.UserInputType == Enum.UserInputType.Touch then
        return input2.UserInputState ~= Enum.UserInputState.End
            and input2.UserInputState ~= Enum.UserInputState.Cancel;
    end;

    if input2.UserInputType == Enum.UserInputType.MouseButton1 then
        return inputService2:IsMouseButtonPressed(Enum.UserInputType.MouseButton1);
    end;

    return false;
end;

function library2:IsSameInput(input2, activeInput)
    if not input2 or not activeInput then return false; end;
    if input2 == activeInput then return true; end;

    return input2.UserInputType == Enum.UserInputType.MouseButton1
        and activeInput.UserInputType == Enum.UserInputType.MouseButton1;
end;

function library2:ClaimPointer(owner2, input2)
    if not owner2 or not library2:IsPrimaryInput(input2) then return false; end;

    if library2.ActivePointerOwner then
        if library2.ActivePointerOwner == owner2
            and library2:IsSameInput(input2, library2.ActivePointerInput) then
            return true;
        end;

        if library2:IsInputActive(library2.ActivePointerInput) then
            return false;
        end;
    end;

    library2.ActivePointerOwner = owner2;
    library2.ActivePointerInput = input2;
    return true;
end;

function library2:ReleasePointer(owner2, input2)
    if library2.ActivePointerOwner ~= owner2 then return; end;
    if input2 and not library2:IsSameInput(input2, library2.ActivePointerInput) then return; end;

    library2.ActivePointerOwner = nil;
    library2.ActivePointerInput = nil;
end;

function library2:BindClick(instance2, callback2)
    instance2.Active = true;

    local owner2 = {};
    local pressInput;
    local pressPosition;

    instance2.InputBegan:Connect(function(input2)
        if not library2:IsPrimaryInput(input2) then return; end;
        if not library2:ClaimPointer(owner2, input2) then return; end;

        pressInput = input2;
        pressPosition = library2:GetInputPosition(input2);

        if input2.UserInputType ~= Enum.UserInputType.Touch then
            library2:SafeCallback(callback2, input2);
        end;
    end);

    library2:GiveSignal(inputService2.InputEnded:Connect(function(input2)
        if not library2:IsSameInput(input2, pressInput) then return; end;

        if input2.UserInputType == Enum.UserInputType.Touch
            and library2.ActivePointerOwner == owner2 then

            local endPosition2 = library2:GetInputPosition(input2);
            local travel2 = (endPosition2 - pressPosition).Magnitude;
            if travel2 <= library2.TouchMoveThreshold and library2:IsMouseOverFrame(instance2, input2) then
                library2:SafeCallback(callback2, input2);
            end;
        end;

        pressInput = nil;
        pressPosition = nil;
        library2:ReleasePointer(owner2, input2);
    end));

    return owner2;
end;

function library2:ClampPopupPosition(frame2, x2, y2, padding2)
    local viewport2 = library2:GetViewportSize();
    local frameSize = frame2.AbsoluteSize;
    local width2 = frameSize.X > 0 and frameSize.X or frame2.Size.X.Offset;
    local height2 = frameSize.Y > 0 and frameSize.Y or frame2.Size.Y.Offset;
    local edge = padding2 or 6;

    return UDim2.fromOffset(
        math.clamp(x2, edge, math.max(edge, viewport2.X - width2 - edge)),
        math.clamp(y2, edge, math.max(edge, viewport2.Y - height2 - edge))
    );
end;

