local rainbowStep = 0
local hue = 0

library2.AnimatedColorPickers = setmetatable({}, { __mode = 'k' });
local animatedColorPickerStep = 0;

table.insert(library2.Signals, renderStepped:Connect(function(delta2)
    rainbowStep = rainbowStep + delta2

    if rainbowStep >= (1 / 60) then
        rainbowStep = 0

        hue = hue + (1 / 400);

        if hue > 1 then
            hue = 0;
        end;

        library2.CurrentRainbowHue = hue;
        library2.CurrentRainbowColor = Color3.fromHSV(hue, 0.8, 1);
    end

    animatedColorPickerStep = animatedColorPickerStep + delta2;
    if animatedColorPickerStep >= (1 / 30) then
        animatedColorPickerStep = 0;
        local now2 = os.clock();

        for colorPicker in next, library2.AnimatedColorPickers do
            if colorPicker.AnimationMode ~= 'Static' and colorPicker.AnimationTick then
                if not colorPicker.DisplayFrame or not colorPicker.DisplayFrame.Parent then
                    library2.AnimatedColorPickers[colorPicker] = nil;
                else
                    local success2 = pcall(colorPicker.AnimationTick, colorPicker, now2);
                    if not success2 then
                        library2.AnimatedColorPickers[colorPicker] = nil;
                    end;
                end;
            end;
        end;
    end;
end))

local function getPlayersString()
    local playerList = players2:GetPlayers();

    for i = 1, #playerList do
        playerList[i] = playerList[i].Name;
    end;

    table.sort(playerList, function(str1, str2) return str1 < str2 end);

    return playerList;
end;

local function getTeamsString()
    local teamList = teams:GetTeams();

    for i = 1, #teamList do
        teamList[i] = teamList[i].Name;
    end;

    table.sort(teamList, function(str1, str2) return str1 < str2 end);

    return teamList;
end;

function library2:SafeCallback(f, ...)
    if (not f) then
        return;
    end;

    -- // сброс кеша
    local espDirty = environment.DrainESPConfigDirty;
    if espDirty then
        espDirty();
    end;

    if not library2.NotifyOnError then
        return f(...);
    end;

    local success, event = pcall(f, ...);

    if not success then
        local message = tostring(event);
        library2:Notify(library2:TranslateFormat('callback errored: %s', message), 5);

        local _, i = message:find(":%d+: ");
        if i then
            message = message:sub(i + 1);
        end;

        pcall(function()
            library2:Notify(message, 6);
        end);
    end;
end;

function library2:AttemptSave()
    if library2.SaveManager then
        library2.SaveManager:Save();
    end;
end;

function library2:Create(class, properties2)
    local _instance = class;

    if type(class) == 'string' then
        _instance = Instance.new(class);
    end;

    for property2, value2 in next, properties2 do
        _instance[property2] = value2;
    end;

    return _instance;
end;

function library2:ApplyTextStroke(inst2)
    inst2.TextStrokeTransparency = 1;

    library2:Create('UIStroke', {
        Color = Color3.new(0, 0, 0);
        Thickness = 1;
        LineJoinMode = Enum.LineJoinMode.Miter;
        Parent = inst2;
    });
end;

function library2:CreateLabel(properties2, isHud)
    local _instance = library2:Create('TextLabel', {
        BackgroundTransparency = 1;
        Font = library2.Font;
        TextColor3 = library2.FontColor;
        TextSize = 16;
        TextStrokeTransparency = 0;
    });

    library2:ApplyTextStroke(_instance);

    library2:AddToRegistry(_instance, {
        TextColor3 = 'FontColor';
    }, isHud);

    return library2:Create(_instance, properties2);
end;

function library2:MakeDraggable(instance2, cutoff)
    instance2.Active = true;

    local dragHeight = cutoff or 40;
    local dragOwner = {};
    local dragging = false;
    local dragElapsed = 0;
    local dragStart;
    local startPosition2;
    local lastDelta;
    local dragInput;

    local dragHandle = library2:Create('TextButton', {
        Name = 'DragHandle';
        Active = true;
        AutoButtonColor = false;
        BackgroundTransparency = 1;
        BorderSizePixel = 0;
        Modal = false;
        Selectable = false;
        Size = UDim2.new(1, 0, 0, dragHeight);
        Text = '';
        TextTransparency = 1;
        ZIndex = instance2.ZIndex + 10;
        Parent = instance2;
    });

    dragHandle.InputBegan:Connect(function(input2)
        if not library2:IsPrimaryInput(input2) then return; end;
        if not library2:ClaimPointer(dragOwner, input2) then return; end;

        dragStart = library2:GetInputPosition(input2);
        startPosition2 = instance2.AbsolutePosition;
        dragElapsed = library2.DragUpdateRate;
        lastDelta = nil;
        dragInput = input2;
        dragging = true;
    end);

    library2:GiveSignal(inputService2.InputEnded:Connect(function(input2)
        if library2:IsSameInput(input2, dragInput) then
            dragging = false;
            dragInput = nil;
            library2:ReleasePointer(dragOwner, input2);
        end;
    end));

    library2:GiveSignal(renderStepped:Connect(function(delta2)
        if not dragging then
            return;
        end;

        dragElapsed = dragElapsed + delta2;
        if dragElapsed < library2.DragUpdateRate then
            return;
        end;
        dragElapsed = dragElapsed % library2.DragUpdateRate;

        local pointer = library2:GetInputPosition(dragInput);
        local delta2 = Vector2.new(
            math.floor(pointer.X - dragStart.X + 0.5),
            math.floor(pointer.Y - dragStart.Y + 0.5)
        );

        if delta2 == lastDelta then
            return;
        end;

        lastDelta = delta2;
        local viewport2 = library2:GetViewportSize();
        local size2 = instance2.AbsoluteSize;
        local x2 = math.clamp(startPosition2.X + delta2.X, 0, math.max(0, viewport2.X - size2.X));
        local y2 = math.clamp(startPosition2.Y + delta2.Y, 0, math.max(0, viewport2.Y - size2.Y));
        local anchor2 = instance2.AnchorPoint;

        instance2.Position = UDim2.fromOffset(
            math.floor(x2 + size2.X * anchor2.X + 0.5),
            math.floor(y2 + size2.Y * anchor2.Y + 0.5)
        );
    end));

    return dragHandle;
end;

function library2:AddToolTip(infoStr, hoverInstance)
    infoStr = library2:Translate(infoStr);

    if library2.IsMobile then
        return;
    end;

    local x2, y2 = library2:GetTextBounds(infoStr, library2.Font, 14);
    local tooltip2 = library2:Create('Frame', {
        BackgroundColor3 = library2.MainColor,
        BorderColor3 = library2.OutlineColor,

        Size = UDim2.fromOffset(x2 + 5, y2 + 4),
        ZIndex = 100,
        Parent = library2.ScreenGui,

        Visible = false,
    })

    local label2 = library2:CreateLabel({
        Position = UDim2.fromOffset(3, 1),
        Size = UDim2.fromOffset(x2, y2);
        TextSize = 14;
        Text = infoStr,
        TextColor3 = library2.FontColor,
        TextXAlignment = Enum.TextXAlignment.Left;
        ZIndex = tooltip2.ZIndex + 1,

        Parent = tooltip2;
    });

    library2:AddToRegistry(tooltip2, {
        BackgroundColor3 = 'MainColor';
        BorderColor3 = 'OutlineColor';
    });

    library2:AddToRegistry(label2, {
        TextColor3 = 'FontColor',
    });

    local isHovering = false

    hoverInstance.MouseEnter:Connect(function()
        if library2:MouseIsOverOpenedFrame() then
            return
        end

        isHovering = true

        tooltip2.Position = UDim2.fromOffset(mouse.X + 15, mouse.Y + 12)
        tooltip2.Visible = true

        while isHovering do
            runService.Heartbeat:Wait()
            tooltip2.Position = UDim2.fromOffset(mouse.X + 15, mouse.Y + 12)
        end
    end)

    hoverInstance.MouseLeave:Connect(function()
        isHovering = false
        tooltip2.Visible = false
    end)
end

function library2:OnHighlight(highlightInstance, instance2, properties2, propertiesDefault)
    highlightInstance.MouseEnter:Connect(function()
        local reg = library2.RegistryMap[instance2];

        for property2, colorIdx in next, properties2 do
            instance2[property2] = library2[colorIdx] or colorIdx;

            if reg and reg.Properties[property2] then
                reg.Properties[property2] = colorIdx;
            end;
        end;
    end)

    highlightInstance.MouseLeave:Connect(function()
        local reg = library2.RegistryMap[instance2];

        for property2, colorIdx in next, propertiesDefault do
            instance2[property2] = library2[colorIdx] or colorIdx;

            if reg and reg.Properties[property2] then
                reg.Properties[property2] = colorIdx;
            end;
        end;
    end)
end;

function library2:MouseIsOverOpenedFrame(input2)
    local pointer = library2:GetInputPosition(input2);

    for frame2, _ in next, library2.OpenedFrames do
        local absPos, absSize = frame2.AbsolutePosition, frame2.AbsoluteSize;

        if pointer.X >= absPos.X and pointer.X <= absPos.X + absSize.X
            and pointer.Y >= absPos.Y and pointer.Y <= absPos.Y + absSize.Y then

            return true;
        end;
    end;
end;

function library2:CloseOpenedFrames(except)
    local pending2 = {};

    for frame2, closeCallback in next, library2.OpenedFrames do
        if frame2 ~= except then
            table.insert(pending2, { frame2, closeCallback });
        end;
    end;

    for _, entry2 in next, pending2 do
        local frame2 = entry2[1];
        local closeCallback = entry2[2];

        if type(closeCallback) == 'function' then
            library2:SafeCallback(closeCallback);
        else
            frame2.Visible = false;
            library2.OpenedFrames[frame2] = nil;
        end;
    end;
end;

function library2:IsMouseOverFrame(frame2, input2)
    local pointer = library2:GetInputPosition(input2);
    local absPos, absSize = frame2.AbsolutePosition, frame2.AbsoluteSize;

    if pointer.X >= absPos.X and pointer.X <= absPos.X + absSize.X
        and pointer.Y >= absPos.Y and pointer.Y <= absPos.Y + absSize.Y then

        return true;
    end;
end;

function library2:UpdateDependencyBoxes()
    if library2.DeferDependencyUpdates then
        library2.DependencyUpdatePending = true;
        return;
    end;

    for _, depbox in next, library2.DependencyBoxes do
        depbox:Update();
    end;
end;

function library2:MapValue(value2, minA, maxA, minB, maxB)
    return (1 - ((value2 - minA) / (maxA - minA))) * minB + ((value2 - minA) / (maxA - minA)) * maxB;
end;

function library2:GetTextBounds(text2, font2, size2, resolution2)
    local bounds2 = textService:GetTextSize(text2, size2, font2, resolution2 or Vector2.new(1920, 1080))
    return bounds2.X, bounds2.Y
end;

function library2:GetDarkerColor(color4)
    local h2, s2, v2 = Color3.toHSV(color4);
    return Color3.fromHSV(h2, s2, v2 / 1.5);
end;
library2.AccentColorDark = library2:GetDarkerColor(library2.AccentColor);

function library2:AddToRegistry(instance2, properties2, isHud)
    local idx2 = #library2.Registry + 1;
    local data2 = {
        Instance = instance2;
        Properties = properties2;
        Idx = idx2;
    };

    table.insert(library2.Registry, data2);
    library2.RegistryMap[instance2] = data2;

    if isHud then
        table.insert(library2.HudRegistry, data2);
    end;
end;

function library2:RemoveFromRegistry(instance2)
    local data2 = library2.RegistryMap[instance2];

    if data2 then
        for idx2 = #library2.Registry, 1, -1 do
            if library2.Registry[idx2] == data2 then
                table.remove(library2.Registry, idx2);
            end;
        end;

        for idx2 = #library2.HudRegistry, 1, -1 do
            if library2.HudRegistry[idx2] == data2 then
                table.remove(library2.HudRegistry, idx2);
            end;
        end;

        library2.RegistryMap[instance2] = nil;
    end;
end;

-- // ищем линейно
function library2:PurgeRegistry(set)
    if next(set) == nil then return; end;

    for _, list2 in ipairs({ library2.Registry, library2.HudRegistry }) do
        local write = 0;
        for read = 1, #list2 do
            local data2 = list2[read];
            if not set[data2.Instance] then
                write = write + 1;
                list2[write] = data2;
            end;
        end;
        for index2 = #list2, write + 1, -1 do
            list2[index2] = nil;
        end;
    end;

    for instance2 in next, set do
        library2.RegistryMap[instance2] = nil;
    end;
end;

function library2:UpdateColorsUsingRegistry()
    for idx2, object2 in next, library2.Registry do
        for property2, colorIdx in next, object2.Properties do
            if type(colorIdx) == 'string' then
                object2.Instance[property2] = library2[colorIdx];
            elseif type(colorIdx) == 'function' then
                object2.Instance[property2] = colorIdx()
            end
        end;
    end;
end;

function library2:GiveSignal(signal)
    table.insert(library2.Signals, signal)
end

function library2:ClampMobileBindButton(button, position2)
    local viewport2 = library2:GetViewportSize();
    local size2 = button.AbsoluteSize;
    local width2 = size2.X > 0 and size2.X or button.Size.X.Offset;
    local height2 = size2.Y > 0 and size2.Y or button.Size.Y.Offset;
    local x2 = position2 and position2.X.Offset or button.Position.X.Offset;
    local y2 = position2 and position2.Y.Offset or button.Position.Y.Offset;
    local edge = 8;

    button.Position = UDim2.fromOffset(
        math.clamp(x2, edge, math.max(edge, viewport2.X - width2 - edge)),
        math.clamp(y2, edge, math.max(edge, viewport2.Y - height2 - edge))
    );
end;

function library2:RefreshMobileBindButtonBounds()
    if library2.LoadedMobileBindLayouts then
        library2:ApplyCurrentMobileBindLayout();
        return;
    end;

    for _, bindButton in ipairs(library2.MobileBindButtons) do
        library2:ClampMobileBindButton(bindButton.Outer);
    end;
end;

function library2:GetMobileBindResolution()
    local viewport2 = library2:GetViewportSize();
    local width2 = math.floor(viewport2.X + 0.5);
    local height2 = math.floor(viewport2.Y + 0.5);
    return width2, height2, string.format('%dx%d', width2, height2);
end;

function library2:CaptureMobileBindLayout()
    if not library2.IsMobile then return nil; end;

    local width2, height2, resolution2 = library2:GetMobileBindResolution();
    local buttons = {};

    for _, bindButton in ipairs(library2.MobileBindButtons) do
        local position2 = bindButton.Outer.Position;
        buttons[tostring(bindButton.Idx)] = {
            x = math.floor(position2.X.Offset + 0.5);
            y = math.floor(position2.Y.Offset + 0.5);
        };
    end;

    return resolution2, {
        schema = 1;
        width = width2;
        height = height2;
        deviceClass = library2.DeviceClass;
        buttons = buttons;
    };
end;

function library2:ResetMobileBindButtonPositions()
    for _, bindButton in ipairs(library2.MobileBindButtons) do
        if bindButton.DefaultPosition then
            library2:ClampMobileBindButton(bindButton.Outer, bindButton.DefaultPosition);
        else
            library2:ClampMobileBindButton(bindButton.Outer);
        end;
    end;
end;

function library2:ApplyCurrentMobileBindLayout()
    if not library2.IsMobile or type(library2.LoadedMobileBindLayouts) ~= 'table' then
        return false;
    end;

    local width2, height2, resolution2 = library2:GetMobileBindResolution();
    local layout2 = library2.LoadedMobileBindLayouts[resolution2];

    if type(layout2) ~= 'table'
        or tonumber(layout2.width) ~= width2
        or tonumber(layout2.height) ~= height2
        or type(layout2.buttons) ~= 'table' then

        library2:ResetMobileBindButtonPositions();
        return false;
    end;

    library2:ResetMobileBindButtonPositions();

    for _, bindButton in ipairs(library2.MobileBindButtons) do
        local position2 = layout2.buttons[tostring(bindButton.Idx)];
        if type(position2) == 'table'
            and type(position2.x) == 'number'
            and type(position2.y) == 'number' then

            library2:ClampMobileBindButton(
                bindButton.Outer,
                UDim2.fromOffset(position2.x, position2.y)
            );
        end;
    end;

    return true;
end;

function library2:SetMobileBindLayouts(layouts)
    library2.LoadedMobileBindLayouts = type(layouts) == 'table' and layouts or nil;
    if library2.LoadedMobileBindLayouts then
        return library2:ApplyCurrentMobileBindLayout();
    end;
    return false;
end;

function library2:SaveCurrentMobileBindLayout()
    if not library2.IsMobile then return; end;

    local manager = library2.MobileLayoutSaveManager;
    local configName = manager and manager.CurrentConfig;
    if configName then
        manager:Save(configName);
    end;
end;

function library2:GetMobileBindOptions()
    local values2 = {};
    for _, bindButton in ipairs(library2.MobileBindButtons) do
        table.insert(values2, bindButton.OptionName);
    end;
    return values2;
end;

function library2:SetVisibleMobileBinds(selected2)
    selected2 = type(selected2) == 'table' and selected2 or {};

    for _, bindButton in ipairs(library2.MobileBindButtons) do
        bindButton:SetVisible(selected2[bindButton.OptionName] == true);
    end;
end;

function library2:SetMobileBindEditing(editing)
    library2.MenuOpen = not not editing;

    for _, bindButton in ipairs(library2.MobileBindButtons) do
        bindButton:SetEditing(library2.MenuOpen);
    end;
end;

function library2:CreateMobileBindButton(idx2, keyPicker, info2)
    if not library2.IsMobile or info2.NoUI or info2.MobileButton == false then
        return nil;
    end;

    library2.MobileBindButtonCount = library2.MobileBindButtonCount + 1;
    local buttonIndex = library2.MobileBindButtonCount;
    local targetButtonWidth = 160;
    local buttonHeight = 34;
    local gap2 = 8;
    local viewport2 = library2:GetViewportSize();
    local columns = viewport2.X >= 540 and 3 or (viewport2.X >= 350 and 2 or 1);
    local buttonWidth = math.min(
        targetButtonWidth,
        math.max(112, math.floor((viewport2.X - 24 - (columns - 1) * gap2) / columns))
    );
    local column = (buttonIndex - 1) % columns;
    local row2 = math.floor((buttonIndex - 1) / columns);
    local buttonName = tostring(info2.Text or idx2 or 'Bind');
    local buttonData = {};
    local dragOwner = {};

    local outer = library2:Create('Frame', {
        Name = 'MobileBind_' .. tostring(idx2);
        Active = true;
        BackgroundColor3 = Color3.new(0, 0, 0);
        BorderColor3 = Color3.new(0, 0, 0);
        Position = UDim2.fromOffset(12 + column * (buttonWidth + gap2), 58 + row2 * (buttonHeight + gap2));
        Size = UDim2.fromOffset(buttonWidth, buttonHeight);
        ZIndex = 230;
        Parent = screenGui2;
    });

    local button = library2:Create('TextButton', {
        AutoButtonColor = false;
        BackgroundColor3 = library2.MainColor;
        BorderColor3 = library2.OutlineColor;
        BorderMode = Enum.BorderMode.Inset;
        Font = library2.Font;
        Position = UDim2.fromOffset(1, 1);
        Size = UDim2.new(1, -2, 1, -2);
        Text = library2:Translate(buttonName);
        TextColor3 = library2.FontColor;
        TextSize = 14;
        TextStrokeTransparency = 0;
        TextTruncate = Enum.TextTruncate.AtEnd;
        ZIndex = 231;
        Parent = outer;
    });
    library2:ApplyTextStroke(button);

    library2:Create('UIGradient', {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1));
            ColorSequenceKeypoint.new(1, Color3.fromRGB(212, 212, 212));
        });
        Rotation = 90;
        Parent = button;
    });

    local accent = library2:Create('Frame', {
        BackgroundColor3 = library2.AccentColor;
        BorderSizePixel = 0;
        Size = UDim2.new(1, 0, 0, 2);
        ZIndex = 232;
        Parent = button;
    });

    local state2 = library2:Create('Frame', {
        AnchorPoint = Vector2.new(0, 0.5);
        BackgroundColor3 = library2.OutlineColor;
        BorderColor3 = Color3.new(0, 0, 0);
        Position = UDim2.new(0, 7, 0.5, 1);
        Size = UDim2.fromOffset(6, 6);
        ZIndex = 233;
        Parent = button;
    });

    local moveLabel = library2:CreateLabel({
        Position = UDim2.new(1, -18, 0, 2);
        Size = UDim2.new(0, 16, 1, -2);
        Text = '<>';
        TextSize = 13;
        Visible = library2.MenuOpen;
        ZIndex = 233;
        Parent = button;
    });

    local modeLabel = library2:CreateLabel({
        Position = UDim2.new(1, -43, 0, 2);
        Size = UDim2.new(0, 22, 1, -2);
        Text = 'T';
        TextSize = 13;
        TextXAlignment = Enum.TextXAlignment.Center;
        ZIndex = 233;
        Parent = button;
    });

    library2:AddToRegistry(button, {
        BackgroundColor3 = 'MainColor';
        BorderColor3 = 'OutlineColor';
        TextColor3 = 'FontColor';
    });
    library2:AddToRegistry(accent, { BackgroundColor3 = 'AccentColor'; });
    library2:AddToRegistry(state2, { BackgroundColor3 = 'OutlineColor'; });

    local dragging = false;
    local dragInput;
    local dragStart;
    local startPosition2;
    local pressedInput;

    local function releaseBind()
        if not pressedInput then return; end;
        pressedInput = nil;

        if keyPicker.Mode == 'Hold' and keyPicker.Toggled then
            keyPicker.Toggled = false;
            keyPicker:DoClick();
            keyPicker:Update();
        end;
    end;

    function buttonData:Update()
        local active2 = keyPicker:GetDisplayState();
        local editing = library2.MenuOpen;
        local borderKey = editing and 'AccentColor' or (active2 and 'AccentColorDark' or 'OutlineColor');
        local stateKey = active2 and 'AccentColor' or 'OutlineColor';

        button.BorderColor3 = library2[borderKey];
        state2.BackgroundColor3 = library2[stateKey];
        moveLabel.Visible = editing;
        modeLabel.Text = keyPicker.Mode == 'Hold' and 'H'
            or (keyPicker.Mode == 'Always' and 'A' or 'T');
        modeLabel.TextColor3 = editing and library2.AccentColor or library2.FontColor;
        library2.RegistryMap[button].Properties.BorderColor3 = borderKey;
        library2.RegistryMap[state2].Properties.BackgroundColor3 = stateKey;
        library2.RegistryMap[modeLabel].Properties.TextColor3 = editing and 'AccentColor' or 'FontColor';
    end;

    function buttonData:CycleMode()
        local nextMode = keyPicker.Mode == 'Hold' and 'Toggle' or 'Hold';
        if type(keyPicker.SetMode) == 'function' then
            keyPicker:SetMode(nextMode, true);
        else
            keyPicker.Mode = nextMode;
            keyPicker:Update();
            library2:AttemptSave();
        end;
    end;

    function buttonData:SetEditing(editing)
        if editing then
            releaseBind();
        else
            dragging = false;
            dragInput = nil;
        end;

        buttonData:Update();
    end;

    function buttonData:SetVisible(visible2)
        buttonData.UserVisible = not not visible2;
        outer.Visible = buttonData.UserVisible;
        if not buttonData.UserVisible then
            releaseBind();
            dragging = false;
            dragInput = nil;
            library2:ReleasePointer(dragOwner);
        end;
    end;

    button.InputBegan:Connect(function(input2)
        if not library2:IsPrimaryInput(input2) then return; end;
        if not library2:ClaimPointer(dragOwner, input2) then return; end;

        if library2.MenuOpen then
            dragging = true;
            dragInput = input2;
            dragStart = library2:GetInputPosition(input2);
            startPosition2 = outer.Position;
            return;
        end;

        pressedInput = input2;
        if keyPicker.Mode == 'Hold' then
            if not keyPicker.Toggled then
                keyPicker.Toggled = true;
                keyPicker:DoClick();
            end;
        elseif keyPicker.Mode ~= 'Always' then
            keyPicker.Toggled = not keyPicker.Toggled;
            keyPicker:DoClick();
            pressedInput = nil;
        end;

        keyPicker:Update();
    end);

    library2:GiveSignal(renderStepped:Connect(function()
        if not dragging then return; end;
        if not library2.MenuOpen or not library2:IsInputActive(dragInput) then
            dragging = false;
            dragInput = nil;
            return;
        end;

        local pointer = library2:GetInputPosition(dragInput);
        local delta2 = pointer - dragStart;
        library2:ClampMobileBindButton(outer, UDim2.fromOffset(
            startPosition2.X.Offset + delta2.X,
            startPosition2.Y.Offset + delta2.Y
        ));
    end));

    library2:GiveSignal(inputService2.InputEnded:Connect(function(input2)
        if library2:IsSameInput(input2, dragInput) then
            local travel2 = (library2:GetInputPosition(input2) - dragStart).Magnitude;
            dragging = false;
            dragInput = nil;
            if library2.MenuOpen and travel2 <= library2.TouchMoveThreshold then
                buttonData:CycleMode();
            end;
            if library2.MenuOpen then
                task.defer(library2.SaveCurrentMobileBindLayout);
            end;
        end;

        if library2:IsSameInput(input2, pressedInput) then
            releaseBind();
        end;

        library2:ReleasePointer(dragOwner, input2);
    end));

    buttonData.Outer = outer;
    buttonData.Button = button;
    buttonData.State = state2;
    buttonData.ModeLabel = modeLabel;
    buttonData.KeyPicker = keyPicker;
    buttonData.Idx = idx2;
    buttonData.Name = buttonName;
    buttonData.OptionName = string.format('%s [%s]', buttonName, tostring(idx2));
    buttonData.DefaultPosition = outer.Position;
    buttonData.UserVisible = true;
    table.insert(library2.MobileBindButtons, buttonData);
    task.defer(function()
        if library2.LoadedMobileBindLayouts then
            library2:ApplyCurrentMobileBindLayout();
        else
            library2:ClampMobileBindButton(outer);
        end;
        buttonData:Update();
    end);

    return buttonData;
end;

function library2:Unload()
    for idx2 = #library2.Signals, 1, -1 do
        local connection2 = table.remove(library2.Signals, idx2)
        connection2:Disconnect()
    end

    for idx2 = #library2.UnloadCallbacks, 1, -1 do
        local callback2 = table.remove(library2.UnloadCallbacks, idx2)
        pcall(callback2)
    end

    for _, drawingObject in ipairs(library2.CursorDrawings or {}) do
        pcall(function()
            drawingObject.Visible = false
            drawingObject:Remove()
        end)
    end
    library2.CursorDrawings = nil
    environment.DrainCursorDrawings = nil

    pcall(function()
        game:GetService('UserInputService').MouseIconEnabled = true
    end)

    if library2.MobileFovGui then
        library2.MobileFovGui:Destroy()
        library2.MobileFovGui = nil
    end

    screenGui2:Destroy()

    -- // на соелущивж
    library2.Unloaded = true
    environment.drain_loaded = false
    environment.drain_build = nil
end

function library2:OnUnload(callback2)
    table.insert(library2.UnloadCallbacks, callback2)
end

do
    local afCoreGui = game:GetService("CoreGui")
    local afHooked = setmetatable({}, { __mode = "k" })

    local function afProcessRow(row)
        if not row or not row.Parent then return end
        local textLabel = row:FindFirstChildOfClass("TextLabel")
        if textLabel and textLabel.Text and string.find(string.lower(textLabel.Text), "drain boot", 1, true) then
            row:Destroy()
        end
    end

    local function afSetupClientLog(clientLog)
        -- // защита от двойной записи
        if afHooked[clientLog] then return end
        afHooked[clientLog] = true

        for _, row in ipairs(clientLog:GetChildren()) do
            pcall(afProcessRow, row)
        end

        library2:GiveSignal(clientLog.ChildAdded:Connect(function(row)
            task.defer(function()
                if row and row.Parent then
                    pcall(afProcessRow, row)
                end
            end)
        end))
    end

    local function afClearAll()
        local devConsole = afCoreGui:FindFirstChild("DevConsoleMaster")
        if not devConsole then return end
        local clientLog = devConsole:FindFirstChild("ClientLog", true)
        if not clientLog then return end
        for _, row in ipairs(clientLog:GetChildren()) do
            pcall(afProcessRow, row)
        end
    end

    local function afAttachConsole(devConsole)
        local existing = devConsole:FindFirstChild("ClientLog", true)
        if existing then
            afSetupClientLog(existing)
        end
        library2:GiveSignal(devConsole.DescendantAdded:Connect(function(descendant)
            if descendant.Name == "ClientLog" then
                afSetupClientLog(descendant)
            end
        end))
    end

    local existing = afCoreGui:FindFirstChild("DevConsoleMaster")
    if existing then
        afAttachConsole(existing)
    end

    library2:GiveSignal(afCoreGui.ChildAdded:Connect(function(child)
        if child.Name == "DevConsoleMaster" then
            afAttachConsole(child)
        end
    end))

    library2:OnUnload(function()
        afClearAll()
    end)
end

library2:GiveSignal(screenGui2.DescendantRemoving:Connect(function(instance2)
    if library2.RegistryMap[instance2] then
        library2:RemoveFromRegistry(instance2);
    end;
end))

