                local colorKey = (button.Selected or button.Hovering) and 'AccentColor' or 'Black';
                button.Outer.BorderColor3 = library2[colorKey];

                local registry2 = library2.RegistryMap[button.Outer];
                if registry2 then
                    registry2.Properties.BorderColor3 = colorKey;
                end;
            end;

            function button:SetSelected(selected2)
                button.Selected = selected2 == true;
                button.Inner.BackgroundColor3 = library2.MainColor;
                button.Label.TextColor3 = library2.FontColor;

                local innerRegistry = library2.RegistryMap[button.Inner];
                if innerRegistry then
                    innerRegistry.Properties.BackgroundColor3 = 'MainColor';
                end;

                local labelRegistry = library2.RegistryMap[button.Label];
                if labelRegistry then
                    labelRegistry.Properties.TextColor3 = 'FontColor';
                end;

                button:RefreshBorder();
            end;

            button.Outer.MouseEnter:Connect(function()
                button.Hovering = true;
                button:RefreshBorder();
            end);

            button.Outer.MouseLeave:Connect(function()
                button.Hovering = false;
                button:RefreshBorder();
            end);

            return button;
