        local contextMenu = {}
        do
            contextMenu.Options = {}
            contextMenu.Container = library2:Create('Frame', {
                BorderColor3 = Color3.new(),
                ZIndex = 14,

                Visible = false,
                Parent = screenGui2
            })

            contextMenu.Inner = library2:Create('Frame', {
                BackgroundColor3 = library2.BackgroundColor;
                BorderColor3 = library2.OutlineColor;
                BorderMode = Enum.BorderMode.Inset;
                Size = UDim2.fromScale(1, 1);
                ZIndex = 15;
                Parent = contextMenu.Container;
            });

            library2:Create('UIListLayout', {
                Name = 'Layout',
                FillDirection = Enum.FillDirection.Vertical;
                SortOrder = Enum.SortOrder.LayoutOrder;
                Parent = contextMenu.Inner;
            });

            library2:Create('UIPadding', {
                Name = 'Padding',
                PaddingLeft = UDim.new(0, 4),
                Parent = contextMenu.Inner,
            });

            local function updateMenuPosition()
                contextMenu.Container.Position = library2:ClampPopupPosition(
                    contextMenu.Container,
                    (displayFrame.AbsolutePosition.X + displayFrame.AbsoluteSize.X) + 4,
                    displayFrame.AbsolutePosition.Y + 1
                );
            end

            local function updateMenuSize()
                local menuWidth = 60
                for i, label in next, contextMenu.Inner:GetChildren() do
                    if label:IsA('TextLabel') then
                        menuWidth = math.max(menuWidth, label.TextBounds.X)
                    end
                end

                contextMenu.Container.Size = UDim2.fromOffset(
                    menuWidth + 8,
                    contextMenu.Inner.Layout.AbsoluteContentSize.Y + 4
                )
            end

            local menuPositionConnection
            contextMenu.Container:GetPropertyChangedSignal('Visible'):Connect(function()
                if contextMenu.Container.Visible then
                    updateMenuPosition();
                    if not menuPositionConnection then
                        menuPositionConnection = displayFrame:GetPropertyChangedSignal('AbsolutePosition'):Connect(updateMenuPosition)
                    end
                elseif menuPositionConnection then
                    menuPositionConnection:Disconnect()
                    menuPositionConnection = nil
                end;
            end)
            contextMenu.Inner.Layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(updateMenuSize)

            task.spawn(updateMenuPosition)
            task.spawn(updateMenuSize)

            library2:AddToRegistry(contextMenu.Inner, {
                BackgroundColor3 = 'BackgroundColor';
                BorderColor3 = 'OutlineColor';
            });

            function contextMenu:Show()
                updateMenuPosition()
                self.Container.Visible = true
            end

            function contextMenu:Hide()
                self.Container.Visible = false
            end

            function contextMenu:AddOption(str3, callback2)
                if type(callback2) ~= 'function' then
                    callback2 = function() end
                end

                local button = library2:CreateLabel({
                    Active = true;
                    Size = UDim2.new(1, 0, 0, 15);
                    TextSize = 13;
                    Text = library2:Translate(str3);
                    ZIndex = 16;
                    Parent = self.Inner;
                    TextXAlignment = Enum.TextXAlignment.Left,
                });

                library2:OnHighlight(button, button,
                    { TextColor3 = 'AccentColor' },
                    { TextColor3 = 'FontColor' }
                );

                library2:BindClick(button, function()
                    callback2()
                end)
            end

            contextMenu:AddOption('Copy color', function()
                library2.ColorClipboard = colorPicker.Value
                library2:Notify(library2:Translate('Copied color!'), 2)
            end)

            contextMenu:AddOption('Paste color', function()
                if not library2.ColorClipboard then
                    return library2:Notify(library2:Translate('You have not copied a color!'), 2)
                end
                colorPicker:SetEditorValueRGB(library2.ColorClipboard)
                library2:AttemptSave();
            end)


            contextMenu:AddOption('Copy HEX', function()
                pcall(setclipboard, colorPicker.Value:ToHex())
                library2:Notify(library2:Translate('Copied hex code to clipboard!'), 2)
            end)

            contextMenu:AddOption('Copy RGB', function()
                pcall(setclipboard, table.concat({ math.floor(colorPicker.Value.R * 255), math.floor(colorPicker.Value.G * 255), math.floor(colorPicker.Value.B * 255) }, ', '))
                library2:Notify(library2:Translate('Copied RGB values to clipboard!'), 2)
            end)

        end

        library2:AddToRegistry(pickerFrameInner, { BackgroundColor3 = 'BackgroundColor'; BorderColor3 = 'OutlineColor'; });
        library2:AddToRegistry(highlight2, { BackgroundColor3 = 'AccentColor'; });
        library2:AddToRegistry(satVibMapInner, { BackgroundColor3 = 'BackgroundColor'; BorderColor3 = 'OutlineColor'; });

        library2:AddToRegistry(hueBoxInner, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor'; });
        library2:AddToRegistry(rgbBoxBase.Frame, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor'; });
        library2:AddToRegistry(rgbBox, { TextColor3 = 'FontColor', });
        library2:AddToRegistry(hueBox, { TextColor3 = 'FontColor', });

        local sequenceTable = {};

        for hue = 0, 1, 0.1 do
            table.insert(sequenceTable, ColorSequenceKeypoint.new(hue, Color3.fromHSV(hue, 1, 1)));
        end;

        local hueSelectorGradient = library2:Create('UIGradient', {
            Color = ColorSequence.new(sequenceTable);
            Rotation = 90;
            Parent = hueSelectorInner;
        });

        hueBox.FocusLost:Connect(function(enter)
            if enter then
                local success, result = pcall(Color3.fromHex, hueBox.Text)
                if success and typeof(result) == 'Color3' then
                    colorPicker.Hue, colorPicker.Sat, colorPicker.Vib = Color3.toHSV(result)
                end
            end

            colorPicker:Display()
            library2:AttemptSave();
        end)

        rgbBox.FocusLost:Connect(function(enter)
            if enter then
                local r, g, b = rgbBox.Text:match('(%d+),%s*(%d+),%s*(%d+)')
                if r and g and b then
                    colorPicker.Hue, colorPicker.Sat, colorPicker.Vib = Color3.toHSV(Color3.fromRGB(r, g, b))
                end
            end

            colorPicker:Display()
            library2:AttemptSave();
        end)

        local function resolveAnimationColor(value2, fallback2)
            if typeof(value2) == 'Color3' then
                return value2;
            end;

            if type(value2) == 'string' then
                local success2, result2 = pcall(Color3.fromHex, value2);
                if success2 and typeof(result2) == 'Color3' then
                    return result2;
                end;
            end;

            return fallback2;
        end;

        local function clampTransparency(value2, fallback2)
            if not supportsTransparency then
                return 0;
            end;

            return math.clamp(tonumber(value2) or fallback2 or 0, 0, 1);
        end;

        function colorPicker:GetEditorSlot()
            return pickerPage == 'Animation' and colorPicker.EditingAnimationColor or 1;
        end;

        function colorPicker:UpdateEditorVisuals()
            local editorColor = Color3.fromHSV(colorPicker.Hue, colorPicker.Sat, colorPicker.Vib);
            satVibMap.BackgroundColor3 = Color3.fromHSV(colorPicker.Hue, 1, 1);

            if transparencyBoxInner then
                transparencyBoxInner.BackgroundColor3 = editorColor;
                transparencyCursor.Position = UDim2.new(1 - colorPicker.EditorTransparency, 0, 0, 0);
            end;

            cursorOuter.Position = UDim2.new(colorPicker.Sat, 0, 1 - colorPicker.Vib, 0);
            hueCursor.Position = UDim2.new(0, 0, colorPicker.Hue, 0);
            hueBox.Text = '#' .. editorColor:ToHex();
            rgbBox.Text = table.concat({
                math.floor(editorColor.R * 255),
                math.floor(editorColor.G * 255),
                math.floor(editorColor.B * 255)
            }, ', ');
        end;

        function colorPicker:LoadEditorFromSlot()
            local slot = colorPicker:GetEditorSlot();
            local color4 = slot == 2 and colorPicker.Color2 or colorPicker.Color1;
            local transparency2 = slot == 2 and colorPicker.Transparency2 or colorPicker.Transparency1;

            colorPicker.EditorTransparency = clampTransparency(transparency2, 0);
            colorPicker:SetHSVFromRGB(color4);
            colorPicker:UpdateEditorVisuals();
        end;

        function colorPicker:GetAnimationOutput(now2)
            local mode2 = colorPicker.AnimationMode;
            local color12 = colorPicker.Color1;
            local color22 = colorPicker.Color2;
            local alpha1 = colorPicker.Transparency1;
            local alpha22 = colorPicker.Transparency2;

            if mode2 == 'Static' then
                return color12, alpha1;
            end;

            local phase2 = (((now2 or os.clock()) * colorPicker.AnimationSpeed) % 1);
            local smooth = 0.5 - (math.cos(phase2 * math.pi * 2) * 0.5);

            if mode2 == 'Rainbow' then
                local hue1, saturation1, value1 = Color3.toHSV(color12);
                local _, saturation2, value22 = Color3.toHSV(color22);
                local saturation = math.max(0.65, saturation1 + ((saturation2 - saturation1) * smooth));
                local value2 = math.max(0.15, value1 + ((value22 - value1) * smooth));
                local color4 = Color3.fromHSV((hue1 + phase2) % 1, saturation, value2);
                return color4, alpha1 + ((alpha22 - alpha1) * smooth);
            end;

            if mode2 == 'Flash' then
                if phase2 < 0.5 then
                    return color12, alpha1;
                end;

                return color22, alpha22;
            end;

            return color12:Lerp(color22, smooth), alpha1 + ((alpha22 - alpha1) * smooth);
        end;

        function colorPicker:ApplyOutput(color4, transparency2, fireCallback)
            colorPicker.Value = color4;
            colorPicker.Transparency = clampTransparency(transparency2, 0);

            displayFrame.BackgroundColor3 = Color3.new(0, 0, 0);
            displayFrame.BackgroundTransparency = 0;
            displayFrame.BorderColor3 = library2:GetDarkerColor(colorPicker.Value);
            colorPreview.BackgroundColor3 = colorPicker.Value;
            colorPreview.BackgroundTransparency = colorPicker.Transparency;

            if fireCallback ~= false then
                library2:SafeCallback(colorPicker.Callback, colorPicker.Value, colorPicker.Transparency);
                library2:SafeCallback(colorPicker.Changed, colorPicker.Value, colorPicker.Transparency);
            end;
        end;

        function colorPicker:RefreshOutput(fireCallback, now2)
            local color4, transparency2 = colorPicker:GetAnimationOutput(now2);
            colorPicker:ApplyOutput(color4, transparency2, fireCallback);
        end;

        function colorPicker:Display()
            local editorColor = Color3.fromHSV(colorPicker.Hue, colorPicker.Sat, colorPicker.Vib);
            local slot = colorPicker:GetEditorSlot();

            if slot == 2 then
                colorPicker.Color2 = editorColor;
                colorPicker.Transparency2 = clampTransparency(colorPicker.EditorTransparency, colorPicker.Transparency2);
            else
                colorPicker.Color1 = editorColor;
                colorPicker.Transparency1 = clampTransparency(colorPicker.EditorTransparency, colorPicker.Transparency1);
            end;

            colorPicker:UpdateEditorVisuals();
            colorPicker:RefreshOutput(true);
            updateAnimationControls();
        end;

        function colorPicker:AnimationTick(now2)
            colorPicker:RefreshOutput(true, now2);
        end;

        function colorPicker:SetPickerPage(page)
            pickerPage = page == 'Animation' and 'Animation' or 'Color';
            colorPicker:LoadEditorFromSlot();
            updateAnimationControls();
        end;

        function colorPicker:SetEditingAnimationColor(slot)
            colorPicker.EditingAnimationColor = slot == 2 and 2 or 1;
            colorPicker:LoadEditorFromSlot();
            updateAnimationControls();
        end;

        function colorPicker:SetAnimationMode(mode2, save)
            if mode2 ~= 'Static' and mode2 ~= 'Rainbow' and mode2 ~= 'Fading' and mode2 ~= 'Flash' then
                mode2 = 'Static';
            end;

            colorPicker.AnimationMode = mode2;
            colorPicker:RefreshOutput(true);
            updateAnimationControls();

            if save then
                library2:AttemptSave();
            end;
        end;

        function colorPicker:SetAnimationSpeed(speed2, save)
            colorPicker.AnimationSpeed = math.clamp(tonumber(speed2) or 1, 0.1, 5);
            colorPicker:RefreshOutput(true);
            updateAnimationControls();

            if save then
                library2:AttemptSave();
            end;
        end;

        function colorPicker:GetAnimationState()
            return {
                Mode = colorPicker.AnimationMode;
                Speed = colorPicker.AnimationSpeed;
                Color1 = colorPicker.Color1;
                Transparency1 = colorPicker.Transparency1;
                Color2 = colorPicker.Color2;
                Transparency2 = colorPicker.Transparency2;
            };
        end;

        function colorPicker:SetAnimationState(state2)
            state2 = type(state2) == 'table' and state2 or {};

            colorPicker.Color1 = resolveAnimationColor(state2.Color1 or state2.color1 or state2.Value or state2.value, colorPicker.Color1);
            colorPicker.Color2 = resolveAnimationColor(state2.Color2 or state2.color2, colorPicker.Color2);
            colorPicker.Transparency1 = clampTransparency(
                state2.Transparency1 or state2.transparency1 or state2.Alpha1 or state2.alpha1 or state2.Transparency or state2.transparency,
                colorPicker.Transparency1
            );
            colorPicker.Transparency2 = clampTransparency(
                state2.Transparency2 or state2.transparency2 or state2.Alpha2 or state2.alpha2,
                colorPicker.Transparency2
            );
            colorPicker.AnimationSpeed = math.clamp(tonumber(state2.Speed or state2.speed) or colorPicker.AnimationSpeed, 0.1, 5);

            local mode2 = state2.Mode or state2.mode or 'Static';
            if mode2 ~= 'Static' and mode2 ~= 'Rainbow' and mode2 ~= 'Fading' and mode2 ~= 'Flash' then
                mode2 = 'Static';
            end;
            colorPicker.AnimationMode = mode2;

            colorPicker:LoadEditorFromSlot();
            colorPicker:RefreshOutput(true);
            updateAnimationControls();
        end;

        function colorPicker:OnChanged(func2)
            colorPicker.Changed = func2;
            func2(colorPicker.Value, colorPicker.Transparency)
        end;

        function colorPicker:Show()
            library2:CloseOpenedFrames(pickerFrameOuter);
            updatePickerPosition();
            pickerFrameOuter.Visible = true;
            library2.OpenedFrames[pickerFrameOuter] = function()
                colorPicker:Hide();
            end;
        end;

        function colorPicker:Hide()
            pickerFrameOuter.Visible = false;
            library2.OpenedFrames[pickerFrameOuter] = nil;
        end;

        function colorPicker:SetValue(hsv, transparency2)
            local color4 = Color3.fromHSV(hsv[1], hsv[2], hsv[3]);
            colorPicker:SetValueRGB(color4, transparency2);
        end;

        function colorPicker:SetValueRGB(color4, transparency2)
            if typeof(color4) ~= 'Color3' then return; end;

            colorPicker.Color1 = color4;
            colorPicker.Transparency1 = clampTransparency(transparency2, 0);

            if colorPicker:GetEditorSlot() == 1 then
                colorPicker:LoadEditorFromSlot();
            end;

            colorPicker:RefreshOutput(true);
            updateAnimationControls();
        end;

        function colorPicker:SetEditorValueRGB(color4, transparency2)
            if typeof(color4) ~= 'Color3' then return; end;

            colorPicker:SetHSVFromRGB(color4);
            if transparency2 ~= nil then
                colorPicker.EditorTransparency = clampTransparency(transparency2, colorPicker.EditorTransparency);
            end;
            colorPicker:Display();
        end;

        satVibMap.InputBegan:Connect(function(input2)
            if library2:IsPrimaryInput(input2) then
                repeat
                    local minX2 = satVibMap.AbsolutePosition.X;
                    local maxX2 = minX2 + satVibMap.AbsoluteSize.X;
                    local pointer = library2:GetInputPosition(input2);
                    local mouseX = math.clamp(pointer.X, minX2, maxX2);

                    local minY2 = satVibMap.AbsolutePosition.Y;
                    local maxY2 = minY2 + satVibMap.AbsoluteSize.Y;
                    local mouseY = math.clamp(pointer.Y, minY2, maxY2);

                    colorPicker.Sat = (mouseX - minX2) / (maxX2 - minX2);
                    colorPicker.Vib = 1 - ((mouseY - minY2) / (maxY2 - minY2));
                    colorPicker:Display();

                    renderStepped:Wait();
                until not library2:IsInputActive(input2);

                library2:AttemptSave();
            end;
        end);

        hueSelectorInner.InputBegan:Connect(function(input2)
            if library2:IsPrimaryInput(input2) then
                repeat
                    local minY2 = hueSelectorInner.AbsolutePosition.Y;
                    local maxY2 = minY2 + hueSelectorInner.AbsoluteSize.Y;
                    local pointer = library2:GetInputPosition(input2);
                    local mouseY = math.clamp(pointer.Y, minY2, maxY2);

                    colorPicker.Hue = ((mouseY - minY2) / (maxY2 - minY2));
                    colorPicker:Display();

                    renderStepped:Wait();
                until not library2:IsInputActive(input2);

                library2:AttemptSave();
            end;
        end);

        library2:BindClick(displayFrame, function(input2)
            if not library2:MouseIsOverOpenedFrame(input2) then
                if pickerFrameOuter.Visible then
                    colorPicker:Hide()
                else
                    contextMenu:Hide()
                    colorPicker:Show()
                end;
            end;
        end);

        displayFrame.InputBegan:Connect(function(input2)
            if input2.UserInputType == Enum.UserInputType.MouseButton2 and not library2:MouseIsOverOpenedFrame(input2) then
                contextMenu:Show()
                colorPicker:Hide()
            end
        end);

        if transparencyBoxInner then
            transparencyBoxInner.InputBegan:Connect(function(input2)
                if library2:IsPrimaryInput(input2) then
                    repeat
                        local minX2 = transparencyBoxInner.AbsolutePosition.X;
                        local maxX2 = minX2 + transparencyBoxInner.AbsoluteSize.X;
                        local pointer = library2:GetInputPosition(input2);
                        local mouseX = math.clamp(pointer.X, minX2, maxX2);

                        colorPicker.EditorTransparency = 1 - ((mouseX - minX2) / (maxX2 - minX2));

                        colorPicker:Display();

                        renderStepped:Wait();
                    until not library2:IsInputActive(input2);

                    library2:AttemptSave();
                end;
            end);
        end;

        speedBarInner.InputBegan:Connect(function(input2)
            if library2:IsPrimaryInput(input2) then
                repeat
                    local minX2 = speedBarInner.AbsolutePosition.X;
                    local maxX2 = minX2 + speedBarInner.AbsoluteSize.X;
                    local pointer = library2:GetInputPosition(input2);
                    local mouseX = math.clamp(pointer.X, minX2, maxX2);
                    local percent2 = (mouseX - minX2) / math.max(maxX2 - minX2, 1);
                    local speed2 = 0.1 + (percent2 * 4.9);
                    speed2 = math.floor((speed2 * 100) + 0.5) / 100;

                    colorPicker:SetAnimationSpeed(speed2, false);
                    renderStepped:Wait();
                until not library2:IsInputActive(input2);

                library2:AttemptSave();
            end;
        end);

        library2:GiveSignal(inputService2.InputBegan:Connect(function(input2)
            if library2:IsPrimaryInput(input2) then
                local absPos, absSize = pickerFrameOuter.AbsolutePosition, pickerFrameOuter.AbsoluteSize;
                local pointer = library2:GetInputPosition(input2);

                if (pointer.X < absPos.X or pointer.X > absPos.X + absSize.X
                    or pointer.Y < (absPos.Y - 20 - 1) or pointer.Y > absPos.Y + absSize.Y)
                    and not library2:IsMouseOverFrame(displayFrame, input2) then

                    colorPicker:Hide();
                end;

                if not library2:IsMouseOverFrame(contextMenu.Container, input2) then
                    contextMenu:Hide()
                end
            end;

            if input2.UserInputType == Enum.UserInputType.MouseButton2 and contextMenu.Container.Visible then
                if not library2:IsMouseOverFrame(contextMenu.Container, input2) and not library2:IsMouseOverFrame(displayFrame, input2) then
                    contextMenu:Hide()
                end
            end
        end))

        colorPicker.DisplayFrame = displayFrame;
        colorPicker:LoadEditorFromSlot();
        colorPicker:RefreshOutput(true);
        updateAnimationControls();
        library2.AnimatedColorPickers[colorPicker] = true;

        options2[idx2] = colorPicker;

        return self;
    end;

    function funcs:AddKeyPicker(idx2, info2)
        local parentObj = self;
        local toggleLabel = self.TextLabel;
        local container2 = self.Container;

        assert(info2.Default, 'AddKeyPicker: Missing default value.');

        local displayText = library2:Translate(info2.Text);

        local keyPicker = {
            Value = info2.Default;
            Toggled = false;
            Mode = info2.Mode or 'Toggle';
            Type = 'KeyPicker';
            Callback = info2.Callback or function(value2) end;
            ChangedCallback = info2.ChangedCallback or function(new) end;

            SyncToggleState = info2.SyncToggleState or false;
        };

        if keyPicker.SyncToggleState then
            info2.Modes = { 'Toggle' }
            info2.Mode = 'Toggle'
        end

        local pickOuter = library2:Create('Frame', {
            Active = true;
            BackgroundColor3 = Color3.new(0, 0, 0);
            BorderColor3 = Color3.new(0, 0, 0);
            Size = library2.IsMobile and UDim2.new(0, 38, 0, 20) or UDim2.new(0, 28, 0, 15);
            LayoutOrder = 30;
            ZIndex = 10;
            Parent = toggleLabel;
        });

        local pickInner = library2:Create('Frame', {
            BackgroundColor3 = library2.BackgroundColor;
            BorderColor3 = library2.OutlineColor;
            BorderMode = Enum.BorderMode.Inset;
            Size = UDim2.new(1, 0, 1, 0);
            ZIndex = 11;
            Parent = pickOuter;
        });

        library2:AddToRegistry(pickInner, {
            BackgroundColor3 = 'BackgroundColor';
            BorderColor3 = 'OutlineColor';
        });

        local displayLabel = library2:CreateLabel({
            Size = UDim2.new(1, 0, 1, 0);
            TextSize = 13;
            Text = info2.Default;
            TextWrapped = true;
            ZIndex = 12;
            Parent = pickInner;
        });

        local modeSelectOuter = library2:Create('Frame', {
            BorderColor3 = Color3.new(0, 0, 0);
            Position = UDim2.fromOffset(toggleLabel.AbsolutePosition.X + toggleLabel.AbsoluteSize.X + 4, toggleLabel.AbsolutePosition.Y + 1);
            Size = UDim2.new(0, 60, 0, 45 + 2);
            Visible = false;
            ZIndex = 14;
            Parent = screenGui2;
        });

        local function updateModeSelectPosition()
            modeSelectOuter.Position = library2:ClampPopupPosition(
                modeSelectOuter,
                toggleLabel.AbsolutePosition.X + toggleLabel.AbsoluteSize.X + 4,
                toggleLabel.AbsolutePosition.Y + 1
            );
        end;

        local modeSelectPositionConnection;
        modeSelectOuter:GetPropertyChangedSignal('Visible'):Connect(function()
            if modeSelectOuter.Visible then
                updateModeSelectPosition();
                if not modeSelectPositionConnection then
                    modeSelectPositionConnection = toggleLabel:GetPropertyChangedSignal('AbsolutePosition'):Connect(updateModeSelectPosition);
                end;
            elseif modeSelectPositionConnection then
                modeSelectPositionConnection:Disconnect();
                modeSelectPositionConnection = nil;
            end;
        end);

        local modeSelectInner = library2:Create('Frame', {
            BackgroundColor3 = library2.BackgroundColor;
            BorderColor3 = library2.OutlineColor;
            BorderMode = Enum.BorderMode.Inset;
            Size = UDim2.new(1, 0, 1, 0);
            ZIndex = 15;
            Parent = modeSelectOuter;
        });

        library2:AddToRegistry(modeSelectInner, {
            BackgroundColor3 = 'BackgroundColor';
            BorderColor3 = 'OutlineColor';
        });

        library2:Create('UIListLayout', {
            FillDirection = Enum.FillDirection.Vertical;
            SortOrder = Enum.SortOrder.LayoutOrder;
            Parent = modeSelectInner;
        });

        local containerLabel = library2:CreateLabel({
            TextXAlignment = Enum.TextXAlignment.Left;
            Size = UDim2.new(1, 0, 0, 18);
            TextSize = 13;
            Visible = false;
            ZIndex = 110;
            Parent = library2.KeybindContainer;
        },  true);

        local modes2 = info2.Modes or { 'Always', 'Toggle', 'Hold' };
        local modeButtons = {};

        for idx2, mode2 in next, modes2 do
            local modeButton = {};

            local label2 = library2:CreateLabel({
                Active = true;
                Size = UDim2.new(1, 0, 0, 15);
                TextSize = 13;
                Text = library2:Translate(mode2);
                ZIndex = 16;
                Parent = modeSelectInner;
            });

            function modeButton:Select()
                for _, button in next, modeButtons do
                    button:Deselect();
                end;

                keyPicker.Mode = mode2;

                label2.TextColor3 = library2.AccentColor;
                library2.RegistryMap[label2].Properties.TextColor3 = 'AccentColor';

                modeSelectOuter.Visible = false;
                if keyPicker.MobileButton then keyPicker.MobileButton:Update(); end;
            end;

            function modeButton:Deselect()
                keyPicker.Mode = nil;

                label2.TextColor3 = library2.FontColor;
                library2.RegistryMap[label2].Properties.TextColor3 = 'FontColor';
            end;

            library2:BindClick(label2, function()
                modeButton:Select();
                library2:AttemptSave();
            end);

            if mode2 == keyPicker.Mode then
                modeButton:Select();
            end;

            modeButtons[mode2] = modeButton;
        end;

        -- // переведенные режимы бывает чет э
        local modeWidth = 60;
        for _, mode2 in next, modes2 do
            modeWidth = math.max(modeWidth, library2:GetTextBounds(library2:Translate(mode2, true), library2.Font, 13) + 8);
        end;
        modeSelectOuter.Size = UDim2.new(0, modeWidth, 0, 45 + 2);

        function keyPicker:GetDisplayState()
            return parentObj.Type == 'Toggle' and parentObj.Value or keyPicker:GetState();
        end;

        function keyPicker:Update()
            if info2.NoUI then
                return;
            end;

            local state2 = keyPicker:GetDisplayState();

            local displayKey = library2.IsMobile and keyPicker.MobileButton and library2:Translate('Touch') or keyPicker.Value;
            displayLabel.Text = displayKey;
            containerLabel.Text = string.format('[%s] %s (%s)', displayKey, displayText, library2:Translate(keyPicker.Mode, true));

            containerLabel.Visible = state2;
            containerLabel.TextColor3 = state2 and library2.AccentColor or library2.FontColor;

            library2.RegistryMap[containerLabel].Properties.TextColor3 = state2 and 'AccentColor' or 'FontColor';
            if library2.RefreshKeybindFrame then library2:RefreshKeybindFrame(); end;
            if keyPicker.MobileButton then keyPicker.MobileButton:Update(); end;
        end;

        function keyPicker:SetMode(mode2, save)
            local modeButton = modeButtons[mode2];
            if not modeButton then return false; end;

            modeButton:Select();
            keyPicker:Update();
            if save then library2:AttemptSave(); end;
            return true;
        end;

        function keyPicker:GetState()
            if keyPicker.Mode == 'Always' then
                return true;
            elseif keyPicker.Mode == 'Hold' then
                if keyPicker.Value == 'None' then
                    return false;
                end

                local key2 = keyPicker.Value;

                if key2 == 'MB1' or key2 == 'MB2' then
                    return key2 == 'MB1' and inputService2:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
                        or key2 == 'MB2' and inputService2:IsMouseButtonPressed(Enum.UserInputType.MouseButton2);
                else
                    return inputService2:IsKeyDown(Enum.KeyCode[keyPicker.Value]);
                end;
            else
                return keyPicker.Toggled;
            end;
        end;

        function keyPicker:SetValue(data2)
            local key2, mode2 = data2[1], data2[2];
            displayLabel.Text = key2;
            keyPicker.Value = key2;
            if not keyPicker:SetMode(mode2) then
                keyPicker:SetMode('Toggle');
            end;
            keyPicker:Update();
        end;

        function keyPicker:OnClick(callback2)
            keyPicker.Clicked = callback2
        end

        function keyPicker:OnChanged(callback2)
            keyPicker.Changed = callback2
            callback2(keyPicker.Value)
        end

        if parentObj.Addons then
            table.insert(parentObj.Addons, keyPicker)
        end

        function keyPicker:DoClick()
            if parentObj.Type == 'Toggle' and keyPicker.SyncToggleState then
                parentObj:SetValue(not parentObj.Value)
            end

            library2:SafeCallback(keyPicker.Callback, keyPicker.Toggled)
            library2:SafeCallback(keyPicker.Clicked, keyPicker.Toggled)
        end

        local picking = false;

        library2:BindClick(pickOuter, function(input2)
            if library2.IsMobile and input2.UserInputType == Enum.UserInputType.Touch then
                updateModeSelectPosition();
                modeSelectOuter.Visible = not modeSelectOuter.Visible;
                return;
            end;

            if input2.UserInputType == Enum.UserInputType.MouseButton1 and not library2:MouseIsOverOpenedFrame(input2) then
                picking = true;

                displayLabel.Text = '';

                local break2;
                local text2 = '';

                task.spawn(function()
                    while (not break2) do
                        if text2 == '...' then
                            text2 = '';
                        end;

                        text2 = text2 .. '.';
                        displayLabel.Text = text2;

                        wait(0.4);
                    end;
                end);

                wait(0.2);

                local event2;
                event2 = inputService2.InputBegan:Connect(function(input2)
                    local key2;

                    if input2.UserInputType == Enum.UserInputType.Keyboard then
                        key2 = input2.KeyCode.Name;
                    elseif input2.UserInputType == Enum.UserInputType.MouseButton1 then
                        key2 = 'MB1';
                    elseif input2.UserInputType == Enum.UserInputType.MouseButton2 then
                        key2 = 'MB2';
                    end;

                    if not key2 then return; end;

                    break2 = true;
                    picking = false;

                    displayLabel.Text = key2;
                    keyPicker.Value = key2;

                    library2:SafeCallback(keyPicker.ChangedCallback, input2.KeyCode or input2.UserInputType)
                    library2:SafeCallback(keyPicker.Changed, input2.KeyCode or input2.UserInputType)

                    library2:AttemptSave();

                    event2:Disconnect();
                end);
            end;
        end);

        pickOuter.InputBegan:Connect(function(input2)
            if input2.UserInputType == Enum.UserInputType.MouseButton2 and not library2:MouseIsOverOpenedFrame(input2) then
                updateModeSelectPosition();
                modeSelectOuter.Visible = true;
            end;
        end);

        library2:GiveSignal(inputService2.InputBegan:Connect(function(input2)
            if (not picking) then
                if keyPicker.Mode == 'Toggle' then
                    local key2 = keyPicker.Value;

                    if key2 == 'MB1' or key2 == 'MB2' then
                        if key2 == 'MB1' and input2.UserInputType == Enum.UserInputType.MouseButton1
                        or key2 == 'MB2' and input2.UserInputType == Enum.UserInputType.MouseButton2 then
                            keyPicker.Toggled = not keyPicker.Toggled
                            keyPicker:DoClick()
                        end;
                    elseif input2.UserInputType == Enum.UserInputType.Keyboard then
                        if input2.KeyCode.Name == key2 then
                            keyPicker.Toggled = not keyPicker.Toggled;
                            keyPicker:DoClick()
                        end;
                    end;
                elseif keyPicker.Mode == 'Hold' then
                    local key2 = keyPicker.Value;
                    local matches2 = (key2 == 'MB1' and input2.UserInputType == Enum.UserInputType.MouseButton1)
                        or (key2 == 'MB2' and input2.UserInputType == Enum.UserInputType.MouseButton2)
                        or (input2.UserInputType == Enum.UserInputType.Keyboard and input2.KeyCode.Name == key2);

                    if matches2 and not keyPicker.Toggled then
                        keyPicker.Toggled = true;
                        keyPicker:DoClick();
                    end;
                end;

                keyPicker:Update();
            end;

            if library2:IsPrimaryInput(input2) then
                local absPos, absSize = modeSelectOuter.AbsolutePosition, modeSelectOuter.AbsoluteSize;
                local pointer = library2:GetInputPosition(input2);

                if (pointer.X < absPos.X or pointer.X > absPos.X + absSize.X
                    or pointer.Y < (absPos.Y - 20 - 1) or pointer.Y > absPos.Y + absSize.Y)
                    and not library2:IsMouseOverFrame(pickOuter, input2) then

                    modeSelectOuter.Visible = false;
                end;
            end;
        end))

        library2:GiveSignal(inputService2.InputEnded:Connect(function(input2)
            if (not picking) then
                if keyPicker.Mode == 'Hold' and keyPicker.Toggled then
                    local key2 = keyPicker.Value;
                    local matches2 = (key2 == 'MB1' and input2.UserInputType == Enum.UserInputType.MouseButton1)
                        or (key2 == 'MB2' and input2.UserInputType == Enum.UserInputType.MouseButton2)
                        or (input2.UserInputType == Enum.UserInputType.Keyboard and input2.KeyCode.Name == key2);

                    if matches2 then
                        keyPicker.Toggled = false;
                        keyPicker:DoClick();
                    end;
                end;

                keyPicker:Update();
            end;
        end))

        keyPicker.MobileButton = library2:CreateMobileBindButton(idx2, keyPicker, info2);
        keyPicker:Update();

        options2[idx2] = keyPicker;

        return self;
    end;

    baseAddons.__index = funcs;
    baseAddons.__namecall = function(table2, key2, ...)
        return funcs[key2](...);
    end;
end;

local baseGroupbox = {};

do
    local funcs = {};

    function funcs:AddBlank(size2)
        local groupbox2 = self;
        local container2 = groupbox2.Container;

        library2:Create('Frame', {
            BackgroundTransparency = 1;
            Size = UDim2.new(1, 0, 0, size2);
            ZIndex = 1;
            Parent = container2;
        });
    end;

    function funcs:AddLabel(text2, doesWrap)
        text2 = library2:Translate(text2);

        local label2 = {};

        local groupbox2 = self;
        local container2 = groupbox2.Container;

        local textLabel2 = library2:CreateLabel({
            Size = UDim2.new(1, -4, 0, library2.IsMobile and 22 or 15);
            TextSize = 14;
            Text = text2;
            TextWrapped = doesWrap or false,
            TextXAlignment = Enum.TextXAlignment.Left;
            ZIndex = 5;
            Parent = container2;
        });

        if doesWrap then
            local y2 = select(2, library2:GetTextBounds(text2, library2.Font, 14, Vector2.new(textLabel2.AbsoluteSize.X, math.huge)))
            textLabel2.Size = UDim2.new(1, -4, 0, y2)
        else
            library2:Create('UIListLayout', {
                Padding = UDim.new(0, 4);
                FillDirection = Enum.FillDirection.Horizontal;
                HorizontalAlignment = Enum.HorizontalAlignment.Right;
                SortOrder = Enum.SortOrder.LayoutOrder;
                Parent = textLabel2;
            });
        end

        label2.TextLabel = textLabel2;
        label2.Container = container2;

        function label2:SetText(text2)
            text2 = library2:Translate(text2, true)
            textLabel2.Text = text2

            if doesWrap then
                local y2 = select(2, library2:GetTextBounds(text2, library2.Font, 14, Vector2.new(textLabel2.AbsoluteSize.X, math.huge)))
                textLabel2.Size = UDim2.new(1, -4, 0, y2)
            end

            groupbox2:Resize();
        end

        if (not doesWrap) then
            setmetatable(label2, baseAddons);
        end

        groupbox2:AddBlank(5);
        groupbox2:Resize();

        return label2;
    end;

    function funcs:AddButton(...)
        local button = {};
        local function processButtonParams(class, obj2, ...)
            local props = select(1, ...)
            if type(props) == 'table' then
                obj2.Text = library2:Translate(props.Text)
                obj2.Func = props.Func
                obj2.DoubleClick = props.DoubleClick
                obj2.Tooltip = props.Tooltip
            else
                obj2.Text = library2:Translate((select(1, ...)))
                obj2.Func = select(2, ...)
            end

            assert(type(obj2.Func) == 'function', 'AddButton: `Func` callback is missing.');
        end

        processButtonParams('Button', button, ...)

        local groupbox2 = self;
        local container2 = groupbox2.Container;

        local function createBaseButton(button)
            local outer = library2:Create('Frame', {
                Active = true;
                BackgroundColor3 = Color3.new(0, 0, 0);
                BorderColor3 = Color3.new(0, 0, 0);
                Size = UDim2.new(1, -4, 0, library2.IsMobile and library2.MobileControlHeight or 20);
                ZIndex = 5;
            });

            local inner = library2:Create('Frame', {
                BackgroundColor3 = library2.MainColor;
                BorderColor3 = library2.OutlineColor;
                BorderMode = Enum.BorderMode.Inset;
                Size = UDim2.new(1, 0, 1, 0);
                ZIndex = 6;
                Parent = outer;
            });

            local label2 = library2:CreateLabel({
                Size = UDim2.new(1, 0, 1, 0);
                TextSize = 14;
                Text = button.Text;
                ZIndex = 6;
                Parent = inner;
            });

            library2:Create('UIGradient', {
                Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(212, 212, 212))
                });
                Rotation = 90;
                Parent = inner;
            });

            library2:AddToRegistry(outer, {
                BorderColor3 = 'Black';
            });

            library2:AddToRegistry(inner, {
                BackgroundColor3 = 'MainColor';
                BorderColor3 = 'OutlineColor';
            });

            library2:OnHighlight(outer, outer,
                { BorderColor3 = 'AccentColor' },
                { BorderColor3 = 'Black' }
            );

            return outer, inner, label2
        end

        local function initEvents(button)
            local function validateClick(input2)
                if library2:MouseIsOverOpenedFrame(input2) then
                    return false
                end

                if not library2:IsPrimaryInput(input2) then
                    return false
                end

                return true
            end

            local confirmToken = 0
            local function resetConfirmation()
                library2:RemoveFromRegistry(button.Label)
                library2:AddToRegistry(button.Label, { TextColor3 = 'FontColor' })
                button.Label.TextColor3 = library2.FontColor
                button.Label.Text = button.Text
                button.Locked = false
            end

            library2:BindClick(button.Outer, function(input2)
                if not validateClick(input2) then return end

                if button.DoubleClick then
                    if button.Locked then
                        confirmToken += 1
                        resetConfirmation()
                        library2:SafeCallback(button.Func)
                        return
                    end

                    library2:RemoveFromRegistry(button.Label)
                    library2:AddToRegistry(button.Label, { TextColor3 = 'AccentColor' })
                    button.Label.TextColor3 = library2.AccentColor
                    button.Label.Text = library2:Translate('Are you sure?')
                    button.Locked = true

                    confirmToken += 1
                    local currentToken = confirmToken
                    task.delay(0.5, function()
                        if button.Locked and confirmToken == currentToken then
                            resetConfirmation()
                        end
                    end)

                    return
                end

                library2:SafeCallback(button.Func);
            end)
        end

        button.Outer, button.Inner, button.Label = createBaseButton(button)
        button.Outer.Parent = container2

        initEvents(button)

        function button:AddTooltip(tooltip)
            if type(tooltip) == 'string' then
                library2:AddToolTip(tooltip, self.Outer)
            end
            return self
        end


        function button:AddButton(...)
            local subButton = {}

            processButtonParams('SubButton', subButton, ...)

            self.Outer.Size = UDim2.new(0.5, -2, 0, 20)

            subButton.Outer, subButton.Inner, subButton.Label = createBaseButton(subButton)

            subButton.Outer.Position = UDim2.new(1, 3, 0, 0)
            subButton.Outer.Size = UDim2.fromOffset(self.Outer.AbsoluteSize.X - 2, self.Outer.AbsoluteSize.Y)
            subButton.Outer.Parent = self.Outer

            function subButton:AddTooltip(tooltip)
                if type(tooltip) == 'string' then
                    library2:AddToolTip(tooltip, self.Outer)
                end
                return subButton
            end

            if type(subButton.Tooltip) == 'string' then
                subButton:AddTooltip(subButton.Tooltip)
            end

            initEvents(subButton)
            return subButton
        end

        if type(button.Tooltip) == 'string' then
            button:AddTooltip(button.Tooltip)
        end

        groupbox2:AddBlank(5);
        groupbox2:Resize();

        return button;
    end;

