    function funcs:AddInput(idx2, info2)
        assert(info2.Text, 'AddInput: Missing `Text` string.')
        info2.Text = library2:Translate(info2.Text);

        local textbox = {
            Value = info2.Default or '';
            Numeric = info2.Numeric or false;
            Finished = info2.Finished or false;
