            Text = info2.Text;
            TextXAlignment = Enum.TextXAlignment.Left;
            ZIndex = 5;
            Parent = container2;
        });

        groupbox2:AddBlank(1);

        local textBoxOuter = library2:Create('Frame', {
            BackgroundColor3 = Color3.new(0, 0, 0);
            BorderColor3 = Color3.new(0, 0, 0);
            Size = UDim2.new(1, -4, 0, 20);
            ZIndex = 5;
            Parent = container2;
        });

        local textBoxInner = library2:Create('Frame', {
            BackgroundColor3 = library2.MainColor;
            BorderColor3 = library2.OutlineColor;
