        );

        if type(info2.Tooltip) == 'string' then
            library2:AddToolTip(info2.Tooltip, textBoxOuter)
        end

        library2:Create('UIGradient', {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(212, 212, 212))
            });
            Rotation = 90;
            Parent = textBoxInner;
        });

        local container2 = library2:Create('Frame', {
            BackgroundTransparency = 1;
            ClipsDescendants = true;

            Position = UDim2.new(0, 5, 0, 0);
            Size = UDim2.new(1, -5, 1, 0);

            ZIndex = 7;
            Parent = textBoxInner;
        })

        local box2 = library2:Create('TextBox', {
            BackgroundTransparency = 1;

            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.fromScale(5, 1),

            Font = library2.Font;
            PlaceholderColor3 = Color3.fromRGB(190, 190, 190);
            PlaceholderText = library2:Translate(info2.Placeholder or '');

            Text = info2.Default or '';
            TextColor3 = library2.FontColor;
            TextSize = 14;
            TextStrokeTransparency = 0;
            TextXAlignment = Enum.TextXAlignment.Left;

            ZIndex = 7;
            Parent = container2;
        });

        library2:ApplyTextStroke(box2);

        function textbox:SetValue(text2)
            if info2.MaxLength and #text2 > info2.MaxLength then
                text2 = text2:sub(1, info2.MaxLength);
            end;

            if textbox.Numeric then
                if (not tonumber(text2)) and text2:len() > 0 then
                    text2 = textbox.Value
                end
            end

            textbox.Value = text2;


            if box2.Text ~= text2 then
                box2.Text = text2;
            end;

            library2:SafeCallback(textbox.Callback, textbox.Value);
            library2:SafeCallback(textbox.Changed, textbox.Value);
        end;

        if textbox.Finished then
            box2.FocusLost:Connect(function(enter)
                if not enter then return end

                textbox:SetValue(box2.Text);
                library2:AttemptSave();
            end)
        else
            box2:GetPropertyChangedSignal('Text'):Connect(function()
                textbox:SetValue(box2.Text);
                library2:AttemptSave();
            end);
        end


        local function update()
            local padding = 2
            local reveal = container2.AbsoluteSize.X

            if not box2:IsFocused() or box2.TextBounds.X <= reveal - 2 * padding then

                box2.Position = UDim2.new(0, padding, 0, 0)
            else

                local cursor = box2.CursorPosition
                if cursor ~= -1 then

                    local subtext = string.sub(box2.Text, 1, cursor-1)
                    local width = textService:GetTextSize(subtext, box2.TextSize, box2.Font, Vector2.new(math.huge, math.huge)).X


                    local currentCursorPos = box2.Position.X.Offset + width


                    if currentCursorPos < padding then
                        box2.Position = UDim2.fromOffset(padding-width, 0)
                    elseif currentCursorPos > reveal - padding - 1 then
                        box2.Position = UDim2.fromOffset(reveal-width-padding-1, 0)
                    end
                end
            end
        end

        task.spawn(update)

        box2:GetPropertyChangedSignal('Text'):Connect(update)
        box2:GetPropertyChangedSignal('CursorPosition'):Connect(update)
        box2.FocusLost:Connect(update)
        box2.Focused:Connect(update)

        library2:AddToRegistry(box2, {
            TextColor3 = 'FontColor';
        });

        function textbox:OnChanged(func2)
            textbox.Changed = func2;
            func2(textbox.Value);
        end;

        groupbox2:AddBlank(5);
        groupbox2:Resize();

        options2[idx2] = textbox;

        return textbox;
    end;

