            Parent = toggleOuter;
        });

        local function updateToggleLayout()
            toggleLabel.Size = UDim2.new(0, math.max(container2.AbsoluteSize.X - toggleSize - 10, 0), 1, 0);
            toggleRegion.Size = UDim2.new(0, math.max(container2.AbsoluteSize.X, toggleSize), 1, 0);
        end;

        container2:GetPropertyChangedSignal('AbsoluteSize'):Connect(updateToggleLayout);
        task.defer(updateToggleLayout);

        library2:OnHighlight(toggleRegion, toggleOuter,
            { BorderColor3 = 'AccentColor' },
            { BorderColor3 = 'Black' }
        );

        function toggle2:UpdateColors()
            toggle2:Display();
        end;

        if type(info2.Tooltip) == 'string' then
            library2:AddToolTip(info2.Tooltip, toggleRegion)
        end

        function toggle2:Display()
            toggleInner.BackgroundColor3 = toggle2.Value and library2.AccentColor or library2.MainColor;
            toggleInner.BorderColor3 = toggle2.Value and library2.AccentColorDark or library2.OutlineColor;

            library2.RegistryMap[toggleInner].Properties.BackgroundColor3 = toggle2.Value and 'AccentColor' or 'MainColor';
            library2.RegistryMap[toggleInner].Properties.BorderColor3 = toggle2.Value and 'AccentColorDark' or 'OutlineColor';
        end;

        function toggle2:OnChanged(func2)
            toggle2.Changed = func2;
            func2(toggle2.Value);
        end;

        function toggle2:SetValue(bool)
            bool = (not not bool);

            toggle2.Value = bool;
            toggle2:Display();

            for _, addon in next, toggle2.Addons do
                if addon.Type == 'KeyPicker' then
                    if addon.SyncToggleState then addon.Toggled = bool end
                    addon:Update()
                end
            end

            library2:SafeCallback(toggle2.Callback, toggle2.Value);
            library2:SafeCallback(toggle2.Changed, toggle2.Value);
            library2:UpdateDependencyBoxes();
        end;

        library2:BindClick(toggleRegion, function(input2)
            if not library2:MouseIsOverOpenedFrame(input2) then
                toggle2:SetValue(not toggle2.Value)
                library2:AttemptSave();
            end;
        end);

        if toggle2.Risky then
            library2:RemoveFromRegistry(toggleLabel)
            toggleLabel.TextColor3 = library2.RiskColor
            library2:AddToRegistry(toggleLabel, { TextColor3 = 'RiskColor' })
        elseif toggle2.Warn then
            library2:RemoveFromRegistry(toggleLabel)
            toggleLabel.TextColor3 = library2.WarnColor
            library2:AddToRegistry(toggleLabel, { TextColor3 = 'WarnColor' })
        end

        toggle2:Display();
        groupbox2:AddBlank(info2.BlankSize or 5 + 2);
        groupbox2:Resize();

        toggle2.TextLabel = toggleLabel;
        toggle2.Container = container2;
        setmetatable(toggle2, baseAddons);

        toggles[idx2] = toggle2;

        library2:UpdateDependencyBoxes();

        return toggle2;
    end;

    function funcs:AddSlider(idx2, info2)
        assert(info2.Default, 'AddSlider: Missing default value.');
        assert(info2.Text, 'AddSlider: Missing slider text.');
        assert(info2.Min, 'AddSlider: Missing minimum value.');
        assert(info2.Max, 'AddSlider: Missing maximum value.');
        assert(info2.Rounding, 'AddSlider: Missing rounding value.');
        info2.Text = library2:Translate(info2.Text);
        info2.Suffix = library2:Translate(info2.Suffix);

        local slider = {
