        for _, child2 in next, container2:GetChildren() do
            previousChildren[child2] = true;
        end;

        if not info2.Compact then
            library2:CreateLabel({
                Size = UDim2.new(1, 0, 0, 10);
                TextSize = 14;
                Text = info2.Text;
                TextXAlignment = Enum.TextXAlignment.Left;
                TextYAlignment = Enum.TextYAlignment.Bottom;
