        });

        local fill2 = library2:Create('Frame', {
            BackgroundColor3 = library2.AccentColor;
            BorderColor3 = library2.AccentColorDark;
            Size = UDim2.new(0, 0, 1, 0);
            ZIndex = 7;
            Parent = sliderInner;
        });

        library2:AddToRegistry(fill2, {
            BackgroundColor3 = 'AccentColor';
            BorderColor3 = 'AccentColorDark';
        });

        local hideBorderRight = library2:Create('Frame', {
            BackgroundColor3 = library2.AccentColor;
            BorderSizePixel = 0;
            Position = UDim2.new(1, 0, 0, 0);
            Size = UDim2.new(0, 1, 1, 0);
            ZIndex = 8;
