        });

        library2:AddToRegistry(hideBorderRight, {
            BackgroundColor3 = 'AccentColor';
        });

        local displayLabel = library2:CreateLabel({
            Size = UDim2.new(1, 0, 1, 0);
            TextSize = 14;
