        );

        if type(info2.Tooltip) == 'string' then
            library2:AddToolTip(info2.Tooltip, sliderOuter)
        end

        function slider:UpdateColors()
            fill2.BackgroundColor3 = library2.AccentColor;
            fill2.BorderColor3 = library2.AccentColorDark;
        end;

        function slider:GetMaxSize()
            slider.MaxSize = math.max(sliderInner.AbsoluteSize.X, 1);
            return slider.MaxSize;
        end;

        function slider:Display()
            local suffix = info2.Suffix or '';

            if info2.Compact then
                displayLabel.Text = info2.Text .. ': ' .. slider.Value .. suffix
            elseif info2.HideMax then
                displayLabel.Text = string.format('%s', slider.Value .. suffix)
            else
                displayLabel.Text = string.format('%s/%s', slider.Value .. suffix, slider.Max .. suffix);
            end

            local maxSize = slider:GetMaxSize();
            local x2 = math.clamp(math.ceil(library2:MapValue(slider.Value, slider.Min, slider.Max, 0, maxSize)), 0, maxSize);
            fill2.Size = UDim2.new(0, x2, 1, 0);

            hideBorderRight.Visible = not (x2 == maxSize or x2 == 0);
        end;

        function slider:OnChanged(func2)
            slider.Changed = func2;
            func2(slider.Value);
        end;

        local function round(value2)
            if slider.Rounding == 0 then
                return math.floor(value2);
            end;


            return tonumber(string.format('%.' .. slider.Rounding .. 'f', value2))
        end;

        function slider:GetValueFromXOffset(x2)
            return round(library2:MapValue(x2, 0, slider:GetMaxSize(), slider.Min, slider.Max));
        end;

        function slider:SetValue(str3)
            local num2 = tonumber(str3);

            if (not num2) then
                return;
            end;

            num2 = math.clamp(num2, slider.Min, slider.Max);

            slider.Value = num2;
            slider:Display();

            library2:SafeCallback(slider.Callback, slider.Value);
            library2:SafeCallback(slider.Changed, slider.Value);
        end;

        local sliderOwner = {};
        local function updateSliderFromInput(input2)
            local pointer = library2:GetInputPosition(input2);
            local nX = math.clamp(pointer.X - sliderInner.AbsolutePosition.X, 0, slider:GetMaxSize());
            local nValue = slider:GetValueFromXOffset(nX);
            local oldValue = slider.Value;
            slider.Value = nValue;
            slider:Display();

            if nValue ~= oldValue then
                library2:SafeCallback(slider.Callback, slider.Value);
                library2:SafeCallback(slider.Changed, slider.Value);
            end;
        end;

        sliderInner.InputBegan:Connect(function(input2)
            if not library2:IsPrimaryInput(input2) or library2:MouseIsOverOpenedFrame(input2) then return; end;
            if not library2:ClaimPointer(sliderOwner, input2) then return; end;

            if input2.UserInputType == Enum.UserInputType.Touch then
                local start2 = library2:GetInputPosition(input2);
                local gesture;

                while library2:IsInputActive(input2) do
                    local delta2 = library2:GetInputPosition(input2) - start2;
                    if delta2.Magnitude >= library2.TouchMoveThreshold then
                        gesture = math.abs(delta2.X) >= math.abs(delta2.Y) and 'Slider' or 'Scroll';
                        break;
                    end;
                    renderStepped:Wait();
                end;

                if gesture == 'Scroll' then
                    library2:ReleasePointer(sliderOwner, input2);
                    return;
                elseif not library2:IsInputActive(input2) then
                    updateSliderFromInput(input2);
                    library2:AttemptSave();
                    library2:ReleasePointer(sliderOwner, input2);
                    return;
                end;
            end;

            repeat
                updateSliderFromInput(input2);
                renderStepped:Wait();
            until not library2:IsInputActive(input2);

            library2:AttemptSave();
            library2:ReleasePointer(sliderOwner, input2);
        end);

        sliderInner:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
            slider:Display();
        end);

        slider:Display();
        groupbox2:AddBlank(info2.BlankSize or 6);
        groupbox2:Resize();

        slider.Elements = {};
        for _, child2 in next, container2:GetChildren() do
            if not previousChildren[child2] and child2:IsA('GuiObject') then
                table.insert(slider.Elements, child2);
            end;
        end;

        function slider:SetVisibility(bool)
            bool = not not bool;
            for _, element2 in next, slider.Elements do
                element2.Visible = bool;
            end;
            groupbox2:Resize();
        end;

        options2[idx2] = slider;

        return slider;
    end;

    function library2:ActivateMobileDropdownScroll(listOuter, scrolling)
        if not library2.IsMobile then return; end;

        library2.ActiveMobileDropdownScroll = {
            ListOuter = listOuter;
            Scrolling = scrolling;
            Input = nil;
            Start = nil;
            CanvasStart = nil;
            Velocity = 0;
            LastCanvasY = scrolling.CanvasPosition.Y;
            LastTime = 0;
        };
    end;

    function library2:DeactivateMobileDropdownScroll(listOuter)
        local state2 = library2.ActiveMobileDropdownScroll;
        if state2 and (listOuter == nil or state2.ListOuter == listOuter) then
            library2.ActiveMobileDropdownScroll = nil;
        end;
    end;

    if library2.IsMobile and not library2.MobileDropdownScrollInitialized then
        library2.MobileDropdownScrollInitialized = true;

        library2:GiveSignal(inputService2.InputBegan:Connect(function(input2)
            local state2 = library2.ActiveMobileDropdownScroll;
            if not state2
                or input2.UserInputType ~= Enum.UserInputType.Touch
                or not state2.ListOuter.Visible
                or not library2:IsMouseOverFrame(state2.Scrolling, input2) then
                return;
            end;

            state2.Input = input2;
            state2.Start = library2:GetInputPosition(input2);
            state2.CanvasStart = state2.Scrolling.CanvasPosition;
            state2.Velocity = 0;
            state2.LastCanvasY = state2.Scrolling.CanvasPosition.Y;
            state2.LastTime = os.clock();
        end));

        library2:GiveSignal(inputService2.InputEnded:Connect(function(input2)
            local state2 = library2.ActiveMobileDropdownScroll;
            if state2 and library2:IsSameInput(input2, state2.Input) then
                state2.Input = nil;
            end;
        end));

        library2:GiveSignal(renderStepped:Connect(function()
            local state2 = library2.ActiveMobileDropdownScroll;
            if not state2 then return; end;
            if not state2.ListOuter.Visible or not state2.Scrolling.Parent then
                library2.ActiveMobileDropdownScroll = nil;
                return;
            end;
            if not state2.Input and math.abs(state2.Velocity) <= 2 then
                state2.Velocity = 0;
                return;
            end;

            local scrolling = state2.Scrolling;
            local maxY2 = math.max(0, scrolling.CanvasSize.Y.Offset - scrolling.AbsoluteSize.Y);
            local now2 = os.clock();
            local dt2 = math.clamp(now2 - (state2.LastTime > 0 and state2.LastTime or now2), 1 / 240, 0.05);

            if state2.Input and library2:IsInputActive(state2.Input) then
                local pointer = library2:GetInputPosition(state2.Input);
                local deltaY = pointer.Y - state2.Start.Y;
                local targetY = math.clamp(state2.CanvasStart.Y - deltaY * 1.15, 0, maxY2);
                state2.Velocity = (targetY - state2.LastCanvasY) / dt2;
                state2.LastCanvasY = targetY;
                state2.LastTime = now2;
                scrolling.CanvasPosition = Vector2.new(0, targetY);
            else
                state2.Input = nil;
                local currentY = scrolling.CanvasPosition.Y;
                local targetY = math.clamp(currentY + state2.Velocity * dt2, 0, maxY2);
                scrolling.CanvasPosition = Vector2.new(0, targetY);
                state2.LastCanvasY = targetY;
                state2.LastTime = now2;
                if targetY == 0 or targetY == maxY2 then
                    state2.Velocity = 0;
                else
                    state2.Velocity = state2.Velocity * math.exp(-9 * dt2);
                end;
            end;
        end));
    end;

    function funcs:AddDropdown(idx2, info2)
        if info2.SpecialType == 'Player' then
            info2.Values = getPlayersString();
