        function dropdown:Display()
            local values2 = dropdown.Values;
            local str3 = '';

            if info2.Multi then
                for idx2, value2 in next, values2 do
                    if dropdown.Value[value2] then
                        str3 = str3 .. showValue(value2) .. ', ';
                    end;
                end;

                str3 = str3:sub(1, #str3 - 2);
            else
                str3 = showValue(dropdown.Value or '');
            end;

            itemList.Text = (str3 == '' and '--' or str3);
        end;

        function dropdown:GetActiveValues()
            if info2.Multi then
                local t2 = {};

                for value2, bool in next, dropdown.Value do
                    table.insert(t2, value2);
                end;

                return t2;
            else
                return dropdown.Value and 1 or 0;
            end;
        end;

        function dropdown:BuildDropdownList()
            local values2 = dropdown.Values;
            local buttons = {};
            local stale = {};
            for _, element2 in next, scrolling:GetChildren() do
                if not element2:IsA('UIListLayout') then
                    stale[element2] = true;
                    for _, child2 in next, element2:GetDescendants() do
                        stale[child2] = true;
                    end;
                end;
            end;
            library2:PurgeRegistry(stale);

            for element2 in next, stale do
                if element2.Parent == scrolling then
                    element2:Destroy();
                end;
            end;

            local count2 = 0;

            for idx2, value2 in next, values2 do
                local table2 = {};

                count2 = count2 + 1;

                local button = library2:Create('Frame', {
                    BackgroundColor3 = library2.MainColor;
                    BorderColor3 = library2.OutlineColor;
                    BorderMode = Enum.BorderMode.Middle;
                    Size = UDim2.new(1, -1, 0, dropdownItemHeight);
                    ZIndex = 23;
                    Active = true,
                    Parent = scrolling;
                });

                library2:AddToRegistry(button, {
                    BackgroundColor3 = 'MainColor';
                    BorderColor3 = 'OutlineColor';
                });

                local buttonLabel = library2:CreateLabel({
                    Active = true;
                    Size = UDim2.new(1, -6, 1, 0);
                    Position = UDim2.new(0, 6, 0, 0);
                    TextSize = 14;
                    Text = showValue(value2);
                    TextXAlignment = Enum.TextXAlignment.Left;
                    ZIndex = 25;
                    Parent = button;
                });

                library2:OnHighlight(button, button,
                    { BorderColor3 = 'AccentColor', ZIndex = 24 },
                    { BorderColor3 = 'OutlineColor', ZIndex = 23 }
                );

                local selected2;

                if info2.Multi then
                    selected2 = dropdown.Value[value2];
                else
                    selected2 = dropdown.Value == value2;
                end;

                function table2:UpdateButton()
                    if info2.Multi then
                        selected2 = dropdown.Value[value2];
                    else
                        selected2 = dropdown.Value == value2;
                    end;

                    buttonLabel.TextColor3 = selected2 and library2.AccentColor or library2.FontColor;
                    library2.RegistryMap[buttonLabel].Properties.TextColor3 = selected2 and 'AccentColor' or 'FontColor';
                end;

                library2:BindClick(buttonLabel, function()
                    local try = not selected2;

                    if dropdown:GetActiveValues() == 1 and (not try) and (not info2.AllowNull) then
                    else
                        if info2.Multi then
                            selected2 = try;

                            if selected2 then
                                dropdown.Value[value2] = true;
                            else
                                dropdown.Value[value2] = nil;
                            end;
                        else
                            selected2 = try;

                            if selected2 then
                                dropdown.Value = value2;
                            else
                                dropdown.Value = nil;
                            end;

                            for _, otherButton in next, buttons do
                                otherButton:UpdateButton();
                            end;
                        end;

                        table2:UpdateButton();
                        dropdown:Display();

                        library2:SafeCallback(dropdown.Callback, dropdown.Value);
                        library2:SafeCallback(dropdown.Changed, dropdown.Value);

                        library2:AttemptSave();
                        if not info2.Multi then
                            dropdown:CloseDropdown();
                        end;
                    end;
                end);

                table2:UpdateButton();

                buttons[button] = table2;
            end;

            dropdown:Display();

            dropdown.ListButtons = buttons;
            dropdown.ListValuesRef = values2;
            dropdown.ListValuesCount = count2;

            scrolling.CanvasSize = UDim2.fromOffset(0, (count2 * dropdownItemHeight) + 1);
            local maxY2 = math.max(0, scrolling.CanvasSize.Y.Offset - scrolling.AbsoluteSize.Y);
            scrolling.CanvasPosition = Vector2.new(0, math.clamp(scrolling.CanvasPosition.Y, 0, maxY2));

            local y2 = math.clamp(count2 * dropdownItemHeight, 0, maxDropdownItems * dropdownItemHeight) + 1;
            recalculateListSize(y2);
        end;

        function dropdown:SetValues(newValues)
            if newValues then
                dropdown.Values = newValues;
            end;

            dropdown:BuildDropdownList();
        end;

		function dropdown:OpenDropdown()
			library2:CloseOpenedFrames(listOuter);
			recalculateListPosition();
			closedHitboxZIndex = dropdownHitbox.ZIndex;
			dismissLayer.Visible = true;
			dropdownHitbox.ZIndex = math.max(closedHitboxZIndex, 22);
			listOuter.Visible = true;
            library2:ActivateMobileDropdownScroll(listOuter, scrolling);
            if not listPositionConnection then
                listPositionConnection = dropdownOuter:GetPropertyChangedSignal('AbsolutePosition'):Connect(recalculateListPosition);
            end;
            library2.OpenedFrames[listOuter] = function()
                dropdown:CloseDropdown();
            end;
            dropdownArrow.Rotation = 180;
        end;

		function dropdown:CloseDropdown()
			library2:DeactivateMobileDropdownScroll(listOuter);
			listOuter.Visible = false;
			dismissLayer.Visible = false;
			dropdownHitbox.ZIndex = closedHitboxZIndex;
            if listPositionConnection then
                listPositionConnection:Disconnect();
                listPositionConnection = nil;
            end;
            library2.OpenedFrames[listOuter] = nil;
            dropdownArrow.Rotation = 0;
        end;

        function dropdown:OnChanged(func2)
            dropdown.Changed = func2;
            func2(dropdown.Value);
        end;

        function dropdown:SetValue(val)
            if dropdown.Multi then
                local nTable = {};

                for value2, bool in next, val do
                    if table.find(dropdown.Values, value2) then
                        nTable[value2] = true
                    end;
                end;

                dropdown.Value = nTable;
            else
                if (not val) then
                    dropdown.Value = nil;
                elseif table.find(dropdown.Values, val) then
                    dropdown.Value = val;
                end;
            end;

            -- // те же значения
            local values2 = dropdown.Values;
            if dropdown.ListButtons
                and dropdown.ListValuesRef == values2
                and dropdown.ListValuesCount == #values2 then
                for _, button in next, dropdown.ListButtons do
                    button:UpdateButton();
                end;
                dropdown:Display();
            else
                dropdown:BuildDropdownList();
            end;

            library2:SafeCallback(dropdown.Callback, dropdown.Value);
            library2:SafeCallback(dropdown.Changed, dropdown.Value);
        end;

        library2:BindClick(dropdownHitbox, function()
            if listOuter.Visible then
                dropdown:CloseDropdown();
            else
                dropdown:OpenDropdown();
            end;
        end);

        library2:BindClick(dismissLayer, function()
            dropdown:CloseDropdown();
        end);

        dropdown:BuildDropdownList();
        dropdown:Display();

        local defaults = {}

        if type(info2.Default) == 'string' then
            local idx2 = table.find(dropdown.Values, info2.Default)
            if idx2 then
                table.insert(defaults, idx2)
            end
        elseif type(info2.Default) == 'table' then
            for _, value2 in next, info2.Default do
                local idx2 = table.find(dropdown.Values, value2)
                if idx2 then
                    table.insert(defaults, idx2)
                end
            end
        elseif type(info2.Default) == 'number' and dropdown.Values[info2.Default] ~= nil then
            table.insert(defaults, info2.Default)
        end

        if next(defaults) then
            for i = 1, #defaults do
                local index2 = defaults[i]
                if info2.Multi then
                    dropdown.Value[dropdown.Values[index2]] = true
                else
                    dropdown.Value = dropdown.Values[index2];
                end

                if (not info2.Multi) then break end
            end

            dropdown:BuildDropdownList();
            dropdown:Display();
        end

        groupbox2:AddBlank(info2.BlankSize or 5);
        groupbox2:Resize();

        options2[idx2] = dropdown;

        return dropdown;
    end;

    function funcs:AddDependencyBox()
        local depbox = {
            Dependencies = {};
        };

        local groupbox2 = self;
        local container2 = groupbox2.Container;

        local holder2 = library2:Create('Frame', {
            BackgroundTransparency = 1;
            Size = UDim2.new(1, 0, 0, 0);
            Visible = false;
            Parent = container2;
        });

        local frame2 = library2:Create('Frame', {
            BackgroundTransparency = 1;
            Size = UDim2.new(1, 0, 1, 0);
            Visible = true;
            Parent = holder2;
        });

        local layout2 = library2:Create('UIListLayout', {
            FillDirection = Enum.FillDirection.Vertical;
            SortOrder = Enum.SortOrder.LayoutOrder;
            Parent = frame2;
        });

        function depbox:Resize()
            holder2.Size = UDim2.new(1, 0, 0, layout2.AbsoluteContentSize.Y);
            groupbox2:Resize();
        end;

        layout2:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
            depbox:Resize();
        end);

        holder2:GetPropertyChangedSignal('Visible'):Connect(function()
            depbox:Resize();
        end);

        function depbox:Update()
            for _, dependency in next, depbox.Dependencies do
                local elem = dependency[1];
                local value2 = dependency[2];

                if elem.Type == 'Toggle' and elem.Value ~= value2 then
                    holder2.Visible = false;
                    depbox:Resize();
                    return;
                end;
            end;

            holder2.Visible = true;
            depbox:Resize();
        end;

        function depbox:SetupDependencies(dependencies)
            for _, dependency in next, dependencies do
                assert(type(dependency) == 'table', 'SetupDependencies: Dependency is not of type `table`.');
                assert(dependency[1], 'SetupDependencies: Dependency is missing element argument.');
                assert(dependency[2] ~= nil, 'SetupDependencies: Dependency is missing value argument.');
            end;

            depbox.Dependencies = dependencies;
            depbox:Update();
        end;

        depbox.Container = frame2;

        setmetatable(depbox, baseGroupbox);

        table.insert(library2.DependencyBoxes, depbox);

        return depbox;
    end;

    baseGroupbox.__index = funcs;
    baseGroupbox.__namecall = function(table2, key2, ...)
        return funcs[key2](...);
    end;
end;

