local function normalizeHorizontalAlignment(value2, default)
    value2 = tostring(value2 or '');
    if value2 == 'Left' or value2 == 'Center' or value2 == 'Right' then
        return value2;
    end;
    return default or 'Center';
end;

local function getHorizontalAlignmentEnum(value2)
    value2 = normalizeHorizontalAlignment(value2, 'Center');
    return value2 == 'Left' and Enum.HorizontalAlignment.Left
        or value2 == 'Right' and Enum.HorizontalAlignment.Right
        or Enum.HorizontalAlignment.Center;
end;

function library2:SetTabSpacing(value2)
    library2.TabSpacing = math.clamp(math.floor((tonumber(value2) or 0) + 0.5), 0, 50);
    if library2.TabListLayout then
        library2.TabListLayout.Padding = UDim.new(0, library2.TabSpacing);
    end;
    if type(library2.RefreshTabLayout) == 'function' then
        library2:RefreshTabLayout();
    end;
end;

function library2:SetTabAlignment(value2)
    library2.TabAlignment = normalizeHorizontalAlignment(value2, 'Center');
    if type(library2.RefreshTabLayout) == 'function' then
        library2:RefreshTabLayout();
    elseif library2.TabListLayout then
        library2.TabListLayout.HorizontalAlignment = getHorizontalAlignmentEnum(library2.TabAlignment);
    end;
end;

function library2:SetWindowTitleAlignment(value2)
    library2.WindowTitleAlignment = normalizeHorizontalAlignment(value2, 'Center');
    library2:RefreshWindowTitleDomain();
end;

function library2:RefreshWindowTitleDomain()
    local title2 = tostring(library2.WindowTitleText or '');
    local dotPosition = title2:find('.', 1, true);
    local hasDomain = dotPosition ~= nil and dotPosition < #title2;
    local prefixText = hasDomain and title2:sub(1, dotPosition - 1) or title2;
    local dotText = hasDomain and '.' or '';
    local textAfterDot = hasDomain and title2:sub(dotPosition + 1) or '';
    local suffixPosition = hasDomain and textAfterDot:find('%s') or nil;
    local domainText = suffixPosition and textAfterDot:sub(1, suffixPosition - 1) or textAfterDot;
    local suffixText = suffixPosition and textAfterDot:sub(suffixPosition) or '';
    local prefixWidth = library2:GetTextBounds(prefixText, library2.Font, 16);
    local dotWidth = library2:GetTextBounds(dotText, library2.Font, 16);
    local domainWidth = library2:GetTextBounds(domainText, library2.Font, 16);
    local suffixWidth = library2:GetTextBounds(suffixText, library2.Font, 16);
    local totalWidth = prefixWidth + dotWidth + domainWidth + suffixWidth;
    local alignment = normalizeHorizontalAlignment(library2.WindowTitleAlignment, 'Center');
    local positionScale = 0.5;
    local startOffset = math.floor(-totalWidth * 0.5 + 0.5);
    if alignment == 'Left' then
        positionScale = 0;
        startOffset = 7;
    elseif alignment == 'Right' then
        positionScale = 1;
        startOffset = -totalWidth - 7;
    end;
    local domainColor = library2.WindowTitleDomainColorEnabled
        and (library2.WindowTitleDomainColor or library2.AccentColor)
        or library2.FontColor;

    for _, entry2 in ipairs(library2.WindowTitleLabels or {}) do
        local layerVisible = not entry2.IsGlow or library2.WindowTitleGlowEnabled;

        entry2.PrefixLabel.Text = prefixText;
        entry2.PrefixLabel.Position = UDim2.new(positionScale, startOffset + entry2.OffsetX, 0, entry2.OffsetY);
        entry2.PrefixLabel.Size = UDim2.new(0, prefixWidth, 0, 25);
        entry2.PrefixLabel.Visible = layerVisible;

        entry2.DotLabel.Text = dotText;
        entry2.DotLabel.TextColor3 = domainColor;
        entry2.DotLabel.Position = UDim2.new(positionScale, startOffset + prefixWidth + entry2.OffsetX, 0, entry2.OffsetY);
        entry2.DotLabel.Size = UDim2.new(0, dotWidth, 0, 25);
        entry2.DotLabel.Visible = hasDomain and layerVisible;

        entry2.DomainLabel.Text = domainText;
        entry2.DomainLabel.TextColor3 = domainColor;
        entry2.DomainLabel.Position = UDim2.new(
            positionScale,
            startOffset + prefixWidth + dotWidth + entry2.OffsetX,
            0,
            entry2.OffsetY
        );
        entry2.DomainLabel.Size = UDim2.new(0, domainWidth, 0, 25);
        entry2.DomainLabel.Visible = hasDomain and layerVisible;

        entry2.SuffixLabel.Text = suffixText;
        entry2.SuffixLabel.TextColor3 = library2.FontColor;
        entry2.SuffixLabel.Position = UDim2.new(
            positionScale,
            startOffset + prefixWidth + dotWidth + domainWidth + entry2.OffsetX,
            0,
            entry2.OffsetY
        );
        entry2.SuffixLabel.Size = UDim2.new(0, suffixWidth, 0, 25);
        entry2.SuffixLabel.Visible = suffixText ~= '' and layerVisible;
    end;
end;

