function library2:GetWatermarkText()
    local text2 = tostring(library2.WatermarkTemplate or '');
    local fps = tostring(library2.CurrentFPS or 0);
    local ping2 = tostring(library2.CurrentPing or 0);

    text2 = text2:gsub('{fps}', fps):gsub('{FPS}', fps);
    text2 = text2:gsub('{ping}', ping2):gsub('{PING}', ping2);

    return text2;
end;

