    local x2, y2 = library2:GetTextBounds(text2, library2.Font, 14);
    library2.Watermark.Size = UDim2.new(0, x2 + 15, 0, (y2 * 1.5) + 3);
    library2.WatermarkText.Text = text2;
end;

