    library2.WatermarkTemplate = tostring(text2 or '');

    local watermarkOption = options2 and options2.Settings_WatermarkText;
    if watermarkOption and watermarkOption.Value ~= library2.WatermarkTemplate then
        watermarkOption:SetValue(library2.WatermarkTemplate);
    end;

    library2:RefreshWatermark();
