do
    local frames = 0;
    local elapsed2 = 0;

    library2:GiveSignal(renderStepped:Connect(function(delta2)
        if not library2.WatermarkEnabled then
            frames = 0;
            elapsed2 = 0;
            return;
        end;

        frames = frames + 1;
        elapsed2 = elapsed2 + delta2;

        if elapsed2 < 0.25 then
            return;
        end;

        library2.CurrentFPS = math.floor((frames / elapsed2) + 0.5);

        local success2, ping2 = pcall(function()
            return stats2.Network.ServerStatsItem['Data Ping']:GetValue();
        end);

        if not success2 then
            success2, ping2 = pcall(function()
                return localPlayer:GetNetworkPing() * 1000;
            end);
        end;

        library2.CurrentPing = success2 and math.floor(ping2 + 0.5) or 0;
        frames = 0;
        elapsed2 = 0;
        library2:RefreshWatermark();
    end));
end;

local function colorToRichHex(color4)
    return string.format('#%02X%02X%02X',
        math.floor(color4.R * 255 + 0.5),
        math.floor(color4.G * 255 + 0.5),
        math.floor(color4.B * 255 + 0.5)
    );
end;

local function escapeRichText(text2)
    return (tostring(text2)
        :gsub('&', '&amp;')
        :gsub('<', '&lt;')
        :gsub('>', '&gt;')
        :gsub('"', '&quot;')
        :gsub("'", '&apos;'));
end;

function library2:BuildRichText(segments2)
    local parts2 = {};
    local plain = {};

    for _, segment2 in ipairs(segments2) do
        local body2 = escapeRichText(segment2[1]);
        plain[#plain + 1] = tostring(segment2[1]);

        local key2 = segment2[2];
        local color4 = typeof(key2) == 'Color3' and key2 or (key2 and library2[key2]);

        if color4 then
            parts2[#parts2 + 1] = string.format('<font color="%s">%s</font>', colorToRichHex(color4), body2);
        else
            parts2[#parts2 + 1] = body2;
        end;
    end;

    return table.concat(parts2), table.concat(plain);
end;

function library2:NotifyRich(segments2, time2)
    if type(segments2) ~= 'table' then
        return library2:Notify(tostring(segments2), time2);
    end;

    local rich, plain = library2:BuildRichText(segments2);
    return library2:Notify(plain, time2, rich);
end;

function library2:Notify(text2, time2, richText)
    if not richText then
        text2 = library2:Translate(text2, true);
    end;

    local xSize, ySize = library2:GetTextBounds(text2, library2.Font, 14);

    ySize = ySize + 7

    local notifyOuter = library2:Create('Frame', {
        BorderColor3 = Color3.new(0, 0, 0);
        Position = UDim2.new(0, 100, 0, 10);
        Size = UDim2.new(0, 0, 0, ySize);
        ClipsDescendants = true;
        ZIndex = 100;
        Parent = library2.NotificationArea;
    });

    local notifyInner = library2:Create('Frame', {
        BackgroundColor3 = library2.MainColor;
        BorderColor3 = library2.OutlineColor;
        BorderMode = Enum.BorderMode.Inset;
        Size = UDim2.new(1, 0, 1, 0);
        ZIndex = 101;
        Parent = notifyOuter;
    });

    library2:AddToRegistry(notifyInner, {
        BackgroundColor3 = 'MainColor';
        BorderColor3 = 'OutlineColor';
    }, true);

    local innerFrame = library2:Create('Frame', {
        BackgroundColor3 = Color3.new(1, 1, 1);
        BorderSizePixel = 0;
        Position = UDim2.new(0, 1, 0, 1);
        Size = UDim2.new(1, -2, 1, -2);
        ZIndex = 102;
        Parent = notifyInner;
    });

    local gradient2 = library2:Create('UIGradient', {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, library2:GetDarkerColor(library2.MainColor)),
            ColorSequenceKeypoint.new(1, library2.MainColor),
        });
        Rotation = -90;
        Parent = innerFrame;
    });

    library2:AddToRegistry(gradient2, {
        Color = function()
            return ColorSequence.new({
                ColorSequenceKeypoint.new(0, library2:GetDarkerColor(library2.MainColor)),
                ColorSequenceKeypoint.new(1, library2.MainColor),
            });
        end
    });

    local notifyLabel = library2:CreateLabel({
        Position = UDim2.new(0, 4, 0, 0);
        Size = UDim2.new(1, -4, 1, 0);
        Text = text2;
        TextXAlignment = Enum.TextXAlignment.Left;
        TextSize = 14;
        ZIndex = 103;
        Parent = innerFrame;
    });

    if richText then
        notifyLabel.RichText = true;
        notifyLabel.Text = richText;
    end;

    local leftColor = library2:Create('Frame', {
        BackgroundColor3 = library2.AccentColor;
        BorderSizePixel = 0;
        Position = UDim2.new(0, -1, 0, -1);
        Size = UDim2.new(0, 3, 1, 2);
        ZIndex = 104;
        Parent = notifyOuter;
    });

    library2:AddToRegistry(leftColor, {
        BackgroundColor3 = 'AccentColor';
    }, true);

    pcall(notifyOuter.TweenSize, notifyOuter, UDim2.new(0, xSize + 8 + 4, 0, ySize), 'Out', 'Quad', 0.4, true);

    task.spawn(function()
        wait(time2 or 5);

        pcall(notifyOuter.TweenSize, notifyOuter, UDim2.new(0, 0, 0, ySize), 'Out', 'Quad', 0.4, true);

        wait(0.4);

        notifyOuter:Destroy();
    end);
end;

function library2:CreateWindow(...)
    local arguments = { ... }
    local config2 = { AnchorPoint = Vector2.zero }

    if type(...) == 'table' then
        config2 = ...;
    else
        config2.Title = arguments[1]
        config2.AutoShow = arguments[2] or false;
    end

    if type(config2.Title) ~= 'string' then config2.Title = 'No title' end
    if type(config2.TabPadding) ~= 'number' then config2.TabPadding = 0 end
    if type(config2.MenuFadeTime) ~= 'number' then config2.MenuFadeTime = 0.2 end

    local mobileMode = library2.IsMobile and config2.Mobile ~= false;
    library2.MobileMode = mobileMode;

    local columnCount = config2.Columns or config2.ColumnCount;
    if type(columnCount) ~= 'number' then columnCount = 3 end
    config2.Columns = mobileMode
        and (library2.DeviceClass == 'Tablet' and math.clamp(math.floor(columnCount), 1, 3)
            or (library2:GetViewportSize().X > library2:GetViewportSize().Y and math.clamp(math.floor(config2.PhoneColumns or 1), 1, 3) or 1))
        or math.clamp(math.floor(columnCount), 1, 3);
    if config2.AutoDistributeRight == nil then config2.AutoDistributeRight = config2.Columns == 3 end

    if typeof(config2.Position) ~= 'UDim2' then config2.Position = UDim2.fromOffset(175, 50) end
    if typeof(config2.Size) ~= 'UDim2' then
        config2.Size = config2.Columns == 3 and UDim2.fromOffset(760, 520) or UDim2.fromOffset(550, 600)
    end

    if config2.Center then
        config2.AnchorPoint = Vector2.new(0.5, 0.5)
        config2.Position = UDim2.fromScale(0.5, 0.5)
    end

    if mobileMode then
        config2.AnchorPoint = Vector2.new(0.5, 0.5);
        config2.Position = UDim2.fromScale(0.5, 0.5);
        config2.AutoDistributeRight = library2.DeviceClass == 'Tablet' and config2.Columns == 3;
        config2.TabPadding = math.min(config2.TabPadding, 4);
    end;

    library2.TabSpacing = math.clamp(math.floor(config2.TabPadding + 0.5), 0, 50);
    library2.TabAlignment = normalizeHorizontalAlignment(config2.TabAlignment or library2.TabAlignment, 'Center');
    library2.WindowTitleAlignment = normalizeHorizontalAlignment(
        config2.TitleAlignment or library2.WindowTitleAlignment,
        'Center'
    );

    local window = {
        Tabs = {};
        Columns = config2.Columns;
        Baseline = {};
    };

    for _, child2 in next, screenGui2:GetChildren() do
        window.Baseline[child2] = true;
    end;

    local outer = library2:Create('CanvasGroup', {
        AnchorPoint = config2.AnchorPoint,
        BackgroundColor3 = Color3.new(0, 0, 0);
