    local function updateMobileWindowSize()
        if not mobileMode then return; end;

        local viewport2 = library2:GetViewportSize();
        if viewport2 == lastMobileViewport then return; end;
        lastMobileViewport = viewport2;
        library2:RefreshDeviceClass();
        window.DeviceClass = library2.DeviceClass;

        local widthRatio = 0.85;
        local heightRatio = 0.72;
        local availableWidth = math.max(1, viewport2.X - 16);
        local availableHeight = math.max(1, viewport2.Y - 24);
        local minWidth = math.min(240, availableWidth);
        local minHeight = math.min(260, availableHeight);
        local width2 = math.max(minWidth, math.min(math.floor(viewport2.X * widthRatio), availableWidth));
        local height2 = math.max(minHeight, math.min(math.floor(viewport2.Y * heightRatio), availableHeight));
        outer.AnchorPoint = Vector2.new(0.5, 0.5);
        outer.Position = UDim2.fromScale(0.5, 0.5);
        outer.Size = UDim2.fromOffset(width2, height2);
        library2:RefreshMobileBindButtonBounds();
    end;

