    local function bindMobileViewport()
        if mobileViewportConnection then
            mobileViewportConnection:Disconnect();
            mobileViewportConnection = nil;
        end;
        if window.Destroyed then return; end;

        local camera2 = workspace2.CurrentCamera;
        if camera2 then
            mobileViewportConnection = camera2:GetPropertyChangedSignal('ViewportSize'):Connect(updateMobileWindowSize);
        end;
        updateMobileWindowSize();
    end;

