                if value2 == 'Friendly' then return statusColors and statusColors.Friendly or Color3.fromRGB(0, 255, 0); end;
                if value2 == 'LocalPlayer' then return Color3.fromRGB(130, 130, 130); end;
                return library2.FontColor;
            end;

            local function unregisterTree(object2)
                library2:RemoveFromRegistry(object2);
                for _, descendant2 in ipairs(object2:GetDescendants()) do
                    library2:RemoveFromRegistry(descendant2);
