            local function setPriority(name2, value2)
                local entry2 = name2 and playerList.Players[name2];
                if not entry2 then return; end;
                if entry2.Player == localPlayer then
                    updateSelection();
                    return;
                end;
                if value2 ~= 'Neutral' and value2 ~= 'Friendly' and value2 ~= 'Enemy' then return; end;
                entry2.Priority.Text = value2;
                updateSelection();
                refreshRows();
                if type(info2.PriorityChanged) == 'function' then
                    library2:SafeCallback(info2.PriorityChanged, entry2.Player, value2);
                end;
            end;

            local priorityGroup = tab2:AddRightGroupbox('Priority');
            local detailGroupY = compactPhoneLayout and 7
                or ((mobileMode and library2.DeviceClass == 'Tablet') and 24 or 30);
            priorityDropdown = priorityGroup:AddDropdown('PlayerList_Priority', {
                Values = { 'Neutral', 'Friendly', 'Enemy' };
                Default = 'Neutral';
                Callback = function(value2)
                    if not syncingPriority then setPriority(selectedName, value2); end;
                end;
            });
            priorityGroup.Holder.Parent = detail;
            priorityGroup.Holder.Position = UDim2.new(0.55, 0, 0, detailGroupY);
            priorityGroup.Holder.Size = UDim2.new(0.45, -8, 0, 49);
            priorityGroup.Holder.ZIndex = 11;
            for _, object2 in ipairs(priorityGroup.Holder:GetDescendants()) do
                if object2:IsA('GuiObject') then object2.ZIndex = math.max(object2.ZIndex, 12); end;
            end;

            local localPlayerGroup = tab2:AddRightGroupbox('LocalPlayer');
            local localPlayerToggle = localPlayerGroup:AddToggle('PlayerList_AreWeSerious', {
                Text = 'Are we serious?';
                Default = false;
                Tooltip = 'You cannot assign a priority to the local player.';
                Callback = function() end;
            });
            localPlayerGroup.Holder.Parent = detail;
            localPlayerGroup.Holder.Position = UDim2.new(0.55, 0, 0, detailGroupY);
            localPlayerGroup.Holder.Size = UDim2.new(0.45, -8, 0, 49);
            localPlayerGroup.Holder.Visible = false;
            localPlayerGroup.Holder.ZIndex = 11;
            for _, object2 in ipairs(localPlayerGroup.Holder:GetDescendants()) do
                if object2:IsA('GuiObject') then object2.ZIndex = math.max(object2.ZIndex, 12); end;
            end;

            local function syncPriorityDropdown(value2)
                syncingPriority = true;
                priorityDropdown:SetValue(value2 == 'LocalPlayer' and 'Neutral' or value2);
                syncingPriority = false;
            end;

            updateSelection = function()
                local entry2 = selectedName and playerList.Players[selectedName];
                if not entry2 then
                    publicDetail.Text = library2:TranslateFormat('Public: %s', '???'); usernameDetail.Text = library2:TranslateFormat('Username: %s', '???'); userIdDetail.Text = library2:TranslateFormat('UserId: %s', '???');
                    avatar.Image = '';
                    priorityGroup.Holder.Visible = true;
                    localPlayerGroup.Holder.Visible = false;
                    syncPriorityDropdown('Neutral');
                    return;
                end;

                local player2 = entry2.Player;
                local isLocalPlayer = player2 == localPlayer;
                priorityGroup.Holder.Visible = not isLocalPlayer;
                localPlayerGroup.Holder.Visible = isLocalPlayer;
                publicDetail.Text = library2:TranslateFormat('Public: %s', player2.DisplayName);
                usernameDetail.Text = library2:TranslateFormat('Username: %s', player2.Name);
                userIdDetail.Text = library2:TranslateFormat('UserId: %s', tostring(player2.UserId));
                syncPriorityDropdown(entry2.Priority.Text);

                thumbnailToken = thumbnailToken + 1;
                local token = thumbnailToken;
                avatar.Image = '';
                task.spawn(function()
                    local success2, image = pcall(function()
                        return players2:GetUserThumbnailAsync(player2.UserId, Enum.ThumbnailType.AvatarBust, Enum.ThumbnailSize.Size100x100);
                    end);
                    if success2 and token == thumbnailToken and selectedName == player2.Name then avatar.Image = image; end;
                end);
            end;

            local function selectPlayer(name2)
                if not playerList.Players[name2] then return; end;
                selectedName = name2;
                updateSelection();
                refreshRows();
            end;

            refreshRows = function()
                for _, row2 in ipairs(playerList.Rows) do unregisterTree(row2); row2:Destroy(); end;
                table.clear(playerList.Rows);

                local query2 = compactPhoneLayout and '' or searchBox.Text:lower();
                local names2 = {};
                for name2, entry2 in next, playerList.Players do
                    local player2 = entry2.Player;
                    local searchable = (name2 .. ' ' .. player2.DisplayName .. ' ' .. tostring(player2.UserId)):lower();
                    if query2 == '' or searchable:find(query2, 1, true) then table.insert(names2, name2); end;
                end;
                table.sort(names2, function(a2, b2) return a2:lower() < b2:lower(); end);

                local rowHeight = compactPhoneLayout and 26 or 20;
                for index2, name2 in ipairs(names2) do
                    local entry2 = playerList.Players[name2];
                    local row2 = library2:Create('Frame', {
                        BackgroundColor3 = name2 == selectedName and library2.AccentColorDark or library2.BackgroundColor;
                        BackgroundTransparency = name2 == selectedName and 0 or 1;
                        BorderSizePixel = 0;
                        Position = UDim2.fromOffset(0, (index2 - 1) * rowHeight);
                        Size = UDim2.new(1, -2, 0, rowHeight);
                        ZIndex = 5;
                        Parent = rowsContainer;
                    });
                    library2:AddToRegistry(row2, { BackgroundColor3 = function()
                        return name2 == selectedName and library2.AccentColorDark or library2.BackgroundColor;
                    end; });
                    local nameLabel = addLabel(
                        row2,
                        name2,
                        UDim2.fromOffset(5, 0),
                        compactPhoneLayout and UDim2.new(0.7, -5, 1, 0) or UDim2.new(0.5, -5, 1, 0)
                    );
                    local exploitFlags = library2.ExploitFlags;
                    if exploitFlags and exploitFlags[entry2.Player.UserId] then
                        nameLabel.RichText = true;
                        nameLabel.Text = name2 .. ' <font color="#ff2d2d">(!)</font>';
                    end;
                    if not compactPhoneLayout then
                        addLabel(row2, tostring(entry2.Player.UserId), UDim2.fromScale(0.5, 0), UDim2.new(0.25, 0, 1, 0), Enum.TextXAlignment.Center);
                    end;
                    local priorityLabel = addLabel(
                        row2,
                        library2:Translate(entry2.Priority.Text),
                        compactPhoneLayout and UDim2.fromScale(0.7, 0) or UDim2.fromScale(0.75, 0),
                        compactPhoneLayout and UDim2.new(0.3, -5, 1, 0) or UDim2.new(0.25, -5, 1, 0),
                        Enum.TextXAlignment.Right
                    );
                    priorityLabel.TextColor3 = priorityColor(entry2.Priority.Text);
                    local click = library2:Create('TextButton', {
                        Active = true;
                        AutoButtonColor = false;
                        BackgroundTransparency = 1;
                        Size = UDim2.fromScale(1, 1);
                        Text = '';
                        ZIndex = 10;
                        Parent = row2;
                    });
                    if compactPhoneLayout then
                        library2:GiveSignal(click.Activated:Connect(function()
                            selectPlayer(name2);
                        end));
                    else
                        library2:BindClick(click, function() selectPlayer(name2); end);
                    end;
                    table.insert(playerList.Rows, row2);
                    entry2.Background = row2;
                end;
                rowsContainer.CanvasSize = UDim2.fromOffset(0, #names2 * rowHeight);
            end;

            function playerList:AddPlayer(player2)
                if not player2 or self.Players[player2.Name] then return; end;
                self.Players[player2.Name] = {
                    Player = player2;
                    Priority = { Text = player2 == localPlayer and 'LocalPlayer' or 'Neutral' };
                };
                if not selectedName then selectedName = player2.Name; end;
                updateSelection(); refreshRows();
            end;

            function playerList:RemovePlayer(playerOrName)
                local name2 = type(playerOrName) == 'string' and playerOrName or playerOrName and playerOrName.Name;
                if not name2 or not self.Players[name2] then return; end;
                self.Players[name2] = nil;
                if selectedName == name2 then selectedName = next(self.Players); end;
                updateSelection(); refreshRows();
            end;

            function playerList:Sync()
                local present = {};
                for _, player2 in ipairs(players2:GetPlayers()) do
                    present[player2.Name] = true;
                    if not self.Players[player2.Name] then
                        self.Players[player2.Name] = {
                            Player = player2;
                            Priority = { Text = player2 == localPlayer and 'LocalPlayer' or 'Neutral' };
                        };
                    end;
                end;
                for name2 in next, self.Players do if not present[name2] then self.Players[name2] = nil; end; end;
                if not selectedName or not self.Players[selectedName] then selectedName = next(self.Players); end;
                updateSelection(); refreshRows();
            end;

            function playerList:SetPriority(playerOrName, value2)
                local name2 = type(playerOrName) == 'string' and playerOrName or playerOrName and playerOrName.Name;
                setPriority(name2, value2);
            end;

            function playerList:GetPriority(playerOrName)
                local name2 = type(playerOrName) == 'string' and playerOrName or playerOrName and playerOrName.Name;
                local entry2 = name2 and self.Players[name2];
                return entry2 and entry2.Priority.Text or 'Neutral';
            end;

            function playerList:GetSelectedPlayer()
                local entry2 = selectedName and self.Players[selectedName];
                return entry2 and entry2.Player or nil;
            end;

            function playerList:Refresh()
                updateSelection();
                refreshRows();
            end;

            searchBox:GetPropertyChangedSignal('Text'):Connect(refreshRows);

            local refreshEvent = Instance.new('BindableEvent');
            library2:BindClick(refreshButton, function() playerList:Sync(); refreshEvent:Fire(); end);
            playerList.Items.Refresh = { Button = refreshButton; MouseButton1Click = refreshEvent.Event; };
            playerList.Items.Search = searchBox;
            playerList.Items.Priority = priorityDropdown;
            playerList.Items.LocalPlayerToggle = localPlayerToggle;
            playerList.Holder = holder2;

            playerList:Sync();
            library2:GiveSignal(players2.PlayerAdded:Connect(function(player2) playerList:AddPlayer(player2); end));
            library2:GiveSignal(players2.PlayerRemoving:Connect(function(player2) playerList:RemovePlayer(player2); end));

            return playerList;
        end;

        function tab2:AddTabbox(info2)
            local tabbox = {
                Tabs = {};
            };
            local column = resolveColumn(info2.Side);

            local boxOuter = library2:Create('Frame', {
                BackgroundColor3 = library2.BackgroundColor;
                BorderColor3 = library2.OutlineColor;
                BorderMode = Enum.BorderMode.Inset;
                Size = UDim2.new(1, 0, 0, 0);
                ZIndex = 2;
                Parent = sides[column];
            });

            library2:AddToRegistry(boxOuter, {
                BackgroundColor3 = 'BackgroundColor';
                BorderColor3 = 'OutlineColor';
            });
            library2:RegisterCustomBackgroundPanel(boxOuter);

            local boxInner = library2:Create('Frame', {
                BackgroundColor3 = library2.BackgroundColor;
                BorderColor3 = Color3.new(0, 0, 0);
                Size = UDim2.new(1, -2, 1, -2);
