            library2:RegisterCustomBackgroundPanel(boxInner);

            local highlight2 = library2:Create('Frame', {
                BackgroundColor3 = library2.AccentColor;
                BorderSizePixel = 0;
                Size = UDim2.new(1, 0, 0, 2);
                ZIndex = 10;
