            });

            library2:AddToRegistry(highlight2, {
                BackgroundColor3 = 'AccentColor';
            });

            local tabboxButtons = library2:Create('Frame', {
                BackgroundTransparency = 1;
                Position = UDim2.new(0, 0, 0, 1);
                Size = UDim2.new(1, 0, 0, 18);
                ZIndex = 5;
                Parent = boxInner;
            });

            library2:Create('UIListLayout', {
                FillDirection = Enum.FillDirection.Horizontal;
                HorizontalAlignment = Enum.HorizontalAlignment.Left;
                SortOrder = Enum.SortOrder.LayoutOrder;
                Parent = tabboxButtons;
            });

            function tabbox:AddTab(name2)
                local tab2 = {};

                local button = library2:Create('Frame', {
                    Active = true;
                    BackgroundColor3 = library2.MainColor;
                    BorderColor3 = Color3.new(0, 0, 0);
                    Size = UDim2.new(0.5, 0, 1, 0);
                    ZIndex = 6;
                    Parent = tabboxButtons;
                });

                library2:AddToRegistry(button, {
                    BackgroundColor3 = 'MainColor';
                });

                local buttonLabel = library2:CreateLabel({
                    Size = UDim2.new(1, 0, 1, 0);
                    TextSize = 14;
                    Text = library2:Translate(name2);
                    TextXAlignment = Enum.TextXAlignment.Center;
                    ZIndex = 7;
                    Parent = button;
                });

                local block2 = library2:Create('Frame', {
                    BackgroundColor3 = library2.BackgroundColor;
                    BorderSizePixel = 0;
                    Position = UDim2.new(0, 0, 1, 0);
                    Size = UDim2.new(1, 0, 0, 1);
                    Visible = false;
                    ZIndex = 9;
                    Parent = button;
                });

                library2:AddToRegistry(block2, {
                    BackgroundColor3 = 'BackgroundColor';
                });

                local container2 = library2:Create('Frame', {
                    BackgroundTransparency = 1;
                    Position = UDim2.new(0, 4, 0, 20);
                    Size = UDim2.new(1, -4, 1, -20);
                    ZIndex = 1;
                    Visible = false;
                    Parent = boxInner;
                });

                library2:Create('UIListLayout', {
                    FillDirection = Enum.FillDirection.Vertical;
                    SortOrder = Enum.SortOrder.LayoutOrder;
                    Parent = container2;
                });

                function tab2:Show()
                    for _, tab2 in next, tabbox.Tabs do
                        tab2:Hide();
                    end;

                    container2.Visible = true;
                    block2.Visible = true;

                    button.BackgroundColor3 = library2.BackgroundColor;
                    library2.RegistryMap[button].Properties.BackgroundColor3 = 'BackgroundColor';

                    tab2:Resize();
                end;

                function tab2:Hide()
                    container2.Visible = false;
                    block2.Visible = false;

                    button.BackgroundColor3 = library2.MainColor;
                    library2.RegistryMap[button].Properties.BackgroundColor3 = 'MainColor';
                end;

                function tab2:Resize()
                    local tabCount = 0;

                    for _, tab2 in next, tabbox.Tabs do
                        tabCount = tabCount + 1;
                    end;

                    for _, button in next, tabboxButtons:GetChildren() do
                        if not button:IsA('UIListLayout') then
                            button.Size = UDim2.new(1 / tabCount, 0, 1, 0);
                        end;
                    end;

                    if (not container2.Visible) then
                        return;
                    end;

                    local size2 = 0;

                    for _, element2 in next, tab2.Container:GetChildren() do
                        if (not element2:IsA('UIListLayout')) and element2.Visible then
                            size2 = size2 + element2.Size.Y.Offset;
                        end;
                    end;

                    boxOuter.Size = UDim2.new(1, 0, 0, 20 + size2 + 2 + 2);
                end;

                library2:BindClick(button, function(input2)
                    if not library2:MouseIsOverOpenedFrame(input2) then
                        tab2:Show();
                        tab2:Resize();
                    end;
                end);

                tab2.Container = container2;
                tabbox.Tabs[name2] = tab2;

                setmetatable(tab2, baseGroupbox);

                tab2:AddBlank(3);
                tab2:Resize();


                if #tabboxButtons:GetChildren() == 2 then
                    tab2:Show();
                end;

                return tab2;
            end;

            tab2.Tabboxes[info2.Name or ''] = tabbox;

            return tabbox;
        end;

        function tab2:AddLeftTabbox(name2)
            return tab2:AddTabbox({ Name = name2, Side = 1; });
        end;

        function tab2:AddCenterTabbox(name2)
            return tab2:AddTabbox({ Name = name2, Side = math.min(2, config2.Columns); });
        end;

        function tab2:AddMiddleTabbox(name2)
            return tab2:AddCenterTabbox(name2);
        end;

        function tab2:AddColumnTabbox(column, name2)
            return tab2:AddTabbox({ Name = name2, Side = column; });
        end;

        function tab2:AddRightTabbox(name2)
            return tab2:AddTabbox({ Name = name2, Side = getNextRightColumn(); });
        end;

        library2:BindClick(tabButton, function()
            tab2:ShowTab();
        end);


        if #tabContainer:GetChildren() == 1 then
            tab2:ShowTab();
        end;

        if isSettingsTab then
            local interface = tab2:AddCenterGroupbox('Interface');

            interface:AddToggle('Settings_ShowWatermark', {
                Text = 'Show watermark';
