                Suffix = ' px';
                Tooltip = 'Sets the distance between page-selection tabs.';
                Callback = function(value2)
                    library2:SetTabSpacing(value2);
                end;
            });

            local windowTitleDomainColorToggle = interface:AddToggle('Settings_WindowTitleDomainColor', {
                Text = 'Custom domain color';
                Default = false;
                Tooltip = 'Colors only the first dot and domain token, stopping at whitespace.';
                Callback = function(value2)
                    library2:SetWindowTitleDomainColorVisibility(value2);
                end;
            });

            windowTitleDomainColorToggle:AddColorPicker('Settings_WindowTitleDomainColorValue', {
                Default = library2.WindowTitleDomainColor;
                Title = 'Domain color';
                Callback = function(color4)
                    library2:SetWindowTitleDomainColor(color4);
                end;
            });

            interface:AddToggle('Settings_ShowKeybinds', {
                Text = 'Show keybinds';
                Default = false;
                Callback = function(value2)
                    library2:SetKeybindVisibility(value2);
                end;
            });

            if mobileMode then
                local mobileBindValues = library2:GetMobileBindOptions();
                if #mobileBindValues > 0 then
                    interface:AddDropdown('Settings_VisibleMobileBinds', {
                        Text = 'Visible touch binds';
                        Values = mobileBindValues;
                        Default = mobileBindValues;
                        Multi = true;
                        AllowNull = true;
                        FormatValue = function(value2)
                            local name2, id2 = string.match(tostring(value2), '^(.*) %[([^%]]*)%]$');
                            if not name2 then return value2; end;
                            return string.format('%s [%s]', library2:Translate(name2, true), id2);
                        end;
                        Callback = function(value2)
                            library2:SetVisibleMobileBinds(value2);
                        end;
                    });
                end;

                interface:AddDropdown('Settings_MobileMenuButtonStyle', {
                    Text = 'Mobile menu button';
                    Values = { 'Compact D', 'Text button' };
                    Default = 'Compact D';
                    Multi = false;
                    Callback = function(value2)
                        library2:SetMobileToggleStyle(value2);
                    end;
                });
            end;

            interface:AddToggle('Settings_WindowTitleGlow', {
                Text = 'Title glow';
                Default = false;
                Callback = function(value2)
                    library2:SetWindowTitleGlowVisibility(value2);
                end;
            });

            local windowTitleGradientToggle = interface:AddToggle('Settings_WindowTitleGradient', {
                Text = 'Title gradient';
                Default = false;
                Callback = function(value2)
                    library2:SetWindowTitleGradientVisibility(value2);
                end;
            });

            windowTitleGradientToggle:AddColorPicker('Settings_WindowTitleGradientStart', {
                Default = library2.WindowTitleGradientStart;
                Title = 'Gradient start';
                Callback = function(color4)
                    library2:SetWindowTitleGradientStart(color4);
                end;
            });

            interface:AddLabel('Gradient end'):AddColorPicker('Settings_WindowTitleGradientEnd', {
                Default = library2.WindowTitleGradientEnd;
                Title = 'Gradient end';
                Callback = function(color4)
                    library2:SetWindowTitleGradientEnd(color4);
                end;
            });

            local windowTitleGradientRotationSlider = interface:AddSlider('Settings_WindowTitleGradientRotation', {
                Text = 'Gradient rotation';
                Min = 0;
                Max = 360;
                Default = 0;
                Rounding = 0;
                Suffix = '°';
                Callback = function(value2)
                    library2:SetWindowTitleGradientRotation(value2);
                end;
            });

            interface:AddToggle('Settings_WindowTitleGradientSpin', {
                Text = 'Gradient spin';
                Default = false;
                Tooltip = 'Continuously rotates the title gradient and updates the rotation slider.';
                Callback = function(value2)
                    library2:SetWindowTitleGradientSpin(value2);

                    if value2 and not windowTitleGradientToggle.Value then
                        windowTitleGradientToggle:SetValue(true);
                    end;
                end;
            });

            interface:AddSlider('Settings_WindowTitleGradientSpinSpeed', {
                Text = 'Spin speed';
                Min = 10;
                Max = 360;
                Default = 90;
                Rounding = 0;
                Suffix = '°/s';
                Callback = function(value2)
                    library2:SetWindowTitleGradientSpinSpeed(value2);
                end;
            });

            local gradientSpinElapsed = 0;
            library2:GiveSignal(renderStepped:Connect(function(delta2)
                if not library2.WindowTitleGradientSpinEnabled then
                    gradientSpinElapsed = 0;
                    return;
                end;

                gradientSpinElapsed = gradientSpinElapsed + delta2;
                if gradientSpinElapsed < 1 / 30 then return end;

                local rotation = math.floor(
                    ((library2.WindowTitleGradientRotation or 0)
                        + gradientSpinElapsed * library2.WindowTitleGradientSpinSpeed) % 360 + 0.5
                );
                gradientSpinElapsed = 0;
                windowTitleGradientRotationSlider:SetValue(rotation);
            end));

        end;

        window.Tabs[name2] = tab2;
        return tab2;
    end;

    local modalElement = library2:Create('TextButton', {
        BackgroundTransparency = 1;
        Size = UDim2.new(0, 0, 0, 0);
        Visible = true;
        Text = '';
        Modal = false;
        Parent = screenGui2;
    });

    local mobileToggleOuter;
    local mobileToggleButton;
    if mobileMode then
        mobileToggleOuter = library2:Create('Frame', {
            AnchorPoint = Vector2.new(1, 0);
            BackgroundColor3 = Color3.new(0, 0, 0);
            BorderColor3 = Color3.new(0, 0, 0);
            Position = UDim2.new(1, -12, 0, 12);
            Size = UDim2.fromOffset(38, 38);
            ZIndex = 250;
            Parent = screenGui2;
        });

        mobileToggleButton = library2:Create('TextButton', {
            AutoButtonColor = false;
            BackgroundColor3 = library2.MainColor;
            BorderColor3 = library2.OutlineColor;
            BorderMode = Enum.BorderMode.Inset;
            Font = library2.Font;
            Position = UDim2.fromOffset(1, 1);
            Size = UDim2.new(1, -2, 1, -2);
            Text = 'd';
            TextColor3 = library2.FontColor;
            TextSize = 18;
            TextStrokeTransparency = 0;
            ZIndex = 251;
            Parent = mobileToggleOuter;
        });
        library2:ApplyTextStroke(mobileToggleButton);

        library2:Create('UIGradient', {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1));
                ColorSequenceKeypoint.new(1, Color3.fromRGB(212, 212, 212));
            });
            Rotation = 90;
            Parent = mobileToggleButton;
        });

        local mobileAccent = library2:Create('Frame', {
            BackgroundColor3 = library2.AccentColor;
            BorderSizePixel = 0;
            Size = UDim2.new(1, 0, 0, 2);
            ZIndex = 252;
            Parent = mobileToggleButton;
        });

        library2:AddToRegistry(mobileToggleButton, {
            BackgroundColor3 = 'MainColor';
            BorderColor3 = 'OutlineColor';
            TextColor3 = 'FontColor';
        });
        library2:AddToRegistry(mobileAccent, { BackgroundColor3 = 'AccentColor'; });
        library2.MobileToggle = mobileToggleOuter;
    end;

    local toggled = false;
    local fading = false;
    local cursorMouseState = true;
    local cursor2;
    local cursorOutline;
    library2.WindowFocused = true;

    library2.MobileToggleStyle = library2.MobileToggleStyle or 'Compact D';
    function library2:SetMobileToggleStyle(value2)
        if not mobileToggleOuter or not mobileToggleButton then return; end;

        local compact2 = value2 ~= 'Text button';
        library2.MobileToggleStyle = compact2 and 'Compact D' or 'Text button';
        mobileToggleOuter.Size = compact2 and UDim2.fromOffset(38, 38) or UDim2.fromOffset(92, 32);
        mobileToggleButton.TextSize = compact2 and 18 or 14;
        mobileToggleButton.Text = compact2
            and 'd'
            or (toggled and 'drain | hide' or 'drain | menu');
    end;

    library2:SetMobileToggleStyle(library2.MobileToggleStyle);

    if not mobileMode then
        local cursorGuiFrames;

        local function destroyCursorVisuals()
            if cursor2 then
                pcall(function()
                    cursor2.Visible = false;
                    cursorOutline.Visible = false;
                end);
            end;
            for _, frame in ipairs(cursorGuiFrames or {}) do
                pcall(function() frame:Destroy() end);
            end;
            cursorGuiFrames = nil;
            cursor2 = nil;
            cursorOutline = nil;
        end;

        local function buildDrawingCursor()
            local newCursor, newOutline;
            local cursorOk = pcall(function()
                newCursor = Drawing.new('Triangle');
                newCursor.Thickness = 1;
                newCursor.Filled = true;
                newCursor.Visible = false;

                newOutline = Drawing.new('Triangle');
                newOutline.Thickness = 1;
                newOutline.Filled = false;
                newOutline.Color = Color3.new(0, 0, 0);
                newOutline.Visible = false;
            end);

            if cursorOk and newCursor and newOutline then
                cursor2 = newCursor;
                cursorOutline = newOutline;

                library2.CursorDrawings = library2.CursorDrawings or {};
                table.insert(library2.CursorDrawings, cursor2);
                table.insert(library2.CursorDrawings, cursorOutline);
                environment.DrainCursorDrawings = library2.CursorDrawings;
                return true;
            end;

                    return false;
        end;

        local function buildGuiCursor()
            local gui = library2.MobileFovGui;
            if not gui or not gui.Parent then
                gui = Instance.new('ScreenGui');
                gui.Name = 'DrainCursorGui';
                gui.IgnoreGuiInset = true;
                gui.ResetOnSpawn = false;
                gui.DisplayOrder = 1000;
                gui.ZIndexBehavior = Enum.ZIndexBehavior.Global;

                local parented = false;
                local player = game:GetService('Players').LocalPlayer;
                local playerGui = player and player:FindFirstChildOfClass('PlayerGui');
                if playerGui then
                    parented = pcall(function() gui.Parent = playerGui end);
                end;
                if not parented then
                    parented = pcall(function() gui.Parent = game:GetService('CoreGui') end);
                end;
                if not parented then
                                return nil;
                end;
                library2.MobileFovGui = gui;
            end;

            local outlineFrame = Instance.new('Frame');
            outlineFrame.AnchorPoint = Vector2.new(0.5, 0.5);
            outlineFrame.Size = UDim2.fromOffset(16, 16);
            outlineFrame.BackgroundColor3 = Color3.new(0, 0, 0);
            outlineFrame.BackgroundTransparency = 0;
            outlineFrame.BorderSizePixel = 0;
            outlineFrame.Rotation = 45;
            outlineFrame.Visible = false;
            outlineFrame.ZIndex = 10001;
            outlineFrame.Parent = gui;

            local fillFrame = Instance.new('Frame');
            fillFrame.AnchorPoint = Vector2.new(0.5, 0.5);
            fillFrame.Size = UDim2.fromOffset(12, 12);
            fillFrame.BackgroundColor3 = Color3.new(1, 1, 1);
            fillFrame.BackgroundTransparency = 0;
            fillFrame.BorderSizePixel = 0;
            fillFrame.Rotation = 45;
            fillFrame.Visible = false;
            fillFrame.ZIndex = 10002;
            fillFrame.Parent = gui;

            cursorGuiFrames = { outlineFrame, fillFrame };

            local points = {
                A = Vector2.new(0, 0),
                B = Vector2.new(0, 0),
                C = Vector2.new(0, 0),
            };

            local function reposition()
                local cx = (points.A.X + points.B.X + points.C.X) / 3;
                local cy = (points.A.Y + points.B.Y + points.C.Y) / 3;
                local pos = UDim2.fromOffset(cx, cy);
                outlineFrame.Position = pos;
                fillFrame.Position = pos;
            end;

            return setmetatable({
                Remove = function()
                    outlineFrame:Destroy();
                    fillFrame:Destroy();
                end;
            }, {
                __index = function(_, key)
                    if key == 'PointA' then return points.A; end;
                    if key == 'PointB' then return points.B; end;
                    if key == 'PointC' then return points.C; end;
                    return nil;
                end;
                __newindex = function(_, key, value)
                    if key == 'Visible' then
                        local state = value == true;
                        outlineFrame.Visible = state;
                        fillFrame.Visible = state;
                    elseif key == 'Color' then
                        fillFrame.BackgroundColor3 = value;
                    elseif key == 'PointA' then
                        points.A = value;
                        reposition();
                    elseif key == 'PointB' then
                        points.B = value;
                        reposition();
                    elseif key == 'PointC' then
                        points.C = value;
                        reposition();
                    end;
                end;
            });
        end;

        function library2:RebuildCursor()
            destroyCursorVisuals();

            if library2.ForceGuiFov then
                local ok, wrapper = pcall(buildGuiCursor);
                if ok and wrapper then
                    cursor2 = wrapper;
                    cursorOutline = wrapper;
                    return;
                end;
                        end;

            buildDrawingCursor();
        end;

        buildDrawingCursor();

        pcall(function()
            library2:GiveSignal(inputService2.WindowFocusReleased:Connect(function()
                library2.WindowFocused = false;
                if cursor2 then
                    cursor2.Visible = false;
                    cursorOutline.Visible = false;
                end;
                inputService2.MouseIconEnabled = cursorMouseState;
            end));
        end);

        pcall(function()
            library2:GiveSignal(inputService2.WindowFocused:Connect(function()
                library2.WindowFocused = true;
            end));
        end);
    end;

    local cursorHidden = false;
    library2:GiveSignal(renderStepped:Connect(function()
        if mobileMode or not cursor2 then return; end

        if not toggled or not outer.Visible or not library2.WindowFocused then
            if not cursorHidden then
                cursorHidden = true;
                cursor2.Visible = false;
                cursorOutline.Visible = false;
            end;
            return;
        end
        cursorHidden = false;

        cursor2.Visible = true;
        cursorOutline.Visible = true;
        inputService2.MouseIconEnabled = false;
        local mPos = library2:GetRawPointerPosition();
        cursor2.Color = library2.AccentColor;
        cursor2.PointA = Vector2.new(mPos.X, mPos.Y);
        cursor2.PointB = Vector2.new(mPos.X + 16, mPos.Y + 6);
        cursor2.PointC = Vector2.new(mPos.X + 6, mPos.Y + 16);
        cursorOutline.PointA = cursor2.PointA;
        cursorOutline.PointB = cursor2.PointB;
        cursorOutline.PointC = cursor2.PointC;
    end));

    function library2:Toggle()
        if fading then
            return;
        end;

        local fadeTime = config2.MenuFadeTime;
		fading = true;
		toggled = (not toggled);
		if not toggled then
			library2:CloseOpenedFrames();
			library2.ActivePointerOwner = nil;
			library2.ActivePointerInput = nil;
		end;
		library2:SetMobileBindEditing(toggled);
        modalElement.Modal = toggled;

        if toggled then

            outer.Visible = true;
            if not mobileMode and cursor2 then
                cursorMouseState = inputService2.MouseIconEnabled;
                inputService2.MouseIconEnabled = false;
                cursor2.Visible = true;
                cursorOutline.Visible = true;
            end;
        else
            if not mobileMode and cursor2 then
                inputService2.MouseIconEnabled = cursorMouseState;
                cursor2.Visible = false;
                cursorOutline.Visible = false;
            end;
        end;

        if mobileToggleButton then
            mobileToggleButton.Text = library2.MobileToggleStyle == 'Text button'
                and (toggled and 'drain | hide' or 'drain | menu')
                or 'd';
        end;

        local fadeTween = tweenService2:Create(
            outer,
            TweenInfo.new(fadeTime, Enum.EasingStyle.Linear),
            { GroupTransparency = toggled and 0 or 1 }
        );
        fadeTween:Play();

        task.wait(fadeTime);

        outer.Visible = toggled;

        fading = false;
    end

    if mobileToggleButton then
        library2:GiveSignal(mobileToggleButton.Activated:Connect(function()
            task.spawn(library2.Toggle);
        end));
    end;

    library2:GiveSignal(inputService2.InputBegan:Connect(function(input2, processed2)
        if window.Destroyed then return end
        if type(library2.ToggleKeybind) == 'table' and library2.ToggleKeybind.Type == 'KeyPicker' then
            if input2.UserInputType == Enum.UserInputType.Keyboard and input2.KeyCode.Name == library2.ToggleKeybind.Value then
                task.spawn(library2.Toggle)
            end
        elseif input2.KeyCode == Enum.KeyCode.RightControl or (input2.KeyCode == Enum.KeyCode.RightShift and (not processed2)) then
            task.spawn(library2.Toggle)
        end
    end))

    if config2.AutoShow then task.spawn(library2.Toggle) end

    function window:Destroy()
        if window.Destroyed then return; end;
        window.Destroyed = true;

        library2:CloseOpenedFrames();
        library2.ActivePointerOwner = nil;
        library2.ActivePointerInput = nil;

        if toggled and not mobileMode then
            inputService2.MouseIconEnabled = cursorMouseState;
        end;
        toggled = false;
        modalElement.Modal = false;

        for _, cursorObject in next, { cursor2, cursorOutline } do
            local index2 = library2.CursorDrawings and table.find(library2.CursorDrawings, cursorObject);
            if index2 then table.remove(library2.CursorDrawings, index2); end;
            pcall(function()
                cursorObject.Visible = false;
                cursorObject:Remove();
            end);
        end;
        cursor2 = nil;
        cursorOutline = nil;

        if mobileViewportConnection then
            mobileViewportConnection:Disconnect();
            mobileViewportConnection = nil;
        end;

        local doomed = { outer, modalElement, mobileToggleOuter };
        for _, child2 in next, screenGui2:GetChildren() do
            if not window.Baseline[child2] and not table.find(doomed, child2) then
                table.insert(doomed, child2);
            end;
        end;

        local stale = {};
        for _, root2 in next, doomed do
            stale[root2] = true;
            for _, descendant2 in next, root2:GetDescendants() do
                stale[descendant2] = true;
            end;
        end;
        library2:PurgeRegistry(stale);

        for _, root2 in next, doomed do
            pcall(function() root2:Destroy(); end);
        end;
    end;

    window.Holder = outer;
    window.MobileMode = mobileMode;
    window.DeviceClass = library2.DeviceClass;
    window.MobileToggle = mobileToggleOuter;

    return window;
end;

local function onPlayerChange()
    local playerList = getPlayersString();

    for _, value2 in next, options2 do
        if value2.Type == 'Dropdown' and value2.SpecialType == 'Player' then
            value2:SetValues(playerList);
        end;
    end;
end;

players2.PlayerAdded:Connect(onPlayerChange);
players2.PlayerRemoving:Connect(onPlayerChange);

getgenv().Library = library2
return library2
end)()

local themeManager = (function()
local httpService = game:GetService('HttpService')
local themeManager = {} do
	themeManager.Folder = 'LinoriaLibSettings'

	themeManager.Library = nil
	themeManager.BuiltInThemes = {
		['Default'] 		= { 1, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"1c1c1c","AccentColor":"0055ff","BackgroundColor":"141414","OutlineColor":"323232"}') },
		['Black Cherry'] 	= { 2, httpService:JSONDecode('{"FontColor":"fff0f4","MainColor":"1a1015","AccentColor":"ff3b6b","BackgroundColor":"090609","OutlineColor":"48212f"}') },
		['BADBAD'] 			= { 3, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"1c1c1c","AccentColor":"badbad","BackgroundColor":"141414","OutlineColor":"323232"}') },
	}

	function themeManager:ApplyTheme(theme)
		local customThemeData = self:GetCustomTheme(theme)
		local data = customThemeData or self.BuiltInThemes[theme]

		if not data then return end

		local scheme = data[2]
		for idx, col in next, customThemeData or scheme do
			self.Library[idx] = Color3.fromHex(col)

			if Options[idx] then
				Options[idx]:SetValueRGB(Color3.fromHex(col))
			end
		end

		self:ThemeUpdate()
	end

	function themeManager:ThemeUpdate()

		local options = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }
		for i, field in next, options do
			if Options and Options[field] then
				self.Library[field] = Options[field].Value
			end
		end

		self.Library.AccentColorDark = self.Library:GetDarkerColor(self.Library.AccentColor);
		self.Library:UpdateColorsUsingRegistry()
	end

	function themeManager:LoadDefault()
		local theme = 'Default'
		local content = isfile(self.Folder .. '/Themes/default.txt') and readfile(self.Folder .. '/Themes/default.txt')

		local isDefault = true
		if content then
			if self.BuiltInThemes[content] then
				theme = content
			elseif self:GetCustomTheme(content) then
				theme = content
				isDefault = false;
			end
		elseif self.BuiltInThemes[self.DefaultTheme] then
		 	theme = self.DefaultTheme
		end

		if isDefault then
			Options.ThemeManager_ThemeList:SetValue(theme)
		else
			self:ApplyTheme(theme)
		end
	end

	function themeManager:SaveDefault(theme)
		writefile(self.Folder .. '/Themes/default.txt', theme)
	end

	function themeManager:CreateThemeManager(groupbox)
		groupbox:AddLabel('Background color'):AddColorPicker('BackgroundColor', { Default = self.Library.BackgroundColor });
		groupbox:AddLabel('Main color')	:AddColorPicker('MainColor', { Default = self.Library.MainColor });
		groupbox:AddLabel('Accent color'):AddColorPicker('AccentColor', { Default = self.Library.AccentColor });
		groupbox:AddLabel('Outline color'):AddColorPicker('OutlineColor', { Default = self.Library.OutlineColor });
		groupbox:AddLabel('Font color')	:AddColorPicker('FontColor', { Default = self.Library.FontColor });

		local themesArray = {}
		for name2, theme2 in next, self.BuiltInThemes do
			table.insert(themesArray, name2)
		end

		table.sort(themesArray, function(a, b) return self.BuiltInThemes[a][1] < self.BuiltInThemes[b][1] end)

		groupbox:AddDivider()
		groupbox:AddDropdown('ThemeManager_ThemeList', { Text = 'Theme list', Values = themesArray, Default = 1 })

		groupbox:AddButton('Set as default', function()
			self:SaveDefault(Options.ThemeManager_ThemeList.Value)
			self.Library:Notify(self.Library:TranslateFormat('Set default theme to %q', Options.ThemeManager_ThemeList.Value))
		end)

		Options.ThemeManager_ThemeList:OnChanged(function()
			self:ApplyTheme(Options.ThemeManager_ThemeList.Value)
		end)

		groupbox:AddDivider()
		groupbox:AddInput('ThemeManager_CustomThemeName', { Text = 'Custom theme name' })
		groupbox:AddDropdown('ThemeManager_CustomThemeList', { Text = 'Custom themes', Values = self:ReloadCustomThemes(), AllowNull = true, Default = 1, Translate = false })
		groupbox:AddDivider()

		groupbox:AddButton('Save theme', function()
			self:SaveCustomTheme(Options.ThemeManager_CustomThemeName.Value)

			Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
			Options.ThemeManager_CustomThemeList:SetValue(nil)
		end):AddButton('Load theme', function()
			self:ApplyTheme(Options.ThemeManager_CustomThemeList.Value)
		end)

		groupbox:AddButton('Refresh list', function()
			Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
			Options.ThemeManager_CustomThemeList:SetValue(nil)
		end)

		groupbox:AddButton('Set as default', function()
			if Options.ThemeManager_CustomThemeList.Value ~= nil and Options.ThemeManager_CustomThemeList.Value ~= '' then
				self:SaveDefault(Options.ThemeManager_CustomThemeList.Value)
				self.Library:Notify(self.Library:TranslateFormat('Set default theme to %q', Options.ThemeManager_CustomThemeList.Value))
			end
		end)

		themeManager:LoadDefault()

		local function updateTheme()
			self:ThemeUpdate()
		end

		Options.BackgroundColor:OnChanged(updateTheme)
		Options.MainColor:OnChanged(updateTheme)
		Options.AccentColor:OnChanged(updateTheme)
		Options.OutlineColor:OnChanged(updateTheme)
		Options.FontColor:OnChanged(updateTheme)
	end

	function themeManager:GetCustomTheme(file)
		local path = self.Folder .. '/Themes/' .. file
		if not isfile(path) then
			return nil
		end

		local data = readfile(path)
		local success, decoded = pcall(httpService.JSONDecode, httpService, data)

		if not success then
			return nil
		end

		return decoded
	end

	function themeManager:SaveCustomTheme(file)
		if file:gsub(' ', '') == '' then
			return self.Library:Notify(self.Library:Translate('Invalid file name for theme (empty)'), 3)
		end

		local theme = {}
		local fields = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }

		for _, field in next, fields do
			theme[field] = Options[field].Value:ToHex()
		end

		writefile(self.Folder .. '/Themes/' .. file .. '.json', httpService:JSONEncode(theme))
	end

	function themeManager:ReloadCustomThemes()
		local list = listfiles(self.Folder .. '/Themes')

		local out = {}
		for i = 1, #list do
			local file = list[i]
			if file:sub(-5) == '.json' then
				local pos = file:find('.json', 1, true)
				local char = file:sub(pos, pos)

				while char ~= '/' and char ~= '\\' and char ~= '' do
					pos = pos - 1
					char = file:sub(pos, pos)
				end

				if char == '/' or char == '\\' then
					table.insert(out, file:sub(pos + 1))
				end
			end
		end

		return out
	end

	function themeManager:SetLibrary(lib)
		self.Library = lib
	end

	function themeManager:BuildFolderTree()
		local paths = {}


		local parts = self.Folder:split('/')
		for idx = 1, #parts do
			paths[#paths + 1] = table.concat(parts, '/', 1, idx)
		end

		table.insert(paths, self.Folder .. '/Themes')
		table.insert(paths, self.Folder .. '/Configs')

		for i = 1, #paths do
			local str = paths[i]
			if not isfolder(str) then
				makefolder(str)
			end
		end
	end

	function themeManager:SetFolder(folder)
		self.Folder = folder
		self:BuildFolderTree()
	end

	function themeManager:CreateGroupBox(tab)
		assert(self.Library, 'Must set ThemeManager.Library first!')
		return tab:AddLeftGroupbox('Themes')
	end

	function themeManager:ApplyToTab(tab)
		assert(self.Library, 'Must set ThemeManager.Library first!')
		local groupbox = self:CreateGroupBox(tab)
		self:CreateThemeManager(groupbox)
	end

	function themeManager:ApplyToGroupbox(groupbox)
		assert(self.Library, 'Must set ThemeManager.Library first!')
		self:CreateThemeManager(groupbox)
	end

	themeManager:BuildFolderTree()
end

return themeManager
end)()

local saveManager = (function()
local httpService = game:GetService('HttpService')

local saveManager = {} do
	saveManager.Folder = 'LinoriaLibSettings'
	saveManager.Ignore = {}
	saveManager.Parser = {
		Toggle = {
			Save = function(idx, object)
				return { type = 'Toggle', idx = idx, value = object.Value }
			end,
			Load = function(idx, data)
				if Toggles[idx] then
					Toggles[idx]:SetValue(data.value)
				end
			end,
		},
		Slider = {
			Save = function(idx, object)
				return { type = 'Slider', idx = idx, value = object.Value }
			end,
			Load = function(idx, data)
				if Options[idx] then

					Options[idx]:SetValue(data.value)
				end
			end,
		},
		Dropdown = {
			Save = function(idx, object)
				return { type = 'Dropdown', idx = idx, value = object.Value, multi = object.Multi }
			end,
			Load = function(idx, data)
				if Options[idx] then
					Options[idx]:SetValue(data.value)
				end
			end,
		},
		ColorPicker = {
			Save = function(idx, object)
				local state = object.GetAnimationState and object:GetAnimationState() or nil
				local primaryColor = state and state.Color1 or object.Value
				local primaryTransparency = state and state.Transparency1 or object.Transparency

				local result = {
					type = 'ColorPicker',
					idx = idx,
					value = primaryColor:ToHex(),
					transparency = primaryTransparency
				}

				if state then
					result.animation = {
						mode = state.Mode,
						speed = state.Speed,
						color1 = state.Color1:ToHex(),
						transparency1 = state.Transparency1,
						color2 = state.Color2:ToHex(),
						transparency2 = state.Transparency2
					}
				end

				return result
			end,
			Load = function(idx, data)
				if Options[idx] then
					local option = Options[idx]
					local animation = type(data.animation) == 'table' and data.animation or nil

					if animation and option.SetAnimationState then
						option:SetAnimationState({
							Mode = animation.mode,
							Speed = animation.speed,
							Color1 = Color3.fromHex(animation.color1 or data.value),
							Transparency1 = animation.transparency1 ~= nil and animation.transparency1 or data.transparency,
							Color2 = Color3.fromHex(animation.color2 or animation.color1 or data.value),
							Transparency2 = animation.transparency2 ~= nil and animation.transparency2 or data.transparency
						})
					elseif option.SetAnimationState then
						option:SetAnimationState({
							Mode = 'Static',
							Color1 = Color3.fromHex(data.value),
							Transparency1 = data.transparency,
							Color2 = Color3.fromHex(data.value),
							Transparency2 = data.transparency
						})
					else
						option:SetValueRGB(Color3.fromHex(data.value), data.transparency)
					end
				end
			end,
		},
		KeyPicker = {
			Save = function(idx, object)
				return { type = 'KeyPicker', idx = idx, mode = object.Mode, key = object.Value }
			end,
			Load = function(idx, data)
				if Options[idx] then
					Options[idx]:SetValue({ data.key, data.mode })
				end
			end,
		},

		Input = {
			Save = function(idx, object)
				return { type = 'Input', idx = idx, text = object.Value }
			end,
			Load = function(idx, data)
				if Options[idx] and type(data.text) == 'string' then
					Options[idx]:SetValue(data.text)
				end
			end,
		},
	}

	function saveManager:SetIgnoreIndexes(list)
		for _, key in next, list do
			self.Ignore[key] = true
		end
	end

	function saveManager:SetFolder(folder)
		self.Folder = folder;
		self:BuildFolderTree()
	end

	function saveManager:Save(name)
		if (not name) then
			return false, 'no config file is selected'
		end

		if self.Loading then
			return false, 'wait for the config to finish loading'
		end

		local fullPath = self.Folder .. '/Configs/' .. name .. '.json'

		local objects = {}

		for idx, toggle in next, Toggles do
			if self.Ignore[idx] then continue end
			if not self.Parser[toggle.Type] then continue end

			table.insert(objects, self.Parser[toggle.Type].Save(idx, toggle))
		end

		for idx, option in next, Options do
			if not self.Parser[option.Type] then continue end
			if self.Ignore[idx] then continue end

			table.insert(objects, self.Parser[option.Type].Save(idx, option))
		end

		local data = {}
		if isfile(fullPath) then
			local existingReadSuccess, existingRaw = pcall(readfile, fullPath)
			if existingReadSuccess then
				local existingDecodeSuccess, existingData = pcall(httpService.JSONDecode, httpService, existingRaw)
				if existingDecodeSuccess and type(existingData) == 'table' then
					data = existingData
				end
			end
		end

		if type(data.objects) == 'table' then
			local currentObjectIds = {}
			for _, object in ipairs(objects) do
				currentObjectIds[tostring(object.idx)] = true
			end

			for _, existingObject in ipairs(data.objects) do
				if type(existingObject) == 'table' and existingObject.idx ~= nil then
					local existingIdx = tostring(existingObject.idx)
					if not currentObjectIds[existingIdx] and not self.Ignore[existingIdx] then
						table.insert(objects, existingObject)
						currentObjectIds[existingIdx] = true
					end
				end
			end
		end

		table.sort(objects, function(a, b)
			local aIdx = tostring(a.idx or '')
			local bIdx = tostring(b.idx or '')

			if aIdx == bIdx then
				return tostring(a.type or '') < tostring(b.type or '')
			end

			return aIdx < bIdx
		end)

		data.version = math.max(tonumber(data.version) or 0, 2)
		data.objects = objects

		if self.Library and self.Library.IsMobile then
			local uiLayouts = type(data.uiLayouts) == 'table' and data.uiLayouts or {}
			local mobileLayouts = type(uiLayouts.mobile) == 'table' and uiLayouts.mobile or {}

			local legacyLayout = type(data.mobileBindLayout) == 'table' and data.mobileBindLayout
				or (type(data.mobile_bind_layout) == 'table' and data.mobile_bind_layout or nil)
			if legacyLayout and type(legacyLayout.width) == 'number' and type(legacyLayout.height) == 'number' then
				local legacyKey = string.format('%dx%d', legacyLayout.width, legacyLayout.height)
				if mobileLayouts[legacyKey] == nil then
					mobileLayouts[legacyKey] = legacyLayout
				end
			end

			local resolution, layout = self.Library:CaptureMobileBindLayout()
			if resolution and layout then
				mobileLayouts[resolution] = layout
			end

			uiLayouts.mobile = mobileLayouts
			data.uiLayouts = uiLayouts
			self.Library.LoadedMobileBindLayouts = mobileLayouts
		end

		local success, encoded = pcall(httpService.JSONEncode, httpService, data)
		if not success then
			return false, 'failed to encode data'
		end

		local writeSuccess, writeError = pcall(writefile, fullPath, encoded)
		if not writeSuccess then
			return false, 'failed to write config: ' .. tostring(writeError)
		end

		self.CurrentConfig = name
		return true
	end

	function saveManager:Load(name)
		if (not name) then
			return false, 'no config file is selected'
		end

		if self.Loading then
			return false, 'another config is still loading'
		end

		local file = self.Folder .. '/Configs/' .. name .. '.json'
		if not isfile(file) then return false, 'invalid file' end

		local readSuccess, raw = pcall(readfile, file)
		if not readSuccess then
			return false, 'read error'
		end

		local success, decoded = pcall(httpService.JSONDecode, httpService, raw)
		if not success then return false, 'decode error' end

		if type(decoded) ~= 'table' or type(decoded.objects) ~= 'table' then
			return false, 'invalid config structure'
		end

		local optionObjects = {}
		local toggleObjects = {}

		for _, object in ipairs(decoded.objects) do
			if type(object) == 'table'
				and type(object.idx) == 'string'
				and type(object.type) == 'string'
				and self.Parser[object.type] then

				if object.type == 'Toggle' then
					table.insert(toggleObjects, object)
				else
					table.insert(optionObjects, object)
				end
			end
		end

		local function stableSort(list)
			table.sort(list, function(a, b)
				local aIdx = tostring(a.idx or '')
				local bIdx = tostring(b.idx or '')

				if aIdx == bIdx then
					return tostring(a.type or '') < tostring(b.type or '')
				end

				return aIdx < bIdx
			end)
		end

		stableSort(optionObjects)
		stableSort(toggleObjects)

		local errors = {}
		local library = self.Library
		local budget = math.max(0.001, tonumber(self.LoadFrameBudget) or 0.004)
		local sliceStart = os.clock()
		local loadStart = sliceStart

		-- // раздаем порциями 
		local function applyObjects(list)
			for _, object in ipairs(list) do
				local parser = self.Parser[object.type]

				if parser and parser.Load then
					local ok, err = pcall(parser.Load, object.idx, object)
					if not ok then
						table.insert(errors, tostring(object.idx) .. ': ' .. tostring(err))
					end
				end

				if os.clock() - sliceStart >= budget then
					task.wait()
					sliceStart = os.clock()
				end
			end
		end

		self.Loading = true
		if library then
			library.DeferDependencyUpdates = true
			library.DependencyUpdatePending = false
		end

		local applied, applyError = pcall(function()
			applyObjects(optionObjects)
			applyObjects(toggleObjects)
		end)

		if library then
			library.DeferDependencyUpdates = false
			if library.DependencyUpdatePending then
				library.DependencyUpdatePending = false
				pcall(library.UpdateDependencyBoxes, library)
			end
		end
		self.Loading = false
		self.LastLoadTime = os.clock() - loadStart

		if not applied then
			table.insert(errors, 'loader: ' .. tostring(applyError))
		end

		if self.Library and self.Library.IsMobile then
			local mobileLayouts = type(decoded.uiLayouts) == 'table'
				and type(decoded.uiLayouts.mobile) == 'table'
				and decoded.uiLayouts.mobile or nil

			if not mobileLayouts then
				local legacyLayout = type(decoded.mobileBindLayout) == 'table' and decoded.mobileBindLayout
					or (type(decoded.mobile_bind_layout) == 'table' and decoded.mobile_bind_layout or nil)
				if legacyLayout and type(legacyLayout.width) == 'number' and type(legacyLayout.height) == 'number' then
					local legacyKey = string.format('%dx%d', legacyLayout.width, legacyLayout.height)
					mobileLayouts = { [legacyKey] = legacyLayout }
				end
			end

			self.Library:SetMobileBindLayouts(mobileLayouts)
		end

		if #errors > 0 then
			if library then library:Notify(library:TranslateFormat('config loaded with %d warnings', #errors), 5) end
			return false, string.format('config partially loaded (%d errors)', #errors)
		end

		self.CurrentConfig = name
		return true
	end

	function saveManager:IgnoreThemeSettings()
		self:SetIgnoreIndexes({
			"BackgroundColor", "MainColor", "AccentColor", "OutlineColor", "FontColor",
			"ThemeManager_ThemeList", 'ThemeManager_CustomThemeList', 'ThemeManager_CustomThemeName',
		})
	end

	function saveManager:BuildFolderTree()
		local paths = {
			self.Folder,
			self.Folder .. '/Themes',
			self.Folder .. '/Configs'
		}

		for i = 1, #paths do
			local str = paths[i]
			if not isfolder(str) then
				makefolder(str)
			end
		end
	end

	function saveManager:RefreshConfigList()
		local list = listfiles(self.Folder .. '/Configs')

		local out = {}
		for i = 1, #list do
			local file = list[i]
			if file:sub(-5) == '.json' then
				local pos = file:find('.json', 1, true)
				local start = pos

				local char = file:sub(pos, pos)
				while char ~= '/' and char ~= '\\' and char ~= '' do
					pos = pos - 1
					char = file:sub(pos, pos)
				end

				if char == '/' or char == '\\' then
					table.insert(out, file:sub(pos + 1, start - 1))
				end
			end
		end

		return out
	end

	function saveManager:SetLibrary(library)
		self.Library = library
		library.MobileLayoutSaveManager = self
	end

	function saveManager:LoadAutoloadConfig()
		if isfile(self.Folder .. '/Configs/autoload.txt') then
			local name = readfile(self.Folder .. '/Configs/autoload.txt')

			local success, err = self:Load(name)
			if not success then
				return self.Library:Notify(self.Library:TranslateFormat('Failed to load autoload config: %s', err))
			end

			self.Library:Notify(self.Library:TranslateFormat('Auto loaded config %q in %.1fs', name, self.LastLoadTime or 0))
		end
	end


	function saveManager:BuildConfigSection(tab)
		assert(self.Library, 'Must set SaveManager.Library')

		local section = tab:AddColumnGroupbox(3, 'Configuration')

		section:AddInput('SaveManager_ConfigName',    { Text = 'Config name' })
		section:AddDropdown('SaveManager_ConfigList', { Text = 'Config list', Values = self:RefreshConfigList(), AllowNull = true, Translate = false })

		section:AddDivider()

		section:AddButton('Create config', function()
			local name = Options.SaveManager_ConfigName.Value

			if name:gsub(' ', '') == '' then
				return self.Library:Notify(self.Library:Translate('Invalid config name (empty)'), 2)
			end

			local success, err = self:Save(name)
			if not success then
				return self.Library:Notify(self.Library:TranslateFormat('Failed to save config: %s', err))
			end

			self.Library:Notify(self.Library:TranslateFormat('Created config %q', name))

			Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
			Options.SaveManager_ConfigList:SetValue(nil)
		end):AddButton('Load config', function()
			local name = Options.SaveManager_ConfigList.Value
			if type(name) == 'string' and not self.Loading then
				self.Library:Notify(self.Library:TranslateFormat('Loading config %q...', name), 2)
			end

			local success, err = self:Load(name)
			if not success then
				return self.Library:Notify(self.Library:TranslateFormat('Failed to load config: %s', err))
			end

			self.Library:Notify(self.Library:TranslateFormat('Loaded config %q in %.1fs', name, self.LastLoadTime or 0))
		end)

		section:AddButton('Overwrite config', function()
			local name = Options.SaveManager_ConfigList.Value

			local success, err = self:Save(name)
			if not success then
				return self.Library:Notify(self.Library:TranslateFormat('Failed to overwrite config: %s', err))
			end

			self.Library:Notify(self.Library:TranslateFormat('Overwrote config %q', name))
		end)

		section:AddButton('Refresh list', function()
			Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
			Options.SaveManager_ConfigList:SetValue(nil)
		end)

		section:AddButton('Set as autoload', function()
			local name = Options.SaveManager_ConfigList.Value
			if type(name) ~= 'string' or name:gsub('%s+', '') == '' then
				return self.Library:Notify(self.Library:Translate('Select a config first'), 2)
			end

			local success, err = pcall(writefile, self.Folder .. '/Configs/autoload.txt', name)
			if not success then
				return self.Library:Notify(self.Library:TranslateFormat('Failed to set autoload: %s', tostring(err)), 3)
			end

			saveManager.AutoloadLabel:SetText(self.Library:TranslateFormat('Current autoload config: %s', name))
			self.Library:Notify(self.Library:TranslateFormat('Set %q to auto load', name))
		end):AddButton('Clear autoload', function()
			local path = self.Folder .. '/Configs/autoload.txt'

			if isfile(path) then
				if type(delfile) ~= 'function' then
					return self.Library:Notify(self.Library:Translate('Failed to clear autoload: file removal is unavailable'), 3)
				end

				local success, err = pcall(delfile, path)
				if not success then
					return self.Library:Notify(self.Library:TranslateFormat('Failed to clear autoload: %s', tostring(err)), 3)
				end
			end

			saveManager.AutoloadLabel:SetText(self.Library:Translate('Current autoload config: none'))
			self.Library:Notify(self.Library:Translate('Autoload config cleared'))
		end)

		saveManager.AutoloadLabel = section:AddLabel('Current autoload config: none', true)

		if isfile(self.Folder .. '/Configs/autoload.txt') then
			local name = readfile(self.Folder .. '/Configs/autoload.txt')
			saveManager.AutoloadLabel:SetText(self.Library:TranslateFormat('Current autoload config: %s', name))
		end

		saveManager:SetIgnoreIndexes({ 'SaveManager_ConfigList', 'SaveManager_ConfigName' })
	end

	saveManager:BuildFolderTree()
end

return saveManager
end)()
