    end

    local function fadeObject(object, onTweenCompleted)
        local tweenInformation = tweenService:Create(object, TweenInfo.new(0.3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
            TextTransparency = 1,
