local function createMobileFovCircle(name, filled, zIndex)
    if not library2.IsMobile or not library2.MobileFovGui then return nil end

    local frame = Instance.new("Frame")
    frame.Name = name
    frame.AnchorPoint = Vector2.new(0.5, 0.5)
    frame.BackgroundTransparency = filled and 0.15 or 1
    frame.BorderSizePixel = 0
    frame.Visible = false
    frame.ZIndex = zIndex or 10
    frame.Parent = library2.MobileFovGui

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(1, 0)
    corner.Parent = frame

    local stroke
    if not filled then
        stroke = Instance.new("UIStroke")
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Thickness = 1
        stroke.Parent = frame
    end

    return {
        Frame = frame,
        Stroke = stroke,
        Filled = filled,
    }
end

local function updateMobileFovCircle(circle, center, radius, color, visible, backgroundTransparency)
    if not circle or not circle.Frame then return end

    local frame = circle.Frame
    frame.Visible = visible == true
    if not frame.Visible then return end

    local diameter = math.max(2, (tonumber(radius) or 1) * 2)
    frame.Position = UDim2.fromOffset(math.floor(center.X + 0.5), math.floor(center.Y + 0.5))
    frame.Size = UDim2.fromOffset(diameter, diameter)

    if circle.Filled then
        frame.BackgroundColor3 = color
        frame.BackgroundTransparency = math.clamp(backgroundTransparency or 0.15, 0, 1)
    elseif circle.Stroke then
        circle.Stroke.Color = color
    end
end

local function removeFovCircle(circle)
    if not circle then return end

    if type(circle) == "table" and circle.Frame then
        circle.Frame:Destroy()
    else
        pcall(function()
            circle:Remove()
        end)
    end
end

local function drainGetFovGui()
    if library2.MobileFovGui then return library2.MobileFovGui end

    local gui = Instance.new("ScreenGui")
    gui.Name = "DrainFovFallback"
    gui.IgnoreGuiInset = true
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 999
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Global

    local parented = false
    local player = game:GetService("Players").LocalPlayer
    if player then
        local playerGui = player:FindFirstChildOfClass("PlayerGui")
        if playerGui then
            parented = pcall(function() gui.Parent = playerGui end)
        end
    end
    if not parented then
        parented = pcall(function() gui.Parent = game:GetService("CoreGui") end)
    end
    if not parented then
        gui:Destroy()
        return nil
    end

    library2.MobileFovGui = gui
    return gui
end

library2.ForceGuiFov = library2.ForceGuiFov or false

local function createFovCircle(name, filled, zIndex, transparency)
    if not library2.IsMobile and not library2.ForceGuiFov then
        local ok, circle = pcall(function()
            local c = Drawing.new("Circle")
            c.Visible = false
            c.Filled = filled and true or false
            c.Thickness = 1
            c.NumSides = 64
            c.Radius = 0
            if filled and transparency ~= nil then
                c.Transparency = transparency
            end
            return c
        end)
        if ok and circle then
            return circle
        end
    end

    local frame = Instance.new("Frame")
    frame.Name = tostring(name)
    frame.AnchorPoint = Vector2.new(0.5, 0.5)
    frame.BackgroundColor3 = Color3.new(1, 1, 1)
    frame.BackgroundTransparency = filled and (transparency or 0.15) or 1
    frame.BorderSizePixel = 0
    frame.Size = UDim2.fromOffset(2, 2)
    frame.Visible = false
    frame.ZIndex = zIndex or 10

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(1, 0)
    corner.Parent = frame

    local stroke
    if not filled then
        stroke = Instance.new("UIStroke")
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Thickness = 1
        stroke.Parent = frame
    end

    local gui = drainGetFovGui()
    if gui then
        frame.Parent = gui
    end

    return setmetatable({
        Frame = frame,
        Filled = filled and true or false,
        Visible = false,
        Position = Vector2.zero,
        Radius = 0,
        Color = Color3.new(1, 1, 1),
        Transparency = transparency or 1,
    }, {
        __newindex = function(self, key, value)
            rawset(self, key, value)
            if key == "Visible" then
                frame.Visible = value == true
            elseif key == "Position" then
                frame.Position = UDim2.fromOffset(math.floor(value.X + 0.5), math.floor(value.Y + 0.5))
            elseif key == "Radius" then
                local diameter = math.max(2, (tonumber(value) or 1) * 2)
                frame.Size = UDim2.fromOffset(diameter, diameter)
            elseif key == "Color" then
                if self.Filled then
                    frame.BackgroundColor3 = value
                elseif stroke then
                    stroke.Color = value
                end
            elseif key == "Transparency" and self.Filled then
                frame.BackgroundTransparency = math.clamp(tonumber(value) or 1, 0, 1)
            end
        end,
    })
end

