local function addActiveTracer(data)
    bb.NextId = bb.NextId + 1
    bb.Active[bb.NextId] = data
    return bb.NextId
end

local function findMzl(gun)
    if not gun or gun.Parent == nil then return nil end
    local names = {"Muzzle", "Flash", "FirePoint", "Handle", "WeaponHandle"}
    for _, n in pairs(names) do
        local p = gun:FindFirstChild(n)
        if p and p:IsA("BasePart") then return p end
    end
    return gun:FindFirstChildWhichIsA("BasePart") or gun
end

local function disconnectGameTrailSource()
    if bb.TrailFolderChildConnection then
        bb.TrailFolderChildConnection:Disconnect()
        bb.TrailFolderChildConnection = nil
    end
    if bb.TrailFolderDescendantConnection then
        bb.TrailFolderDescendantConnection:Disconnect()
        bb.TrailFolderDescendantConnection = nil
    end
    if bb.TrailCameraChildConnection then
        bb.TrailCameraChildConnection:Disconnect()
        bb.TrailCameraChildConnection = nil
    end
    bb.TrailFolder = nil
    bb.TrailCamera = nil
end

local function restoreGameTrail(trail)
    local original = bb.TrailRecords[trail]
    if not original then return end

    if trail and trail.Parent then
        for property, value in pairs(original) do
            pcall(function() trail[property] = value end)
        end
    end
    bb.TrailRecords[trail] = nil
end

local function restoreAllGameTrails()
    local trails = {}
    for trail in pairs(bb.TrailRecords) do
        trails[#trails + 1] = trail
    end
    for _, trail in ipairs(trails) do
        restoreGameTrail(trail)
    end
end

local function styleGameTrail(trail)
    if not bb.On or bb.Type ~= "Trail" or not trail or not trail:IsA("Trail") or not trail.Parent then
        return
    end

    if not bb.TrailRecords[trail] then
        bb.TrailRecords[trail] = {
            Enabled = trail.Enabled,
            Color = trail.Color,
            Transparency = trail.Transparency,
            Lifetime = trail.Lifetime,
            MinLength = trail.MinLength,
            MaxLength = trail.MaxLength,
            Texture = trail.Texture,
            TextureLength = trail.TextureLength,
            TextureMode = trail.TextureMode,
            WidthScale = trail.WidthScale,
            FaceCamera = trail.FaceCamera,
            LightEmission = trail.LightEmission,
            LightInfluence = trail.LightInfluence,
        }
    end

    local textureData = tTexs[bb.CurTex] or tTexs.DNA
    local baseTransparency = math.clamp(tonumber(bb.Trans) or 0, 0, 1)
    trail.Enabled = true
    trail.Color = ColorSequence.new(bb.Col)
    trail.Lifetime = math.max(tonumber(bb.Life) or 2, 0.05)
    trail.MinLength = 0
    trail.MaxLength = 0
    trail.Texture = bb.CurTex == "Custom" and bb.CustomTex or textureData.Tex
    trail.TextureLength = textureData.Len or 5
    trail.TextureMode = Enum.TextureMode[textureData.Mode] or Enum.TextureMode.Wrap
    local widthMultiplier = math.max(tonumber(bb.Thick) or 0.1, 0.01) / 0.1
    local widthKeypoints = {}
    for _, keypoint in ipairs(bb.TrailRecords[trail].WidthScale.Keypoints) do
        widthKeypoints[#widthKeypoints + 1] = NumberSequenceKeypoint.new(
            keypoint.Time,
            math.clamp(keypoint.Value * widthMultiplier, 0, 1),
            0
        )
    end
    trail.WidthScale = NumberSequence.new(widthKeypoints)
    trail.FaceCamera = true
    trail.LightEmission = 1
    trail.LightInfluence = 0

    if bb.SmoothFade then
        local fadeStart = math.clamp(
            1 - (math.max(tonumber(bb.FadeSpeed) or 1, 0.01) / trail.Lifetime),
            0.01,
            0.99
        )
        trail.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, baseTransparency),
            NumberSequenceKeypoint.new(fadeStart, baseTransparency),
            NumberSequenceKeypoint.new(1, 1),
        })
    else
        trail.Transparency = NumberSequence.new(baseTransparency)
    end
end

local function scanGameTrailRoot(root)
    if not root then return end
    if root:IsA("Trail") then
        styleGameTrail(root)
    end
    for _, object in ipairs(root:GetDescendants()) do
        if object:IsA("Trail") then
            styleGameTrail(object)
        end
    end
end

local function bindGameTrailFolder(folder)
    if bb.TrailFolder and bb.TrailFolder ~= folder then
        restoreAllGameTrails()
    end
    if bb.TrailFolderChildConnection then
        bb.TrailFolderChildConnection:Disconnect()
        bb.TrailFolderChildConnection = nil
    end
    if bb.TrailFolderDescendantConnection then
        bb.TrailFolderDescendantConnection:Disconnect()
        bb.TrailFolderDescendantConnection = nil
    end

    bb.TrailFolder = folder
    if not folder then return end

    scanGameTrailRoot(folder)
    bb.TrailFolderChildConnection = folder.ChildAdded:Connect(function(child)
        scanGameTrailRoot(child)
        task.defer(function()
            if bb.On and child.Parent then
                scanGameTrailRoot(child)
            end
        end)
    end)
    bb.TrailFolderDescendantConnection = folder.DescendantAdded:Connect(function(object)
        if object:IsA("Trail") then
            styleGameTrail(object)
            task.defer(function()
                if bb.On and object.Parent then
                    styleGameTrail(object)
                end
            end)
        end
    end)
end

local function bindGameTrailCamera(camera)
    if bb.TrailCamera and bb.TrailCamera ~= camera then
        restoreAllGameTrails()
    end
    if bb.TrailCameraChildConnection then
        bb.TrailCameraChildConnection:Disconnect()
        bb.TrailCameraChildConnection = nil
    end

    bb.TrailCamera = camera
    if not camera then
        bindGameTrailFolder(nil)
        return
    end

    cam2 = camera
    bindGameTrailFolder(camera:FindFirstChild("Bullets"))
    bb.TrailCameraChildConnection = camera.ChildAdded:Connect(function(child)
        if child.Name == "Bullets" then
            bindGameTrailFolder(child)
        end
    end)
end

local function refreshGameTrails()
    if bb.Type ~= "Trail" then
        restoreAllGameTrails()
        return
    end

    local camera = workspace.CurrentCamera
    if camera ~= bb.TrailCamera then
        bindGameTrailCamera(camera)
    elseif bb.TrailFolder and bb.TrailFolder.Parent then
        scanGameTrailRoot(bb.TrailFolder)
    elseif camera then
        bindGameTrailFolder(camera:FindFirstChild("Bullets"))
    end
end

local function updateGameTrails()
    if bb.Type ~= "Trail" then
        if next(bb.TrailRecords) then
            restoreAllGameTrails()
        end
        return
    end

    for trail in pairs(bb.TrailRecords) do
        if not trail or not trail.Parent then
            bb.TrailRecords[trail] = nil
        end
    end
end

local function crBeam(sPos, ePos, col)
    if not bb.On or not sPos or not ePos then return nil end
    local bm, a0, a1
    local suc, err = pcall(function()
        bm = Instance.new("Beam")
        a0 = Instance.new("Attachment")
        a1 = Instance.new("Attachment")
        local par = workspace:FindFirstChild("Terrain") or workspace
        a0.Position = sPos; a0.Parent = par
        a1.Position = ePos; a1.Parent = par
        bm.Attachment0 = a0; bm.Attachment1 = a1
        bm.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, col), ColorSequenceKeypoint.new(1, col)})
        local tData = tTexs[bb.CurTex] or tTexs["DNA"]
        bm.Width0 = tData.W0 or bb.Thick
        bm.Width1 = tData.W1 or (bb.Thick * 0.5)
        if bb.CurTex == "Custom" then bm.Texture = bb.CustomTex else bm.Texture = tData.Tex end
        bm.TextureLength = tData.Len; bm.TextureSpeed = tData.Spd
        bm.TextureMode = Enum.TextureMode[tData.Mode] or Enum.TextureMode.Wrap
        if tData.Segs then bm.Segments = tData.Segs end
        bm.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, bb.Trans * 0.5),
            NumberSequenceKeypoint.new(0.5, bb.Trans),
            NumberSequenceKeypoint.new(1, 1)
        })
        bm.FaceCamera = true; bm.LightEmission = 0.5; bm.LightInfluence = 0.1; bm.Parent = par
    end)
    if not suc then
        if bm then bm:Destroy() end
        if a0 then a0:Destroy() end
        if a1 then a1:Destroy() end
        return nil
    end
    return addActiveTracer({Beam = bm, Atts = {a0, a1}, Created = tick(), Type = "Beam"})
end

local function crAstralix(sPos, ePos, col)
    if not bb.On or not sPos or not ePos then return nil end
    local suc, err = pcall(function()
        local dir    = (ePos - sPos)
        local dist   = dir.Magnitude
        local mid    = sPos + dir * 0.5
        local cf     = CFrame.lookAt(mid, ePos) * CFrame.Angles(0, math.rad(90), 0)

        local par = Instance.new("Part")
        par.Name         = "RapidSting"
        par.Size         = Vector3.new(dist, 0.1, 0.1)
        par.CFrame       = cf
        par.Anchored     = true
        par.CanCollide   = false
        par.CanQuery     = false
        par.CanTouch     = false
        par.CastShadow   = false
        par.Massless     = true
        par.Transparency = 1
        par.Parent       = workspace

        local trFd = NumberSequence.new({NumberSequenceKeypoint.new(0,0), NumberSequenceKeypoint.new(1,1)})
        local szSeq = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1.5),
            NumberSequenceKeypoint.new(0.5, 1),
            NumberSequenceKeypoint.new(1, 0)
        })
        local sqSeq = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.5),
            NumberSequenceKeypoint.new(1, 0)
        })

        local function mkSlash(name, tex)
            local pe = Instance.new("ParticleEmitter")
            pe.Name              = name
            pe.Brightness        = 2
            pe.Color             = ColorSequence.new(col)
            pe.LightEmission     = 1; pe.LightInfluence = 0
            pe.Orientation       = Enum.ParticleOrientation.VelocityParallel
            pe.Size              = szSeq
            pe.Squash            = sqSeq
            pe.Texture           = tex
            pe.Transparency      = trFd
            pe.ZOffset           = 0
            pe.EmissionDirection = Enum.NormalId.Back
            pe.Enabled           = true
            pe.Lifetime          = NumberRange.new(0.3, 0.3)
            pe.Rate              = 10
            pe.Rotation          = NumberRange.new(90, 90)
            pe.RotSpeed          = NumberRange.new(0, 0)
            pe.Speed             = NumberRange.new(40, 40)
            pe.SpreadAngle       = Vector2.new(0, 0)
            pe.Shape             = Enum.ParticleEmitterShape.Box
            pe.ShapeInOut        = Enum.ParticleEmitterShapeInOut.Outward
            pe.ShapeStyle        = Enum.ParticleEmitterShapeStyle.Surface
            pe.Drag              = 2
            pe.LockedToPart      = false
            pe:SetAttribute("EmitCount", 1)
            pe.Parent            = par
            pe:Emit(math.ceil(dist / 2))
            pe.Enabled = false
            return pe
        end

        local sl1 = mkSlash("MainSlash1", "http://www.roblox.com/asset/?id=6820821916")
        local sl2 = mkSlash("MainSlash2", "http://www.roblox.com/asset/?id=12684715885")

        local weld = Instance.new("Motor6D")
        weld.Name         = "Weld"
        weld.C0           = CFrame.new(-dist * 0.5 - 0.023, 0, -6.5)
        weld.C1           = CFrame.new(0, 0, 0)
        weld.Part1        = par
        weld.MaxVelocity  = 0
        weld.Parent       = par

        addActiveTracer({Part = par, Atts = {sl1, sl2, weld}, Created = tick(), Type = "Astralix"})
    end)
end

local function updatePartTracerStyle(tracer, transparency)
    local part = tracer and tracer.Part
    if not part or not part.Parent then return end

    transparency = math.clamp(tonumber(transparency) or bb.Trans or 0, 0, 1)
    if bb.Mat == "BoxHandleAdornment" then
        if tracer.ForceFieldMesh then
            tracer.ForceFieldMesh:Destroy()
            tracer.ForceFieldMesh = nil
        end

        local adornment = tracer.Adornment
        if not adornment or not adornment.Parent then
            if adornment then adornment:Destroy() end
            adornment = Instance.new("BoxHandleAdornment")
            adornment.Name = "DrainBulletTracerAdornment"
            adornment.Adornee = part
            adornment.CFrame = CFrame.identity
            adornment.AlwaysOnTop = true
            adornment.ZIndex = 10
            adornment.Parent = part
            tracer.Adornment = adornment
        end

        adornment.Size = part.Size
        adornment.Color3 = bb.Col
        adornment.Transparency = transparency
        adornment.Visible = true
        part.Transparency = 1
    else
        if tracer.Adornment then
            tracer.Adornment:Destroy()
            tracer.Adornment = nil
        end
        part.Color = bb.Col
        part.Material = resolveVisualMaterial(bb.Mat, Enum.Material.ForceField)
        part.Transparency = transparency

        if bb.Mat == "ForceField" and bb.ForceFieldAnimation ~= "Off" then
            local mesh = tracer.ForceFieldMesh
            if not mesh or not mesh.Parent then
                mesh = Instance.new("SpecialMesh")
                mesh.Name = "DrainBulletTracerForceFieldMesh"
                mesh.MeshType = Enum.MeshType.Brick
                mesh.Scale = Vector3.new(1, 1, 1)
                mesh.Parent = part
                tracer.ForceFieldMesh = mesh
            end
            mesh.TextureId = forcefieldAnimationTexture(bb.ForceFieldAnimation)
        elseif tracer.ForceFieldMesh then
            tracer.ForceFieldMesh:Destroy()
            tracer.ForceFieldMesh = nil
        end
    end
end

local function crPart(sPos, ePos, col)
    local created
    local ok = pcall(function()
        local dist = (sPos - ePos).Magnitude
        local part = Instance.new("Part")
        part.Name = "DrainBulletTracer"
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.CastShadow = false
        part.Massless = true
        part.Color = col
        part.Transparency = 1
        local thickness = bb.Thick or 0.1
        part.Size = Vector3.new(thickness, thickness, dist)
        part.CFrame = CFrame.lookAt(sPos, ePos) * CFrame.new(0, 0, -dist / 2)
        part.Parent = workspace

        local tracer = {Part = part, Created = tick(), Type = "Part"}
        updatePartTracerStyle(tracer, bb.Trans)
        created = addActiveTracer(tracer)
    end)
    return ok and created or nil
end

local function crTracer(sPos, ePos, col)
    if not bb.On then return nil end
    if not sPos or not ePos then return nil end
    if bb.Type == "Trail" then
        return nil
    elseif bb.CurTex == "Astralix" then
        return crAstralix(sPos, ePos, col)
    elseif bb.Type == "Part" then
        return crPart(sPos, ePos, col)
    end
    return crBeam(sPos, ePos, col)
end

local function clrTracers()
    for id, t in pairs(bb.Active) do
        pcall(function()
            if t.Beam then t.Beam:Destroy()
            elseif t.Part then t.Part:Destroy() end
            if t.Atts then
                for _, a in ipairs(t.Atts) do
                    if a and a.Parent then a:Destroy() end
                end
            end
        end)
        bb.Active[id] = nil
    end
    bb.Active = {}
end

local function setupBb()
    local ev2 = repSt:FindFirstChild("Events2")
    if ev2 then
        local viz = ev2:FindFirstChild("Visualize")
        if viz then
            local c = viz.Event:Connect(function(_, sc, _, gun, _, sPos, bps)
                if not bb.On or not bps then return end
                local char = lp2.Character; if not char then return end
                local myTool = char:FindFirstChildOfClass("Tool"); if myTool ~= gun then return end
                local mzl = findMzl(gun); local mzlPos = mzl and mzl.Position or sPos
                for _, bDir in pairs(bps) do
                    local ray = Ray.new(mzlPos, bDir * 1000)
                    local hit, hitPos = workspace:FindPartOnRayWithIgnoreList(ray, {cam2, char, gun})
                    local ePos = hit and hitPos or mzlPos + (bDir * 500)
                    crTracer(mzlPos, ePos, bb.Col)
                end
            end)
            table.insert(bb.Conns, c)
        end
    end
    local ev = repSt:FindFirstChild("Events")
    if ev then
        local fire = ev:FindFirstChild("GNX_S")
        if fire then
            local c = fire.OnClientEvent:Connect(function(st, sc, gun, ft, sPos, dirs, silenced)
                if not bb.On or not dirs then return end
                local char = lp2.Character; if not char then return end
                local tool = char:FindFirstChildOfClass("Tool"); if tool ~= gun then return end
                local mzl = findMzl(gun); local mzlPos = mzl and mzl.Position or sPos
                for _, dir in pairs(dirs) do
                    local ray = Ray.new(mzlPos, dir * 1000)
                    local hit, hitPos = workspace:FindPartOnRayWithIgnoreList(ray, {cam2, char, gun})
                    local ePos = hit and hitPos or mzlPos + (dir * 500)
                    crTracer(mzlPos, ePos, bb.Col)
                end
            end)
            table.insert(bb.Conns, c)
        end
    end

    bindGameTrailCamera(workspace.CurrentCamera)
    table.insert(bb.Conns, workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        bindGameTrailCamera(workspace.CurrentCamera)
    end))
end

local function toggleBb(state)
    bb.On = state
    if bb.On then
        clrTracers()
        restoreAllGameTrails()
        disconnectGameTrailSource()
        for _, c in pairs(bb.Conns) do if c then c:Disconnect() end end
        bb.Conns = {}
        local suc, err = pcall(setupBb)

        local updateConnection = rs2.RenderStepped:Connect(function()
            updateGameTrails()
            for id, tracer in pairs(bb.Active) do
                local elapsed = tick() - tracer.Created
                local fadeSpeed = math.max(bb.FadeSpeed or 1, 0.01)
                local maxLife = bb.SmoothFade and (bb.Life + fadeSpeed) or bb.Life

                if elapsed > maxLife then
                    pcall(function()
                        if tracer.Beam then tracer.Beam:Destroy() end
                        if tracer.Part then tracer.Part:Destroy() end
                        if tracer.Atts then
                            for _, attachment in ipairs(tracer.Atts) do
                                if attachment and attachment.Parent then attachment:Destroy() end
                            end
                        end
                    end)
                    bb.Active[id] = nil
                    continue
                end

                local transparency = bb.Trans
                if bb.SmoothFade and elapsed > bb.Life then
                    local fadeAmount = math.clamp((elapsed - bb.Life) / fadeSpeed, 0, 1)
                    transparency = bb.Trans + fadeAmount * (1 - bb.Trans)
                end

                pcall(function()
                    if tracer.Type == "Beam" and tracer.Beam then
                        tracer.Beam.Color = ColorSequence.new({
                            ColorSequenceKeypoint.new(0, bb.Col),
                            ColorSequenceKeypoint.new(1, bb.Col)
                        })
                        tracer.Beam.Transparency = NumberSequence.new({
                            NumberSequenceKeypoint.new(0, transparency * 0.5),
                            NumberSequenceKeypoint.new(0.5, transparency),
                            NumberSequenceKeypoint.new(1, 1)
                        })
                    elseif tracer.Type == "Part" and tracer.Part then
                        updatePartTracerStyle(tracer, transparency)
                    elseif tracer.Type == "Astralix" and tracer.Atts then
                        for index = 1, 2 do
                            local emitter = tracer.Atts[index]
                            if emitter then
                                emitter.Color = ColorSequence.new(bb.Col)
                                emitter.Transparency = NumberSequence.new({
                                    NumberSequenceKeypoint.new(0, transparency),
                                    NumberSequenceKeypoint.new(1, 1)
                                })
                            end
                        end
                    end
                end)
            end
        end)
        table.insert(bb.Conns, updateConnection)

        local charC = lp2.CharacterAdded:Connect(function()
            if not bb.On then return end
            clrTracers()
            task.defer(refreshGameTrails)
        end)
        table.insert(bb.Conns, charC)
        local remC = lp2.CharacterRemoving:Connect(function() if bb.On then clrTracers() end end)
        table.insert(bb.Conns, remC)
    else
        clrTracers()
        restoreAllGameTrails()
        disconnectGameTrailSource()
        for _, c in pairs(bb.Conns) do if c then c:Disconnect() end end
        bb.Conns = {}
    end
end

local function cleanupBulletTracers()
    toggleBb(false)
    if environment.DrainBulletTracerCleanup == cleanupBulletTracers then
        environment.DrainBulletTracerCleanup = nil
    end
end

