drainBootLog("library built")

do
    local loaderRoot = "drain.solutions"
    local loaderFolders = { "Configs", "Themes", "Languages", "Cache", "Wallbang" }
    local buildVersion = "V2.7.8-D"
    local buildDate = "30.09.2026"
    local gameIcon = "" -- nil
    pcall(function()
        local info = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
        if info and info.IconImageAssetId and info.IconImageAssetId ~= 0 then
            gameIcon = "rbxassetid://" .. tostring(info.IconImageAssetId)
        end
    end)

    -- // фолбек
    if gameIcon == "" then
        pcall(function()
            local universe = game.GameId
            if universe and universe ~= 0 then
                gameIcon = "rbxthumb://type=GameIcon&id=" .. tostring(universe) .. "&w=150&h=150"
            end
        end)
    end

    local loaderStrings = {
        ["loader.info"] = "Info",
        ["loader.options"] = "Options",
        ["loader.language"] = "Language",
        ["loader.welcome"] = "Welcome",
        ["loader.game"] = "Criminality",
        ["loader.version"] = "Ver",
        ["loader.updated"] = "Updated",
        ["loader.expires"] = "Expires",
        ["loader.status"] = "Status",
        ["loader.lifetime"] = "Lifetime",
        ["loader.days"] = "days",
        ["loader.load"] = "Load",
        ["loader.exit"] = "Exit",
        ["loader.working"] = "Working",
        ["loader.outdated"] = "Outdated - use at own risk", -- убрано
        ["loader.loading"] = "Loading...",
    }

    local function t2(key)
        return library2:Translate(loaderStrings[key] or key)
    end

    local function hasFs()
        return type(isfolder) == "function" and type(makefolder) == "function"
            and type(writefile) == "function" and type(readfile) == "function"
    end

    if hasFs() then
        if not isfolder(loaderRoot) then makefolder(loaderRoot) end
        for _, name in ipairs(loaderFolders) do
            local path = loaderRoot .. "/" .. name
            if not isfolder(path) then makefolder(path) end
        end
    end

    local function migrate(oldPath, newPath)
        if not hasFs() or not isfolder(oldPath) or type(listfiles) ~= "function" then return 0, 0 end

        local moved, failed = 0, 0
        for _, file in ipairs(listfiles(oldPath)) do
            local name = string.match(file, "[^/\\]+$")
            if not name then
                failed += 1
            else
                local ok, body = pcall(readfile, file)
                if ok and type(body) == "string" then
                    local target = newPath .. "/" .. name
                    local written = pcall(writefile, target, body)
                    if written and isfile(target) and readfile(target) == body then
                        moved += 1
                        if type(delfile) == "function" then pcall(delfile, file) end
                    else
                        failed += 1
                    end
                else
                    failed += 1
                end
            end
        end

        -- // убираем пустую папку
        if failed == 0 and type(delfolder) == "function" and #listfiles(oldPath) == 0 then
            pcall(delfolder, oldPath)
        end

        return moved, failed
    end

    -- // раскидываем по папкам
    local function relocate(oldFile, newFile)
        if not hasFs() or not isfile(oldFile) or isfile(newFile) then return 0, 0 end

        local ok, body = pcall(readfile, oldFile)
        if not ok or type(body) ~= "string" then return 0, 1 end

        local written = pcall(writefile, newFile, body)
        if written and isfile(newFile) and readfile(newFile) == body then
            if type(delfile) == "function" then pcall(delfile, oldFile) end
            return 1, 0
        end
        return 0, 1
    end

    local movedFiles, failedFiles = 0, 0
    do
        local a, b = migrate(loaderRoot .. "/settings", loaderRoot .. "/Configs")
        local c, d = migrate(loaderRoot .. "/themes", loaderRoot .. "/Themes")
        movedFiles, failedFiles = a + c, b + d

        local singles = {
            { "/wallbang.json", "/Wallbang/wallbang.json" },
            { "/custom_background_cache.txt", "/Cache/custom_background_cache.txt" },
            { "/custom_background_cache.png", "/Cache/custom_background_cache.png" },
            { "/custom_background_cache.jpg", "/Cache/custom_background_cache.jpg" },
            { "/custom_background_cache.jpeg", "/Cache/custom_background_cache.jpeg" },
            { "/custom_background_cache.webp", "/Cache/custom_background_cache.webp" },
        }

        for _, pair in ipairs(singles) do
            local ok, bad = relocate(loaderRoot .. pair[1], loaderRoot .. pair[2])
            movedFiles += ok
            failedFiles += bad
        end
    end

    local language = {
        Folder = loaderRoot .. "/Languages",
        List = { "English", "中文" },
        Current = "English",
        TemplatePending = false,
    }

    language.Read = function(path)
        local ok, decoded = pcall(function()
            local content = readfile(path)
            if string.sub(content, 1, 3) == "\239\187\191" then
                content = string.sub(content, 4)
            end
            return game:GetService("HttpService"):JSONDecode(content)
        end)
        return if ok and type(decoded) == "table" then decoded else nil
    end

    language.Json = function(text)
        return '"' .. string.gsub(text, '[%c"\\]', function(char)
            if char == '"' then return '\\"' end
            if char == "\\" then return "\\\\" end
            if char == "\n" then return "\\n" end
            if char == "\r" then return "\\r" end
            if char == "\t" then return "\\t" end
            return string.format("\\u%04x", string.byte(char))
        end) .. '"'
    end

    -- // фолс если есть файл но он не читаетмя
    language.Apply = function(name)
        local builtin = drainLanguages[name]
        local strings, readable = builtin and builtin() or {}, true
        local path = language.Folder .. "/" .. name .. ".json"
        if name ~= "English" and hasFs() and isfile(path) then
            local decoded = language.Read(path)
            readable = decoded ~= nil
            local legacy = {}
            for key, value in pairs(decoded or {}) do
                if type(key) == "string" and type(value) == "string" and value ~= "" then
                    local english = loaderStrings[key]
                    if english then
                        legacy[english] = value
                    else
                        strings[key] = value
                    end
                end
            end
            for english, value in pairs(legacy) do
                if decoded[english] == nil then strings[english] = value end
            end
        end

        library2.Strings = strings
        language.Current = name
        if hasFs() then
            pcall(writefile, loaderRoot .. "/loader.json", '{"language":' .. language.Json(name) .. '}')
        end
        return readable
    end

    language.SaveTemplate = function()
        language.TemplatePending = false
        if not hasFs() then return end

        local lines = {}
        for key in pairs(library2.SeenStrings) do lines[#lines + 1] = key end
        table.sort(lines)
        for index, key in ipairs(lines) do
            local encoded = language.Json(key)
            lines[index] = "  " .. encoded .. ": " .. encoded
        end

        local content = "{\n" .. table.concat(lines, ",\n") .. "\n}\n"
        local path = language.Folder .. "/Default.json"
        local ok, current = pcall(readfile, path)
        if ok and current == content then return end
        pcall(writefile, path, content)
    end

    library2.FinishLanguage = function()
        language.SaveTemplate()
        library2.OnNewString = function()
            if language.TemplatePending then return end
            language.TemplatePending = true
            task.delay(5, language.SaveTemplate)
        end
    end
    library2:OnUnload(function() library2.OnNewString = nil end)

    if hasFs() then
        local template = isfile(language.Folder .. "/Default.json") and language.Read(language.Folder .. "/Default.json")
        for key in pairs(template or {}) do
            if type(key) == "string" and not loaderStrings[key] then
                library2.SeenStrings[key] = true
            end
        end

        if type(listfiles) == "function" then
            local ok, files = pcall(listfiles, language.Folder)
            local custom = {}
            for _, file in ipairs(ok and files or {}) do
                local name = string.match(file, '([^/\\"]+)%.json$')
                if name and name ~= "Default" and not table.find(language.List, name) then
                    custom[#custom + 1] = name
                end
            end
            table.sort(custom)
            for _, name in ipairs(custom) do
                language.List[#language.List + 1] = name
            end
        end

        local saved = isfile(loaderRoot .. "/loader.json") and language.Read(loaderRoot .. "/loader.json")
        local name = saved and saved.language
        if name == "Default" then name = "English" end
        if type(name) == "string" and table.find(language.List, name) then
            language.Current = name
        end
    end

    if not language.Apply(language.Current) then
        library2:Notify(library2:TranslateFormat("Language file %s could not be read, it was skipped", language.Current .. ".json"), 6)
    end

    local function gameVersion()
        local gui = lp2:FindFirstChild("PlayerGui")
        local core = gui and gui:FindFirstChild("CoreGUI")
        local info = core and core:FindFirstChild("ServerInfo")
        if not info then return nil end

        local text = info:IsA("TextLabel") and info.Text or nil
        if not text then
            for _, item in ipairs(info:GetDescendants()) do
                if item:IsA("TextLabel") and string.find(item.Text, "|", 1, true) then
                    text = item.Text
                    break
                end
            end
        end
        if not text then return nil end

        local parts = {}
        for piece in string.gmatch(text, "[^|]+") do
            parts[#parts + 1] = string.match(piece, "^%s*(.-)%s*$")
        end
        return parts[2]
    end

    local liveVersion = gameVersion()
    local outdated = false

    local nick = lp2.DisplayName or lp2.Name
    if #nick > 16 then nick = string.sub(nick, 1, 13) .. "..." end

    local loader = { Proceed = false, Aborted = false, Rebuild = false, Window = nil, SavedPosition = nil, SavedAnchor = nil }

    loader.Build = function()
        -- // берем срок у луармора (доделать вообще бы )
        local expires = t2("loader.lifetime")
        do
            local data = getgenv and getgenv().LRM_UserData
            local authExpire = type(data) == "table" and tonumber(data.auth_expire) or nil
            if authExpire and authExpire > 0 then
                local left = authExpire - os.time()
                expires = left > 0 and (math.floor(left / 86400) .. " " .. t2("loader.days"))
                    or t2("loader.expires")
            end
        end

        local windowCfg = {
            Title = "drain.solutions",
            Center = true,
            AutoShow = true,
            Columns = 1,
            PhoneColumns = 2,
            Size = UDim2.fromOffset(440, 366),
            TabPadding = 8,
            GroupboxPadding = 14,
            MenuFadeTime = 0.2,
        }

        if loader.SavedPosition then
            windowCfg.Center = false
            windowCfg.Position = loader.SavedPosition
            windowCfg.AnchorPoint = loader.SavedAnchor
        end

        local loaderWindow = library2:CreateWindow(windowCfg)
        loader.Window = loaderWindow

        local holder = loaderWindow.Holder
        if holder then
            library2:GiveSignal(holder:GetPropertyChangedSignal("Position"):Connect(function()
                loader.SavedPosition = holder.Position
                loader.SavedAnchor = holder.AnchorPoint
            end))
        end

        local mainTab = loaderWindow:AddTab("Main")

        local loaderSettingsTab = loaderWindow:AddTab("Settings", true)
        pcall(function()
            themeManager:SetLibrary(library2)
            themeManager:SetFolder(loaderRoot)
            themeManager:ApplyToTab(loaderSettingsTab)
        end)

        local infoBox = mainTab:AddLeftGroupbox(t2("loader.info"))

        pcall(function()
            local holder = infoBox.Container or infoBox.Holder
            if not holder then return end

            local row = library2:Create('Frame', {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 104),
                ZIndex = 5,
                Parent = holder,
            })

            if gameIcon ~= "" then
                local icon = library2:Create('ImageLabel', {
                    BackgroundColor3 = library2.MainColor,
                    BorderColor3 = library2.OutlineColor,
                    BorderSizePixel = 1,
                    Image = gameIcon,
                    Position = UDim2.fromOffset(2, 4),
                    Size = UDim2.fromOffset(96, 96),
                    ScaleType = Enum.ScaleType.Fit,
                    ZIndex = 6,
                    Parent = row,
                })

                library2:AddToRegistry(icon, {
                    BackgroundColor3 = 'MainColor',
                    BorderColor3 = 'OutlineColor',
                })
            end

            local lines = {
                t2("loader.welcome") .. ", " .. nick .. "!",
                t2("loader.game"),
                t2("loader.version") .. ": " .. (liveVersion or buildVersion),
                t2("loader.updated") .. ": " .. buildDate,
                t2("loader.expires") .. ": " .. expires,
            }

            local textLeft = gameIcon ~= "" and 106 or 2
            local textTop = 4

            for index, text in ipairs(lines) do
                library2:CreateLabel({
                    Position = UDim2.new(0, textLeft, 0, textTop + (index - 1) * 16),
                    Size = UDim2.new(1, -textLeft - 2, 0, 16),
                    Text = text,
                    TextSize = 14,
                    TextColor3 = library2.FontColor,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 6,
                    Parent = row,
                })
            end

            if type(infoBox.Resize) == "function" then infoBox:Resize() end
        end)

        local optionsBox = mainTab:AddColumnGroupbox(loaderWindow.Columns, t2("loader.options"))
        optionsBox:AddButton({
            Text = t2("loader.load"),
            Func = function()
                loader.Proceed = true
            end,
        }):AddButton({
            Text = t2("loader.exit"),
            Func = function()
                loader.Aborted = true
            end,
        })

        local langBox = mainTab:AddColumnGroupbox(loaderWindow.Columns, t2("loader.language"))
        langBox:AddDropdown('LoaderLanguage', {
            Values = language.List,
            Default = language.Current,
            Multi = false,
            Translate = false,
            Tooltip = "Copy Default.json in drain.solutions/Languages, translate the values and save it under a new name.",
            Callback = function(name)
                if name == language.Current then return end
                if not language.Apply(name) then
                    library2:Notify(library2:TranslateFormat("Language file %s could not be read, it was skipped", name .. ".json"), 6)
                end
                loader.Rebuild = true
            end,
        })

        if failedFiles > 0 then
            langBox:AddLabel("", true):SetText(library2:TranslateFormat("Moved %d files, %d failed", movedFiles, failedFiles))
        elseif movedFiles > 0 then
            langBox:AddLabel("", true):SetText(library2:TranslateFormat("Moved %d old files", movedFiles))
        end
    end

    loader.Release = function()
        loader.Window:Destroy()
        options2.LoaderLanguage = nil
        for key in pairs(options2) do
            if type(key) == "string" and string.find(key, "ThemeManager_", 1, true) then
                options2[key] = nil
            end
        end
        for key in pairs(toggles) do
            if type(key) == "string" and string.find(key, "ThemeManager_", 1, true) then
                toggles[key] = nil
            end
        end
    end

    loader.Build()

    while not loader.Proceed do
        if loader.Aborted or library2.Unloaded then
            library2:Unload()

            pcall(function()
                game:GetService("UserInputService").MouseIconEnabled = true
            end)
            if type(environment.DrainCursorDrawings) == 'table' then
                for _, drawing in ipairs(environment.DrainCursorDrawings) do
                    pcall(function()
                        drawing.Visible = false
                        drawing:Remove()
                    end)
                end
                environment.DrainCursorDrawings = nil
            end
            return
        end
        if loader.Rebuild then
            loader.Rebuild = false
            loader.Release()
            loader.Build()
        end
        task.wait()
    end

    loader.Release()

    task.wait(0.1)
end

