    Warn     = true,
    Tooltip = "Holds a game animation while the desync runs so the offset reads as movement instead of a position jump.",
    Callback = function(state)
        fakePos.Anim.Enabled = state
        if not state then fakePos.AnimStop() end
    end,
})

desyncSection:AddDropdown('DesyncAnimPreset', {
    Text = "Animation",
