        fakePos.Anim.CustomId = text
        fakePos.AnimStop()
    end,
})

desyncSection:AddSlider('DesyncAnimFreeze', {
    Text = "Freeze At",
    Min = 0,
    Max = 5,
    Default = 1.755,
    Rounding = 3,
    FixedDecimals = true,
    Suffix = "s",
    Tooltip = "Holds the animation at this timestamp. Zero lets it play through instead.",
    Callback = function(value) fakePos.Anim.Freeze = value end,
})

desyncSection:AddSlider('DesyncAntiAimOffset', {
    Text = "Yaw Offset",
    Min = -180,
    Max = 180,
    Default = 0,
    Rounding = 0,
    Suffix = "°",
    Tooltip = "Added on top of whatever the method produces.",
    Callback = function(value) fakePos.AntiAim.Offset = value end,
})

do
    local ahSection = desyncPage:AddColumnGroupbox(3, "Anti Hit")

    local ac = {
        NeckC0    = CFrame.new(0, 0.4, 0.3),
        NeckC1    = CFrame.new(0, -0.1, 0.4) * CFrame.Angles(math.rad(90), math.rad(-180), 0),
        LShoulder = CFrame.new(-1, 0.5, 0,  0.020794034, -7.74860382e-07, -0.999783635, -0.98459357,  0.173654854, -0.0204781592,  0.173617214,  0.984806538,  0.00361025333),
        RShoulder = CFrame.new( 1, 0.5, 0,  0.020793736,  1.07288361e-06,  0.999783933,  0.984594166,  0.173652649, -0.0204781592, -0.173615277,  0.984807134,  0.00360971689),
        Mag6D     = CFrame.new(0.00922322646, 0.729015231, -1.10657895, 0.999783754, -6.51925802e-09, -0.0207949243, -0.0204789862, 0.173652411, -0.984594107,  0.00361109618,  0.984807014,  0.17361486),
        Tool6D    = CFrame.new(0.00922359806, 0.729012489, -1.10657847, 0.999783754, -2.79396772e-09, -0.0207949281, -0.0204789862, 0.173653483, -0.984593868,  0.00361111294,  0.984806776,  0.173615932),
    }

    local ahArmReach = Vector3.new(0, 4096, 0)

    local ahNeckOrig = CFrame.new(0, 1, 0, -1, 0, 0, 0, 0, 1, 0, 1, -0)

    -- // позы по формуле CFrame.new(-1, 0.5, 0) * CFrame.Angles(pitch, -1.55, roll)
    local ahPose = {
        down = {
            Left  = CFrame.new(-1, 0.5, 0) * CFrame.Angles(-1.4, -1.55, 0),
            Right = CFrame.new( 1, 0.5, 0) * CFrame.Angles(-1.4,  1.55, 0),
        },
        out = {
            Left  = CFrame.new(-1, 0.5, 0) * CFrame.Angles(0, -1.55, math.rad(80)),
            Right = CFrame.new( 1, 0.5, 0) * CFrame.Angles(0,  1.55, -math.rad(80)),
        },
    }

    local ahHeadValues = {
        ["Hide Head"]   = "hide",
        ["Break Neck"]  = "break",
        ["Custom Anim"] = "anim",
        ["Custom Yaw"]  = "custom",
    }

    local ahNeckOverflow = Vector3.new(0.0062371133826673, -6, -0.181367501616478)
    local ahTweakRate = 0.34
    local ahArmsValues = {
        ["Hands Up"]   = "handsup",
        ["Arms Down"]  = "handsdown",
        ["Arms Out"]   = "openhands",
        ["Frozen"]     = "frozen",
        ["Break Arms"] = "break",
    }

    local ahStanceValues = {
        ["Off"]      = "off",
        ["Crouched"] = "crouch",
        ["Standing"] = "stand",
    }

    local ahSprintValues = {
        ["Off"]       = "off",
        ["Sprinting"] = "sprint",
        ["Walking"]   = "walk",
    }

    local ah = {
        HeadEnabled  = false,
        HandsEnabled = false,
        HeadMode     = nil,
        HandsMode    = nil,
        CustomYaw    = 30,
        AnimId       = "282574440",
        AnimFreeze   = 0.3,
        AnimObj      = Instance.new("Animation"),
        AnimTrack    = nil,
        OrigC0       = nil,
        OrigC1       = nil,
        LastChar     = nil,
        Conn         = nil,
        HookInstalled = false,
        OldNamecall   = nil,
        MoveRemote    = nil,
        Tweak         = nil,
        TweakAt       = 0,
        Stance        = "off",
        Sprint        = "off",
        SpoofSpeed    = false,
        SpeedValue    = 16,
    }

    local function ahSpoofing()
        return ah.HandsMode ~= nil
            or ah.HeadMode ~= nil
            or ah.Stance ~= "off"
            or ah.Sprint ~= "off"
            or ah.SpoofSpeed
    end

    local function ahFindTweak()
        if ah.Tweak ~= nil then return ah.Tweak end

        if type(getgc) ~= "function"
            or type(debug) ~= "table"
            or type(debug.getinfo) ~= "function" then
            ah.Tweak = false
            return false
        end

        for _, value in pairs(getgc(true)) do
            if type(value) == "function" then
                local ok, info = pcall(debug.getinfo, value)
                if ok and type(info) == "table"
                    and info.name == "DoTweak"
                    and info.numparams == 11 then
                    ah.Tweak = value
                    return value
                end
            end
        end

        ah.Tweak = false
        return false
    end
    ah.AnimObj.AnimationId = "rbxassetid://282574440"
    ah.OrigShoulders = {}
    ah.OrigMotors = {}

    local function ahStopAnim()
        if ah.AnimTrack then
            pcall(function() ah.AnimTrack:Stop(0) end)
            ah.AnimTrack = nil
        end
    end

    local function ahRestoreNeck()
        local char = lp2.Character
        if not char then
            ah.OrigC0 = nil
            ah.OrigC1 = nil
            return
        end

        local head  = char:FindFirstChild("Head")
        local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
        local neck  = (head and head:FindFirstChild("Neck"))
                   or (torso and torso:FindFirstChild("Neck"))

        if neck and ah.OrigC0 then
            neck.C0 = ah.OrigC0
            neck.C1 = ah.OrigC1
        end

        ah.OrigC0 = nil
        ah.OrigC1 = nil
    end

    local function ahRestoreArms()
        for motor, c0 in pairs(ah.OrigShoulders) do
            if motor.Parent then
                pcall(function() motor.C0 = c0 end)
            end
        end
        for motor, c0 in pairs(ah.OrigMotors) do
            if motor.Parent then
                pcall(function() motor.C0 = c0 end)
            end
        end

        ah.OrigShoulders = {}
        ah.OrigMotors = {}
    end

    local function ahDisconnect()
        if ah.HeadMode == nil and ah.HandsMode == nil then
            if ah.Conn then
                ah.Conn:Disconnect()
                ah.Conn = nil
            end
            ahStopAnim()
            ahRestoreNeck()
            ahRestoreArms()
        end
    end

    local function ahConnect()
        if ah.Conn then return end

        ah.Conn = rs2.RenderStepped:Connect(function()
            local char = lp2.Character
            if not char then return end

            -- // новый спавн
            if char ~= ah.LastChar then
                ah.LastChar = char
                ah.OrigC0 = nil
                ah.OrigC1 = nil
                ah.OrigShoulders = {}
                ah.OrigMotors = {}
            end

            local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
            local head  = char:FindFirstChild("Head")

            if ah.HeadMode == "hide" then
                local neck = (head and head:FindFirstChild("Neck"))
                          or (torso and torso:FindFirstChild("Neck"))
                if neck then
                    if not ah.OrigC0 then
                        ah.OrigC0 = neck.C0
                        ah.OrigC1 = neck.C1
                    end
                    neck.C0 = ac.NeckC0
                    neck.C1 = ac.NeckC1
                end

            elseif ah.HeadMode == "anim" then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then
                    if not ah.AnimTrack or not ah.AnimTrack.IsPlaying then
                        local animator = hum:FindFirstChildOfClass("Animator") or hum
                        pcall(function()
                            ah.AnimTrack = animator:LoadAnimation(ah.AnimObj)
                            ah.AnimTrack.Priority = Enum.AnimationPriority.Action4
                            ah.AnimTrack:Play(0)
                        end)
                    end
                    if ah.AnimTrack then
                        pcall(function()
                            ah.AnimTrack:AdjustSpeed(0)
                            ah.AnimTrack.TimePosition = ah.AnimFreeze
                        end)
                    end
                end

            elseif ah.HeadMode == "custom" then
                local neck = (head and head:FindFirstChild("Neck"))
                          or (torso and torso:FindFirstChild("Neck"))
                if neck then
                    if not ah.OrigC0 then
                        ah.OrigC0 = neck.C0
                        ah.OrigC1 = neck.C1
                    end
                    neck.C0 = ahNeckOrig * CFrame.Angles(math.rad(ah.CustomYaw), 0, 0)
                end

                local root = char:FindFirstChild("HumanoidRootPart")
                local tweak = ah.Tweak
                local now = os.clock()

                if tweak and root and (now - ah.TweakAt) >= ahTweakRate then
                    ah.TweakAt = now
                    local look = CFrame.Angles(math.rad(ah.CustomYaw), 0, 0).LookVector
                    pcall(
                        tweak, char,
                        root.Position + Vector3.new(0, 10, 0), root.Position, look,
                        true, false, true, true, true, 9e9, true
                    )
                end

            else
                ahStopAnim()
                ahRestoreNeck()
            end

            if ah.HandsMode and torso then
                local lS = torso:FindFirstChild("Left Shoulder")
                local rS = torso:FindFirstChild("Right Shoulder")

                if ah.HandsMode == "handsup" then
                    if lS then
                        ah.OrigShoulders[lS] = ah.OrigShoulders[lS] or lS.C0
                        lS.C0 = ac.LShoulder
                    end
                    if rS then
                        ah.OrigShoulders[rS] = ah.OrigShoulders[rS] or rS.C0
                        rS.C0 = ac.RShoulder
                    end

                    local tool = char:FindFirstChildOfClass("Tool")
                    if tool then
                        for _, v in ipairs(tool:GetDescendants()) do
                            if v:IsA("Motor6D") then
                                if v.Name == "Mag6D_Torso" then
                                    ah.OrigMotors[v] = ah.OrigMotors[v] or v.C0
                                    v.C0 = ac.Mag6D
                                elseif v.Name == "Tool6D_Torso" then
                                    ah.OrigMotors[v] = ah.OrigMotors[v] or v.C0
                                    v.C0 = ac.Tool6D
                                end
                            end
                        end
                    end

                else
                    local pose = ah.HandsMode == "handsdown" and ahPose.down
                        or ah.HandsMode == "openhands" and ahPose.out
                        or nil

                    if pose then
                        if lS then
                            ah.OrigShoulders[lS] = ah.OrigShoulders[lS] or lS.C0
                            lS.C0 = pose.Left
                        end
                        if rS then
                            ah.OrigShoulders[rS] = ah.OrigShoulders[rS] or rS.C0
                            rS.C0 = pose.Right
                        end
                    end
                end

            end
        end)
    end

    local function ahInstallHook()
        if ah.HookInstalled then return end

        if not (hookmetamethod and getnamecallmethod) then
            library2:Notify(library2:Translate("Anti Hit: hook API unavailable, server-side arms won't work"), 5)
            return
        end

        ah.HookInstalled = true

        local moveEvents = repSt:FindFirstChild("Events")
        ah.MoveRemote = moveEvents and moveEvents:FindFirstChild(LPH_ENCSTR("MOVZREP"))

        local callback = LPH_NO_VIRTUALIZE(function(self, ...)
            if ahSpoofing()
                and self == ah.MoveRemote
                and getnamecallmethod() == "FireServer"
            then
                local args = { ... }
                local movement = args[1]
                local packet = type(movement) == "table" and movement[1] or nil

                if type(packet) == "table" then
                    pcall(function()
                        if ah.Sprint ~= "off" then
                            movement[2] = ah.Sprint == "sprint"
                        end
                        if ah.Stance ~= "off" then
                            movement[3] = ah.Stance == "crouch"
                        end
                        if ah.SpoofSpeed then
                            movement[4] = ah.SpeedValue
                        end

                        local origin = packet[2]

                        if ah.HandsMode and typeof(origin) == "Vector3" then
                            if ah.HandsMode == "handsup" then
                                packet[1] = origin + ahArmReach
                            elseif ah.HandsMode == "handsdown" then
                                packet[1] = origin - ahArmReach
                            elseif ah.HandsMode == "break" then
                                -- // одинаковые точки = нулевая разница
                                packet[1] = origin
                            elseif ah.HandsMode == "frozen" then
                                packet[5] = false
                            end
                        end

                        if ah.HeadMode == "break" then
                            packet[3] = ahNeckOverflow
                        elseif ah.HeadMode == "hide" then
                            packet[4] = false
                        end
                    end)

                    return ah.OldNamecall(self, table.unpack(args))
                end
            end

            return ah.OldNamecall(self, ...)
        end)

        if newcclosure then callback = newcclosure(callback) end
        ah.OldNamecall = hookmetamethod(game, "__namecall", callback)
    end

    ahSection:AddDropdown('AHHeadMode', {
        Text    = "Head Mode",
        Values  = { "Hide Head", "Break Neck", "Custom Anim", "Custom Yaw" }, -- анимки на голову, типо життер какой нибудь иили чет такое
        Default = "Hide Head",
        Multi   = false,
        Tooltip = "Hide Head sinks the head into the torso and stops your look angle from replicating.",
        Callback = function(value)
            ahStopAnim()
            ahRestoreNeck()

            ah.HeadMode = ah.HeadEnabled and ahHeadValues[value] or nil

            if ah.HeadMode then
                if ah.HeadMode == "custom" then ahFindTweak() end
                ahInstallHook()
                ahConnect()
            else
                ahDisconnect()
            end
        end,
    })

    local ahHeadToggle = ahSection:AddToggle('AHHeadEnabled', {
        Text    = "Head Enabled",
        Default = false,
        Tooltip = "Toggles the selected head mode on/off.",
        Callback = function(state)
            ah.HeadEnabled = state
            ahStopAnim()
            ahRestoreNeck()

            if state then
                ah.HeadMode = ahHeadValues[options2.AHHeadMode.Value]
                if ah.HeadMode then
                    if ah.HeadMode == "custom" then ahFindTweak() end
                    ahInstallHook()
                    ahConnect()
                end
            else
                ah.HeadMode = nil
                ahDisconnect()
            end
        end,
    })

    ahHeadToggle:AddKeyPicker('AHHeadKey', {
        Default  = "None",
        Mode     = "Toggle",
        Text     = "Head Mode",
        Callback = function(active) toggles.AHHeadEnabled:SetValue(active) end,
    })

    ahSection:AddInput('AHAnimId', {
        Text       = "Anim ID",
        Default    = "282574440",
        Placeholder = "rbxassetid:// or plain number",
        Tooltip    = "Animation ID for Custom Anim.",
        Callback = function(text)
            local id = normalizeAsset(text)
            if id ~= "" then
                ah.AnimId = id
                ah.AnimObj = Instance.new("Animation")
                ah.AnimObj.AnimationId = id
                ahStopAnim()
            end
        end,
    })

    ahSection:AddSlider('AHAnimFreeze', {
        Text     = "Anim Freeze Pos",
        Default  = 30,
        Min      = 0,
        Max      = 100,
        Rounding = 0,
        Suffix   = "%",
        Tooltip  = "Animation freeze position (% of its length).",
        Callback = function(value) ah.AnimFreeze = value / 100 end,
    })

    ahSection:AddSlider('AHCustomYaw', {
        Text     = "Custom Yaw Angle",
        Default  = 30,
        Min      = -90,
        Max      = 90,
        Rounding = 0,
        Suffix   = "°",
        Tooltip  = "Neck angle for Custom Yaw.",
        Callback = function(value) ah.CustomYaw = value end,
    })

    ahSection:AddDivider()

    ahSection:AddDropdown('AHHandsMode', {
        Text    = "Arms Mode",
        Values  = { "Hands Up", "Arms Down", "Arms Out", "Frozen", "Break Arms" },
        Default = "Hands Up",
        Multi   = false,
        Tooltip = "Arm angle comes from one vertical value, so these modes push it past its limits.",
        Callback = function(value)
            if not ah.HandsEnabled then return end

            ah.HandsMode = ahArmsValues[value]

            if not ah.HandsMode then
                ahRestoreArms()
                ahDisconnect()
            else
                ahRestoreArms()
            end
        end,
    })

    local ahHandsToggle = ahSection:AddToggle('AHHandsEnabled', {
        Text    = "Arms Enabled",
        Default = false,
        Tooltip = "Applies Arms Mode to your shoulders, so the arm hitboxes move with it.",
        Callback = function(state)
            ah.HandsEnabled = state
            ahRestoreArms()

            if state then
                ah.HandsMode = ahArmsValues[options2.AHHandsMode.Value] or "handsup"
                ahInstallHook()
                ahConnect()
            else
                ah.HandsMode = nil
                ahDisconnect()
            end
        end,
    })

    ahHandsToggle:AddKeyPicker('AHHandsKey', {
        Default  = "None",
        Mode     = "Toggle",
        Text     = "Arms Mode",
        Callback = function(active) toggles.AHHandsEnabled:SetValue(active) end,
    })

    ahSection:AddDivider()

    ahSection:AddDropdown('AHStance', {
        Text    = "Force Stance",
        Values  = { "Off", "Crouched", "Standing" },
        Default = "Off",
        Multi   = false,
        Tooltip = "Overrides the crouch flag that goes out with your movement.",
        Callback = function(value)
            ah.Stance = ahStanceValues[value] or "off"
            if ah.Stance ~= "off" then ahInstallHook() end
        end,
    })

    ahSection:AddDropdown('AHSprint', {
        Text    = "Force Sprint",
        Values  = { "Off", "Sprinting", "Walking" },
        Default = "Off",
        Multi   = false,
        Tooltip = "Same idea for the sprint flag.",
        Callback = function(value)
            ah.Sprint = ahSprintValues[value] or "off"
            if ah.Sprint ~= "off" then ahInstallHook() end
        end,
    })

    ahSection:AddToggle('AHSpoofSpeed', {
        Text    = "Spoof Footsteps",
        Default = false,
        Tooltip = "Replaces the movement speed you report.",
        Callback = function(state)
            ah.SpoofSpeed = state
            if state then ahInstallHook() end
        end,
    })

    ahSection:AddSlider('AHSpoofSpeedValue', {
        Text     = "Reported Speed",
        Min      = 0,
        Max      = 100,
        Default  = 0,
        Rounding = 0,
        Suffix   = " st/s",
        Tooltip  = "0 reports standing still, which mutes the steps others hear. Values above 50 stop getting louder because of their own cap.",
        Callback = function(value) ah.SpeedValue = value end,
    })

    library2:OnUnload(function()
        ah.HeadEnabled = false
        ah.HandsEnabled = false
        ah.HeadMode = nil
        ah.HandsMode = nil
        ah.Stance = "off"
        ah.Sprint = "off"
        ah.SpoofSpeed = false

        if ah.Conn then
            ah.Conn:Disconnect()
            ah.Conn = nil
        end

        ahStopAnim()
        ahRestoreNeck()
        ahRestoreArms()

        if ah.HookInstalled and ah.OldNamecall then
            pcall(function() hookmetamethod(game, "__namecall", ah.OldNamecall) end)
        end
    end)
end

library2:OnUnload(function()
    fakePos.Enabled = false
    fakePos.Angles.Enabled = false
    fakePos.AntiAim.Enabled = false
    fakePos.Rotate.Enabled = false
    fakePos.Anim.Enabled = false
    fakePos.Stop()
    fakePos.RotateStop()
    fakePos.AnimStop()
end)

end)()


drainBootLog("window built")

-- // есп без виртуализации
local sensoryEsp = LPH_NO_VIRTUALIZE(function()

local userInputService = game:GetService("UserInputService")
local runService = game:GetService("RunService")
local players2 = game:GetService("Players")
local coreGui2 = game:GetService("CoreGui")
local workspace2 = game:GetService("Workspace")
local replicatedStorage = game:GetService("ReplicatedStorage")
local httpService2 = game:GetService("HttpService")
local localPlayer = players2.LocalPlayer
local camera2 = workspace2.CurrentCamera
local uiContainer = gethui and gethui() or coreGui2
local bootstrapPlayers = players2
local esp = {}
local chamsContainer
local meshChamsFolder
local screenGui2
local playerRemovingConnection
local playerAddedConnection
local inputBeganConnection
local cameraConnection
local characterConnections = {}
local espActive = false
local espRenderEnabled = false
local currentRunId = httpService2:GenerateGUID(false)

if getgenv().SensoryESP_Unload then
    pcall(getgenv().SensoryESP_Unload)
end

local oldChams = uiContainer:FindFirstChild("SensoryESP_Chams")
    or workspace2:FindFirstChild("SensoryESP_Chams")
if oldChams then
    pcall(function() oldChams:Destroy() end)
end

