local silentAim
;(function()
local saHitscanGroups = {
    Head = { "Head" },
    Body = { "Torso", "UpperTorso", "LowerTorso" },
    Arms = {
        "Left Arm", "Right Arm",
        "LeftUpperArm", "RightUpperArm",
        "LeftLowerArm", "RightLowerArm",
        "LeftHand", "RightHand",
    },
    Legs = {
        "Left Leg", "Right Leg",
        "LeftUpperLeg", "RightUpperLeg",
        "LeftLowerLeg", "RightLowerLeg",
        "LeftFoot", "RightFoot",
    },
}

local saPriorityParts = {
    Head = { Head = true },
    Body = { Torso = true, UpperTorso = true, LowerTorso = true },
}

local saPointSizes = {
    Head = Vector3.new(1, 1, 1),
    Torso = Vector3.new(2, 2, 1),
    ["Left Arm"] = Vector3.new(1, 2, 1),
    ["Right Arm"] = Vector3.new(1, 2, 1),
    ["Left Leg"] = Vector3.new(1, 2, 1),
    ["Right Leg"] = Vector3.new(1, 2, 1),
}

silentAim = {
    Enabled      = false,
    Method       = "Module",
    HitChance    = 50,
    Accuracy     = 70,
    HitscanPriority = "Closest",
    HitscanPoints = {
        Head = true,
        Body = true,
        Arms = true,
        Legs = true,
    },
    PointScale   = 62,
    Spread       = 3,
    AdjustMovement = false,
    AdjustDrop   = false,
    WallCheck    = true,
    CheckDown    = false,
    DeadCheck    = false,
    CheckForceShield = false,
    CheckFriendly = false,
    FOVRadius    = 10, 
    DrawFOV      = false,
    FOVCenterOnly = false,
    FOVFilled    = false,
    FOVColor     = Color3.fromRGB(255, 255, 255),
    FOVFillColor = Color3.fromRGB(175, 86, 86),
    target       = nil,
    targetPlayer = nil,
    SwitchDelay  = 0,
    _lastSwitchTime = 0,
    _lastTargetPlayer = nil,
    MaxDistance  = 500,
}

local saMapRayParams = RaycastParams.new()
saMapRayParams.FilterType = Enum.RaycastFilterType.Include
saMapRayParams.IgnoreWater = true

local function saGetHitscanPartNames()
    local names = {}
    local seen = {}

    for groupName, enabled in pairs(silentAim.HitscanPoints) do
        if enabled then
            local group = saHitscanGroups[groupName]
            if group then
                for _, name in ipairs(group) do
                    if not seen[name] then
                        seen[name] = true
                        names[#names + 1] = name
                    end
                end
            end
        end
    end

    return names
end

local function saShouldIgnore(player)
    if not player or player == lp2 then return true end

    local char = player.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hum then return true end

    if silentAim.DeadCheck and hum.Health <= 0 then return true end
    if silentAim.CheckForceShield and char:FindFirstChildOfClass("ForceField") then return true end

    if silentAim.CheckDown then
        local charStats = repSt:FindFirstChild("CharStats")
        local playerStats = charStats and charStats:FindFirstChild(player.Name)
        local downed = playerStats and playerStats:FindFirstChild("Downed")
        if downed and downed.Value == true then return true end
    end

    if silentAim.CheckFriendly and getPlayerStatus(player) == "Friendly" then
        return true
    end

    if silentAim.MaxDistance > 0 then
        local localRoot = lp2.Character and lp2.Character:FindFirstChild("HumanoidRootPart")
        local targetRoot = char:FindFirstChild("HumanoidRootPart")
        if localRoot and targetRoot and (localRoot.Position - targetRoot.Position).Magnitude > silentAim.MaxDistance then
            return true
        end
    end

    return false
end

local function saPathBlocked(origin, goal)
    if not silentAim.WallCheck then return false end

    local direction = goal - origin
    if direction.Magnitude <= 0 then return false end

    local mapFolder = workspace:FindFirstChild("Map")
    if not mapFolder then return false end

    saMapRayParams.FilterDescendantsInstances = { mapFolder }

    local unit = direction.Unit
    local remaining = direction.Magnitude
    local current = origin

    while remaining > 0 do
        local result = workspace:Raycast(current, unit * remaining, saMapRayParams)
        if not result then return false end

        local hit = result.Instance
        if hit and hit.CanCollide and hit.Transparency < 1 then
            return true
        end

        local travelled = (result.Position - current).Magnitude
        if travelled <= 0.0001 then return true end
        remaining -= travelled
        current = result.Position + unit / 20
    end

    return false
end

local function saGetPointScalePosition(part)
    if not part then return nil end
    if silentAim.PointScale <= 0 then return part.Position end

    local size = saPointSizes[part.Name] or part.Size
    local factor = silentAim.PointScale / 200

    return part.Position + Vector3.new(
        (math.random() * 2 - 1) * size.X * factor,
        (math.random() * 2 - 1) * size.Y * factor,
        (math.random() * 2 - 1) * size.Z * factor
    )
end

local function saGetWeaponData(tool)
    tool = tool or (lp2.Character and lp2.Character:FindFirstChildOfClass("Tool"))
    local configModule = tool and tool:FindFirstChild("Config")
    if not configModule then return nil, nil end

    local success, config = pcall(require, configModule)
    local bulletSettings = success and config and config.BulletSettings
    local velocity = bulletSettings and tonumber(bulletSettings.Velocity)
    local acceleration = bulletSettings and bulletSettings.Acceleration

    if not velocity then return nil, nil end
    if typeof(acceleration) ~= "Vector3" then acceleration = Vector3.zero end

    return velocity * 1.5, acceleration
end

local function saSolvePrediction(origin, position, targetVelocity, projectileVelocity)
    if not projectileVelocity or projectileVelocity <= 0 then return position end

    local ping = 0
    pcall(function()
        ping = stats2.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
    end)

    local travelTime = (origin - position).Magnitude / projectileVelocity + ping / 2
    return position + Vector3.new(targetVelocity.X, 0, targetVelocity.Z) * travelTime
end

local function saSolveDrop(origin, acceleration, goal, projectileVelocity)
    if not projectileVelocity or projectileVelocity <= 0 or typeof(acceleration) ~= "Vector3" then
        return goal
    end

    local direction = goal - origin
    local travelTime = direction.Magnitude / projectileVelocity
    local halfAcceleration = acceleration / 2

    for _ = 1, 100 do
        local previous = travelTime
        travelTime = (direction - halfAcceleration * travelTime * travelTime).Magnitude / projectileVelocity
        if math.abs(travelTime - previous) < 0.00001 then break end
    end

    return origin + direction - halfAcceleration * travelTime * travelTime
end

local function saApplySpread(origin, goal)
    if silentAim.Spread <= 0 then return goal end

    local randomOffset = Vector3.new(
        math.random() * 2 - 1,
        math.random() * 2 - 1,
        math.random() * 2 - 1
    )

    if randomOffset.Magnitude <= 0.0001 then return goal end

    local spreadMultiplier = ((goal - origin).Magnitude / 100) * silentAim.Spread / 10
    return goal + randomOffset.Unit * spreadMultiplier
end

local function saBuildGoal(origin, part, tool, includeSpread)
    local goal = saGetPointScalePosition(part) or part.Position
    local projectileVelocity, acceleration = saGetWeaponData(tool)

    if silentAim.AdjustMovement and projectileVelocity then
        local targetVelocity = part.AssemblyLinearVelocity
        if typeof(targetVelocity) ~= "Vector3" then targetVelocity = part.Velocity end
        goal = saSolvePrediction(origin, goal, targetVelocity, projectileVelocity)
    end

    if silentAim.AdjustDrop and projectileVelocity and acceleration then
        goal = saSolveDrop(origin, acceleration, goal, projectileVelocity)
    end

    if includeSpread then
        goal = saApplySpread(origin, goal)
    end

    return goal
end

local function saCollectPointsForPlayer(player, cameraPosition, cameraLook, maximumAngle, partNames)
    if saShouldIgnore(player) then return {} end

    local character = player.Character
    local points = {}

    for _, partName in ipairs(partNames) do
        local part = character:FindFirstChild(partName)
        if not part or not part:IsA("BasePart") then continue end

        local offset = part.Position - cameraPosition
        if offset.Magnitude <= 0 then continue end

        local angle = math.acos(math.clamp(cameraLook:Dot(offset.Unit), -1, 1))
        if angle > maximumAngle then continue end
        if saPathBlocked(cameraPosition, part.Position) then continue end

        points[#points + 1] = {
            player = player,
            part = part,
            angle = angle,
        }
    end

    return points
end

local function saChoosePoint(points, useAccuracyRoll)
    if #points == 0 then return nil end

    local priorityNames = saPriorityParts[silentAim.HitscanPriority]
    local usePriority = priorityNames ~= nil
        and (not useAccuracyRoll or math.random(1, 100) <= silentAim.Accuracy)

    if usePriority then
        local bestPriority, bestPriorityAngle = nil, math.huge
        for _, point in ipairs(points) do
            if priorityNames[point.part.Name] and point.angle < bestPriorityAngle then
                bestPriority = point
                bestPriorityAngle = point.angle
            end
        end
        if bestPriority then return bestPriority end
    end

    local best, bestAngle = nil, math.huge
    for _, point in ipairs(points) do
        if point.angle < bestAngle then
            best = point
            bestAngle = point.angle
        end
    end

    return best
end

local function saFindTarget(useAccuracyRoll, onlyPlayer)
    local cameraCFrame = cam2.CFrame
    local cameraPosition = cameraCFrame.Position
    local cameraLook = cameraCFrame.LookVector
    local maximumAngle = math.rad(math.max(0, silentAim.FOVRadius)) / 2
    local partNames = saGetHitscanPartNames()
    if #partNames == 0 then return nil end

    local points = {}

    if onlyPlayer then
        points = saCollectPointsForPlayer(onlyPlayer, cameraPosition, cameraLook, maximumAngle, partNames)
    else
        for _, player in ipairs(plrs:GetPlayers()) do
            local playerPoints = saCollectPointsForPlayer(player, cameraPosition, cameraLook, maximumAngle, partNames)
            for _, point in ipairs(playerPoints) do
                points[#points + 1] = point
            end
        end
    end

    return saChoosePoint(points, useAccuracyRoll)
end

local function saRefreshTarget(useAccuracyRoll)
    if not silentAim.Enabled then
        silentAim.target = nil
        silentAim.targetPlayer = nil
        return nil
    end

    local candidate = saFindTarget(useAccuracyRoll)
    local candidatePlayer = candidate and candidate.player or nil

    if candidatePlayer ~= silentAim._lastTargetPlayer then
        local now = tick()
        local keepOld = silentAim.SwitchDelay > 0
            and silentAim._lastTargetPlayer ~= nil
            and (now - silentAim._lastSwitchTime) < silentAim.SwitchDelay

        if keepOld then
            local oldCandidate = saFindTarget(useAccuracyRoll, silentAim._lastTargetPlayer)
            if oldCandidate then
                candidate = oldCandidate
                candidatePlayer = oldCandidate.player
            else
                silentAim._lastTargetPlayer = candidatePlayer
                silentAim._lastSwitchTime = now
            end
        else
            silentAim._lastTargetPlayer = candidatePlayer
            silentAim._lastSwitchTime = now
        end
    end

    silentAim.target = candidate and candidate.part or nil
    silentAim.targetPlayer = candidatePlayer
    return silentAim.target
end

local saRing = createFovCircle("SilentAimFovRing", false, 10)
local saFill = createFovCircle("SilentAimFovFill", true, 9, 0.85)

local function saGetDrawRadius()
    local cameraFov = math.max(1, cam2.FieldOfView)
    local halfSilent = math.rad(math.max(0, silentAim.FOVRadius)) / 2
    local halfCamera = math.rad(cameraFov) / 2
    return math.tan(halfSilent) / math.tan(halfCamera) * (cam2.ViewportSize.Y / 2)
end

