local saOldNamecall
local saRaycastHookInstalled = false

local function saInstallRaycastHook()
    if saRaycastHookInstalled then return true end
    if not (hookmetamethod and getnamecallmethod) then return false end

    saRaycastHookInstalled = true
    local callback = LPH_NO_VIRTUALIZE(function(self, ...)
        local args = { ... }
        local method = getnamecallmethod()

        if method == "Raycast"
            and silentAim.Enabled
            and silentAim.Method == "Raycast"
            and self == workspace
            and args[1]
            and typeof(args[1]) == "Vector3"
            and math.random(1, 100) <= silentAim.HitChance
        then
            local external = true
            pcall(function() external = not checkcaller() end)

            if external then
                local targetPart = saRefreshTarget(true)
                if targetPart then
                    local tool = lp2.Character and lp2.Character:FindFirstChildOfClass("Tool")
                    local goal = saBuildGoal(args[1], targetPart, tool, true)
                    local delta = goal - args[1]
                    if delta.Magnitude > 0 then
                        local reach = typeof(args[2]) == "Vector3" and args[2].Magnitude or 0
                        args[2] = delta.Unit * math.max(reach, delta.Magnitude + 1)
                        return saOldNamecall(self, table.unpack(args))
                    end
                end
            end
        end

        return saOldNamecall(self, ...)
    end)

    if newcclosure then callback = newcclosure(callback) end
    saOldNamecall = hookmetamethod(game, "__namecall", callback)
    return saOldNamecall ~= nil
end

local saShootModule
local saOldShootModule
local saModuleHookInstalled = false
local saScanWarned = false

local function saResolveShootModule()
    if type(saShootModule) == "function" then return saShootModule end

    local newModules = repSt:FindFirstChild("NewModules")
    local client = newModules and newModules:FindFirstChild("Client")
    local services = client and client:FindFirstChild("Services")
    local effects = services and services:FindFirstChild("Effects")
    local shootModuleScript = effects and effects:FindFirstChild("Shoot")
    if not shootModuleScript then return nil end

    local ok, module = pcall(require, shootModuleScript)
    if ok and type(module) == "function" then
        saShootModule = module
        return module
    end

    return nil
end

local function saInstallModuleHook()
    if saModuleHookInstalled then return true end
    if not hookfunction then return false end

    local shootModule = saResolveShootModule()
    if type(shootModule) ~= "function" then return false end

    local callback = LPH_NO_VIRTUALIZE(function(self, ...)
        if not silentAim.Enabled or silentAim.Method ~= "Module" then
            return saOldShootModule(...)
        end

        if math.random(1, 100) > silentAim.HitChance then
            return saOldShootModule(...)
        end

        local args = { ... }

        local bullets, bulletsIndex
        for i = 1, #args do
            local v = args[i]
            if type(v) == "table" and not bullets then
                local allVectors = true
                local count = 0
                for _, vv in pairs(v) do
                    count = count + 1
                    if count > 32 then break end
                    if typeof(vv) ~= "Vector3" then
                        allVectors = false
                        break
                    end
                end
                if allVectors and count > 0 then
                    bullets = v
                    bulletsIndex = i
                end
            end
        end

        local origin
        if bulletsIndex then
            for i = bulletsIndex - 1, 1, -1 do
                if typeof(args[i]) == "Vector3" then
                    origin = args[i]
                    break
                end
            end
        end

        if not (bullets and origin) then
            if not saScanWarned then
                saScanWarned = true
            end
            return saOldShootModule(...)
        end

        local targetPart = saRefreshTarget(true)

        if not targetPart then
            return saOldShootModule(...)
        end

        local tool = lp2.Character and lp2.Character:FindFirstChildOfClass("Tool")
        local goal = saBuildGoal(origin, targetPart, tool, true)
        local direction = goal - origin

        if direction.Magnitude <= 0 then
            return saOldShootModule(...)
        end

        direction = direction.Unit

        local right = direction:Cross(Vector3.new(0, 1, 0))
        if right.Magnitude < 0.001 then right = direction:Cross(Vector3.new(1, 0, 0)) end
        right = right.Unit
        local up = right:Cross(direction).Unit
        local jitter = 0.004

        for i = 1, #bullets do
            if i == 1 then
                bullets[i] = direction
            else
                bullets[i] = (direction
                    + right * ((math.random() * 2 - 1) * jitter)
                    + up * ((math.random() * 2 - 1) * jitter)).Unit
            end
        end

        return saOldShootModule(table.unpack(args))
    end)

    if newcclosure then callback = newcclosure(callback) end
    saOldShootModule = hookfunction(shootModule, callback)
    saModuleHookInstalled = saOldShootModule ~= nil
    return saModuleHookInstalled
end

do
    local events2 = repSt:FindFirstChild("Events2")
    local visualize = events2 and events2:FindFirstChild("Visualize")
