            payload[string.format("%x", math.random(256, 4095))] = math.random() * 2 - 1
        end

        pcall(checkRemote.FireServer, checkRemote, tool, serverTick.Value * 2 - 91873, payload)
    end

    if visualize and visualize.Event and hitRemote then
        local remoteSilentConnection = visualize.Event:Connect(function(_, shotId, _, tool, _, origin, pelletDirs)
            if not silentAim.Enabled or silentAim.Method ~= "Remote" or not tool then return end

            local char = lp2.Character
            if not char or char:FindFirstChildOfClass("ForceField") then return end
            if char:FindFirstChildOfClass("Tool") ~= tool then return end
            if math.random(1, 100) > silentAim.HitChance then return end

            local targetPart = saRefreshTarget(true)
            if not targetPart or not targetPart.Parent then return end

            if typeof(origin) ~= "Vector3" then
                local handle = tool:FindFirstChild("WeaponHandle", true) or tool:FindFirstChild("Handle", true)
                local firePoint = handle and (handle:FindFirstChild("FirePoint", true) or handle:FindFirstChild("Muzzle", true))
                origin = firePoint and (firePoint:IsA("Attachment") and firePoint.WorldPosition or firePoint.Position) or cam2.CFrame.Position
            end

            local pointPosition = saGetPointScalePosition(targetPart) or targetPart.Position
            local goal = saBuildGoal(origin, targetPart, tool, true)
            local delta = goal - origin
            if delta.Magnitude <= 0 then return end
            local direction = delta.Unit

            local pelletCount = type(pelletDirs) == "table" and math.clamp(#pelletDirs, 1, 100) or 1
            task.wait(0.005)

            if not silentAim.Enabled
                or lp2.Character ~= char
                or char:FindFirstChildOfClass("Tool") ~= tool
                or tool.Parent == nil
                or targetPart.Parent == nil then
                return
            end

            for i = 1, pelletCount do
                pcall(function()
                    hitRemote:FireServer(
                        saHitMarker, tool, shotId, i, targetPart, pointPosition, direction,
                        nil, nil, nil, nil
                    )
                end)
            end

            saPingCheck(tool)

            local hitmarker = tool:FindFirstChild("Hitmarker")
            if hitmarker and hitmarker:IsA("BindableEvent") then
                hitmarker:Fire(targetPart)
            end
        end)
        library2:GiveSignal(remoteSilentConnection)
    end
end

local silentAimSection = legitPage:AddLeftGroupbox("Silent Aim")

local function saPrepareMethod(method)
    if method == "Module" then
        if not saInstallModuleHook() then
            library2:Notify(library2:Translate("Silent Aim: Module method is unavailable on this executor/game build; use Raycast or Remote."), 5)
            return false
        end
        return true
    elseif method == "Raycast" then
        if not saInstallRaycastHook() then
            library2:Notify(library2:Translate("Silent Aim: Raycast needs metamethod hooks; use Module or Remote."), 5)
            return false
        end
        return true
    end

    return true
end

