local legitAimFlags = {
    enabled = false,
    fov = 10,
    speed = 50,
    smoothing = "Linear",
    switch_delay = 100,
    accuracy = 60,
    hitscan_priority = "Head",
    hitscan_points = {
        Head = true,
        Torso = true,
        RightArm = false,
        LeftArm = false,
        RightLeg = false,
        LeftLeg = false,
    },
    wall_check = true,
    adjust_drop = false,
    adjust_movement = false,
    check_downed = false,
    dead_check = false,
    force_shield_check = false,
    check_friendly = false,
    show_fov = false,
    fov_color = Color3.fromRGB(181, 179, 253),
}

local legitAimbotController = {
    CurrentTarget = nil,
    PreviousTarget = { data = nil, tick = 0 },
    FovCircle = nil,
    Unloaded = false,
}
library2.LegitAimbotController = legitAimbotController

legitAimbotController.ShouldIgnore = function(player)
    if not player or player == lp2 then return true end

    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not humanoid then return true end

    if legitAimFlags.dead_check and humanoid.Health <= 0 then return true end
    if legitAimFlags.force_shield_check and character:FindFirstChildOfClass("ForceField") then return true end

    if legitAimFlags.check_downed then
        local charStats = repSt:FindFirstChild("CharStats")
        local playerStats = charStats and charStats:FindFirstChild(player.Name)
        local downed = playerStats and playerStats:FindFirstChild("Downed")
        if downed and downed.Value == true then return true end
    end

    if legitAimFlags.check_friendly and getPlayerStatus(player) == "Friendly" then
        return true
    end

    return false
end

local legitAimPointMap = {
    Head = { "Head" },
    Torso = { "Torso", "UpperTorso" },
    RightArm = { "Right Arm", "RightUpperArm", "RightLowerArm" },
    LeftArm = { "Left Arm", "LeftUpperArm", "LeftLowerArm" },
    RightLeg = { "Right Leg", "RightUpperLeg", "RightLowerLeg" },
    LeftLeg = { "Left Leg", "LeftUpperLeg", "LeftLowerLeg" },
}

local legitAimPriorityMap = {
    Head = { Head = true },
    Body = { Torso = true, UpperTorso = true },
}

local legitAimRayParams = RaycastParams.new()
legitAimRayParams.FilterType = Enum.RaycastFilterType.Include

local function getLegitAimHitscanParts()
    local parts = {}
    for key, enabled in pairs(legitAimFlags.hitscan_points) do
        if enabled and legitAimPointMap[key] then
            for _, name in ipairs(legitAimPointMap[key]) do
                parts[#parts + 1] = name
            end
        end
    end
    return parts
end

local function legitAimPathBlocked(origin, goal)
    local direction = goal - origin
    if direction.Magnitude <= 0 then return false end

    local mapFolder = workspace:FindFirstChild("Map")
    legitAimRayParams.FilterDescendantsInstances = mapFolder and { mapFolder } or {}

    local unit = direction.Unit
    local remaining = direction.Magnitude
    local current = origin

    while remaining > 0 do
        local result = workspace:Raycast(current, unit * remaining, legitAimRayParams)
        if not result then return false end

        local part = result.Instance
        if part and part.CanCollide and part.Transparency < 1 then
            return true
        end

        remaining = remaining - (result.Position - current).Magnitude
        current = result.Position + unit / 20
    end

    return false
end

local function solveLegitAimPrediction(origin, partPosition, partVelocity, velocity)
    local ping = 0
    pcall(function()
        ping = stats2.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
    end)

    local travelTime = (origin - partPosition).Magnitude / velocity + ping / 2
    return partPosition + Vector3.new(partVelocity.X, 0, partVelocity.Z) * travelTime
end

local function solveLegitAimDrop(origin, acceleration, goal, velocity)
    local direction = goal - origin
    local travelTime = direction.Magnitude / velocity
    local halfAcceleration = acceleration / 2

    for _ = 1, 100 do
        local previous = travelTime
        travelTime = (direction - halfAcceleration * travelTime * travelTime).Magnitude / velocity
        if math.abs(travelTime - previous) < 0.00001 then break end
    end

    return origin + direction - halfAcceleration * travelTime * travelTime
end

local function getLegitAimWeaponData()
    local character = lp2.Character
    local tool = character and character:FindFirstChildOfClass("Tool")
    local configModule = tool and tool:FindFirstChild("Config")
    if not configModule then return nil, nil end

    local success, config = pcall(require, configModule)
    local bulletSettings = success and config and config.BulletSettings
    local velocity = bulletSettings and tonumber(bulletSettings.Velocity)
    local acceleration = bulletSettings and bulletSettings.Acceleration
    if not velocity then return nil, nil end
    if typeof(acceleration) ~= "Vector3" then acceleration = Vector3.zero end

    return velocity * 1.5, acceleration
end

local function getLegitAimEnemies()
    local cameraCFrame = cam2.CFrame
    local cameraPosition = cameraCFrame.Position
    local cameraLook = cameraCFrame.LookVector
    local maxAngle = math.rad(legitAimFlags.fov) / 2
    local enemies = {}

    for _, player in ipairs(plrs:GetPlayers()) do
        if legitAimbotController.ShouldIgnore(player) then continue end

        local character = player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not root or not humanoid then continue end

        local offset = root.Position - cameraPosition
        if offset.Magnitude <= 0 then continue end

        local angle = math.acos(math.clamp(cameraLook:Dot(offset.Unit), -1, 1))
        if angle > maxAngle then continue end

        enemies[#enemies + 1] = {
            player = player,
            character = character,
            root = root,
            angle = angle,
        }
    end

    return enemies
end

local function findLegitAimTarget()
    local cameraPosition = cam2.CFrame.Position
    local cameraLook = cam2.CFrame.LookVector
    local partNames = getLegitAimHitscanParts()
    if #partNames == 0 then return nil end

    local points = {}
    for _, data in ipairs(getLegitAimEnemies()) do
        for _, partName in ipairs(partNames) do
            local part = data.character:FindFirstChild(partName)
            if not part then continue end
            if legitAimFlags.wall_check and legitAimPathBlocked(cameraPosition, part.Position) then continue end

            local offset = part.Position - cameraPosition
            if offset.Magnitude <= 0 then continue end

            points[#points + 1] = {
                part = part,
                data = data,
                angle = math.acos(math.clamp(cameraLook:Dot(offset.Unit), -1, 1)),
            }
        end
    end

    if #points == 0 then return nil end

    local priorityParts = legitAimPriorityMap[legitAimFlags.hitscan_priority]
    if priorityParts and math.random(1, 100) <= legitAimFlags.accuracy then
        local bestPriority, bestPriorityAngle = nil, math.huge
        for _, point in ipairs(points) do
            if priorityParts[point.part.Name] and point.angle < bestPriorityAngle then
                bestPriority = point
                bestPriorityAngle = point.angle
            end
        end
        if bestPriority then return bestPriority end
    end

    local best, bestAngle = nil, math.huge
    for _, point in ipairs(points) do
        if point.angle < bestAngle then
            best = point
            bestAngle = point.angle
        end
    end
    return best
end

local function removeLegitAimFov()
    if not legitAimbotController.FovCircle then return end
    removeFovCircle(legitAimbotController.FovCircle)
    legitAimbotController.FovCircle = nil
end

local jumpTrack = {
    Enabled = false,
    TriggerOnLand = true,
    HoldTime = 420,
    CooldownMin = 80,
    CooldownMax = 220,
    FlickMin = 40,
    FlickMax = 100,

    State = "idle",
    Target = nil,
    WasAirborne = nil,
    LastStep = 0,
    Since = 0,
    Until = 0,
    FlickAlpha = 0,
    FlickTime = 0.05,
}

jumpTrack.Airborne = function(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return false end

    local state = humanoid:GetState()
    return state == Enum.HumanoidStateType.Jumping
        or state == Enum.HumanoidStateType.Freefall
end

jumpTrack.Reset = function(character)
    jumpTrack.State = "idle"
    jumpTrack.Target = character
    jumpTrack.WasAirborne = nil
end

jumpTrack.Roll = function(a, b)
    local low, high = math.min(a, b), math.max(a, b)
    return low + math.random() * (high - low)
end

jumpTrack.Step = function(character, cameraCFrame, aimPosition, smoothing, deltaTime)
    if not jumpTrack.Enabled or not character then return nil end

    local now = os.clock()
    if character ~= jumpTrack.Target or now - jumpTrack.LastStep > 0.25 then
        jumpTrack.Reset(character)
    end
    jumpTrack.LastStep = now

    local airborne = jumpTrack.Airborne(character)
    local tookOff = airborne and jumpTrack.WasAirborne == false
    jumpTrack.WasAirborne = airborne

    if tookOff then
        jumpTrack.State = "frozen"
        jumpTrack.Since = now
    elseif jumpTrack.State == "frozen" then
        local release = if jumpTrack.TriggerOnLand
            then not airborne
            else (now - jumpTrack.Since) * 1000 >= jumpTrack.HoldTime
        if release then
            jumpTrack.State = "cooldown"
            jumpTrack.Until = now + jumpTrack.Roll(jumpTrack.CooldownMin, jumpTrack.CooldownMax) / 1000
        end
    end

    if jumpTrack.State == "cooldown" and now >= jumpTrack.Until then
        jumpTrack.State = "flick"
        jumpTrack.FlickAlpha = 0
        jumpTrack.FlickTime = math.max(jumpTrack.Roll(jumpTrack.FlickMin, jumpTrack.FlickMax), 1) / 1000
    end

    if jumpTrack.State == "idle" then return nil end

    local cameraPosition = cameraCFrame.Position
    local pitch, yaw, roll = cameraCFrame:ToOrientation()
    local wantPitch, wantYaw = CFrame.lookAt(cameraPosition, aimPosition):ToOrientation()

    yaw += ((wantYaw - yaw + math.pi) % (2 * math.pi) - math.pi) * smoothing

    if jumpTrack.State == "flick" then
        local left = 1 - jumpTrack.FlickAlpha
        jumpTrack.FlickAlpha = math.min(1, jumpTrack.FlickAlpha + deltaTime / jumpTrack.FlickTime)
        -- // еасиненг
        pitch += (wantPitch - pitch) * (1 - ((1 - jumpTrack.FlickAlpha) / left) ^ 3)
        if jumpTrack.FlickAlpha >= 1 then jumpTrack.State = "idle" end
    end

    return CFrame.new(cameraPosition) * CFrame.fromOrientation(pitch, yaw, roll)
end

local legitAimbotConnection = rs2.RenderStepped:Connect(function(deltaTime)
    if legitAimbotController.Unloaded then return end

    if not legitAimFlags.enabled then
        if legitAimbotController.FovCircle then removeLegitAimFov() end
        legitAimbotController.CurrentTarget = nil
        return
    end

    if legitAimFlags.enabled and legitAimFlags.show_fov
        and (library2.IsMobile or library2.WindowFocused ~= false) then
        if not legitAimbotController.FovCircle then
            legitAimbotController.FovCircle = createFovCircle("LegitAimFov", false, 10)
        end

        local circle = legitAimbotController.FovCircle
        local center = getAimScreenPosition()
        local radius = math.tan(math.rad(legitAimFlags.fov) / 2)
            / math.tan(math.rad(cam2.FieldOfView) / 2)
            * (cam2.ViewportSize.Y / 2)
        if library2.IsMobile then
            updateMobileFovCircle(circle, center, radius, legitAimFlags.fov_color, true)
        else
            circle.Position = center
            circle.Radius = radius
            circle.Color = legitAimFlags.fov_color
            circle.Visible = true
        end
    else
        removeLegitAimFov()
    end

    if not legitAimFlags.enabled then
        legitAimbotController.CurrentTarget = nil
        return
    end

    local currentTarget = legitAimbotController.CurrentTarget
    if currentTarget then
        local data = currentTarget.data
        local part = currentTarget.part
        local root = data and data.root
        local previousTarget = legitAimbotController.PreviousTarget
        local sinceSwitch = tick() - previousTarget.tick

        if root and root.Parent and part and part.Parent
            and not legitAimbotController.ShouldIgnore(data and data.player)
            and (data == previousTarget.data or sinceSwitch > legitAimFlags.switch_delay / 1000) then

            local aimPosition = part.Position
            if legitAimFlags.wall_check and legitAimPathBlocked(cam2.CFrame.Position, aimPosition) then
                legitAimbotController.CurrentTarget = nil
                return
            end

            local velocity, acceleration = getLegitAimWeaponData()
            if legitAimFlags.adjust_movement and velocity then
                aimPosition = solveLegitAimPrediction(cam2.CFrame.Position, aimPosition, part.Velocity, velocity)
            end
            if legitAimFlags.adjust_drop and velocity and acceleration then
                aimPosition = solveLegitAimDrop(cam2.CFrame.Position, acceleration, aimPosition, velocity)
            end

            previousTarget.data = data
            previousTarget.tick = tick()

            local smoothing
            if legitAimFlags.smoothing == "Linear" then
                smoothing = legitAimFlags.speed / 10 * deltaTime
            else
                smoothing = 1 - math.exp(-legitAimFlags.speed / 2 * deltaTime * currentTarget.angle)
            end

            smoothing = math.clamp(smoothing, 0, 1)
            local cameraPosition = cam2.CFrame.Position
            cam2.CFrame = jumpTrack.Step(data.character, cam2.CFrame, aimPosition, smoothing, deltaTime)
                or cam2.CFrame:Lerp(CFrame.lookAt(cameraPosition, aimPosition), smoothing)
            return
        end

        legitAimbotController.CurrentTarget = nil
        return
    end

    legitAimbotController.CurrentTarget = findLegitAimTarget()
end)
library2:GiveSignal(legitAimbotConnection)

local cleanupLegitAimbot
cleanupLegitAimbot = function()
    if legitAimbotController.Unloaded then return end
    legitAimbotController.Unloaded = true
    legitAimFlags.enabled = false
    legitAimbotController.CurrentTarget = nil
    jumpTrack.Reset()
    removeLegitAimFov()

    if environment.DrainLegitAimbotCleanup == cleanupLegitAimbot then
        environment.DrainLegitAimbotCleanup = nil
    end
end

