local triggerbotFlags = {
    enabled = false,
    reaction_time = 120,
    hitboxes = { Head = true, Body = true, Arms = true, Legs = true },
    magnet = false,
    magnet_fov = 10,
    magnet_speed = 50,
    magnet_accuracy = 60,
    magnet_priority = "Closest",
    check_downed = false,
    dead_check = false,
    force_shield_check = false,
    check_friendly = false,
    candidate = nil,
    candidate_since = 0,
    last_shot = 0,
}

triggerbotFlags.should_ignore = function(player)
    if not player or player == lp2 then return true end

    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not humanoid then return true end

    if triggerbotFlags.dead_check and humanoid.Health <= 0 then return true end
    if triggerbotFlags.force_shield_check and character:FindFirstChildOfClass("ForceField") then return true end

    if triggerbotFlags.check_downed then
        local charStats = repSt:FindFirstChild("CharStats")
        local playerStats = charStats and charStats:FindFirstChild(player.Name)
        local downed = playerStats and playerStats:FindFirstChild("Downed")
        if downed and downed.Value == true then return true end
    end

    if triggerbotFlags.check_friendly and getPlayerStatus(player) == "Friendly" then
        return true
    end

    return false
end

local triggerHitboxMap = {
    Head = { "Head" },
    Body = { "Torso", "UpperTorso", "LowerTorso" },
    Arms = { "Left Arm", "Right Arm", "LeftUpperArm", "RightUpperArm", "LeftLowerArm", "RightLowerArm" },
    Legs = { "Left Leg", "Right Leg", "LeftUpperLeg", "RightUpperLeg", "LeftLowerLeg", "RightLowerLeg" },
}

local function triggerbotKeyActive()
    local key = options2.TriggerBotKey
    if not key or key.Value == "None" then return true end
    return key:GetState()
end

local function triggerbotCollectParts(character)
    local parts = {}
    if not character then return parts end
    for category, names in pairs(triggerHitboxMap) do
        if triggerbotFlags.hitboxes[category] then
            for _, name in ipairs(names) do
                local part = character:FindFirstChild(name, true)
                if part and part:IsA("BasePart") then parts[#parts + 1] = part end
            end
        end
    end
    return parts
end

local function triggerbotScreenRay()
    local camera = workspace.CurrentCamera or cam2
    if not camera then return nil end
    local point = getAimScreenPosition(false)
    local ray = camera:ViewportPointToRay(point.X, point.Y, 0)
    return ray.Origin, ray.Direction.Unit, camera
end

local function triggerbotClick(screenPoint)
    if type(mouse1click) == "function" then
        pcall(mouse1click)
        return
    end
    if type(mouse1press) == "function" and type(mouse1release) == "function" then
        pcall(mouse1press)
        task.delay(1 / 60, function() pcall(mouse1release) end)
        return
    end

    pcall(function()
        local vim = game:GetService("VirtualInputManager")
        local x, y = screenPoint.X, screenPoint.Y
        vim:SendMouseButtonEvent(x, y, 0, true, game, 0)
        task.delay(1 / 60, function()
            pcall(function() vim:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
        end)
    end)
end

local function triggerbotFindMagnetTarget()
    local origin, _, camera = triggerbotScreenRay()
    if not origin or not camera then return nil end

    local cameraLook = camera.CFrame.LookVector
    local maxAngle = math.rad(triggerbotFlags.magnet_fov) / 2
    local candidates = {}

    for _, player in ipairs(plrs:GetPlayers()) do
        if triggerbotFlags.should_ignore(player) then continue end
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not character or not humanoid then continue end

        for _, part in ipairs(triggerbotCollectParts(character)) do
            local delta = part.Position - origin
            if delta.Magnitude <= 0.001 then continue end
            local angle = math.acos(math.clamp(cameraLook:Dot(delta.Unit), -1, 1))
            if angle <= maxAngle and not legitAimPathBlocked(origin, part.Position) then
                candidates[#candidates + 1] = { part = part, angle = angle }
            end
        end
    end

    if #candidates == 0 then return nil end
    table.sort(candidates, function(a, b) return a.angle < b.angle end)

    local priority = triggerbotFlags.magnet_priority
    if priority ~= "Closest" and math.random(1, 100) <= triggerbotFlags.magnet_accuracy then
        for _, candidate in ipairs(candidates) do
            local name = candidate.part.Name
            if priority == "Head" and name == "Head" then return candidate.part end
            if priority == "Body" and (name == "Torso" or name == "UpperTorso" or name == "LowerTorso") then
                return candidate.part
            end
        end
    end

    return candidates[1].part
end

local function triggerbotProcess(deltaTime)
    if not triggerbotFlags.enabled or not triggerbotKeyActive() or library2.MenuOpen then
        triggerbotFlags.candidate = nil
        triggerbotFlags.candidate_since = 0
        return
    end

    local origin, direction, camera = triggerbotScreenRay()
    if not origin or not direction or not camera then return end

    if triggerbotFlags.magnet then
        local magnetPart = triggerbotFindMagnetTarget()
        if magnetPart then
            local alpha = math.clamp((triggerbotFlags.magnet_speed / 10) * deltaTime, 0, 1)
            camera.CFrame = camera.CFrame:Lerp(CFrame.lookAt(camera.CFrame.Position, magnetPart.Position), alpha)
            origin, direction = triggerbotScreenRay()
            if not origin or not direction then return end
        end
    end

    local included = {}
    for _, player in ipairs(plrs:GetPlayers()) do
        if triggerbotFlags.should_ignore(player) then continue end
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if character and humanoid then
            for _, part in ipairs(triggerbotCollectParts(character)) do included[#included + 1] = part end
        end
    end

    if #included == 0 then
        triggerbotFlags.candidate = nil
        return
    end

    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = included
    params.IgnoreWater = true
    local result = workspace:Raycast(origin, direction * 1000, params)
    local part = result and result.Instance or nil

    if not part or legitAimPathBlocked(origin, result.Position) then
        triggerbotFlags.candidate = nil
        triggerbotFlags.candidate_since = 0
        return
    end

    local now = os.clock()
    if triggerbotFlags.candidate ~= part then
        triggerbotFlags.candidate = part
        triggerbotFlags.candidate_since = now
        return
    end

    if now - triggerbotFlags.candidate_since < (triggerbotFlags.reaction_time / 1000) then return end
    if now - triggerbotFlags.last_shot < 0.06 then return end

    triggerbotFlags.last_shot = now
    local point = getAimScreenPosition(false)
    triggerbotClick(point)
end

