local miscSection = miscPage:AddColumnGroupbox(3, "Misc")
local securitySection = miscPage:AddLeftGroupbox("Security")
local stockFinderSection = miscPage:AddCenterGroupbox("Stock Finder")
local stockFinder = {
    Query = "",
    UseESP = true,
    ReplaceName = false,
    Color = Color3.fromRGB(90, 170, 255),
    Objects = {},
}

local function stockFinderClear()
    for index = #stockFinder.Objects, 1, -1 do
        local object = table.remove(stockFinder.Objects, index)
        pcall(function() object:Destroy() end)
    end
end

local function stockFinderAnchor(shop)
    local dealer = shop:FindFirstChild("ArmoryMan") or shop:FindFirstChild("DealerMan")
    if dealer then
        if dealer:IsA("BasePart") then return dealer end
        if dealer:IsA("Model") then
            return dealer:FindFirstChild("Head", true)
                or dealer:FindFirstChild("HumanoidRootPart", true)
                or dealer:FindFirstChildWhichIsA("BasePart", true)
        end
    end
    return shop:FindFirstChild("MainPart") or shop:FindFirstChildWhichIsA("BasePart", true)
end

local function stockFinderMakeEsp(shop, itemName, shopType, amount)
    if not stockFinder.UseESP then return end
    local adornee = stockFinderAnchor(shop)
    if not adornee or not adornee:IsA("BasePart") then return end

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "DrainStockFinderESP"
    billboard.AlwaysOnTop = true
    billboard.Size = UDim2.fromOffset(260, 28)
    billboard.StudsOffset = Vector3.new(0, 3, 0)
    billboard.Adornee = adornee
    billboard.Parent = adornee

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = library2.Font
    label.TextSize = 14
    label.TextStrokeTransparency = 0
    label.TextColor3 = stockFinder.Color

    local typeTag = shopType == "LegalStore" and "[Armory] " or "[Illegal] "
    local displayName = stockFinder.ReplaceName and stockFinder.Query or itemName
    label.Text = typeTag .. displayName .. " x" .. tostring(amount)
    label.Parent = billboard

    stockFinder.Objects[#stockFinder.Objects + 1] = billboard
end

local function stockFinderRun()
    stockFinderClear()
    local query = tostring(stockFinder.Query or ""):match("^%s*(.-)%s*$") or ""
    if query == "" then
        library2:Notify(library2:Translate("Stock Finder: enter an item name"), 4)
        return
    end

    local map = workspace:FindFirstChild("Map")
    local shops = map and map:FindFirstChild("Shopz")
    if not shops then
        library2:Notify(library2:Translate("Stock Finder: Shopz not found"), 4)
        return
    end

    local queryLower = query:lower()
    local lp = game:GetService("Players").LocalPlayer
    local char = lp and lp.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")

    local matches = {}
    for _, shop in ipairs(shops:GetChildren()) do
        local stocks = shop:FindFirstChild("CurrentStocks")
        local typeVal = shop:FindFirstChild("Type")
        local shopType = typeVal and typeVal.Value or "IllegalStore"
        if stocks then
            local exact
            local partial
            for _, item in ipairs(stocks:GetChildren()) do
                local nameLower = item.Name:lower()
                if nameLower == queryLower then
                    exact = item
                    break
                elseif not partial and nameLower:find(queryLower, 1, true) then
                    partial = item
                end
            end
            local item = exact or partial
            local amount = item and tonumber(item.Value)
            if item and amount and amount > 0 then
                local mainPart = shop:FindFirstChild("MainPart")
                local dist = root and mainPart
                    and (root.Position - mainPart.Position).Magnitude
                    or math.huge
                matches[#matches + 1] = { shop = shop, item = item, shopType = shopType, amount = amount, dist = dist }
            end
        end
    end

    -- ближайшие первыми
    table.sort(matches, function(a, b) return a.dist < b.dist end)

    for _, match in ipairs(matches) do
        stockFinderMakeEsp(match.shop, match.item.Name, match.shopType, match.amount)
    end

    if #matches == 0 then
        library2:Notify(library2:TranslateFormat("Stock Finder: no stock found for %s", query), 4)
    else
        library2:Notify(library2:TranslateFormat("Stock Finder: found %d location(s)", #matches), 4)
    end
end

stockFinderSection:AddInput('MiscStockFinderQuery', {
    Text = "Search Item",
    Default = "",
    Finished = false,
    Placeholder = "Beretta",
    Callback = function(value) stockFinder.Query = value end,
})

stockFinderSection:AddToggle('MiscStockFinderUseESP', {
    Text = "Use ESP",
    Default = true,
    Callback = function(value)
        stockFinder.UseESP = value
        if not value then stockFinderClear() end
    end,
