    Callback = function(color)
        stockFinder.Color = color
        for _, billboard in ipairs(stockFinder.Objects) do
            local label = billboard and billboard:FindFirstChildOfClass("TextLabel")
            if label then label.TextColor3 = color end
        end
    end,
})

stockFinderSection:AddToggle('MiscStockFinderReplaceName', {
