    Callback = function(value)
        stockFinder.ReplaceName = value
        if #stockFinder.Objects > 0 then stockFinderRun() end
    end,
})

stockFinderSection:AddButton({
    Text = "Find Stock",
    Func = stockFinderRun,
})

stockFinderSection:AddButton({
    Text = "Clear Stock ESP",
    Func = stockFinderClear,
})

library2:OnUnload(stockFinderClear)


;(function()
local publicNameSpoof = {
    Enabled = false,
    FakeName = lp2.Name,
    FakeDisplay = lp2.DisplayName,
    Conns = {},
    Originals = setmetatable({}, { __mode = "k" }),
    PreviousIncomingMessage = nil,
    ChatCallback = nil,
}

local function pnsRemember(object)
    if publicNameSpoof.Originals[object] == nil then
        publicNameSpoof.Originals[object] = object.Text
    end
end

local function pnsGetDisplay()
    return publicNameSpoof.FakeDisplay
end

local function pnsGetName()
    return publicNameSpoof.FakeName
end

local function pnsSpoofTextObject(object)
    if not publicNameSpoof.Enabled then return end
    if not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then return end

    local function apply()
        local text = object.Text
        if text == "" then return end

        local targetDisplay = pnsGetDisplay()
        local targetName = pnsGetName()
        local realDisplay = lp2.DisplayName
        local realName = lp2.Name
        if text:find(targetDisplay, 1, true) then return end

        local newText = text
        if newText:find(realDisplay, 1, true) then
            newText = newText:gsub(realDisplay, targetDisplay)
        end
        if newText:find(realName, 1, true) then
            newText = newText:gsub(realName, targetName)
        end
        if newText ~= object.Text then
            pnsRemember(object)
            object.Text = newText
        end
    end

    apply()
    table.insert(publicNameSpoof.Conns, object:GetPropertyChangedSignal("Text"):Connect(apply))
end

local function pnsMonitorBillboard(billboard)
    for _, object in ipairs(billboard:GetDescendants()) do
        if object:IsA("TextLabel") then
            local function apply()
                local targetDisplay = pnsGetDisplay()
                if object.Text ~= targetDisplay then
                    pnsRemember(object)
                    object.Text = targetDisplay
                end
            end

            apply()
            table.insert(publicNameSpoof.Conns, object:GetPropertyChangedSignal("Text"):Connect(apply))
        end
    end

    table.insert(publicNameSpoof.Conns, billboard.DescendantAdded:Connect(function(object)
        if not publicNameSpoof.Enabled or not object:IsA("TextLabel") then return end
        pnsRemember(object)
        object.Text = pnsGetDisplay()
        table.insert(publicNameSpoof.Conns, object:GetPropertyChangedSignal("Text"):Connect(function()
            if object.Text ~= pnsGetDisplay() then
                pnsRemember(object)
                object.Text = pnsGetDisplay()
            end
        end))
    end))
end

local function pnsMonitorCharacter(character)
    local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
    if humanoid then
        local function applyHumanoid()
            local displayName3 = pnsGetDisplay()
            if humanoid.DisplayName ~= displayName3 then humanoid.DisplayName = displayName3 end
        end

        applyHumanoid()
        table.insert(publicNameSpoof.Conns, humanoid:GetPropertyChangedSignal("DisplayName"):Connect(applyHumanoid))
    end

    task.wait(0.3)
    if not publicNameSpoof.Enabled then return end
    for _, billboard in ipairs(character:GetDescendants()) do
        if billboard:IsA("BillboardGui") then
            pnsMonitorBillboard(billboard)
        end
    end
end

local function pnsEnable()
    if publicNameSpoof.Enabled then return end
    publicNameSpoof.Enabled = true

    for _, object in ipairs(lp2.PlayerGui:GetDescendants()) do
        pnsSpoofTextObject(object)
    end
    table.insert(publicNameSpoof.Conns, lp2.PlayerGui.DescendantAdded:Connect(pnsSpoofTextObject))

    pcall(function()
        local coreGui3 = game:GetService("CoreGui")
        for _, object in ipairs(coreGui3:GetDescendants()) do
            pnsSpoofTextObject(object)
        end
        table.insert(publicNameSpoof.Conns, coreGui3.DescendantAdded:Connect(pnsSpoofTextObject))
    end)

    if lp2.Character then task.spawn(pnsMonitorCharacter, lp2.Character) end
    table.insert(publicNameSpoof.Conns, lp2.CharacterAdded:Connect(function(character)
        if not publicNameSpoof.Enabled then return end
        task.wait(0.5)
        pnsMonitorCharacter(character)
    end))

    pcall(function()
        local realName = lp2.Name
        local realDisplay = lp2.DisplayName
        for _, object in ipairs(workspace:GetDescendants()) do
            if object:IsA("BillboardGui") then
                for _, textObject in ipairs(object:GetDescendants()) do
                    if textObject:IsA("TextLabel") then
                        local text = textObject.Text
                        if text:find(realName, 1, true) or text:find(realDisplay, 1, true) then
                            pnsMonitorBillboard(object)
                            break
                        end
                    end
                end
            end
        end

        table.insert(publicNameSpoof.Conns, workspace.DescendantAdded:Connect(function(object)
            if not publicNameSpoof.Enabled or not object:IsA("BillboardGui") then return end
            task.wait(0.3)
            if not publicNameSpoof.Enabled then return end
            for _, textObject in ipairs(object:GetDescendants()) do
                if textObject:IsA("TextLabel") then
                    local text = textObject.Text
                    if text:find(lp2.Name, 1, true) or text:find(lp2.DisplayName, 1, true) then
                        pnsMonitorBillboard(object)
                        break
                    end
                end
            end
        end))
    end)

    pcall(function()
        local textChatService = game:GetService("TextChatService")
        if textChatService.ChatVersion ~= Enum.ChatVersion.TextChatService then return end

        publicNameSpoof.PreviousIncomingMessage = textChatService.OnIncomingMessage
        publicNameSpoof.ChatCallback = function(message)
            local properties
            if publicNameSpoof.PreviousIncomingMessage then
                local success, result = pcall(publicNameSpoof.PreviousIncomingMessage, message)
                if success then properties = result end
            end
            if not properties then properties = Instance.new("TextChatMessageProperties") end
            if message.TextSource and message.TextSource.UserId == lp2.UserId then
                properties.PrefixText = pnsGetDisplay()
            end
            return properties
        end
        textChatService.OnIncomingMessage = publicNameSpoof.ChatCallback
    end)
end

local function pnsDisable()
    publicNameSpoof.Enabled = false
    for _, connection in ipairs(publicNameSpoof.Conns) do
        pcall(function() connection:Disconnect() end)
    end
    publicNameSpoof.Conns = {}

    for object, original in pairs(publicNameSpoof.Originals) do
        pcall(function()
            if object.Parent then object.Text = original end
        end)
        publicNameSpoof.Originals[object] = nil
    end

    pcall(function()
        local character = lp2.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid then humanoid.DisplayName = lp2.DisplayName end
    end)

    pcall(function()
        local textChatService = game:GetService("TextChatService")
        if textChatService.ChatVersion == Enum.ChatVersion.TextChatService
            and textChatService.OnIncomingMessage == publicNameSpoof.ChatCallback then
            textChatService.OnIncomingMessage = publicNameSpoof.PreviousIncomingMessage
        end
    end)
    publicNameSpoof.PreviousIncomingMessage = nil
    publicNameSpoof.ChatCallback = nil
end

