local function spoofLock(key, getObject, property, getValue, connections)
    if connections[key] then
        connections[key]:Disconnect()
        connections[key] = nil
    end
    connections[key .. "_active"] = true
    connections[key .. "_get"] = getObject
    connections[key .. "_property"] = property

    local function apply()
        pcall(function()
            local object = getObject()
            if not object then return end
            if connections[key .. "_original"] == nil then
                connections[key .. "_original"] = object[property]
            end
            local value = getValue()
            if object[property] ~= value then object[property] = value end
        end)
    end

    apply()
    pcall(function()
        local object = getObject()
        if object then
            connections[key] = object:GetPropertyChangedSignal(property):Connect(apply)
        end
    end)

    task.spawn(function()
        while connections[key .. "_active"] do
            task.wait(0.5)
            if not connections[key .. "_active"] then break end
            apply()
            if not connections[key] or not connections[key].Connected then
                pcall(function()
                    local object = getObject()
                    if object then
                        connections[key] = object:GetPropertyChangedSignal(property):Connect(apply)
                    end
                end)
            end
        end
    end)
end

local function spoofStop(key, connections)
    connections[key .. "_active"] = nil
    if connections[key] then
        connections[key]:Disconnect()
        connections[key] = nil
    end

    local getObject = connections[key .. "_get"]
    local property = connections[key .. "_property"]
    local original = connections[key .. "_original"]
    if getObject and property and original ~= nil then
        pcall(function()
            local object = getObject()
            if object then object[property] = original end
        end)
    end
    connections[key .. "_original"] = nil
    connections[key .. "_get"] = nil
    connections[key .. "_property"] = nil
end

