    return leaderstats and leaderstats:FindFirstChild("Level")
end

local function applyLeaderboardLevel()
    local level = getLeaderboardLevel()
    if level then pcall(function() level.Value = leaderboardSpoof.Value end) end
end

local function startLeaderboardSpoof()
    local level = getLeaderboardLevel()
    if level and leaderboardSpoof.Original == nil then
        leaderboardSpoof.Original = level.Value
    end

    applyLeaderboardLevel()

    if level then
        leaderboardSpoof.Connection = level:GetPropertyChangedSignal("Value"):Connect(function()
            if leaderboardSpoof.Enabled then task.defer(applyLeaderboardLevel) end
        end)
    end
end

local function stopLeaderboardSpoof()
    leaderboardSpoof.Enabled = false

    if leaderboardSpoof.Connection then
        leaderboardSpoof.Connection:Disconnect()
        leaderboardSpoof.Connection = nil
    end

    if leaderboardSpoof.Original ~= nil then
        local level = getLeaderboardLevel()
        if level then pcall(function() level.Value = leaderboardSpoof.Original end) end
        leaderboardSpoof.Original = nil
    end
end

