local function destroyVisualPool(pool)
    if not pool then return end
    for _, item in ipairs(pool.Rails) do
        if item.Adornment then item.Adornment:Destroy() end
        if item.ForceFieldMesh then item.ForceFieldMesh:Destroy() end
        if item.Shell then item.Shell:Destroy() end
        if item.Core then item.Core:Destroy() end
    end
    for _, marker in ipairs(pool.Bounces) do marker:Destroy() end
    if pool.Impact then pool.Impact:Destroy() end
    if pool.Indicator then
        if pool.Indicator.Body then pool.Indicator.Body:Destroy() end
        if pool.Indicator.Halo then pool.Indicator.Halo:Destroy() end
    end
    table.clear(pool.Rails)
    table.clear(pool.Bounces)
end

local function hideVisualPool(pool)
    if not pool then return end
    for _, item in ipairs(pool.Rails) do
        item.Shell.Transparency = 1
        item.Core.Transparency = 1
        if item.Adornment then item.Adornment.Visible = false end
    end
    for _, marker in ipairs(pool.Bounces) do marker.Transparency = 1 end
    pool.Impact.Transparency = 1
    pool.Indicator.Body.Transparency = 1
    pool.Indicator.Halo.Transparency = 1
end

local function ensureRail(pool, index)
    if not pool.Rails[index] then pool.Rails[index] = createRailItem() end
    return pool.Rails[index]
end

local function ensureMarker(markers, index)
