    return markers[index]
end

local function segmentCframe(pointA, pointB)
    local midpoint = pointA:Lerp(pointB, 0.5)
    return CFrame.lookAt(midpoint, pointB) * CFrame.Angles(0, math.pi * 0.5, 0)
end

local function applyRailShellStyle(item, color, transparency)
    local shell = item.Shell
    if config2.RailMaterial == "BoxHandleAdornment" then
        if item.ForceFieldMesh then
            item.ForceFieldMesh:Destroy()
            item.ForceFieldMesh = nil
        end

        local adornment = item.Adornment
        if not adornment or not adornment.Parent then
            if adornment then adornment:Destroy() end
            adornment = Instance.new("BoxHandleAdornment")
            adornment.Name = randomName("ra_")
            adornment.Adornee = shell
            adornment.CFrame = CFrame.identity
            adornment.AlwaysOnTop = true
            adornment.ZIndex = 10
            adornment.Parent = shell
            item.Adornment = adornment
        end

        adornment.Size = shell.Size
        adornment.Color3 = color
        adornment.Transparency = transparency
        adornment.Visible = true
        shell.Transparency = 1
    else
        if item.Adornment then
            item.Adornment:Destroy()
            item.Adornment = nil
        end
        shell.Material = resolveVisualMaterial(config2.RailMaterial, Enum.Material.Glass)
        shell.Color = color
        shell.Transparency = transparency

        if config2.RailMaterial == "ForceField" and config2.RailForceFieldAnimation ~= "Off" then
            local mesh = item.ForceFieldMesh
            if not mesh or not mesh.Parent then
                mesh = Instance.new("SpecialMesh")
                mesh.Name = "DrainGrenadeTrajectoryForceFieldMesh"
                mesh.MeshType = Enum.MeshType.Cylinder
                mesh.Scale = Vector3.new(1, 1, 1)
                mesh.Parent = shell
                item.ForceFieldMesh = mesh
            end
            mesh.TextureId = forcefieldAnimationTexture(config2.RailForceFieldAnimation)
        elseif item.ForceFieldMesh then
            item.ForceFieldMesh:Destroy()
            item.ForceFieldMesh = nil
        end
    end
end

local function placeRail(item, pointA, pointB, width, shellColor, coreColor, transparency)
    local length = (pointB - pointA).Magnitude
    if length <= 0.001 then
        item.Shell.Transparency = 1
        item.Core.Transparency = 1
        if item.Adornment then item.Adornment.Visible = false end
        return
    end

    local shellDiameter = math.max(width * 2.8, 0.09)
    local coreDiameter = math.max(width * 0.82, 0.025)
    local frame = segmentCframe(pointA, pointB)

    item.Shell.CFrame = frame
    item.Shell.Size = Vector3.new(length + shellDiameter * 0.42, shellDiameter, shellDiameter)
    applyRailShellStyle(
        item,
        shellColor,
        math.clamp(0.48 + transparency * 0.48, 0, 0.94)
    )

    item.Core.CFrame = frame
    item.Core.Size = Vector3.new(length + coreDiameter * 0.65, coreDiameter, coreDiameter)
    item.Core.Color = coreColor
    item.Core.Transparency = math.clamp(transparency * 0.55, 0, 0.88)
end

local function placeIndicator(indicator, position, direction, width, color)
    if direction.Magnitude <= 0.001 then
        indicator.Body.Transparency = 1
        indicator.Halo.Transparency = 1
        return
    end

    local frame = CFrame.lookAt(position, position + direction) * CFrame.Angles(0, math.pi * 0.5, 0)
    local diameter = math.max(width * 2.1, 0.18)
    local length = math.max(width * 5.2, 0.42)

    indicator.Body.CFrame = frame
    indicator.Body.Size = Vector3.new(length, diameter, diameter)
    indicator.Body.Color = color
    indicator.Body.Transparency = 0.02

    indicator.Halo.CFrame = frame
    indicator.Halo.Size = Vector3.new(length * 1.55, diameter * 1.8, diameter * 1.8)
    indicator.Halo.Color = color
    indicator.Halo.Transparency = 0.62
end

local function placeMarker(marker, position, size, color, transparency)
    marker.CFrame = CFrame.new(position)
    marker.Size = Vector3.new(size, size, size)
    marker.Color = color
    marker.Transparency = transparency
end

local function samplePath(points, spacing)
    if #points == 0 then return {} end
    if #points == 1 then return { points[1] } end

    local sampled = { points[1] }
    local distanceToNext = spacing

    for index = 1, #points - 1 do
        local pointA = points[index]
        local pointB = points[index + 1]
        local delta = pointB - pointA
        local length = delta.Magnitude
        if length > 0.0001 then
            local direction = delta / length
            local cursor = pointA
            local remaining = length
            while remaining >= distanceToNext do
                cursor += direction * distanceToNext
                table.insert(sampled, cursor)
                remaining -= distanceToNext
                distanceToNext = spacing
            end
            distanceToNext -= remaining
        end
    end

    local finalPoint = points[#points]
    if (sampled[#sampled] - finalPoint).Magnitude > 0.05 then
        table.insert(sampled, finalPoint)
    else
        sampled[#sampled] = finalPoint
    end

    if #sampled > config2.MaxVisualPoints then
        local compressed = table.create(config2.MaxVisualPoints)
        for index = 1, config2.MaxVisualPoints do
            local sourceIndex = math.floor(
                1 + ((index - 1) / (config2.MaxVisualPoints - 1)) * (#sampled - 1)
            )
            compressed[index] = sampled[sourceIndex]
        end
        compressed[config2.MaxVisualPoints] = finalPoint
        return compressed
    end
    return sampled
end

local function isHardCorner(points, index)
    if index <= 1 or index >= #points then return false end
    local incoming = points[index] - points[index - 1]
    local outgoing = points[index + 1] - points[index]
    if incoming.Magnitude <= 0.001 or outgoing.Magnitude <= 0.001 then return false end
    return incoming.Unit:Dot(outgoing.Unit) < 0.72
end

local function catmullRom(point0, point1, point2, point3, alpha)
    local alpha2 = alpha * alpha
    local alpha3 = alpha2 * alpha
    return (
        point1 * 2
        + (point2 - point0) * alpha
        + (point0 * 2 - point1 * 5 + point2 * 4 - point3) * alpha2
        + (point3 - point0 + (point1 - point2) * 3) * alpha3
    ) * 0.5
end

local function buildSplinePath(points)
    local controls = samplePath(points, 2.75)
    if #controls < 3 then return samplePath(points, 0.85) end

    local subdivisions = 3
    local smoothed = table.create((#controls - 1) * subdivisions + 1)
    for index = 1, #controls - 1 do
        local point0 = controls[math.max(index - 1, 1)]
        local point1 = controls[index]
        local point2 = controls[index + 1]
        local point3 = controls[math.min(index + 2, #controls)]
        local preserveCorner = isHardCorner(controls, index) or isHardCorner(controls, index + 1)

        for step = 0, subdivisions - 1 do
            local alpha = step / subdivisions
            local point = preserveCorner
                and point1:Lerp(point2, alpha)
                or catmullRom(point0, point1, point2, point3, alpha)
            table.insert(smoothed, point)
        end
    end
    table.insert(smoothed, controls[#controls])
    return samplePath(smoothed, 0.85)
end

local function measurePath(points)
    local length = 0
    for index = 1, #points - 1 do
        length += (points[index + 1] - points[index]).Magnitude
    end
    return length
end

local function pointOnPath(points, distance)
    local travelled = 0
    for index = 1, #points - 1 do
        local pointA = points[index]
        local pointB = points[index + 1]
        local delta = pointB - pointA
        local length = delta.Magnitude
        if length > 0.001 and travelled + length >= distance then
            local alpha = math.clamp((distance - travelled) / length, 0, 1)
            return pointA:Lerp(pointB, alpha), delta / length
        end
        travelled += length
    end

    local finalDelta = points[#points] - points[math.max(#points - 1, 1)]
    return points[#points], finalDelta.Magnitude > 0.001 and finalDelta.Unit or Vector3.new(0, 0, -1)
end

local function renderPath(points, pool, options)
    if not pool then return end
    if #points < 2 then
        hideVisualPool(pool)
        return
    end

    local sampled = buildSplinePath(points)
    local camera = options.ClipNearCamera and workspace2.CurrentCamera or nil
    local cameraPosition = camera and camera.CFrame.Position or nil
    local startColor = options.StartColor
    local endColor = options.EndColor or startColor
    local coreColor = options.CoreColor or startColor
    local width = options.Width
    local baseTransparency = options.Transparency or 0.1

    local railCount = 0
    for index = 1, #sampled - 1 do
        local pointA = sampled[index]
        local pointB = sampled[index + 1]
        if not cameraPosition
            or (pointA - cameraPosition).Magnitude > config2.CameraClipDistance
            or (pointB - cameraPosition).Magnitude > config2.CameraClipDistance then
            railCount += 1
            local ratio = (index - 0.5) / math.max(#sampled - 1, 1)
            local transparency = baseTransparency
            if options.FadeTail then
                transparency = math.clamp(baseTransparency + ((1 - ratio) * 0.72), 0, 0.95)
            end
            placeRail(
                ensureRail(pool, railCount),
                pointA,
                pointB,
                width,
                startColor:Lerp(endColor, ratio),
                coreColor,
                transparency
            )
        end
    end
    for index = railCount + 1, #pool.Rails do
        pool.Rails[index].Shell.Transparency = 1
        pool.Rails[index].Core.Transparency = 1
        if pool.Rails[index].Adornment then pool.Rails[index].Adornment.Visible = false end
    end

    if options.ShowIndicator then
        local totalLength = measurePath(sampled)
        if totalLength > 0.001 then
            local indicatorDistance = (os.clock() * config2.IndicatorSpeed) % totalLength
            local position, direction = pointOnPath(sampled, indicatorDistance)
            if not cameraPosition or (position - cameraPosition).Magnitude > config2.CameraClipDistance then
                placeIndicator(pool.Indicator, position, direction, width, options.IndicatorColor or coreColor)
            else
                pool.Indicator.Body.Transparency = 1
                pool.Indicator.Halo.Transparency = 1
            end
        end
    else
        pool.Indicator.Body.Transparency = 1
        pool.Indicator.Halo.Transparency = 1
    end

    local bouncePoints = options.Bounces or {}
    if options.ShowBounces then
        for index, point in ipairs(bouncePoints) do
            placeMarker(
                ensureMarker(pool.Bounces, index),
                point,
                math.max(width * 3.2, 0.2),
                endColor,
                0.05
            )
        end
        for index = #bouncePoints + 1, #pool.Bounces do pool.Bounces[index].Transparency = 1 end
    else
        for _, marker in ipairs(pool.Bounces) do marker.Transparency = 1 end
    end

    if options.ShowImpact then
        local pulse = 1 + (math.sin(os.clock() * 5) * 0.12)
        placeMarker(
            pool.Impact,
            points[#points],
            math.max(width * 5.5, 0.38) * pulse,
            endColor,
            0.08
        )
    else
        pool.Impact.Transparency = 1
    end
end

previewPool = newVisualPool()

local function getCharacter()
    return lp2.Character
end

local function getHead(character)
    return character and character:FindFirstChild("Head")
end

local function getAimPoint()
    local camera = workspace2.CurrentCamera
    if library2.IsMobile and camera then
        local viewport = camera.ViewportSize
        local success, centerRay = pcall(function()
            return camera:ViewportPointToRay(viewport.X * 0.5, viewport.Y * 0.5, 0)
        end)
        if success and centerRay and centerRay.Direction.Magnitude > 0.001 then
            local direction = centerRay.Direction.Unit
            return centerRay.Origin + direction * 1000, direction
        end

        local direction = camera.CFrame.LookVector
        return camera.CFrame.Position + direction * 1000, direction
    end

    local external = rawget(_G, "GetMousePoint")
    if type(external) == "function" then
        local success, point = pcall(external)
        if success and typeof(point) == "Vector3" then return point end
    end
    if mouse and mouse.Hit then return mouse.Hit.Position end
    return camera and (camera.CFrame.Position + camera.CFrame.LookVector * 500) or Vector3.zero
end

local function isThrowableTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local handle = tool:FindFirstChild("Handle")
    local rightGrip = tool:FindFirstChild("RightGrip")
    local grip = (handle and handle:IsA("BasePart") and handle)
        or (rightGrip and rightGrip:IsA("BasePart") and rightGrip)
    local event = tool:FindFirstChild("Event")
    local pin = tool:FindFirstChild("PinPulled")
    return grip ~= nil
        and event ~= nil
        and event:IsA("RemoteEvent")
        and pin ~= nil
        and pin:IsA("BoolValue")
        and tool:FindFirstChild("AnimsFolder") ~= nil
end

local function getGripPart(tool)
    local handle = tool:FindFirstChild("Handle")
    if handle and handle:IsA("BasePart") then return handle end
    local rightGrip = tool:FindFirstChild("RightGrip")
    if rightGrip and rightGrip:IsA("BasePart") then return rightGrip end
end

local function findServerScript(tool)
    for _, child in ipairs(tool:GetChildren()) do
        if child:IsA("Script") and child.Name:lower():find("server", 1, true) then
            return child
        end
    end
end

local function getScriptSource(scriptObject)
    if not scriptObject then return end
    local success, source = pcall(function() return scriptObject.Source end)
    if success and type(source) == "string" and #source > 0 then return source end
end

local function parseSettings(source)
    local settings = {}
    local startPosition = source:find("local Settings%s*=%s*{")
    if not startPosition then return settings end
    local braceStart = source:find("{", startPosition, true)
    if not braceStart then return settings end

    local depth = 0
    local braceEnd
    for index = braceStart, #source do
        local character = source:sub(index, index)
        if character == "{" then
            depth += 1
        elseif character == "}" then
            depth -= 1
            if depth == 0 then
                braceEnd = index
                break
            end
        end
    end
    if not braceEnd then return settings end

    local block = source:sub(braceStart + 1, braceEnd - 1)
    for key, rawValue in block:gmatch("([%a_][%w_]*)%s*=%s*([^;\n,]+)") do
        local cleanValue = rawValue:gsub("%-%-.*", ""):gsub("%s+", "")
        local numericValue = tonumber(cleanValue)
        if numericValue then settings[key] = numericValue end
    end
    return settings
end

local function evaluateExpression(expression, settings)
    if not expression then return end
    local rewritten = expression:gsub("Settings%.([%a_][%w_]*)", function(key)
        return settings[key] and tostring(settings[key]) or "0"
    end):gsub("%s+", "")
    if rewritten == "" then return end
    local direct = tonumber(rewritten)
    if direct then return direct end
    local left, operator, right = rewritten:match("^(%-?[%d%.]+)([%+%-%*/])(%-?[%d%.]+)$")
    left = tonumber(left)
    right = tonumber(right)
    if not (left and right and operator) then return end
    if operator == "+" then return left + right end
    if operator == "-" then return left - right end
    if operator == "*" then return left * right end
    if operator == "/" and right ~= 0 then return left / right end
end

local function analyzeToolProfile(tool)
    local profile = {
        mode = "fallback",
        throwSpeed = config2.ThrowSpeed,
        maxPredictTime = config2.PredictionTime,
        throwFuse = config2.FuseTime,
        pullFuse = nil,
        minFlight = 0,
        stopSpeed = nil,
        touchFuseDelay = nil,
        explodeOnTouch = false,
    }

    local handle = getGripPart(tool)
    local throwSoundId
    local hasAttachmentX = false
    local hasClickDetector = false
    local hasBouncePack = false
    local hasSingleBounce = false

    if tool:FindFirstChild("Lighter") then profile.explodeOnTouch = true end
    if handle then
        hasAttachmentX = handle:FindFirstChild("X") ~= nil
        hasClickDetector = handle:FindFirstChild("ClickDetector") ~= nil
        hasBouncePack = handle:FindFirstChild("Bounce1") ~= nil
        hasSingleBounce = handle:FindFirstChild("Bounce") ~= nil
        if handle:FindFirstChild("ExtinguishS")
            or handle:FindFirstChild("FireIdle")
            or handle:FindFirstChild("Spark")
            or handle:FindFirstChild("CanForce") then
            profile.explodeOnTouch = true
        end
        local throwSound = handle:FindFirstChild("Throw")
        if throwSound and throwSound:IsA("Sound") then
            throwSoundId = tostring(throwSound.SoundId)
            if throwSoundId:find("1657151608", 1, true) then profile.explodeOnTouch = true end
        end
    end

    local function applyStructuralFallback()
        if profile.explodeOnTouch then
            profile.mode = "fixed_after_pull"
            profile.pullFuse = tool:FindFirstChild("Lighter") and 5 or 7
            profile.maxPredictTime = tool:FindFirstChild("Lighter") and 3.5 or 6.25
            return
        end
        if hasBouncePack then
            profile.mode = "fixed_after_throw"
            if hasAttachmentX or hasClickDetector then
                profile.throwFuse = 2.5
            else
                profile.throwFuse = 1.8 + config2.ThrowDelaySafety
            end
            profile.maxPredictTime = profile.throwFuse
            return
        end
        if hasSingleBounce then
            if throwSoundId and throwSoundId:find("360521794", 1, true) then
                profile.mode = "until_slow"
                profile.minFlight = 0.75
                profile.stopSpeed = 4
                profile.maxPredictTime = 4.8
            else
                profile.mode = "fixed_after_throw"
                profile.throwFuse = 1.8 + config2.ThrowDelaySafety
                profile.maxPredictTime = profile.throwFuse
            end
        end
    end

    local source = getScriptSource(findServerScript(tool))
    if not source then
        applyStructuralFallback()
        return profile
    end

    local settings = parseSettings(source)
    if settings.VELOCITY then profile.throwSpeed = settings.VELOCITY end
    if source:find("Explode(Handle.CFrame,true)", 1, true)
        or source:find("Explode(Handle.CFrame,\"Water\")", 1, true)
        or source:find("Explode(\"Water\")", 1, true) then
        profile.explodeOnTouch = true
    end
    if source:find("delay(Settings.ExplodeTime - Settings.PullTime", 1, true) and settings.ExplodeTime then
        profile.mode = "fixed_after_pull"
        profile.pullFuse = settings.ExplodeTime
        profile.maxPredictTime = math.max(0.2, settings.ExplodeTime)
        return profile
    end
    if source:find("function DoTimer()", 1, true) and settings.ExplodeTime then
        profile.mode = "fixed_after_throw"
        profile.throwFuse = settings.ExplodeTime
        profile.maxPredictTime = math.max(0.2, settings.ExplodeTime)
        return profile
    end

    local minFlightExpression = source:match("fastWait%(([^%)]+)%)%s*[\r\n]+%s*repeat%s+fastWait")
    local stopSpeed = tonumber(source:match("until%s+Handle%.Velocity%.Magnitude%s*<=%s*([%d%.]+)"))
    local minFlight = evaluateExpression(minFlightExpression, settings)
    if stopSpeed and minFlight then
        profile.mode = "until_slow"
        profile.minFlight = math.max(0, minFlight)
        profile.stopSpeed = stopSpeed
        profile.maxPredictTime = stopSpeed <= 3 and 5.1 or 4.6
        return profile
    end

    local maximumDelay
    local minimumDelay
    for expression in source:gmatch("delay%(([^,]+),%s*function%s*%(") do
        local value = evaluateExpression(expression, settings)
        if value and value > 0 then
            maximumDelay = not maximumDelay and value or math.max(maximumDelay, value)
            minimumDelay = not minimumDelay and value or math.min(minimumDelay, value)
        end
    end
    if maximumDelay then
        profile.mode = "fixed_after_throw"
        profile.throwFuse = maximumDelay + config2.ThrowDelaySafety
        profile.maxPredictTime = math.max(0.2, profile.throwFuse)
        if minimumDelay and minimumDelay < maximumDelay then profile.touchFuseDelay = minimumDelay end
    else
        applyStructuralFallback()
    end
    return profile
end

local function isFirstPerson(head)
    local camera = workspace2.CurrentCamera
    return camera ~= nil and head ~= nil and (camera.CFrame.Position - head.Position).Magnitude <= 1.1
end

local function getSimulationWindow(state, now)
    local profile = state.profile or {}
    local maximumTime = profile.mode == "fallback"
        and config2.PredictionTime
        or profile.maxPredictTime
        or config2.PredictionTime
    local minimumFlight = 0
    local stopSpeed
    local touchFuseDelay = profile.touchFuseDelay
    local explodeOnTouch = profile.explodeOnTouch == true

    if profile.mode == "fixed_after_throw" then
        maximumTime = math.max(0.05, profile.throwFuse or config2.FuseTime)
    elseif profile.mode == "fixed_after_pull" then
        local heldTime = state.pinPulledAt and (now - state.pinPulledAt) or 0
        maximumTime = math.max(0.05, (profile.pullFuse or config2.FuseTime) - heldTime)
    elseif profile.mode == "until_slow" then
        minimumFlight = profile.minFlight or 0
        stopSpeed = profile.stopSpeed
    end

    if state.timerValue and state.timerValue > 0 then
        if state.timerIsCountdown then
            maximumTime = math.min(maximumTime, math.max(0.05, state.timerValue))
        elseif profile.mode == "fallback" then
            maximumTime = math.min(maximumTime, state.timerValue)
        end
    end
    maximumTime = math.min(maximumTime, config2.PredictionTime)
    return maximumTime, minimumFlight, stopSpeed, touchFuseDelay, explodeOnTouch
end

local function buildCastParams(tool)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.IgnoreWater = false
    pcall(function() params.RespectCanCollide = true end)

    local collisionGroup = rawget(_G, "CG_NCC")
    if type(collisionGroup) == "string" and collisionGroup ~= "" then
        pcall(function() params.CollisionGroup = collisionGroup end)
    end

    local filter = { visualFolder }
    local character = getCharacter()
    if character then table.insert(filter, character) end
    local charactersFolder = workspace2:FindFirstChild("Characters")
    if charactersFolder then table.insert(filter, charactersFolder) end
    if tool then table.insert(filter, tool) end
    params.FilterDescendantsInstances = filter
    return params
end

local function castWithRadius(origin, radius, direction, params)
    local success, result = pcall(function()
        return workspace2:Spherecast(origin, radius, direction, params)
    end)
    if success then return result end
    return workspace2:Raycast(origin, direction, params)
end

local function pushPoint(points, point)
    local previous = points[#points]
    if not previous then
        points[1] = point
    elseif (previous - point).Magnitude <= 0.01 then
        points[#points] = point
    else
        table.insert(points, point)
    end
end

local function simulateTrajectory(tool, state, now)
    local character = getCharacter()
    local head = getHead(character)
    if not head then return {}, {} end

    local startPosition = head.Position
    local aimPoint, cameraDirection = getAimPoint()
    local aimDelta = aimPoint - startPosition
    if not cameraDirection and aimDelta.Magnitude < 0.001 then return {}, {} end
    local direction = cameraDirection or aimDelta.Unit
    if grenadeHelper.Active and grenadeHelper.Direction then
        direction = grenadeHelper.Direction
    end
    local renderStart = startPosition
    if isFirstPerson(head) then renderStart = startPosition + direction * config2.FirstPersonOffset end

    local handle = state.handle
    if not handle or not handle.Parent then return {}, {} end
    local hitbox = handle:FindFirstChild("HB")
    local collisionPart = hitbox and hitbox:IsA("BasePart") and hitbox or handle
    local radius = math.max(collisionPart.Size.X, collisionPart.Size.Y, collisionPart.Size.Z) * 0.5
    local params = buildCastParams(tool)
    local profile = state.profile or {}
    local speed = state.learnedSpeed or profile.throwSpeed or config2.ThrowSpeed
    local gravity = Vector3.new(0, -workspace2.Gravity * config2.GravityScale, 0)
    local maximumTime, minimumFlight, stopSpeed, touchFuseDelay, explodeOnTouch =
        getSimulationWindow(state, now)

    local points = { renderStart }
    local bouncePoints = {}
    local position = startPosition
    local velocity = direction * speed
    local elapsed = 0
    local bounceCount = 0
    local dynamicMaximumTime = maximumTime

    while elapsed < dynamicMaximumTime and #points < config2.MaxPoints do
        local step = math.min(config2.SimulationStep, dynamicMaximumTime - elapsed)
        local displacement = velocity * step + 0.5 * gravity * step * step
        local hit = castWithRadius(position, radius, displacement, params)
        if hit and hit.Instance and hit.Instance ~= workspace2.Terrain and not hit.Instance.CanCollide then
            hit = nil
        end

        if hit then
            local travelDistance = displacement.Magnitude
            local alpha = travelDistance > 0.00001
                and math.clamp((hit.Position - position).Magnitude / travelDistance, 0, 1)
                or 1
            local hitTime = step * alpha
            local centerAtHit = hit.Position + hit.Normal * radius
            pushPoint(points, centerAtHit)
            table.insert(bouncePoints, centerAtHit)

            local impactVelocity = velocity + gravity * hitTime
            local normalSpeed = impactVelocity:Dot(hit.Normal)
            local normalVelocity = hit.Normal * normalSpeed
            local tangentVelocity = impactVelocity - normalVelocity

            if normalSpeed < 0 then
                local friction = state.surfaceFriction or 2
                local elasticity = state.surfaceElasticity or 0
                local upDot = math.abs(hit.Normal:Dot(Vector3.yAxis))
                local tangentDamping = math.clamp(
                    1 - friction * 0.15,
                    config2.MinTangentDamping,
                    config2.MaxTangentDamping
                )
                local restitution = math.clamp(
                    config2.MinRestitution + elasticity * 0.85,
                    config2.MinRestitution,
                    config2.MaxRestitution
                )
                if upDot > 0.75 then
                    tangentDamping *= 0.9
                    restitution *= 0.62
                elseif upDot < 0.35 then
                    tangentDamping *= 0.78
                    restitution *= 0.5
                else
                    tangentDamping *= 0.84
                    restitution *= 0.75
                end
                if impactVelocity.Magnitude <= config2.LowSpeedRestitutionCutoff then
                    restitution *= config2.LowSpeedRestitutionMultiplier
                end
                velocity = tangentVelocity * tangentDamping - normalVelocity * restitution
            else
                local tangentDamping = math.clamp(
                    1 - (state.surfaceFriction or 2) * 0.15,
                    config2.MinTangentDamping,
                    config2.MaxTangentDamping
                )
                velocity = impactVelocity * tangentDamping
            end

            position = centerAtHit + hit.Normal * 0.02
            if explodeOnTouch then
                dynamicMaximumTime = math.min(dynamicMaximumTime, elapsed + hitTime + 0.02)
                break
            end
            if touchFuseDelay then
                dynamicMaximumTime = math.min(dynamicMaximumTime, elapsed + hitTime + touchFuseDelay)
            end
            bounceCount += 1
            if bounceCount >= config2.MaxBounces then break end
        else
            position += displacement
            velocity += gravity * step
            pushPoint(points, position)
        end

        elapsed += step
        if velocity.Magnitude <= config2.MinSpeed then break end
        if stopSpeed and elapsed >= minimumFlight and velocity.Magnitude <= stopSpeed then break end
    end
    return points, bouncePoints
end

local function addTool(tool)
    if toolStates[tool] or not isThrowableTool(tool) then return end
    local pin = tool:FindFirstChild("PinPulled")
    local timerObject = pin and pin:FindFirstChild("Timer")
    local handle = getGripPart(tool)
    local hitbox = handle and handle:FindFirstChild("HB")
    local collisionPart = hitbox and hitbox:IsA("BasePart") and hitbox or handle
    local friction = 2
    local elasticity = 0

    if collisionPart and collisionPart:IsA("BasePart") then
        local properties = collisionPart.CustomPhysicalProperties
        if properties then
            friction = properties.Friction
            elasticity = properties.Elasticity
        end
    end

    local timerValue = timerObject and timerObject:IsA("NumberValue") and timerObject.Value or nil
    local profile = analyzeToolProfile(tool)
    toolStates[tool] = {
        tool = tool,
        handle = handle,
        pin = pin,
        timerObject = timerObject,
        timerValue = timerValue,
        lastTimerValue = timerValue,
        timerIsCountdown = false,
        lastPin = pin and pin.Value or false,
        pinPulledAt = pin and pin.Value and os.clock() or nil,
        flightStarted = false,
        profile = profile,
        surfaceFriction = friction,
        surfaceElasticity = elasticity,
        learnedSpeed = profile and profile.throwSpeed or nil,
    }
end

local function startFlight(state)
    local handle = state.handle
    if not handle or not handle:IsA("BasePart") or activeByPart[handle] then return end
    local flight = {
        part = handle,
        points = {},
        pool = newVisualPool(),
        lastSample = 0,
        startedAt = os.clock(),
    }
    activeByPart[handle] = flight
    table.insert(activeFlights, flight)

    local currentSpeed = handle.AssemblyLinearVelocity.Magnitude
    if currentSpeed > 40 then
        local baseSpeed = state.profile and state.profile.throwSpeed or config2.ThrowSpeed
        state.learnedSpeed = math.clamp(currentSpeed, baseSpeed * 0.85, baseSpeed * 1.2)
    end
end

local function cleanupFlight(index)
    local flight = activeFlights[index]
    if not flight then return end
    activeByPart[flight.part] = nil
    destroyVisualPool(flight.pool)
    table.remove(activeFlights, index)
end

local function getEquippedThrowable()
    local character = getCharacter()
    if not character then return end
    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Tool") and toolStates[child] then return child end
    end
end

local function grenadeHelperKeyActive()
    local key = options2.MiscGrenadeHelperKey
    if not key or key.Value == "None" then return true end
    return key:GetState()
end

local function grenadeHelperResolveVelocity(origin, goal, speed, gravity)
    local displacement = goal - origin
    local horizontal = Vector3.new(displacement.X, 0, displacement.Z)
    local horizontalDistance = horizontal.Magnitude
    if horizontalDistance <= 0.001 or speed <= 0 or gravity <= 0 then return nil end

    local speedSquared = speed * speed
    local discriminant = speedSquared * speedSquared
        - gravity * (gravity * horizontalDistance * horizontalDistance + 2 * displacement.Y * speedSquared)
    if discriminant < 0 then return nil end

    local theta = math.atan((speedSquared + math.sqrt(discriminant)) / (gravity * horizontalDistance))
    return horizontal.Unit * (speed * math.cos(theta)) + Vector3.new(0, speed * math.sin(theta), 0)
end

local function grenadeHelperFindTarget(origin, cameraLook)
    local bestPlayer
    local bestAngle = math.huge
    local maxAngle = math.rad(grenadeHelper.FOV) / 2

    for _, player in ipairs(plrs:GetPlayers()) do
        if player == lp2 or getPlayerStatus(player) == "Friendly" then continue end
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not root or not humanoid or humanoid.Health <= 0 or character:FindFirstChildOfClass("ForceField") then continue end

        local delta = root.Position - origin
        if delta.Magnitude <= 0.001 then continue end
        local angle = math.acos(math.clamp(cameraLook:Dot(delta.Unit), -1, 1))
        if angle <= maxAngle and angle < bestAngle then
            bestAngle = angle
            bestPlayer = player
        end
    end

    return bestPlayer
end

local function grenadeHelperUpdate(deltaTime)
    grenadeHelper.Active = grenadeHelper.Enabled and not library2.MenuOpen and grenadeHelperKeyActive()
    grenadeHelper.Direction = nil
    grenadeHelper.Target = nil
    if not grenadeHelper.Active then return end

    local camera = workspace.CurrentCamera or cam2
    local character = getCharacter()
    local head = getHead(character)
    local tool = getEquippedThrowable()
    if not camera or not head or not tool then return end

    local state = toolStates[tool]
    local profile = state and state.profile or nil
    local speed = (state and state.learnedSpeed) or (profile and profile.throwSpeed) or config2.ThrowSpeed
    local target = grenadeHelperFindTarget(head.Position, camera.CFrame.LookVector)
    if not target then return end

    local root = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
    if not root then return end

    local goal = root.Position - Vector3.new(0, 3.5, 0)
    if grenadeHelper.AdjustMovement then
        local ping = 0
        pcall(function() ping = stats2.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000 end)
        local travel = (head.Position - goal).Magnitude / math.max(speed, 1) + ping / 2
        local velocity = root.AssemblyLinearVelocity
        goal += Vector3.new(velocity.X, 0, velocity.Z) * travel
    end

    local velocity = grenadeHelperResolveVelocity(
        head.Position,
        goal,
        speed,
        workspace2.Gravity * config2.GravityScale
    )
    if not velocity or velocity.Magnitude <= 0.001 then return end

    grenadeHelper.Target = target
    grenadeHelper.Direction = velocity.Unit

    if grenadeHelper.AutomaticAim then
        local alpha = math.clamp((grenadeHelper.Speed / 10) * deltaTime, 0, 1)
        camera.CFrame = camera.CFrame:Lerp(
            CFrame.lookAt(camera.CFrame.Position, camera.CFrame.Position + grenadeHelper.Direction),
            alpha
        )
    end
end

local function scanTools()
    local backpack = lp2:FindFirstChildOfClass("Backpack")
    if backpack then
        for _, child in ipairs(backpack:GetChildren()) do addTool(child) end
    end
    local character = getCharacter()
    if character then
        for _, child in ipairs(character:GetChildren()) do addTool(child) end
    end
end

local function extractFlightPositions(points)
    local positions = table.create(#points)
    for index, point in ipairs(points) do positions[index] = point.Position end
    return positions
end

local function clearRuntimeVisuals()
    hideVisualPool(previewPool)
    for index = #activeFlights, 1, -1 do cleanupFlight(index) end
end

startRenderer = function()
    if renderConnection then return end
    renderConnection = rs2.RenderStepped:Connect(function(deltaTime)
        if not enabled and not grenadeHelper.Enabled then return end
        local now = os.clock()
        grenadeHelperUpdate(deltaTime)

        if now >= nextToolScan then
            scanTools()
            nextToolScan = now + 0.4
        end

        local character = getCharacter()
        for tool, state in pairs(toolStates) do
            local pin = state.pin
            if pin and pin.Parent and pin.Value ~= state.lastPin then
                state.lastPin = pin.Value
                if pin.Value then
                    state.pinPulledAt = now
                else
                    state.pinPulledAt = nil
                    state.flightStarted = false
                    state.timerIsCountdown = false
                    if state.timerObject and state.timerObject:IsA("NumberValue") then
                        state.lastTimerValue = state.timerObject.Value
                        state.timerValue = state.timerObject.Value
                    end
                end
            end

            if (not state.timerObject or not state.timerObject.Parent) and pin and pin.Parent then
                local timerObject = pin:FindFirstChild("Timer")
                if timerObject and timerObject:IsA("NumberValue") then state.timerObject = timerObject end
            end

            local timerObject = state.timerObject
            if timerObject and timerObject.Parent and timerObject:IsA("NumberValue") then
                local currentTimer = timerObject.Value
                if state.lastTimerValue and currentTimer < state.lastTimerValue - 0.01 then
                    state.timerIsCountdown = true
                end
                state.timerValue = currentTimer
                state.lastTimerValue = currentTimer
            else
                state.timerValue = nil
            end

            local handle = state.handle
            if handle and handle.Parent then
                if handle:IsDescendantOf(tool) then
                    state.flightStarted = false
                elseif not state.flightStarted
                    and handle:IsDescendantOf(workspace2)
                    and (not character or not handle:IsDescendantOf(character))
                    and handle.AssemblyLinearVelocity.Magnitude > config2.FlightStartSpeed then
                    state.flightStarted = true
                    startFlight(state)
                    if previewTool == tool then
                        previewTool = nil
                        hideVisualPool(previewPool)
                    end
                end
            end

            if not tool:IsDescendantOf(game)
                and (not handle or not handle:IsDescendantOf(workspace2)) then
                if previewTool == tool then previewTool = nil end
                toolStates[tool] = nil
            end
        end

        local equipped = getEquippedThrowable()
        if equipped ~= previewTool then
            previewTool = equipped
            lastPreviewTick = 0
        end

        local previewRequested = enabled or (grenadeHelper.Active and grenadeHelper.Direction ~= nil)
        if previewRequested and previewTool and now - lastPreviewTick >= config2.PreviewInterval then
            local state = toolStates[previewTool]
            if state then
                local points, bouncePoints = simulateTrajectory(previewTool, state, now)
                renderPath(points, previewPool, {
                    StartColor = config2.PreviewColor,
                    EndColor = config2.ImpactColor,
                    CoreColor = config2.CoreColor,
                    IndicatorColor = config2.IndicatorColor,
                    Width = config2.Thickness,
                    Transparency = 0.08,
                    ClipNearCamera = true,
                    ShowIndicator = config2.ShowIndicator,
                    ShowImpact = config2.ShowImpact,
                    ShowBounces = config2.ShowBounces,
                    Bounces = bouncePoints,
                })
            end
            lastPreviewTick = now
        elseif not previewRequested or not previewTool then
            hideVisualPool(previewPool)
        end

        for index = #activeFlights, 1, -1 do
            local flight = activeFlights[index]
            local part = flight.part
            if not part
                or not part.Parent
                or not part:IsDescendantOf(workspace2)
                or now - flight.startedAt > config2.MaxLiveTime then
                cleanupFlight(index)
            else
                if now - flight.lastSample >= config2.LiveSampleStep then
                    flight.lastSample = now
                    table.insert(flight.points, { Position = part.Position, Time = now })
                end
                while #flight.points > 0 and now - flight.points[1].Time > config2.LiveLifetime do
                    table.remove(flight.points, 1)
                end

                if #flight.points <= 1
                    and part.AssemblyLinearVelocity.Magnitude < 1.2
                    and now - flight.startedAt > 0.25 then
                    cleanupFlight(index)
                elseif config2.ShowLiveTrail then
                    renderPath(extractFlightPositions(flight.points), flight.pool, {
                        StartColor = config2.LiveColor,
                        EndColor = config2.LiveColor,
                        CoreColor = config2.LiveColor,
                        Width = config2.Thickness,
                        Transparency = 0.05,
                        FadeTail = true,
                        ShowIndicator = false,
                        ShowImpact = false,
                        ShowBounces = false,
                    })
                else
                    hideVisualPool(flight.pool)
                end
            end
        end
    end)
    library2:GiveSignal(renderConnection)
end

