local finishAura = {
    Enabled    = false,
    Connection = nil,
    Range      = 7,
}

local function finishAuraHasMarkedEnemies()
    if not (playerlist and playerlist.Players) then return false end
    for _, entry in pairs(playerlist.Players) do
        if entry.Priority and entry.Priority.Text == "Enemy" then
            return true
        end
    end
    return false
end

local function finishAuraIsValidTarget(player, hasEnemies)
    local status = getPlayerStatus(player)
    if hasEnemies then
        return status == "Enemy"
    end
    return status ~= "Friendly"
end

local function finishAuraEnable()
    if finishAura.Enabled then return end
    finishAura.Enabled = true

    finishAura.Connection = rs2.RenderStepped:Connect(function()
        if not finishAura.Enabled then return end

        local localChar = lp2.Character
        local localHrp   = localChar and localChar:FindFirstChild("HumanoidRootPart")
        local tool        = localChar and localChar:FindFirstChildOfClass("Tool")
        if not (localHrp and tool) then return end

        local events      = repSt:FindFirstChild("Events")
        local invokeEvent = events and events:FindFirstChild("XMHH.2")
        local fireEvent   = events and events:FindFirstChild("XMHH2.2")
        if not (invokeEvent and fireEvent) then return end

        local hasEnemies = finishAuraHasMarkedEnemies()

        for _, player in ipairs(plrs:GetPlayers()) do
            if player ~= lp2 and finishAuraIsValidTarget(player, hasEnemies) then
                local targetChar = player.Character
                local targetHrp  = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                local targetHead = targetChar and targetChar:FindFirstChild("Head")
                local targetHumanoid2 = targetChar and targetChar:FindFirstChildOfClass("Humanoid")
                local charStats2  = repSt:FindFirstChild("CharStats")
                local statEntry  = charStats2 and charStats2:FindFirstChild(player.Name)
                local downedValue = statEntry and statEntry:FindFirstChild("Downed")

                if targetHrp and targetHead and targetHumanoid2 and downedValue
                    and (localHrp.Position - targetHrp.Position).Magnitude <= finishAura.Range
                    and targetHumanoid2.Health > 0
                    and downedValue.Value == true
                then
                    local invokeResult = invokeEvent:InvokeServer(
                        LPH_ENCSTR("\240\159\141\158"), tick(), tool, "EXECQX"
                    )
                    task.wait(0.25)
                    fireEvent:FireServer(
                        LPH_ENCSTR("\240\159\141\158"), tick(), tool, "2389ZFX34", invokeResult, false,
                        localChar:FindFirstChild("Right Leg"), targetHead, targetChar,
                        targetHead.Position, targetHead.Position
                    )
                end
            end
        end
    end)
end

local function finishAuraDisable()
    if not finishAura.Enabled then return end
    finishAura.Enabled = false

    if finishAura.Connection then
        finishAura.Connection:Disconnect()
        finishAura.Connection = nil
    end
end

miscSection:AddToggle('MiscFinishAura', {
    Text = "Finish Aura",
    Default  = false,
    Warn     = true,
    Callback = function(state)
        if state then finishAuraEnable() else finishAuraDisable() end
    end,
})

local meleeAura = {
    Enabled    = false,
    Connection = nil,
    Toggle     = nil,
    Range      = 20,
    Cooldown   = 0.35,
    MinHealth  = 15,
    Busy       = false,
    LastSwing  = 0,
}

meleeAura.PickTarget = function(localHrp, hasEnemies)
    local bestChar, bestDist

    for _, player in ipairs(plrs:GetPlayers()) do
        if player ~= lp2 and finishAuraIsValidTarget(player, hasEnemies) then
            local targetChar = player.Character
            local targetHrp  = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
            local targetHead = targetChar and targetChar:FindFirstChild("Head")
            local targetHumanoid2 = targetChar and targetChar:FindFirstChildOfClass("Humanoid")

            if targetHrp and targetHead and targetHumanoid2
                and targetHumanoid2.Health > meleeAura.MinHealth
                and not targetChar:FindFirstChildOfClass("ForceField")
            then
                local dist = (localHrp.Position - targetHrp.Position).Magnitude
                if dist <= meleeAura.Range and (not bestDist or dist < bestDist) then
                    bestChar, bestDist = targetChar, dist
                end
            end
        end
    end

    return bestChar
end

meleeAura.Swing = function(targetChar)
    local localChar  = lp2.Character
    local localHrp   = localChar and localChar:FindFirstChild("HumanoidRootPart")
    local tool        = localChar and localChar:FindFirstChildOfClass("Tool")
    local targetHead = targetChar:FindFirstChild("Head")
    if not (localHrp and tool and targetHead) then return end

    local events       = repSt:FindFirstChild("Events")
    local invokeEvent = events and events:FindFirstChild("XMHH.2")
    local fireEvent   = events and events:FindFirstChild("XMHH2.2")
    if not (invokeEvent and fireEvent) then return end

    local invokeResult = invokeEvent:InvokeServer("\240\159\141\158", tick(), tool, "43TRFWX", "Normal", tick(), true)
    task.wait(0.3)

    if not meleeAura.Enabled then return end

    localChar = lp2.Character
    localHrp  = localChar and localChar:FindFirstChild("HumanoidRootPart")
    tool       = localChar and localChar:FindFirstChildOfClass("Tool")
    if not (localHrp and tool) then return end
    if not (targetChar.Parent and targetHead.Parent) then return end

    local handle = tool:FindFirstChild("WeaponHandle")
        or tool:FindFirstChild("Handle")
        or localChar:FindFirstChild("Right Arm")
    if not handle then return end

    fireEvent:FireServer("\240\159\141\158", tick(), tool, "2389ZFX34", invokeResult, false, handle, targetHead, targetChar, localHrp.Position, targetHead.Position)
end

meleeAura.Disable = function()
    if not meleeAura.Enabled then return end
    meleeAura.Enabled = false
    meleeAura.Busy = false

    if meleeAura.Connection then
        meleeAura.Connection:Disconnect()
        meleeAura.Connection = nil
    end
end

meleeAura.Enable = function()
    if meleeAura.Enabled then return end
    meleeAura.Enabled = true

    meleeAura.Connection = rs2.RenderStepped:Connect(function()
        if not meleeAura.Enabled or meleeAura.Busy then return end

        local now = os.clock()
        if now - meleeAura.LastSwing < meleeAura.Cooldown then return end

        local localChar = lp2.Character
        local localHrp  = localChar and localChar:FindFirstChild("HumanoidRootPart")
        local tool       = localChar and localChar:FindFirstChildOfClass("Tool")
        if not (localHrp and tool) then return end

        local targetChar = meleeAura.PickTarget(localHrp, finishAuraHasMarkedEnemies())
        if not targetChar then return end

        meleeAura.LastSwing = now
        meleeAura.Busy = true

        task.spawn(function()
            pcall(meleeAura.Swing, targetChar)
            meleeAura.Busy = false
        end)
    end)
end

library2:OnUnload(function()
    meleeAura.Disable()
end)

