-- // вообще хуйня и тестовый
local meleeSpoof = {
    Enabled = false,
    Hitbox = "Head",
    Hooked = setmetatable({}, { __mode = "k" }),
    Conns = {},
}

meleeSpoof.Hook = function(tool)
    if meleeSpoof.Hooked[tool] then return end
    if type(getconnections) ~= "function" or type(getupvalues) ~= "function"
        or type(hookfunction) ~= "function" then
        return
    end

    local ok = pcall(function()
        for _, conn in ipairs(getconnections(tool.Activated)) do
            local fn = conn.Function
            if fn and (type(islclosure) ~= "function" or islclosure(fn)) then
                local env = getupvalues(fn)[1]
                local handler = typeof(env) == "userdata" and env.HZ45598425 or nil
                if handler then
                    meleeSpoof.Hooked[tool] = true

                    local original
                    original = hookfunction(handler, function(part, character, ...)
                        if meleeSpoof.Enabled and character then
                            local spoofed = character:FindFirstChild(meleeSpoof.Hitbox)
                            if spoofed then part = spoofed end
                        end
                        return original(part, character, ...)
                    end)
                    return
                end
            end
        end
    end)

    return ok
end

meleeSpoof.Scan = function()
    local char = lp2.Character
    if not char then return end

    for _, item in ipairs(char:GetChildren()) do
        if item:IsA("Tool") then meleeSpoof.Hook(item) end
    end
    if lp2:FindFirstChild("Backpack") then
        for _, item in ipairs(lp2.Backpack:GetChildren()) do
            if item:IsA("Tool") then meleeSpoof.Hook(item) end
        end
    end
end

meleeSpoof.Stop = function()
    for _, conn in ipairs(meleeSpoof.Conns) do
        pcall(function() conn:Disconnect() end)
    end
    table.clear(meleeSpoof.Conns)
end

miscSection:AddToggle('MiscMeleeSpoof', {
    Text = "Melee Silent",
    Default = false,
    Warn     = true,
    Tooltip = "Registers melee hits on the chosen hitbox instead of the part you actually hit.",
    Callback = function(state)
        meleeSpoof.Enabled = state
        meleeSpoof.Stop()
        if not state then return end

        meleeSpoof.Scan()

        local char = lp2.Character
        if char then
            meleeSpoof.Conns[#meleeSpoof.Conns + 1] = char.ChildAdded:Connect(function(item)
                if item:IsA("Tool") then meleeSpoof.Hook(item) end
            end)
        end
        meleeSpoof.Conns[#meleeSpoof.Conns + 1] = lp2.CharacterAdded:Connect(function()
            task.wait(1)
            if meleeSpoof.Enabled then meleeSpoof.Scan() end
        end)
    end,
})

