-- // сайлент через рейкаст (а не спуф)
local meleeSilent = {
    Enabled     = false,
    FOV         = 15,
    OldNamecall = nil,
    HitParts    = { Head = true },
    PartGroups  = {
        Head  = { "Head" },
        Body  = { "Torso", "UpperTorso", "LowerTorso" }, -- вообше нужны онли р6 костии нуу
        Arms  = { "Right Arm", "Left Arm", "RightUpperArm", "LeftUpperArm", "RightLowerArm", "LeftLowerArm" },
        Legs  = { "Right Leg", "Left Leg", "RightUpperLeg", "LeftUpperLeg", "RightLowerLeg", "LeftLowerLeg" },
    },
}

meleeSilent.GetParts = function()
    local parts = {}
    for group, enabled in pairs(meleeSilent.HitParts) do
        if enabled then
            for _, name in ipairs(meleeSilent.PartGroups[group] or {}) do
                parts[#parts + 1] = name
            end
        end
    end
    return parts
end

meleeSilent.Install = function()
    if meleeSilent.OldNamecall then return end
    if not hookmetamethod or not getnamecallmethod then return end

    local mt = getrawmetatable(game)
    local old
    old = hookmetamethod(game, "__namecall", function(self, ...)
        if not meleeSilent.Enabled then return old(self, ...) end

        local method = getnamecallmethod()
        if method ~= "Raycast" then return old(self, ...) end

  -- //
        local caller = getcallingscript and getcallingscript()
        if not caller or caller.Name ~= "Client" then return old(self, ...) end

        local args = { ... }
        local origin = args[1]
        if typeof(origin) ~= "Vector3" then return old(self, ...) end

        local cam = workspace.CurrentCamera
        if not cam then return old(self, ...) end

        local camCf     = cam.CFrame
        local camPos    = camCf.Position
        local lookVec   = camCf.LookVector
        local fovCos    = math.cos(math.rad(meleeSilent.FOV))

        local targetParts = meleeSilent.GetParts()
        if #targetParts == 0 then return old(self, ...) end

        local bestDot  = -1
        local bestPos  = nil

        for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
            if player == lp2 then continue end
            local char = player.Character
            if not char then continue end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum or hum.Health <= 0 then continue end
            if char:FindFirstChildOfClass("ForceField") then continue end
            if getPlayerStatus and getPlayerStatus(player) == "Friendly" then continue end

            for _, partName in ipairs(targetParts) do
                local part = char:FindFirstChild(partName)
                if not part then continue end

                local dir = part.Position - camPos
                local mag = dir.Magnitude
                if mag > 30 then continue end -- // <30 = useless

                local dotVal = lookVec:Dot(dir / mag)
                if dotVal < fovCos then continue end

                if dotVal > bestDot then
                    bestDot = dotVal
                    bestPos = part.Position
                end
            end
        end

        if bestPos then
            args[2] = (bestPos - origin).Unit * 1000
            return old(self, table.unpack(args))
        end

        return old(self, ...)
    end)

    meleeSilent.OldNamecall = old
end

meleeSilent.Uninstall = function()
    if not meleeSilent.OldNamecall then return end
    if not hookmetamethod then return end
    pcall(function()
        hookmetamethod(game, "__namecall", meleeSilent.OldNamecall)
    end)
    meleeSilent.OldNamecall = nil
end

miscSection:AddToggle('MiscMeleeSilent', {
    Text    = "Melee Silent Aim",
