    local controlTools = {
        ["C4"] = true, ["RPG-7"] = true, ["RPG-29"] = true, ["M320-1"] = true,
        ["SCAR-H-X"] = true, ["SBL-MK3"] = true, ["HL-MK3"] = true, ["A-HL-MK3"] = true,
        ["A-HL-MK4"] = true, ["HL-MK2"] = true, ["FireworkLauncher"] = true,
        ["A-FW-L"] = true, ["HallowsLauncher"] = true, ["AT4"] = true, ["AT4_"] = true,
        ["Panzerfaust-3"] = true, ["AUTO-PANZER"] = true, ["RPG-18"] = true,
        ["FlareGun"] = true, ["Plasma-Rocket-Launcher"] = true,
    }

    local controlProjectiles = {
        ["TransIgnore"] = true, ["RPG_Rocket"] = true, ["GrenadeLauncherGrenade"] = true,
        ["SBL_Rocket"] = true, ["Hallows_Rocket3"] = true, ["A_Hallows_Rocket3"] = true,
        ["Hallows_Rocket2"] = true, ["FireworkLauncher_Rocket"] = true,
        ["Hallows_Rocket"] = true, ["AT4_Rocket"] = true, ["Flare_Rocket"] = true,
        ["Rpg18"] = true, ["_B__RPG_Rocket"] = true, ["_B__RPG_Rocket2"] = true,
    }

    local forward, sideways = 0, 0
    local currentObject, bodyVelocity, bodyGyro
    local lookDir, followPos, yaw, pitch
    local camOverridden, savedSubject, savedCFrame, savedMouseBehavior, savedMouseIcon
    local recentShots = {}
    local shotConns, c4ToolConn, c4Remote = {}, nil, nil
    local charChildConn
    local teleportLock, handledProjectiles = nil, setmetatable({}, { __mode = "k" })
    local autoTpDeadline = 0

    local wallbangParents, wallbangApplied, wallbangSuppressed, wallbangTick = {}, false, false, 0
    local wallbangTargets, wallbangSeen, wallbangScanAt = {}, {}, 0
    local cachedMapPart

    local function holdingControlTool()
        local char = lp2.Character
        if char then
            for _, child in ipairs(char:GetChildren()) do
                if child:IsA("Tool") and controlTools[child.Name] then return true end
            end
        end
        local bp = lp2:FindFirstChildOfClass("Backpack")
        if bp then
            for _, child in ipairs(bp:GetChildren()) do
                if child:IsA("Tool") and controlTools[child.Name] then return true end
            end
        end
        return false
    end

    local function wallbangWanted()
        return noclipEnabled and not wallbangSuppressed
    end

    local wallbangMapFolders = { "ATMz", "BredMakurz", "Doors", "MysteryBoxes",
        "StreetLights", "ProximityShops", "SpawnedSupplyPlanes", "VendingMachines" }

    local function setParent(inst, parent)
        inst.Parent = parent
    end

    local function addWallbangTarget(inst)
        if inst and not wallbangSeen[inst] then
            wallbangSeen[inst] = true
            wallbangTargets[#wallbangTargets + 1] = inst
        end
    end


    local function scanWallbangTargets()
        local filter = workspace:FindFirstChild("Filter")
        if filter then
            addWallbangTarget(filter:FindFirstChild("Snow"))
            addWallbangTarget(filter:FindFirstChild("WaterCurrents"))
            local parts = filter:FindFirstChild("Parts")
            if parts then
                for _, item in ipairs(parts:GetChildren()) do
                    if item.Name ~= "AA_COPYRIGHT" then addWallbangTarget(item) end
                end
            end
        end

        local map = workspace:FindFirstChild("Map")
        if map then
            for _, name in ipairs(wallbangMapFolders) do
                addWallbangTarget(map:FindFirstChild(name))
            end
            local parts = map:FindFirstChild("Parts")
            if parts then
                for _, item in ipairs(parts:GetChildren()) do
                    if item.Name ~= "AA_COPYRIGHT" then addWallbangTarget(item) end
                end
            end
        end
    end

    local function syncWallbang(on)
        local characters = workspace:FindFirstChild("Characters")
        if on then
            if not characters then return end

            if os.clock() - wallbangScanAt >= 5 then
                wallbangScanAt = os.clock()
                scanWallbangTargets()
            end

            for i = 1, #wallbangTargets do
                local target = wallbangTargets[i]
                if target and target.Parent and target.Parent ~= characters then
                    if wallbangParents[target] == nil then wallbangParents[target] = target.Parent end
                    pcall(setParent, target, characters)
                end
            end
            wallbangApplied = true
            return
        end

        for target, parent in pairs(wallbangParents) do
            if target and target.Parent and parent and parent.Parent and target.Parent ~= parent then
                pcall(setParent, target, parent)
            end
        end
        table.clear(wallbangParents)
        table.clear(wallbangTargets)
        table.clear(wallbangSeen)
        wallbangScanAt = 0
        wallbangApplied = false
    end

    local function ensureCamera()
        local cam = workspace.CurrentCamera
        if not cam then return false end
        if not camOverridden then
            savedSubject = cam.CameraSubject
            savedCFrame = cam.CFrame
            savedMouseBehavior = uis.MouseBehavior
            savedMouseIcon = uis.MouseIconEnabled
            camOverridden = true
        end
        cam.CameraType = Enum.CameraType.Scriptable
        uis.MouseBehavior = Enum.MouseBehavior.LockCenter
        uis.MouseIconEnabled = false
        return true
    end

    local function handsFree()
        return autoTeleport
    end

    local function applyCameraFrame()
        if not currentObject or not lookDir then return end
        local cam = workspace.CurrentCamera
        if not cam then return end
        cam.CameraType = Enum.CameraType.Scriptable

        local cf
        if not pcall(function() cf = currentObject.CFrame end) or not cf then return end

        local desired = cf.Position - lookDir * 7 + Vector3.new(0, 2.4, 0)
        followPos = followPos and followPos:Lerp(desired, 0.25) or desired
        cam.CFrame = CFrame.lookAt(followPos, cf.Position + lookDir * 18 + Vector3.new(0, 0.8, 0))
    end

    local function releaseControl()
        forward, sideways = 0, 0
        teleportLock = nil
        wallbangSuppressed = false

        if bodyVelocity then pcall(function() bodyVelocity:Destroy() end) end
        if bodyGyro then pcall(function() bodyGyro:Destroy() end) end
        bodyVelocity, bodyGyro, currentObject = nil, nil, nil

        local char = lp2.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then root.Anchored = false end

        local cam = workspace.CurrentCamera
        if cam and camOverridden then
            cam.CameraType = Enum.CameraType.Custom
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                cam.CameraSubject = hum
            elseif savedSubject and savedSubject.Parent then
                cam.CameraSubject = savedSubject
            end
            if savedCFrame then cam.CFrame = savedCFrame end
        end
        camOverridden = false
        savedSubject, savedCFrame = nil, nil
        lookDir, followPos, yaw, pitch = nil, nil, nil, nil

        uis.MouseBehavior = savedMouseBehavior or Enum.MouseBehavior.Default
        uis.MouseIconEnabled = savedMouseIcon == nil and true or savedMouseIcon
        savedMouseBehavior, savedMouseIcon = nil, nil
        task.defer(function()
            pcall(function()
                uis.MouseBehavior = Enum.MouseBehavior.Default
                uis.MouseIconEnabled = true
            end)
        end)
    end

    local function markShot(name) recentShots[name] = os.clock() end

    local function isRecentShot(name)
        local t = recentShots[name]
        if t and (os.clock() - t) <= 1.6 then return true end
        if not controlProjectiles[name] then return false end
        local any = recentShots["__any"]
        return any and (os.clock() - any) <= 1.2
    end

    local function markToolShot(name)
        markShot("__any")
        for projectile in pairs(controlProjectiles) do markShot(projectile) end
        if name == "C4" then markShot("TransIgnore") end
    end

    local function bindShotTools(char)
        for _, conn in ipairs(shotConns) do pcall(function() conn:Disconnect() end) end
        table.clear(shotConns)
        if not char then return end

        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") and controlTools[child.Name] and child.Name ~= "C4" then
                shotConns[#shotConns + 1] = child.Activated:Connect(function()
                    markToolShot(child.Name)
                end)
            end
        end
    end

    local function airDetonate()
        if not currentObject or currentObject.Name ~= "TransIgnore" then return end
        if not c4Remote or not c4Remote:IsA("RemoteEvent") then return end

        local mapPart = cachedMapPart
        if not mapPart or not mapPart.Parent then
            mapPart = nil
            local map = workspace:FindFirstChild("Map")
            local parts = map and map:FindFirstChild("Parts")
            if parts then
                mapPart = parts:FindFirstChildWhichIsA("BasePart", true)
            end
            if not mapPart and map then
                mapPart = map:FindFirstChildWhichIsA("BasePart", true)
            end
            cachedMapPart = mapPart
        end

        local detonating = currentObject

        local blastCf = detonating.CFrame
        local lock = teleportLock
        if lock and lock.part and lock.part.Parent then
            blastCf = CFrame.new(lock.part.Position)
            pcall(function()
                detonating.CFrame = blastCf
                detonating.AssemblyLinearVelocity = Vector3.zero
            end)
        end

        if mapPart then
            pcall(function() c4Remote:FireServer("Do", mapPart, blastCf) end)
        end
        pcall(function() c4Remote:FireServer("Detonate") end)
        task.delay(0.55, function()
            if currentObject == detonating then releaseControl() end
        end)
    end

    local function bindC4(char)
        if c4ToolConn then pcall(function() c4ToolConn:Disconnect() end) end
        c4ToolConn, c4Remote = nil, nil

        if not char then return end
        local tool = char:FindFirstChild("C4")
        if not tool or not tool:IsA("Tool") then return end

        local ev = tool:FindFirstChild("Event")
        if ev and ev:IsA("RemoteEvent") then c4Remote = ev end

        c4ToolConn = tool.Activated:Connect(function()
            if currentObject and currentObject.Name == "TransIgnore" then
                airDetonate()
            else
                markShot("TransIgnore")
            end
        end)
    end

    local function validTarget(player)
        if player == lp2 then return false end
        if getPlayerStatus(player) == "Friendly" then return false end
        local char = player.Character
        if not char then return false end
        local hum = char:FindFirstChildOfClass("Humanoid")
        return hum ~= nil and hum.Health > 0
    end

    local tpDebugOn, tpDebugAt = false, 0
    local function tpDebug(text)
        if not tpDebugOn then return end
        local now = os.clock()
        if now - tpDebugAt < 0.4 then return end
        tpDebugAt = now
        library2:Notify("projectile tp: " .. text, 4)
    end

    local blastNames = {
        ["C4Explosion"] = true, ["RPG_Explosion_Long"] = true, ["RPG_Explosion_Short"] = true,
        ["GL_Explosion_Long"] = true, ["GL_Explosion_Short"] = true, ["SBL_Explosion"] = true,
        ["Hallows_Explosion2_Long"] = true, ["Hallows_Explosion2_Short"] = true,
        ["Hallows_Explosion"] = true, ["Firework_Explosion"] = true, ["VortexExplosion"] = true,
        ["Panzer_Explosion_Long"] = true, ["Panzer_Explosion_Short"] = true,
        ["BigExplosion2"] = true,
    }

    local groundParams = RaycastParams.new()
    groundParams.FilterType = Enum.RaycastFilterType.Exclude
    local groundIgnore = {}

    local function blastPointFor(part)
        if aimPart ~= "Ground" or not part or not part.Parent then
            return part and part.Position
        end

        table.clear(groundIgnore)
        groundIgnore[1] = part.Parent
        if lp2.Character then groundIgnore[#groundIgnore + 1] = lp2.Character end
        if currentObject then groundIgnore[#groundIgnore + 1] = currentObject end
        groundParams.FilterDescendantsInstances = groundIgnore

        local hit = workspace:Raycast(part.Position, Vector3.new(0, -60, 0), groundParams)
        if hit then
            return hit.Position + Vector3.new(0, 1.5, 0)
        end
        return part.Position
    end

    local function targetPartOf(player)
        local char = player.Character
        if not char then return nil end

        if aimPart == "Head" then
            return char:FindFirstChild("Head")
                or char:FindFirstChild("UpperTorso")
                or char:FindFirstChild("Torso")
                or char:FindFirstChild("HumanoidRootPart")
                or char:FindFirstChildWhichIsA("BasePart")
        end

        if aimPart == "Root" then
            return char:FindFirstChild("HumanoidRootPart")
                or char:FindFirstChild("UpperTorso")
                or char:FindFirstChild("Torso")
                or char:FindFirstChild("Head")
                or char:FindFirstChildWhichIsA("BasePart")
        end

        return char:FindFirstChild("UpperTorso")
            or char:FindFirstChild("Torso")
            or char:FindFirstChild("HumanoidRootPart")
            or char:FindFirstChild("Head")
            or char:FindFirstChildWhichIsA("BasePart")
    end

    local function wantedTarget(player)
        if not validTarget(player) then return false end
        if priorityOnly and getPlayerStatus(player) ~= "Enemy" then return false end
        return true
    end

    local diagValid, diagScreen, diagWorld = 0, math.huge, math.huge

    local function findTarget()
        local cam = workspace.CurrentCamera
        local best, bestScore
        diagValid, diagScreen, diagWorld = 0, math.huge, math.huge

        if cam and targetMode ~= "Nearest" then
            local viewport = cam.ViewportSize
            local center = Vector2.new(viewport.X / 2, viewport.Y / 2)
            for _, player in ipairs(plrs:GetPlayers()) do
                if wantedTarget(player) then
                    local part = targetPartOf(player)
                    if part then
                        local pos, onScreen = cam:WorldToViewportPoint(part.Position)
                        if onScreen then
                            local dist = (Vector2.new(pos.X, pos.Y) - center).Magnitude
                            if dist < diagScreen then diagScreen = dist end
                            if dist <= searchRadius and (not bestScore or dist < bestScore) then
                                best, bestScore = part, dist
                            end
                        end
                    end
                end
            end
        end
        if best then return best end

        local origin = currentObject and currentObject.Position
        if not origin then
            local char = lp2.Character
            local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head"))
            origin = root and root.Position
        end
        if not origin then return nil end

        for _, player in ipairs(plrs:GetPlayers()) do
            if wantedTarget(player) then
                diagValid += 1
                local part = targetPartOf(player)
                if part then
                    local dist = (part.Position - origin).Magnitude
                    if dist < diagWorld then diagWorld = dist end
                    if dist <= maxWorldDist and (not bestScore or dist < bestScore) then
                        best, bestScore = part, dist
                    end
                end
            end
        end
        return best
    end

    local function teleportToTarget()
        if not currentObject or not currentObject.Parent then
            tpDebug("no projectile")
            return false
        end
        local part = findTarget()
        if not part then
            tpDebug(string.format("no target: %d valid, screen %s px, world %s st",
                diagValid,
                diagScreen == math.huge and "none on screen" or string.format("%.0f", diagScreen),
                diagWorld == math.huge and "none" or string.format("%.0f", diagWorld)))
            return false
        end

        wallbangSuppressed = true
        if wallbangApplied then syncWallbang(false) end

        local center = blastPointFor(part)
        if not center then
            tpDebug("no blast point")
            return false
        end
        local isC4 = currentObject.Name == "TransIgnore"
        local approach, destination = Vector3.zero, center

        if not isC4 then
            approach = center - currentObject.Position
            approach = approach.Magnitude > 0.001 and approach.Unit or Vector3.new(0, 0, -1)
            destination = center - approach * impactGap
        end

        local ok = pcall(function()
            currentObject.CFrame = CFrame.new(destination)
        end)
        if not ok then
            tpDebug("cframe write threw")
            return false
        end
        pcall(function() currentObject.AssemblyLinearVelocity = Vector3.zero end)
        pcall(function() currentObject.AssemblyAngularVelocity = Vector3.zero end)


        local landed
        if pcall(function() landed = currentObject.Position end) and landed then
            tpDebug(string.format("wrote %s, off by %.1f st",
                tostring(currentObject.Name), (landed - destination).Magnitude))
        end

        if isC4 then
            forward, sideways = 0, 0
            if bodyVelocity then pcall(function() bodyVelocity.Velocity = Vector3.zero end) end
            if bodyGyro then pcall(function() bodyGyro.CFrame = CFrame.new(destination) end) end
        else
            lookDir = approach
            pitch = math.asin(math.clamp(approach.Y, -1, 1))
            yaw = math.atan2(-approach.X, -approach.Z)
            forward, sideways = 1, 0
            if bodyVelocity then
                pcall(function() bodyVelocity.Velocity = approach * flySpeed end)
            end
            if bodyGyro then
                pcall(function() bodyGyro.CFrame = CFrame.lookAt(destination, center) end)
            end
        end
        followPos = nil

    
        teleportLock = {
            part = part,
            isC4 = isC4,
            settleUntil = os.clock() + settleTime,
            expires = os.clock() + holdTime,
        }
        return true
    end

    local function registerProjectile(projectile)
        if not enabled or currentObject or not projectile then return end
        task.wait()
        if not lp2.Character or not projectile.Parent then return end
        if not controlProjectiles[projectile.Name] or not isRecentShot(projectile.Name) then return end
        if not holdingControlTool() then return end

        local char = lp2.Character
        local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
        if root then
            local pos
            if not pcall(function() pos = projectile.Position end) or not pos then return end
            if (pos - root.Position).Magnitude > 30 then return end
        end

        if not handsFree() then
            if not ensureCamera() then return end
            local myRoot = char:FindFirstChild("HumanoidRootPart")
            if myRoot then myRoot.Anchored = true end
        end

        local startCf
        if pcall(function() startCf = projectile.CFrame end) and startCf then
            local cam = workspace.CurrentCamera
            lookDir = cam and cam.CFrame.LookVector or startCf.LookVector
            lookDir = lookDir.Magnitude > 0.001 and lookDir.Unit or Vector3.new(0, 0, -1)
            pitch = math.asin(math.clamp(lookDir.Y, -1, 1))
            yaw = math.atan2(-lookDir.X, -lookDir.Z)
            followPos = startCf.Position - lookDir * 7 + Vector3.new(0, 2.4, 0)
        else
            lookDir, pitch, yaw, followPos = Vector3.new(0, 0, -1), 0, 0, nil
        end

        pcall(function()
            for _, name in ipairs({ "BodyForce", "BodyAngularVelocity", "Sound" }) do
                local child = projectile:FindFirstChild(name)
                if child then child:Destroy() end
            end
            local rot = projectile:FindFirstChild("RotPart")
            local rotAv = rot and rot:FindFirstChild("BodyAngularVelocity")
            if rotAv then rotAv:Destroy() end
        end)

        bodyVelocity = Instance.new("BodyVelocity")
        bodyVelocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
        bodyVelocity.Velocity = Vector3.zero
        bodyVelocity.Parent = projectile

        bodyGyro = Instance.new("BodyGyro")
        bodyGyro.P = 9e4
        bodyGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
        bodyGyro.Parent = projectile

        currentObject = projectile
        recentShots[projectile.Name] = nil

        if autoTeleport then
            autoTpDeadline = os.clock() + autoTpWindow
            if teleportToTarget() then
                handledProjectiles[projectile] = true
            end
        end
        if autoActivate and projectile.Name == "TransIgnore" then
            task.delay(autoTeleport and 0.1 or 0, function()
                if currentObject == projectile then airDetonate() end
            end)
        end
    end

    if vParts then
        library2:GiveSignal(vParts.ChildAdded:Connect(registerProjectile))
    end

    if debris then
        library2:GiveSignal(debris.ChildAdded:Connect(function(child)
            if not currentObject or not blastNames[child.Name] then return end

            local here = currentObject.Position
            local there
            if not pcall(function() there = child.Position end) or not there then
                releaseControl()
                return
            end
            if (there - here).Magnitude <= 40 then
                releaseControl()
            end
        end))
    end

    library2:GiveSignal(uis.InputBegan:Connect(function(input, processed)
        if processed then return end
        local key = input.KeyCode
        if key == Enum.KeyCode.W then forward = 1
        elseif key == Enum.KeyCode.S then forward = -1
        elseif key == Enum.KeyCode.D then sideways = 1
        elseif key == Enum.KeyCode.A then sideways = -1 end
    end))

    library2:GiveSignal(uis.InputEnded:Connect(function(input)
        local key = input.KeyCode
        if key == Enum.KeyCode.W or key == Enum.KeyCode.S then forward = 0
        elseif key == Enum.KeyCode.A or key == Enum.KeyCode.D then sideways = 0 end
    end))

    library2:GiveSignal(lp2.CharacterRemoving:Connect(releaseControl))

    local function hookCharacter(char)
        bindC4(char)
        bindShotTools(char)
        if charChildConn then pcall(function() charChildConn:Disconnect() end) end
        charChildConn = char.ChildAdded:Connect(function(child)
            if not child:IsA("Tool") then return end
            if child.Name == "C4" then bindC4(char) end
            bindShotTools(char)
        end)
    end

    if lp2.Character then hookCharacter(lp2.Character) end
    library2:GiveSignal(lp2.CharacterAdded:Connect(function(char)
        releaseControl()
        hookCharacter(char)
    end))

    library2:GiveSignal(rs2.RenderStepped:Connect(function()
        if not enabled or not currentObject or not currentObject.Parent then return end
        if handsFree() then return end
        if ensureCamera() then applyCameraFrame() end
    end))

    library2:GiveSignal(rs2.Heartbeat:Connect(function()
        if wallbangWanted() then
            wallbangTick = wallbangTick + 1
            if wallbangTick >= 120 then
                wallbangTick = 0
                syncWallbang(true)
            end
        else
            wallbangTick = 0
            if wallbangApplied then syncWallbang(false) end
        end

        if autoTeleport
            and currentObject
            and currentObject.Parent
            and not teleportLock
            and not handledProjectiles[currentObject]
            and os.clock() <= autoTpDeadline then
            if teleportToTarget() then
                handledProjectiles[currentObject] = true
            end
        end

        local lock = teleportLock
        if lock and currentObject and currentObject.Parent and lock.part and lock.part.Parent then
            if os.clock() > lock.expires then
                teleportLock = nil
            else
                local center = blastPointFor(lock.part) or lock.part.Position
                if lock.isC4 then
                    pcall(function() currentObject.CFrame = CFrame.new(center) end)
                    pcall(function() currentObject.AssemblyLinearVelocity = Vector3.zero end)
                    if bodyVelocity then
                        pcall(function() bodyVelocity.Velocity = Vector3.zero end)
                    end
                else
                    local approach = center - currentObject.Position
                    approach = approach.Magnitude > 0.001 and approach.Unit or currentObject.CFrame.LookVector

                    if os.clock() <= lock.settleUntil then
                        local hold = center - approach * impactGap
                        pcall(function() currentObject.CFrame = CFrame.new(hold) end)
                        pcall(function() currentObject.AssemblyLinearVelocity = Vector3.zero end)
                        if bodyVelocity then
                            pcall(function() bodyVelocity.Velocity = Vector3.zero end)
                        end
                    else
                        if (currentObject.Position - center).Magnitude > impactGap * 1.5 then
                            pcall(function()
                                currentObject.CFrame = CFrame.new(center - approach * impactGap)
                            end)
                        end
                        lookDir, forward, sideways = approach, 1, 0
                        if bodyVelocity then
                            pcall(function() bodyVelocity.Velocity = approach * flySpeed end)
                        end
                    end
                end
            end
        elseif lock then
            teleportLock = nil
        end

        if not currentObject then return end
        if not enabled or not currentObject.Parent or not bodyVelocity or not bodyGyro then
            releaseControl()
            return
        end
        if handsFree() then return end
        if not ensureCamera() then return end

        local cf
        if not pcall(function() cf = currentObject.CFrame end) then
            releaseControl()
            return
        end

        local delta = uis:GetMouseDelta()
        yaw = (yaw or 0) - delta.X * 0.0024
        pitch = math.clamp((pitch or 0) - delta.Y * 0.0024, -1.22, 1.1)

        local desired = Vector3.new(
            -math.sin(yaw) * math.cos(pitch),
            math.sin(pitch),
            -math.cos(yaw) * math.cos(pitch)
        )
        desired = desired.Magnitude > 0.001 and desired.Unit or Vector3.new(0, 0, -1)

        lookDir = lookDir and lookDir:Lerp(desired, 0.35) or desired
        lookDir = lookDir.Magnitude > 0.001 and lookDir.Unit or desired

        local right = lookDir:Cross(Vector3.new(0, 1, 0))
        right = right.Magnitude > 0.001 and right.Unit or Vector3.new(1, 0, 0)

        local move = (lookDir * forward) + (right * sideways)
        if move.Magnitude > 1 then move = move.Unit end

        bodyVelocity.Velocity = move * flySpeed
        bodyGyro.CFrame = CFrame.lookAt(cf.Position, cf.Position + lookDir)
        applyCameraFrame()
    end))

    local projectileToggle = projectileSection:AddToggle('MiscProjectileControl', {
        Text = "Projectile Control",
        Default = false,
        Tooltip = "Take over rockets and C4 in flight, fly them with WASD and the mouse",
        Callback = function(state)
            enabled = state
            syncWallbang(wallbangWanted())
