local noWireDamage = {
    Enabled = false,
    Root = nil,
    Connection = nil,
    DiscoveryConnection = nil,
    Originals = setmetatable({}, { __mode = "k" }),
}

local noWireDamageNames = {
    BarbedWire = true,
    Spike = true,
}

local noWireDamageModifiedNames = {
    ["BarbedWire#"] = "BarbedWire",
    ["Spike#"] = "Spike",
}

local function getNoWireDamageRoot()
    local filter = workspace:FindFirstChild("Filter")
    local parts = filter and filter:FindFirstChild("Parts")
    local filteredParts = parts and parts:FindFirstChild("F_Parts")
    return filteredParts and filteredParts:FindFirstChild("FBJ943")
end

local function protectNoWireDamageInstance(instance)
    local originalName = noWireDamageNames[instance.Name] and instance.Name
        or noWireDamageModifiedNames[instance.Name]
    if not originalName then return end

    noWireDamage.Originals[instance] = originalName
    if instance.Name == originalName then
        instance.Name = originalName .. "#"
    end
end

local function scanNoWireDamageRoot(root)
    for _, instance in ipairs(root:GetDescendants()) do
        protectNoWireDamageInstance(instance)
    end
end

local function disableNoWireDamage()
    noWireDamage.Enabled = false

    if noWireDamage.Connection then
        noWireDamage.Connection:Disconnect()
        noWireDamage.Connection = nil
    end

    if noWireDamage.DiscoveryConnection then
        noWireDamage.DiscoveryConnection:Disconnect()
        noWireDamage.DiscoveryConnection = nil
    end

    for instance, originalName in pairs(noWireDamage.Originals) do
        if instance.Parent then
            instance.Name = originalName
        end
        noWireDamage.Originals[instance] = nil
    end

    noWireDamage.Root = nil
end

local function attachNoWireDamageRoot(root)
    noWireDamage.Root = root
    scanNoWireDamageRoot(root)

    if noWireDamage.DiscoveryConnection then
        noWireDamage.DiscoveryConnection:Disconnect()
        noWireDamage.DiscoveryConnection = nil
    end

    noWireDamage.Connection = root.DescendantAdded:Connect(function(instance)
        if noWireDamage.Enabled then
            protectNoWireDamageInstance(instance)
        end
    end)
end

local function enableNoWireDamage()
    disableNoWireDamage()
    noWireDamage.Enabled = true

    local root = getNoWireDamageRoot()
    if root then
        attachNoWireDamageRoot(root)
        return
    end

    noWireDamage.DiscoveryConnection = workspace.DescendantAdded:Connect(function()
        if not noWireDamage.Enabled then return end

        local discoveredRoot = getNoWireDamageRoot()
        if discoveredRoot then
            attachNoWireDamageRoot(discoveredRoot)
        end
    end)
end

miscSection:AddToggle('MiscNoWireDamage', {
    Text = "No Wire Damage",
    Default = false,
    Warn     = true,
    Callback = function(state)
        if state then
            enableNoWireDamage()
        else
            disableNoWireDamage()
        end
    end,
})

library2:OnUnload(disableNoWireDamage)


local function removeNoFallDamageFf()
    if rb.NoFallDamageFF then
        pcall(function() rb.NoFallDamageFF:Destroy() end)
        rb.NoFallDamageFF = nil
    end
end

local function applyNoFallDamageFf(character)
    removeNoFallDamageFf()
    if not character then return end

    local ff = Instance.new("ForceField")
    ff.Visible = false
    ff.Parent = character
    rb.NoFallDamageFF = ff
end

local noFallDamageHeartbeat = nil

local function stopNoFallDamageForcefield()
    if noFallDamageHeartbeat then
        noFallDamageHeartbeat:Disconnect()
        noFallDamageHeartbeat = nil
    end
    if rb.NoFallDamageCharConn then
        rb.NoFallDamageCharConn:Disconnect()
        rb.NoFallDamageCharConn = nil
    end
    removeNoFallDamageFf()
end

local function startNoFallDamageForcefield()
    stopNoFallDamageForcefield()
    if not (rb.NoFallDamage and rb.NoFallDamageMethod == "ForceField") then return end

    applyNoFallDamageFf(lp2.Character)
    rb.NoFallDamageCharConn = lp2.CharacterAdded:Connect(function(char)
        if rb.NoFallDamage and rb.NoFallDamageMethod == "ForceField" then
            applyNoFallDamageFf(char)
        end
    end)

    noFallDamageHeartbeat = rs2.Heartbeat:Connect(function()
        if not (rb.NoFallDamage and rb.NoFallDamageMethod == "ForceField") then return end

        local char = lp2.Character
        if not char then return end

        local existing = char:FindFirstChildOfClass("ForceField")
        if not existing or existing ~= rb.NoFallDamageFF then
            applyNoFallDamageFf(char)
        end
    end)
end

local noFallDamageHookOriginal = nil
local function installNoFallDamageHook()
    if noFallDamageHookOriginal then return end

    local events = repSt:FindFirstChild("Events")
    local fallEvent = events and events:FindFirstChild("__RZDONL")
    if not fallEvent then return end

    noFallDamageHookOriginal = hookmetamethod(game, "__namecall", LPH_NO_VIRTUALIZE(function(self, ...)
        if getnamecallmethod() == "FireServer" and self == fallEvent then
            local args = { ... }
            if rb.NoFallDamage and rb.NoFallDamageMethod == "Block Remote"
                and (args[1] == "FlllD" or args[1] == "FllH") then
                return
            end
        end
        return noFallDamageHookOriginal(self, ...)
    end))
end

miscSection:AddToggle('MiscNoFallDamage', {
    Text = "No Fall Damage",
    Default  = false,
    Callback = function(state)
        rb.NoFallDamage = state
        if not state then
            stopNoFallDamageForcefield()
            return
        end

        if rb.NoFallDamageMethod == "ForceField" then
            startNoFallDamageForcefield()
        else
            stopNoFallDamageForcefield()
            installNoFallDamageHook()
        end
    end,
})

miscSection:AddDropdown('MiscNoFallDamageMethod', {
    Text = "Method",
    Values = {"Block Remote", "ForceField"},
    Default  = "Block Remote",
    Multi    = false,
    Callback = function(v)
        rb.NoFallDamageMethod = v
        if not rb.NoFallDamage then return end

        if v == "ForceField" then
            startNoFallDamageForcefield()
        else
            stopNoFallDamageForcefield()
            installNoFallDamageHook()
        end
    end,
})

library2:OnUnload(stopNoFallDamageForcefield)

local movementSection = miscPage:AddRightGroupbox("Movement")

local movement2 = {
    TPWalkOn    = false,
    TPWalkSpeed = 16,
    TPWalkConn  = nil,

    SpeedOn     = false,
    SpeedMethod = "CFrame",
    SpeedValue  = 16,
    SpeedConn   = nil,
}

local function getSpeedMoveVector()
    local camCf = cam2.CFrame
    local flatLook = Vector3.new(camCf.LookVector.X, 0, camCf.LookVector.Z)
    if flatLook.Magnitude == 0 then flatLook = Vector3.new(0, 0, -1) end
    flatLook = flatLook.Unit
    local flatRight = Vector3.new(camCf.RightVector.X, 0, camCf.RightVector.Z).Unit

    local moveVec = Vector3.new()
    if uis:IsKeyDown(Enum.KeyCode.W) then moveVec += flatLook end
    if uis:IsKeyDown(Enum.KeyCode.S) then moveVec -= flatLook end
    if uis:IsKeyDown(Enum.KeyCode.D) then moveVec += flatRight end
    if uis:IsKeyDown(Enum.KeyCode.A) then moveVec -= flatRight end

    return moveVec
end

movementSection:AddToggle('MiscTPWalk', {
    Text = "Teleport Walk",
    Default  = false,
    Warn     = true,
    Callback = function(state)
        movement2.TPWalkOn = state

        if movement2.TPWalkConn then
            movement2.TPWalkConn:Disconnect()
            movement2.TPWalkConn = nil
        end

        if state then
            movement2.TPWalkConn = rs2.RenderStepped:Connect(function(dt)
                local char = lp2.Character
                local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                if not (hrp and hum) then return end

                local moveDir = hum.MoveDirection
                if moveDir.Magnitude > 0 then
                    hrp.CFrame = hrp.CFrame + (moveDir.Unit * movement2.TPWalkSpeed * dt)
                end
            end)
        end
    end,
})

movementSection:AddSlider('MiscTPWalkSpeed', {
