})

movementSection:AddToggle('MiscSpeed', {
    Text = "Speed",
    Default  = false,
    Callback = function(state)
        movement2.SpeedOn = state

        if movement2.SpeedConn then
            movement2.SpeedConn:Disconnect()
            movement2.SpeedConn = nil
        end

        if state then
            movement2.SpeedConn = rs2.RenderStepped:Connect(function(dt)
                local char = lp2.Character
                local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                if not hrp then return end

                local moveVec = getSpeedMoveVector()
                local hasInput = moveVec.Magnitude > 0
                if hasInput then moveVec = moveVec.Unit end

                if movement2.SpeedMethod == "Velocity" then
                    local horizontal = moveVec * movement2.SpeedValue
                    local vel = hrp.AssemblyLinearVelocity
                    hrp.AssemblyLinearVelocity = Vector3.new(horizontal.X, vel.Y, horizontal.Z)
                elseif hasInput then
                    hrp.CFrame = hrp.CFrame + (moveVec * movement2.SpeedValue * dt)
                end
            end)
        end
    end,
})

