local flyState = { On = false, Conn = nil, Speed = 50, Mode = "Normal" }

local function fly(hrp)
    local events = repSt:FindFirstChild("Events")
    local event  = events and events:FindFirstChild("__RZDONL")

    if flyState.Conn then
        flyState.Conn:Disconnect()
        flyState.Conn = nil
    end

    if flyState.On then
        local function onStep()
            if not flyState.On or not hrp or not hrp.Parent then
                if flyState.Conn then
                    flyState.Conn:Disconnect()
                    flyState.Conn = nil
                end
                return
            end

            local camera = workspace.CurrentCamera or cam2
            local moveVector = Vector3.new(0, 0, 0)
            if library2.IsMobile then
                moveVector = camera.CFrame.LookVector * flyState.Speed
            else
                if uis:IsKeyDown(Enum.KeyCode.W) then
                    moveVector = moveVector + (camera.CFrame.LookVector * flyState.Speed)
                end
                if uis:IsKeyDown(Enum.KeyCode.S) then
                    moveVector = moveVector - (camera.CFrame.LookVector * flyState.Speed)
                end
                if uis:IsKeyDown(Enum.KeyCode.A) then
                    moveVector = moveVector - (camera.CFrame.RightVector * flyState.Speed)
                end
                if uis:IsKeyDown(Enum.KeyCode.D) then
                    moveVector = moveVector + (camera.CFrame.RightVector * flyState.Speed)
                end
            end

            hrp.AssemblyLinearVelocity = moveVector

            if flyState.Mode == "Ragdoll" and event then
                event:FireServer("__---r", Vector3.new(0, 0, 0), hrp.CFrame, false)
            end
        end

        flyState.Conn = rs2.RenderStepped:Connect(onStep)
        task.spawn(onStep)
    else
        if hrp and hrp.Parent then hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end
    end
end

local function enableFly()
    flyState.On = true
    local char = lp2.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then fly(hrp) end
end

local function disableFly()
    flyState.On = false
    local char = lp2.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    fly(hrp)
end

library2:GiveSignal(lp2.CharacterAdded:Connect(function(character)
    if not flyState.On then return end
    local hrp = character:WaitForChild("HumanoidRootPart", 5)
    if flyState.On and hrp then fly(hrp) end
end))
library2:OnUnload(disableFly)

