local spectateRageTargetProvider

local spectateEnemy = {
    Enabled             = false,
    Mode                = "Rage Target",
    Target              = nil,
    Connection          = nil,
    OriginalSubject     = nil,
    OriginalCameraType  = nil,
}

drainBootLog("misc built")

local function spectateResetCamera()
    local camera = workspace.CurrentCamera or cam2
    local humanoid = lp2.Character and lp2.Character:FindFirstChildOfClass("Humanoid")
    if not camera then return end

    camera.CameraType = spectateEnemy.OriginalCameraType or Enum.CameraType.Custom
    if humanoid then
        camera.CameraSubject = humanoid
    elseif spectateEnemy.OriginalSubject and spectateEnemy.OriginalSubject.Parent then
        camera.CameraSubject = spectateEnemy.OriginalSubject
    end
end

local function spectateGetTargetHumanoid(player)
    if not player or player == lp2 or not player.Parent then return nil end
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then return nil end
    return humanoid
end

local function spectateResolveTarget()
    if spectateEnemy.Mode == "Rage Target" then
        return spectateRageTargetProvider and spectateRageTargetProvider() or nil
    elseif spectateEnemy.Mode == "Manual Enemy" then
        if playerlist and type(playerlist.GetSelectedPlayer) == "function" then
            local player = playerlist:GetSelectedPlayer()
            return player ~= lp2 and player or nil
        end
        return nil
    end

    return spectate_find_enemy_target()
end

local function enableSpectateEnemy()
    if spectateEnemy.Enabled then return end
    spectateEnemy.Enabled = true
    local camera = workspace.CurrentCamera or cam2
    spectateEnemy.OriginalSubject = camera and camera.CameraSubject or nil
    spectateEnemy.OriginalCameraType = camera and camera.CameraType or Enum.CameraType.Custom
    spectateEnemy.Target = spectateResolveTarget()

    spectateEnemy.Connection = rs2.RenderStepped:Connect(function()
        if not spectateEnemy.Enabled then return end

        local resolvedTarget = spectateResolveTarget()
        if resolvedTarget ~= spectateEnemy.Target then
            spectateEnemy.Target = resolvedTarget
        end

        local targetHumanoid = spectateGetTargetHumanoid(spectateEnemy.Target)

        local currentCamera = workspace.CurrentCamera or cam2
        if targetHumanoid and currentCamera then
            if currentCamera.CameraType ~= Enum.CameraType.Custom then
                currentCamera.CameraType = Enum.CameraType.Custom
            end
            if currentCamera.CameraSubject ~= targetHumanoid then
                currentCamera.CameraSubject = targetHumanoid
            end
        elseif currentCamera then
            spectateResetCamera()
        end
    end)
end

local function disableSpectateEnemy()
    if not spectateEnemy.Enabled and not spectateEnemy.Connection then return end
    spectateEnemy.Enabled = false

    if spectateEnemy.Connection then
        spectateEnemy.Connection:Disconnect()
        spectateEnemy.Connection = nil
    end

    spectateResetCamera()
    spectateEnemy.Target = nil
    spectateEnemy.OriginalSubject = nil
    spectateEnemy.OriginalCameraType = nil
end

library2:OnUnload(disableSpectateEnemy)

local fastPickupEnabled = false

local fastPickup = {
    Originals = setmetatable({}, { __mode = "k" }),
    Conn = nil,
}

fastPickup.Apply = function(prompt)
    if fastPickup.Originals[prompt] == nil then
        fastPickup.Originals[prompt] = prompt.HoldDuration
    end
    if prompt.HoldDuration ~= 0 then prompt.HoldDuration = 0 end
end

local function bypassProximityPrompts()
    for _, v in pairs(workspace:GetDescendants()) do
        if v:IsA("ProximityPrompt") then
            fastPickup.Apply(v)
        end
    end
end

local function enableBypass()
    fastPickupEnabled = true
    bypassProximityPrompts()

    if not fastPickup.Conn then
        fastPickup.Conn = game:GetService("ProximityPromptService")
            .PromptButtonHoldBegan:Connect(function(v)
                if fastPickupEnabled then fastPickup.Apply(v) end
            end)
    end
end

local function disableBypass()
    fastPickupEnabled = false

    if fastPickup.Conn then
        fastPickup.Conn:Disconnect()
        fastPickup.Conn = nil
    end

    for prompt, original in pairs(fastPickup.Originals) do
        pcall(function()
            if prompt.Parent then prompt.HoldDuration = original end
        end)
        fastPickup.Originals[prompt] = nil
    end
end

library2:OnUnload(disableBypass)

