local noclip = {
    Conn = nil,
    Touched = setmetatable({}, { __mode = "k" }),
    Cache = {},
    Char = nil,
    ScanAt = 0,
    ScanInterval = 0.5,
}

noclip.Rescan = function(char)
    table.clear(noclip.Cache)
    for _, descendant in ipairs(char:GetDescendants()) do
        if descendant:IsA("BasePart") then
            noclip.Cache[#noclip.Cache + 1] = descendant
        end
    end
    noclip.Char = char
end

noclip.Restore = function()
    for part in pairs(noclip.Touched) do
        if part.Parent then part.CanCollide = true end
    end
    table.clear(noclip.Touched)
    table.clear(noclip.Cache)
    noclip.Char = nil
end

local noclipToggle = otherSection:AddToggle('MiscNoclip', {
    Text = "Noclip",
    Default  = false,
    Warn     = true,
    Callback = function(state)
        if noclip.Conn then
            noclip.Conn:Disconnect()
            noclip.Conn = nil
        end

        if not state then
            noclip.Restore()
            -- //
            local char = lp2.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 then
                pcall(hum.ChangeState, hum, Enum.HumanoidStateType.Running)
            end
            return
        end

        noclip.ScanAt = 0
        noclip.Conn = rs2.RenderStepped:Connect(function()
            local char = lp2.Character
            if not char then return end
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            if not (humanoid and humanoid.Health > 15) then return end

            local now = os.clock()
            if char ~= noclip.Char or (now - noclip.ScanAt) >= noclip.ScanInterval then
                noclip.ScanAt = now
                noclip.Rescan(char)
            end

            for _, part in ipairs(noclip.Cache) do
                if part.CanCollide then
                    part.CanCollide = false
                    noclip.Touched[part] = true
                end
            end
            local current = humanoid:GetState()
            if current == Enum.HumanoidStateType.StrafingNoPhysics
                or current == Enum.HumanoidStateType.Physics then
                pcall(humanoid.ChangeState, humanoid, Enum.HumanoidStateType.Running)
            end
        end)
    end,
})

library2:OnUnload(function()
    if noclip.Conn then
        noclip.Conn:Disconnect()
        noclip.Conn = nil
    end
    noclip.Restore()
end)

