local noFailLockPick = {
    Enabled = false,
    Connections = {},
    OriginalSizes = {},
}

local function trackLockpickBar(element)
    if not noFailLockPick.Enabled or noFailLockPick.OriginalSizes[element] then return end
    if not element:IsA("ImageLabel") or element.Name ~= "Bar" or not element.Parent or element.Parent.Name == "Attempts" then return end

    local targetSize2 = UDim2.new(0, 280, 0, 280)
    noFailLockPick.OriginalSizes[element] = element.Size
    element.Size = targetSize2
    table.insert(noFailLockPick.Connections, element:GetPropertyChangedSignal("Size"):Connect(function()
        if noFailLockPick.Enabled and element.Parent and element.Size ~= targetSize2 then
            element.Size = targetSize2
        end
    end))
end

local function modifyLockpickGui(gui)
    if not noFailLockPick.Enabled then return end
    for _, element in ipairs(gui:GetDescendants()) do
        trackLockpickBar(element)
    end
    table.insert(noFailLockPick.Connections, gui.DescendantAdded:Connect(trackLockpickBar))
end

local function disableNoFailLockpick()
    noFailLockPick.Enabled = false
    for _, connection in ipairs(noFailLockPick.Connections) do
        connection:Disconnect()
    end
    noFailLockPick.Connections = {}

    for element, originalSize in pairs(noFailLockPick.OriginalSizes) do
        if element and element.Parent then element.Size = originalSize end
    end
    noFailLockPick.OriginalSizes = {}
end

local function enableNoFailLockpick()
    disableNoFailLockpick()
    noFailLockPick.Enabled = true

    for _, child in ipairs(lp2.PlayerGui:GetChildren()) do
        if child:IsA("ScreenGui") and child.Name == "LockpickGUI" then
            modifyLockpickGui(child)
        end
    end

    table.insert(noFailLockPick.Connections, lp2.PlayerGui.ChildAdded:Connect(function(child)
        if not noFailLockPick.Enabled then return end
        if child:IsA("ScreenGui") and child.Name == "LockpickGUI" then
            task.defer(modifyLockpickGui, child)
        end
    end))
end

otherSection:AddToggle('MiscNoFailLockpick', {
    Text = "No Fail Lockpick",
    Default  = false,
    Callback = function(state)
        if state then enableNoFailLockpick() else disableNoFailLockpick() end
    end,
})

library2:OnUnload(disableNoFailLockpick)

local autoPickupMoney = { Enabled = false, Conn = nil }

otherSection:AddToggle('MiscAutoPickupMoney', {
    Text = "Auto Pickup Money",
    Default  = false,
    Callback = function(state)
        autoPickupMoney.Enabled = state

        if autoPickupMoney.Conn then
            autoPickupMoney.Conn:Disconnect()
            autoPickupMoney.Conn = nil
        end

        if not state then return end

        local canPickup       = true
        local lastPickupTime = tick()
        local lastScan2        = 0

        autoPickupMoney.Conn = rs2.RenderStepped:Connect(function()
            if not autoPickupMoney.Enabled then return end

            if not canPickup then
                if tick() - lastPickupTime >= 1 then
                    canPickup       = true
                    lastPickupTime = tick()
                end
                return
            end

            local now = os.clock()
            if (now - lastScan2) < 0.1 then return end
            lastScan2 = now

            local char = lp2.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            local filter        = workspace:FindFirstChild("Filter")
            local spawnedMoney = filter and filter:FindFirstChild("SpawnedBread")
            local pickupEvent  = repSt.Events:FindFirstChild("CZDPZUS")
            if not spawnedMoney or not pickupEvent then return end

            local nearest  = nil
            local minDist = 5

            for _, money in ipairs(spawnedMoney:GetChildren()) do
                if money:IsA("BasePart") then
                    local dist = (hrp.Position - money.Position).Magnitude
                    if dist < minDist then
                        minDist = dist
                        nearest  = money
                    end
                end
            end

            if nearest then
                pickupEvent:FireServer(nearest)
                canPickup       = false
                lastPickupTime = tick()
            end
        end)
    end,
})

