local autoRefillAmmo = { Enabled = false, Conn = nil, LastRefill = 0 }

otherSection:AddToggle('MiscAutoRefillAmmo', {
    Text = "Auto Refill Ammo",
    Default  = false,
    Tooltip = "Automatically refills ammo near a compatible store.",
    Callback = function(state)
        autoRefillAmmo.Enabled = state

        if autoRefillAmmo.Conn then
            autoRefillAmmo.Conn:Disconnect()
            autoRefillAmmo.Conn = nil
        end

        if not state then return end

        autoRefillAmmo.Conn = rs2.Heartbeat:Connect(function()
            if not autoRefillAmmo.Enabled then return end

            if tick() - autoRefillAmmo.LastRefill < 0.5 then return end

            local char = lp2.Character
            if not char then return end

            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            local tool = char:FindFirstChildOfClass("Tool")
            if not tool then return end

            local weaponName2 = tool.Name

            local openEvent  = repSt.Events:FindFirstChild("BYZERSPROTEC")
            local buyEvent   = repSt.Events:FindFirstChild("SSHPRMTE1")

            if not openEvent or not buyEvent then return end

            local shopz = workspace:FindFirstChild("Map")
                and workspace.Map:FindFirstChild("Shopz")

            if not shopz then return end

            local closestStore = nil
            local closestDist  = 15

            for _, storeFolder in ipairs(shopz:GetChildren()) do
                local mainPart2 = storeFolder:FindFirstChild("MainPart")
                if mainPart2 then
                    local dist = (hrp.Position - mainPart2.Position).Magnitude
                    if dist < closestDist then
                        closestDist = dist
                        local storeType = "IllegalStore"
                        if storeFolder.Name:lower():find("armor") or storeFolder.Name:lower():find("legal") then
                            storeType = "LegalStore"
                        end
                        closestStore = {
                            name = storeType,
                            main_part = mainPart2,
                            dist = dist,
                            folder = storeFolder.Name
                        }
                    end
                end
            end

            if closestStore then
                local success, err = pcall(function()
                    openEvent:FireServer()
                    buyEvent:InvokeServer(closestStore.name, "Guns", weaponName2, closestStore.main_part, "ResupplyAmmo", true)
                    autoRefillAmmo.LastRefill = tick()

                    task.wait(0.1)
                    local backpackWeapon = lp2.Backpack:FindFirstChild(weaponName2)
                    if backpackWeapon and char:FindFirstChild("Humanoid") then
                        char.Humanoid:EquipTool(backpackWeapon)
                    end
                end)
            end
        end)
    end,
})

