otherSection:AddToggle('MiscAutoBuy', {
    Text = "Auto Buy",
    Default  = false,
    Callback = function(state)
        autoBuy.Enabled = state

        if autoBuy.Conn then
            autoBuy.Conn:Disconnect()
            autoBuy.Conn = nil
        end

        if not state then return end

        autoBuy.Conn = rs2.Heartbeat:Connect(function()
            if not autoBuy.Enabled or autoBuy.Busy then return end

            if tick() - autoBuy.LastBuy < 1 then return end

            local char = lp2.Character
            if not char then return end

            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            local buyEvent = repSt.Events:FindFirstChild("SSHPRMTE1")
            if not buyEvent then return end

            local shopz = workspace:FindFirstChild("Map")
                and workspace.Map:FindFirstChild("Shopz")

            if not shopz then return end

            local closestDealer = nil
            local closestDist = 15

            for _, storeFolder in ipairs(shopz:GetChildren()) do
                local mainPart2 = storeFolder:FindFirstChild("MainPart")
                if mainPart2 then
                    local dist = (hrp.Position - mainPart2.Position).Magnitude
                    if dist < closestDist then
                        closestDist = dist
                        closestDealer = mainPart2
                    end
                end
            end

            if not closestDealer then return end

            autoBuy.LastBuy = tick()
            autoBuy.Busy = true

            local item = autoBuy.Item
            local known = autoBuy.Known[item]

            local function attempt(storeType, category)
                local ok, result = pcall(function()
                    return buyEvent:InvokeServer(storeType, category, item, closestDealer)
                end)
                return ok and result
            end

            if known and attempt(known[1], known[2]) then
                autoBuy.Busy = false
                autoBuy.LastBuy = tick()
                return
            end

            for _, storeType in ipairs(autoBuy.Stores) do
                for _, category in ipairs(autoBuy.Categories) do
                    if not autoBuy.Enabled then
                        autoBuy.Busy = false
                        return
                    end
                    if attempt(storeType, category) then
                        autoBuy.Known[item] = { storeType, category }
                        autoBuy.Busy = false
                        autoBuy.LastBuy = tick()
                        return
                    end
                end
            end

            autoBuy.Busy = false
            autoBuy.LastBuy = tick()
        end)
    end,
})

local autoClaimAllowance = { Enabled = false, Conn = nil, LastClaim = 0, Busy = false }

local function findNearestAtm(maxDistance2)
    local char = lp2.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end

    local map = workspace:FindFirstChild("Map")
    local atmFolder = map and map:FindFirstChild("ATMz")
    if not atmFolder then return nil end

    local closestPart, closestDist = nil, maxDistance2
    for _, atm in ipairs(atmFolder:GetChildren()) do
        local mainPart2 = atm:FindFirstChild("MainPart")
        if mainPart2 then
            local distance = (hrp.Position - mainPart2.Position).Magnitude
            if distance < closestDist then
                closestDist  = distance
                closestPart  = mainPart2
            end
        end
    end

    return closestPart
end

