local invisAnim = {
    Wanted = false,
    Active = false,
    Gen = 0,
    Char = nil,
    Hum = nil,
    Root = nil,
    Conn = nil,
    DescConn = nil,
    Originals = setmetatable({}, { __mode = "k" }),
    Tracked = setmetatable({}, { __mode = "k" }),
    ScanAt = 0,
    ScanInterval = 0.2,
    Alpha = 0.5,
    Offset = Vector3.new(0, 1.44, 0),
    Toggle = nil,
}

invisAnim.Refresh = function()
    local char = lp2.Character
    invisAnim.Char = char
    invisAnim.Hum = char and char:FindFirstChildOfClass("Humanoid") or nil
    invisAnim.Root = char and char:FindFirstChild("HumanoidRootPart") or nil

    return char ~= nil
        and invisAnim.Hum ~= nil
        and invisAnim.Root ~= nil
        and invisAnim.Hum.RigType == Enum.HumanoidRigType.R6
        and char:FindFirstChild("Torso") ~= nil
end

invisAnim.Track = function(part)
    if not part:IsA("BasePart") or invisAnim.Tracked[part] then return end
    invisAnim.Tracked[part] = true
    if invisAnim.Originals[part] == nil then
        local original = part.Transparency
        if math.abs(original - invisAnim.Alpha) < 0.001 then original = 0 end
        invisAnim.Originals[part] = original
    end
end

invisAnim.ApplyAlpha = function()
    local char = invisAnim.Char
    if not char then return end

    local now = os.clock()
    if now - invisAnim.ScanAt >= invisAnim.ScanInterval then
        invisAnim.ScanAt = now
        for _, part in ipairs(char:GetDescendants()) do
            invisAnim.Track(part)
        end
    end

    for part in pairs(invisAnim.Tracked) do
        if not part.Parent then
            invisAnim.Tracked[part] = nil
        else
            local original = invisAnim.Originals[part] or 0
            local target = if original >= 1 then original else invisAnim.Alpha
            if part.Transparency ~= target then
                part.Transparency = target
            end
        end
    end
end

invisAnim.Restore = function()
    if invisAnim.Hum and invisAnim.Hum.Parent then
        invisAnim.Hum.CameraOffset = Vector3.zero
    end

    for part, transparency in pairs(invisAnim.Originals) do
        pcall(function() part.Transparency = transparency end)
    end

    table.clear(invisAnim.Originals)
    table.clear(invisAnim.Tracked)

    local char = invisAnim.Char
    if not char or not char.Parent then return end
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") and math.abs(part.Transparency - invisAnim.Alpha) < 0.001 then
            pcall(function() part.Transparency = 0 end)
        end
    end
end

invisAnim.Stop = function()
    invisAnim.Active = false
    invisAnim.Gen += 1

    if invisAnim.Conn then
        invisAnim.Conn:Disconnect()
        invisAnim.Conn = nil
    end
    if invisAnim.DescConn then
        invisAnim.DescConn:Disconnect()
        invisAnim.DescConn = nil
    end

    invisAnim.Restore()

    local cam = workspace.CurrentCamera or cam2
    local hum = invisAnim.Hum
    if cam and hum and hum.Parent then
        cam.CameraSubject = hum
    end
end

invisAnim.Step = function()
    if not invisAnim.Active then return end

    local hum, root = invisAnim.Hum, invisAnim.Root
    if not invisAnim.Char or not hum or not root
        or hum.Health <= 0
        or not root:IsDescendantOf(workspace) then
        invisAnim.Stop()
        return
    end

    local gen = invisAnim.Gen
    local cam = workspace.CurrentCamera or cam2
    local savedCFrame = root.CFrame
    local savedOffset = hum.CameraOffset
    local _, yaw = (cam and cam.CFrame or savedCFrame):ToOrientation()

    root.CFrame = CFrame.new(root.Position)
        * CFrame.fromOrientation(0, yaw, 0)
        * CFrame.Angles(math.rad(90), 0, 0)
    hum.CameraOffset = invisAnim.Offset

    rs2.RenderStepped:Wait()

    if hum:IsDescendantOf(workspace) then hum.CameraOffset = savedOffset end
    if root:IsDescendantOf(workspace) then root.CFrame = savedCFrame end
    if not invisAnim.Active or gen ~= invisAnim.Gen or not root:IsDescendantOf(workspace) then
        return
    end

    if cam then
        local look = cam.CFrame.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude > 0.001 then
            root.CFrame = CFrame.new(root.Position, root.Position + flat.Unit)
        end
    end

    invisAnim.ApplyAlpha()
end

invisAnim.Start = function()
    if invisAnim.Active then return true end
    if not invisAnim.Refresh() then
        notify("Invisible", "R6 character required", 5)
        return false
    end

    invisAnim.Gen += 1
    invisAnim.ScanAt = 0
    table.clear(invisAnim.Originals)
    table.clear(invisAnim.Tracked)
    invisAnim.Active = true

    if invisAnim.DescConn then invisAnim.DescConn:Disconnect() end
    invisAnim.DescConn = invisAnim.Char.DescendantAdded:Connect(function(descendant)
        if invisAnim.Active then invisAnim.Track(descendant) end
    end)

    local cam = workspace.CurrentCamera or cam2
    if cam then cam.CameraSubject = invisAnim.Root end

    if invisAnim.Conn then invisAnim.Conn:Disconnect() end
    invisAnim.Conn = rs2.Heartbeat:Connect(invisAnim.Step)
    return true
end

invisAnim.Toggle = otherSection:AddToggle('MiscInvisible', {
    Text = "Invisible",
    Default  = false,
    Warn     = true,
    Tooltip = "R6 only. Drops the character flat for one frame each tick so the pose replicates, no animation is played.",
    Callback = function(state)
        invisAnim.Wanted = state
        if not state then
            invisAnim.Stop()
            return
        end
        if not invisAnim.Start() then
            task.defer(function()
                if invisAnim.Toggle.Value then invisAnim.Toggle:SetValue(false) end
            end)
        end
