    "Rust", "CODE200", "Minecraft", "Neverlose", "Gamesense",
    "Bonk", "Bat", "Laser Beam", "Fatality", "Bow",
}

local rageHitSoundNames = (function()
    local seen = {}
    local names = {}

    for _, name in ipairs(rageHitSoundFeatured) do
        if rageHitSounds[name] and not seen[name] then
            seen[name] = true
            names[#names + 1] = name
        end
    end

    local rest = {}
    for name in pairs(rageHitSounds) do
        if not seen[name] then
            rest[#rest + 1] = name
        end
    end
    table.sort(rest)

    for _, name in ipairs(rest) do
        names[#names + 1] = name
    end

    return names
end)()

