local function playRageHitsound()
    if not ragebotFlags.hit_Sound or not rageHitSound.Parent then return end

    rageHitSound.SoundId = ragebotFlags.hit_Sound_Id
    rageHitSound.Volume = ragebotFlags.hit_Sound_Volume
    pcall(function() rageHitSound:Play() end)
end

local function rememberRageHitmarkerSound(sound)
    if ragebotController.HitmarkerOriginals[sound] then return end

    ragebotController.HitmarkerOriginals[sound] = {
        SoundId = sound.SoundId,
        Volume = sound.Volume,
        SoundGroup = sound.SoundGroup,
    }
end

local function restoreRageHitmarkerSound(sound)
    local original = ragebotController.HitmarkerOriginals[sound]
    if not original then return end

    if sound.Parent then
        pcall(function()
            sound.SoundId = original.SoundId
            sound.Volume = original.Volume
            sound.SoundGroup = original.SoundGroup
        end)
    end

    ragebotController.HitmarkerOriginals[sound] = nil
end

local function restoreRageHitmarkerSounds()
    local pending = {}
    for sound in next, ragebotController.HitmarkerOriginals do
        pending[#pending + 1] = sound
    end

    for _, sound in ipairs(pending) do
        ragebotController.HitSoundApplying[sound] = true
        restoreRageHitmarkerSound(sound)
        ragebotController.HitSoundApplying[sound] = nil
    end
end

local function applyRageHitmarkerSoundSettings(sound)
    if not sound
        or not sound:IsA("Sound")
        or sound.Name ~= "HitmarkerSound"
        or not ragebotFlags.hit_Sound
        or ragebotController.HitSoundApplying[sound] then
        return
    end

    rememberRageHitmarkerSound(sound)
    local original = ragebotController.HitmarkerOriginals[sound]

    ragebotController.HitSoundApplying[sound] = true
    pcall(function()
        if ragebotFlags.hit_Sound_Method == "ID Swap" then
            if sound.SoundId ~= ragebotFlags.hit_Sound_Id then
                sound.SoundId = ragebotFlags.hit_Sound_Id
            end
            if sound.Volume ~= ragebotFlags.hit_Sound_Volume then
                sound.Volume = ragebotFlags.hit_Sound_Volume
            end
            if sound.SoundGroup ~= nil then
                sound.SoundGroup = nil
            end
        elseif ragebotFlags.hit_Sound_Method == "Hit Check" then
            if original then
                if sound.SoundId ~= original.SoundId then
                    sound.SoundId = original.SoundId
                end
                if sound.SoundGroup ~= original.SoundGroup then
                    sound.SoundGroup = original.SoundGroup
                end
            end
            if sound.Volume ~= 0 then
                sound.Volume = 0
            end
        end
    end)
    ragebotController.HitSoundApplying[sound] = nil
end


local hitChams = {
    Enabled = false,
    Color = Color3.fromRGB(181, 179, 253),
    Transparency = 0.35,

    Duration = 1.25,
    Fade = true,
    FadeDelay = 0.10,
    FadeStyle = "Smooth",
    MaxCount = 5,

    ConfirmWindow = 1.00,
    TargetGrace = 1.50,

    Watched = {},
    RecentDamage = {},
    PendingSounds = {},
    Effects = {},


    LastHitmarkerPulse = 0,
    NextEffectId = 0,


    SoundConnections = setmetatable({}, { __mode = "k" }),
    SoundLastPulse = setmetatable({}, { __mode = "k" }),

    Folder = nil,
    MonitorConnection = nil,
    RenderConnection = nil,
}

local function hitChamsGetFolder()
    if hitChams.Folder and hitChams.Folder.Parent then
        return hitChams.Folder
    end

    local old = workspace:FindFirstChild("DrainHitChams")
    if old then
        pcall(function() old:Destroy() end)
    end

    local folder = Instance.new("Folder")
    folder.Name = "DrainHitChams"
    folder.Parent = workspace
    hitChams.Folder = folder
    return folder
end

local function hitChamsPlayerFromPart(part)
    if not part or not part.Parent then return nil end

    local character = part:FindFirstAncestorOfClass("Model")
    if not character then return nil end

    return plrs:GetPlayerFromCharacter(character)
end

local function hitChamsCurrentTargets()
    local targets = {}
    local now = os.clock()

    local function add(player, source)
        if not player or player == lp2 or not player.Parent then return end
        targets[player] = source
    end


    if silentAim.Enabled and silentAim.target then
        add(hitChamsPlayerFromPart(silentAim.target), "Silent Aim")
    end


    if legitAimFlags.enabled then
        local current = legitAimbotController.CurrentTarget
        local data = current and current.data
        add(data and data.player, "Aimbot")
    end


    if ragebotFlags.enabled then
        add(ragebotFlags.locked_Target, "Ragebot")

        if ragebotController.LastShotTarget
            and (now - ragebotController.LastShotTargetTime) <= hitChams.TargetGrace then
            add(ragebotController.LastShotTarget, "Ragebot")
        end
    end

    return targets
end

local function hitChamsIsCurrentOrRecentTarget(player)
    if not player then return false end

    local current = hitChamsCurrentTargets()
    if current[player] then
        return true
    end

    local watched = hitChams.Watched[player]
    return watched
        and (os.clock() - watched.LastSeen) <= hitChams.TargetGrace
end

local function hitChamsSnapshot(character)
    if not character or not character.Parent then return nil end

    local snapshot = {}


    for _, object in ipairs(character:GetChildren()) do
        if object:IsA("BasePart")
            and object.Name ~= "HumanoidRootPart"
            and object.Transparency < 1 then

            snapshot[#snapshot + 1] = {
                Name = object.Name,
                CFrame = object.CFrame,
                Size = object.Size,
            }
        end
    end


    if #snapshot == 0 then
        local root = character:FindFirstChild("HumanoidRootPart")
        if root and root:IsA("BasePart") then
            snapshot[1] = {
                Name = root.Name,
                CFrame = root.CFrame,
                Size = root.Size,
            }
        end
    end

    return #snapshot > 0 and snapshot or nil
end

local function hitChamsDestroyEffect(effect)
    if effect and effect.Root then
        pcall(function() effect.Root:Destroy() end)
        effect.Root = nil
    end
end

local function hitChamsClearEffects()
    for index = #hitChams.Effects, 1, -1 do
        hitChamsDestroyEffect(hitChams.Effects[index])
        table.remove(hitChams.Effects, index)
    end
end

local function hitChamsCurve(progress)
    progress = math.clamp(progress, 0, 1)

    if hitChams.FadeStyle == "Linear" then
        return progress
    elseif hitChams.FadeStyle == "Exponential" then
        return progress * progress
    end


    return progress * progress * (3 - 2 * progress)
end

local function hitChamsSpawn(damage)
    if not hitChams.Enabled or not damage or not damage.Snapshot then return end

    hitChams.NextEffectId += 1

    local root = Instance.new("Folder")
    root.Name = string.format(
        "HitChams_%s_%d",
        tostring(damage.Player and damage.Player.UserId or "Target"),
        hitChams.NextEffectId
    )
    root.Parent = hitChamsGetFolder()

    local effect = {
        Root = root,
        CreatedAt = os.clock(),
        Adornments = {},
    }

    for _, saved in ipairs(damage.Snapshot) do


        local anchorPart = Instance.new("Part")
        anchorPart.Name = saved.Name
        anchorPart.Anchored = true
        anchorPart.CanCollide = false
        anchorPart.CanTouch = false
        anchorPart.CanQuery = false
        anchorPart.CastShadow = false
        anchorPart.Transparency = 1
        anchorPart.Size = saved.Size
        anchorPart.CFrame = saved.CFrame
        anchorPart.Parent = root

        local box = Instance.new("BoxHandleAdornment")
        box.Name = "HitChamsBox"
        box.Adornee = anchorPart
        box.Size = saved.Size
        box.CFrame = CFrame.identity
        box.Color3 = hitChams.Color
        box.Transparency = hitChams.Transparency
        box.AlwaysOnTop = true
        box.ZIndex = 8
        box.Parent = anchorPart

        effect.Adornments[#effect.Adornments + 1] = box
    end

    hitChams.Effects[#hitChams.Effects + 1] = effect


    local maxCount = math.max(math.floor(hitChams.MaxCount or 1), 1)
    while #hitChams.Effects > maxCount do
        local oldest = table.remove(hitChams.Effects, 1)
        hitChamsDestroyEffect(oldest)
    end
end

local function hitChamsConfirmDamage(damage)
    if not damage or damage.Confirmed or not hitChams.Enabled then return false end

    damage.Confirmed = true
    hitChamsSpawn(damage)
    return true
end

local function hitChamsConfirmRecentDamage(soundTime)
    local confirmed = 0

    for _, damage in ipairs(hitChams.RecentDamage) do
        if not damage.Confirmed then
            local distance = math.abs(soundTime - damage.Time)

            if distance <= hitChams.ConfirmWindow then
                if hitChamsConfirmDamage(damage) then
                    confirmed += 1
                end
            end
        end
    end

    return confirmed
end

local function hitChamsHasRecentSound(damageTime)
    local pulse = hitChams.LastHitmarkerPulse or 0
    return pulse > 0
        and math.abs(damageTime - pulse) <= hitChams.ConfirmWindow
end

local function hitChamsOnHitmarkerSound()
    if not hitChams.Enabled then return end

    local now = os.clock()


    hitChams.LastHitmarkerPulse = now

    hitChamsConfirmRecentDamage(now)
end

local function hitChamsUnwatch(player)
    local data = hitChams.Watched[player]
    if not data then return end

    if data.HealthConnection then
        pcall(function() data.HealthConnection:Disconnect() end)
    end

    hitChams.Watched[player] = nil
end

local function hitChamsRecordHealth(player, data, newHealth)
    if not data then return end

    newHealth = tonumber(newHealth)
    if not newHealth then return end

    local oldHealth = tonumber(data.LastHealth)
    if oldHealth == nil then
        data.LastHealth = newHealth
        return
    end


    data.LastHealth = newHealth

    if not hitChams.Enabled then return end
    if newHealth >= oldHealth then return end
    if data.Character ~= player.Character then return end
    if not hitChamsIsCurrentOrRecentTarget(player) then return end

    local now = os.clock()


    if data.LastDamageTime
        and (now - data.LastDamageTime) < 0.025
        and data.LastDamageHealth == newHealth then
        return
    end

    data.LastDamageTime = now
    data.LastDamageHealth = newHealth

    local snapshot = hitChamsSnapshot(data.Character)
    if not snapshot then return end

    local damage = {
        Player = player,
        Character = data.Character,
        Time = now,
        OldHealth = oldHealth,
        NewHealth = newHealth,
        Damage = math.max(oldHealth - newHealth, 0),
        Snapshot = snapshot,
        Confirmed = false,
        Source = data.Source,
    }

    hitChams.RecentDamage[#hitChams.RecentDamage + 1] = damage


    if hitChamsHasRecentSound(now) then
        hitChamsConfirmDamage(damage)
    end
end

local function hitChamsTrackPlayer(player, source)
    if not hitChams.Enabled or not player or player == lp2 then return end

    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not humanoid then return end

    local now = os.clock()
    local current = hitChams.Watched[player]

    if current and current.Humanoid == humanoid then
        current.LastSeen = now
        current.Source = source or current.Source


        hitChamsRecordHealth(player, current, humanoid.Health)
        return
    end

    if current then
        hitChamsUnwatch(player)
    end

    local data = {
        Player = player,
        Character = character,
        Humanoid = humanoid,
        LastHealth = humanoid.Health,
        LastSeen = now,
        Source = source,
        LastDamageTime = nil,
        LastDamageHealth = nil,
        HealthConnection = nil,
    }

    data.HealthConnection = humanoid.HealthChanged:Connect(function(newHealth)
        hitChamsRecordHealth(player, data, newHealth)
    end)

    hitChams.Watched[player] = data
end

local hitChamsUpdateTargets = LPH_NO_VIRTUALIZE(function()
    if not hitChams.Enabled then return end

    local now = os.clock()
    local targets = hitChamsCurrentTargets()

    for player, source in pairs(targets) do
        hitChamsTrackPlayer(player, source)
    end

    for player, data in pairs(hitChams.Watched) do
        if targets[player] then
            data.LastSeen = now

            local humanoid = data.Humanoid
            if humanoid and humanoid.Parent then
                hitChamsRecordHealth(player, data, humanoid.Health)
            end
        elseif (now - data.LastSeen) > hitChams.TargetGrace then
            hitChamsUnwatch(player)
        else


            local humanoid = data.Humanoid
            if humanoid and humanoid.Parent then
                hitChamsRecordHealth(player, data, humanoid.Health)
            end
        end
    end

    for index = #hitChams.RecentDamage, 1, -1 do
        if (now - hitChams.RecentDamage[index].Time) > (hitChams.ConfirmWindow + 0.35) then
            table.remove(hitChams.RecentDamage, index)
        end
    end

    if hitChams.LastHitmarkerPulse > 0
        and (now - hitChams.LastHitmarkerPulse) > hitChams.ConfirmWindow then
        hitChams.LastHitmarkerPulse = 0
    end
end)

local hitChamsUpdateEffects = LPH_NO_VIRTUALIZE(function()
    if not hitChams.Enabled then
        hitChamsClearEffects()
        return
    end

    local now = os.clock()
    local duration = math.max(hitChams.Duration, 0.05)

    for index = #hitChams.Effects, 1, -1 do
        local effect = hitChams.Effects[index]
        local age = now - effect.CreatedAt

        if age >= duration then
            hitChamsDestroyEffect(effect)
            table.remove(hitChams.Effects, index)
        elseif hitChams.Fade and age >= hitChams.FadeDelay then
            local fadeLength = math.max(duration - hitChams.FadeDelay, 0.01)
            local progress = (age - hitChams.FadeDelay) / fadeLength
            local curve = hitChamsCurve(progress)
            local transparency = hitChams.Transparency
                + (1 - hitChams.Transparency) * curve

            for _, box in ipairs(effect.Adornments) do
                if box.Parent then
                    box.Color3 = hitChams.Color
                    box.Transparency = math.clamp(transparency, 0, 1)
                end
            end
        else
            for _, box in ipairs(effect.Adornments) do
                if box.Parent then
                    box.Color3 = hitChams.Color
                    box.Transparency = hitChams.Transparency
                end
            end
        end
    end
end)

local function hitChamsSetEnabled(state)
    hitChams.Enabled = state

    if not state then
        local players = {}
        for player in pairs(hitChams.Watched) do
            players[#players + 1] = player
        end
        for _, player in ipairs(players) do
            hitChamsUnwatch(player)
        end

        table.clear(hitChams.RecentDamage)
        table.clear(hitChams.PendingSounds)
        hitChams.LastHitmarkerPulse = 0
        hitChamsClearEffects()
        return
    end

    hitChamsGetFolder()
    hitChamsUpdateTargets()
end

local hitChamsUnwatchSound

local function hitChamsCleanup()
    hitChams.Enabled = false

    local players = {}
    for player in pairs(hitChams.Watched) do
        players[#players + 1] = player
    end
    for _, player in ipairs(players) do
        hitChamsUnwatch(player)
    end

    table.clear(hitChams.RecentDamage)
    table.clear(hitChams.PendingSounds)
    hitChams.LastHitmarkerPulse = 0
    hitChamsClearEffects()

    local watchedSounds = {}
    for sound in pairs(hitChams.SoundConnections) do
        watchedSounds[#watchedSounds + 1] = sound
    end
    for _, sound in ipairs(watchedSounds) do
        hitChamsUnwatchSound(sound)
    end

    if hitChams.MonitorConnection then
        pcall(function() hitChams.MonitorConnection:Disconnect() end)
        hitChams.MonitorConnection = nil
    end

    if hitChams.RenderConnection then
        pcall(function() hitChams.RenderConnection:Disconnect() end)
        hitChams.RenderConnection = nil
    end

    if hitChams.Folder then
        pcall(function() hitChams.Folder:Destroy() end)
        hitChams.Folder = nil
    end
end

