library2:GiveSignal(hitChams.RenderConnection)

hitChamsUnwatchSound = function(sound)
    local data = hitChams.SoundConnections[sound]
    if not data then return end

    for _, connection in pairs(data) do
        if typeof(connection) == "RBXScriptConnection" then
            pcall(function() connection:Disconnect() end)
        end
    end

    hitChams.SoundConnections[sound] = nil
    hitChams.SoundLastPulse[sound] = nil
end

local function hitChamsSignalSound(sound)
    local now = os.clock()
    local previous = hitChams.SoundLastPulse[sound] or 0
    if (now - previous) < 0.012 then
        return
    end

    hitChams.SoundLastPulse[sound] = now

    if ragebotFlags.hit_Sound and ragebotFlags.hit_Sound_Method == "Hit Check" then
        playRageHitsound()
    end

    if hitChams.Enabled then
        hitChamsOnHitmarkerSound()
    end
end

local function hitChamsWatchSound(sound)
    if not sound
        or not sound:IsA("Sound")
        or sound.Name ~= "HitmarkerSound"
        or hitChams.SoundConnections[sound] then
        return
    end

    local connections = {}


    local okPlayed, playedConnection = pcall(function()
        return sound.Played:Connect(function()
            hitChamsSignalSound(sound)
        end)
    end)
    if okPlayed and playedConnection then
        connections.Played = playedConnection
    end


    connections.Playing = sound:GetPropertyChangedSignal("Playing"):Connect(function()
        if sound.Playing then
            applyRageHitmarkerSoundSettings(sound)
            hitChamsSignalSound(sound)
        end
    end)

    connections.SoundId = sound:GetPropertyChangedSignal("SoundId"):Connect(function()
        applyRageHitmarkerSoundSettings(sound)
    end)
    connections.Volume = sound:GetPropertyChangedSignal("Volume"):Connect(function()
        applyRageHitmarkerSoundSettings(sound)
    end)
    connections.SoundGroup = sound:GetPropertyChangedSignal("SoundGroup"):Connect(function()
        applyRageHitmarkerSoundSettings(sound)
    end)

    connections.Destroying = sound.Destroying:Connect(function()
        hitChamsUnwatchSound(sound)
    end)

    hitChams.SoundConnections[sound] = connections


    if sound.Playing then
        hitChamsSignalSound(sound)
    end
end

local function handleRageHitmarkerSound(sound, allowPlayback)
    if sound.Name ~= "HitmarkerSound" or not sound:IsA("Sound") then return end

    applyRageHitmarkerSoundSettings(sound)
    hitChamsWatchSound(sound)
end

local function applyRageHitmarkerHook()
    if ragebotController.HitmarkerHookPending or ragebotController.Unloaded then return end
    ragebotController.HitmarkerHookPending = true

    task.spawn(function()
        local playerGuiSuccess, playerGui = pcall(function()
            return lp2:FindFirstChild("PlayerGui") or lp2:WaitForChild("PlayerGui", 5)
        end)
        local coreGuiSuccess, coreGui = pcall(function()
            return playerGuiSuccess and playerGui
                and (playerGui:FindFirstChild("CoreGUI") or playerGui:WaitForChild("CoreGUI", 5))
        end)
        ragebotController.HitmarkerHookPending = false
        if not playerGuiSuccess or not coreGuiSuccess or not coreGui or ragebotController.Unloaded then return end

        if ragebotController.HitmarkerConnection and ragebotController.HitmarkerCoreGui ~= coreGui then
            ragebotController.HitmarkerConnection:Disconnect()
            ragebotController.HitmarkerConnection = nil
        end

        ragebotController.HitmarkerCoreGui = coreGui

        for _, object in ipairs(coreGui:GetDescendants()) do
            handleRageHitmarkerSound(object, false)
        end

        if not ragebotController.HitmarkerConnection then
            ragebotController.HitmarkerConnection = coreGui.DescendantAdded:Connect(function(object)
                handleRageHitmarkerSound(object, true)
            end)
        end
    end)
end

local function updateRageHitsound()
    if rageHitSound.Parent then
        rageHitSound.SoundId = ragebotFlags.hit_Sound_Id
        rageHitSound.Volume = ragebotFlags.hit_Sound_Volume
    end

    if ragebotFlags.hit_Sound then
        for sound in pairs(hitChams.SoundConnections) do
            applyRageHitmarkerSoundSettings(sound)
        end
    else
        restoreRageHitmarkerSounds()
    end

    if ragebotFlags.hit_Sound or hitChams.Enabled then
        applyRageHitmarkerHook()
    end
end

