local function isRageDowned(player)
    local charStats = ragebotController:GetCharStats()

    if not charStats then
        if not ragebotController.CharStatsWarned then
            ragebotController.CharStatsWarned = true
            notify("Rage Bot", "CharStats not found, Downed check unavailable", 4)
        end
        return false
    end

    local stats = charStats:FindFirstChild(player.Name)
    local downed = stats and stats:FindFirstChild("Downed")
    return downed ~= nil and downed.Value == true
end

local function hasMarkedRageEnemies()
    if not (playerlist and playerlist.Players) then return false end
    for _, entry in pairs(playerlist.Players) do
        if entry.Priority and entry.Priority.Text == "Enemy" then
            return true
        end
    end
    return false
end

local isValidRageTarget = LPH_NO_VIRTUALIZE(function(player)
    if not player or player == lp2 then return false end

    local status = getPlayerStatus(player)
    if status == "Friendly" then return false end
    if ragebotFlags.priority_Only and status ~= "Enemy" then return false end

    local character = player.Character
    if not character then return false end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or not root then return false end
    if ragebotFlags.check_Dead and humanoid.Health <= 0 then return false end
    if ragebotFlags.check_ForceField and character:FindFirstChildOfClass("ForceField") then return false end
    if ragebotFlags.check_Downed and isRageDowned(player) then return false end
    if ragebotFlags.check_Team and lp2.Team ~= nil and player.Team == lp2.Team then return false end

    return true
end)

local function getValidRageTarget(player)
    if not isValidRageTarget(player) then return nil end
    local character = player.Character
    return character, character:FindFirstChild("HumanoidRootPart")
end

function ragebotController:ApplyStickiness(targets)
    local sticky = self.StickyTarget
    if not sticky then return end

    local index
    for i, target in ipairs(targets) do
        if target.Player == sticky then
            index = i
            break
        end
    end

    if not index then
        self.StickyTarget = nil
        return
    end

    if not ragebotFlags.target_Sticky or index == 1 then return end

    local current = targets[index]
    local best = targets[1]

    if best.Priority ~= current.Priority then return end

    local margin = math.clamp(tonumber(ragebotFlags.target_Switch_Margin) or 25, 0, 100) / 100
    local threshold = current.SelectionValue * (1 - margin)

    if best.SelectionValue < threshold then return end

    table.remove(targets, index)
    table.insert(targets, 1, current)
end

local buildSortedRageTargets = LPH_NO_VIRTUALIZE(function()
    local targets = {}
    local hasMarkedEnemies = hasMarkedRageEnemies()
    local requireEnemy = ragebotFlags.priority_Only
    local useFov = ragebotFlags.fov_Limit
    local selectionMode = ragebotFlags.target_Selection
    local mousePosition = getAimScreenPosition()
    local localCharacter = lp2.Character
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    if not localRoot then return targets end

    local lockedTarget = ragebotFlags.locked_Target
    if not hasMarkedEnemies then
        ragebotFlags.locked_Target = nil
        lockedTarget = nil
    elseif lockedTarget and (
        not lockedTarget.Parent
        or getPlayerStatus(lockedTarget) ~= "Enemy"
        or not isValidRageTarget(lockedTarget)
    ) then
        ragebotFlags.locked_Target = nil
        lockedTarget = nil
    end

    for _, player in ipairs(plrs:GetPlayers()) do
        local status = getPlayerStatus(player)
        if requireEnemy and status ~= "Enemy" then continue end

        local character, root = getValidRageTarget(player)
        if character and root then
            local screenTarget = character:FindFirstChild("Head") or root
            local screenPosition, onScreen = cam2:WorldToViewportPoint(screenTarget.Position)
            local screenDistance = onScreen
                and (Vector2.new(screenPosition.X, screenPosition.Y) - mousePosition).Magnitude
                or math.huge
            local worldDistance = (root.Position - localRoot.Position).Magnitude
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            local health = humanoid and humanoid.Health or math.huge
            local selectionValue

            if worldDistance > ragebotFlags.max_Distance then continue end

            if selectionMode == "Distance" then
                selectionValue = worldDistance
            elseif selectionMode == "Lowest HP" then
                selectionValue = health
            else
                selectionValue = screenDistance
            end

            if useFov then
                if not onScreen then continue end
                if screenDistance > ragebotFlags.fov_Radius then continue end
            end

            targets[#targets + 1] = {
                Player = player,
                Character = character,
                Root = root,
                Distance = selectionValue,
                SelectionValue = selectionValue,
                ScreenDistance = screenDistance,
                WorldDistance = worldDistance,
                Health = health,
                OnScreen = onScreen,
                Priority = status == "Enemy" and 0 or 1,
                Locked = player == lockedTarget,
            }
        end
    end

    table.sort(targets, function(left, right)
        if left.Priority ~= right.Priority then
            return left.Priority < right.Priority
        end
        if left.SelectionValue ~= right.SelectionValue then
            return left.SelectionValue < right.SelectionValue
        end
        if left.Locked ~= right.Locked then
            return left.Locked
        end
        if left.WorldDistance ~= right.WorldDistance then
            return left.WorldDistance < right.WorldDistance
        end
        if left.ScreenDistance ~= right.ScreenDistance then
            return left.ScreenDistance < right.ScreenDistance
        end
        return left.Player.UserId < right.Player.UserId
    end)

    ragebotController:ApplyStickiness(targets)

    if hasMarkedEnemies then
        ragebotFlags.locked_Target = nil
        for _, target in ipairs(targets) do
            if target.Priority == 0 then
                ragebotFlags.locked_Target = target.Player
                break
            end
        end
    end

    return targets
end)

local rageTargetCacheWindow = 1 / 240
local rageTargetCacheTime = -math.huge
local rageTargetCache = {}

local getSortedRageTargets = LPH_NO_VIRTUALIZE(function()
    local now = os.clock()
    if (now - rageTargetCacheTime) < rageTargetCacheWindow then
        return rageTargetCache
    end

    rageTargetCache = buildSortedRageTargets()
    rageTargetCacheTime = now
    return rageTargetCache
end)

local function resetRageTargetCache()
    rageTargetCache = {}
    rageTargetCacheTime = -math.huge
end

local function findRageTarget()
    local target = getSortedRageTargets()[1]
    if not target then return nil end
    return target.Player, target.Character, target.Root
end

spectateRageTargetProvider = function()
