    return target and target.Player or nil
end

local function generateRageShotId(length)
    local result = ""
    for _ = 1, length do
        result = result .. string.char(math.random(65, 122))
    end
    return result
end

rageProto.ShotId = function()
    local counter = ragebotController.ShotCounter or 0
    ragebotController.ShotCounter = counter + 1
    task.delay(5, function()
        ragebotController.ShotCounter = math.max((ragebotController.ShotCounter or 1) - 1, 0)
    end)
    return generateRageShotId(30) .. tostring(counter)
end

rageProto.SecurityCode = function()
    local values = repSt:FindFirstChild("Values")
    local serverTick = values and values:FindFirstChild("ServerTick")
    if not serverTick then return tick() end
    return serverTick.Value - 28951
end

rageProto.ClientTick = function()
    local values = repSt:FindFirstChild("Values")
    local clientTick = values and values:FindFirstChild("ClientServerTick")
    if not clientTick then return nil end
    return clientTick.Value
end

rageProto.ReloadSpan = function(info)
    local span = (info and tonumber(info.ReloadTime)) or 2
    local stats = repSt:FindFirstChild("CharStats")
    stats = stats and stats:FindFirstChild(lp2.Name)
    if not stats then return span end

    local health = stats:FindFirstChild("HealthValues")
    if health then
        for _, name in ipairs({ "Left Arm", "Right Arm" }) do
            local limb = health:FindFirstChild(name)
            local broken = limb and limb:FindFirstChild("Broken")
            if broken and broken.Value then span *= 1.15 end
        end
    end

    local currents = stats:FindFirstChild("Currents")
    local speed = currents and currents:FindFirstChild("RL_SPM")
    if speed and type(speed.Value) == "number" and speed.Value > 0 then
        span /= speed.Value
    end

    return span
end

local wallLearnLimit

local ragePathFinding = LPH_NO_VIRTUALIZE(function()
    local pathCache = setmetatable({}, { __mode = "k" })
    local lastGood = setmetatable({}, { __mode = "k" })
    local scanCursor = setmetatable({}, { __mode = "k" })
    local methodScore = setmetatable({}, { __mode = "k" })

    local rayBudget = {
        Left = 0,
        Time = -math.huge,
        Deadline = math.huge,
        Scans = setmetatable({}, { __mode = "k" }),
        Scan = nil,
        Last = nil,
        Base = {},
        ServerScratch = {},
    }

    local hitRadiusMax = 4

    local slackLimit = 0
    local leadOffset = Vector3.zero

    local shotCache = setmetatable({}, { __mode = "k" })

    local pingValue = 0
    local pingTime = -math.huge

    local cacheDriftLimit = 24
    local seedLimit = 4
    local seedFailLimit = 3
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.IgnoreWater = true

    local wallParams = RaycastParams.new()
    wallParams.FilterType = Enum.RaycastFilterType.Exclude
    wallParams.IgnoreWater = true

    local exitParams = RaycastParams.new()
    exitParams.FilterType = Enum.RaycastFilterType.Include
    exitParams.IgnoreWater = true

    local serverRayParams = RaycastParams.new()
    serverRayParams.FilterType = Enum.RaycastFilterType.Exclude
    serverRayParams.IgnoreWater = true

    local wallScratch = {}
    local exitScratch = { nil }
    local serverRaySkipCache = setmetatable({}, { __mode = "k" })
    local charactersFolder2 = workspace:FindFirstChild("Characters")

    local r6Hitboxes = {
        Head = true, Torso = true,
        ["Left Arm"] = true, ["Right Arm"] = true,
        ["Left Leg"] = true, ["Right Leg"] = true,
    }

    local serverRaySkip = LPH_NO_VIRTUALIZE(function(instance)
        local cached = serverRaySkipCache[instance]
        if cached ~= nil then
            if cached == 2 then return false end
            if cached == 1 then return true end
        else
            if instance:FindFirstChild("CanHitT") then
                serverRaySkipCache[instance] = 2
                return false
            end
            if instance:FindFirstChild("FilterV") or instance:GetAttribute("RayHandlerIG") then
                serverRaySkipCache[instance] = 1
                return true
            end
            if charactersFolder2 and instance:IsDescendantOf(charactersFolder2)
                and not r6Hitboxes[instance.Name] then
                serverRaySkipCache[instance] = 1
                return true
            end
            serverRaySkipCache[instance] = 0
        end

        return instance.Transparency >= 1 and instance.Name ~= "MainPart"
    end)

    local serverCast = LPH_NO_VIRTUALIZE(function(fromPosition, direction)
        for _ = 1, 16 do
            local hit = workspace:Raycast(fromPosition, direction, serverRayParams)
            if not hit then return nil end
            if not serverRaySkip(hit.Instance) then return hit.Position end

            rayBudget.Left -= 1
            local scratch = rayBudget.ServerScratch
            scratch[#scratch + 1] = hit.Instance
            serverRayParams.FilterDescendantsInstances = scratch
        end

        return nil
    end)

    local wallInfo = {
        Thickness = 0,
        Walls = 0,
        Material = "Unknown",
        Name = "Unknown",
        Learned = false,
    }

    local fixedVectors = {
        Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 1, 0),
        -Vector3.new(1, 0, 0), -Vector3.new(0, 0, 1), -Vector3.new(0, 1, 0),
        Vector3.new(1, 1, 0) / math.sqrt(2), Vector3.new(1, 0, 1) / math.sqrt(2), Vector3.new(0, 1, 1) / math.sqrt(2),
        Vector3.new(-1, 1, 0) / math.sqrt(2), Vector3.new(-1, 0, 1) / math.sqrt(2),
        -Vector3.new(1, 0, 1) / math.sqrt(2), -Vector3.new(-1, 0, 1) / math.sqrt(2), -Vector3.new(0, -1, 1) / math.sqrt(2),
        Vector3.new(1, 1, 1) / math.sqrt(3), Vector3.new(-1, 1, 1) / math.sqrt(3), Vector3.new(1, 1, -1) / math.sqrt(3),
        -Vector3.new(1, 1, 1) / math.sqrt(3), -Vector3.new(1, -1, 1) / math.sqrt(3),
        Vector3.new(1, 2, 0) / math.sqrt(5), Vector3.new(-1, 2, 0) / math.sqrt(5), Vector3.new(1, 0, 2) / math.sqrt(5), Vector3.new(-1, 0, 2) / math.sqrt(5),
        -Vector3.new(-1, 0, 2) / math.sqrt(5), -Vector3.new(1, 0, 2) / math.sqrt(5),
    }

    local cardinalDirections = { -- // gamesense pathfinding gon be like: 
        Vector3.new(0, 1, 0), -- -- // not pasted of gs btw nigga
        Vector3.new(0, -1, 0),
        Vector3.new(0, 0, 1),
        Vector3.new(0, 0, -1),
        Vector3.new(1, 0, 0),
        Vector3.new(-1, 0, 0),
    }

    local bounceDirections = {
        Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0),
        Vector3.new(0, 1, 0), Vector3.new(0, -1, 0),
        Vector3.new(0, 0, 1), Vector3.new(0, 0, -1),
        Vector3.new(1, 1, 0).Unit, Vector3.new(-1, 1, 0).Unit,
    }

    local methodOrder = {
        "Fixed",
        "Hemi",
        "Bounce",
        "Femboy",
        "Random",
        "Cardinals",
        "Vector",
        "Hammersley",
        "Halo",
        "Cylinder",
        "Shell",
    }

    local boneOrder = {
        "Head",
        "Torso",
        "HumanoidRootPart",
        "Left Arm",
        "Right Arm",
        "Left Leg",
        "Right Leg",
    }

    local methodRank = (function()
        local ranks = {}
        for index, name in ipairs(methodOrder) do
            ranks[name] = index
        end
        return ranks
    end)()

    local boneWeights = {
        Head = 4,
        Torso = 3,
        HumanoidRootPart = 2,
        ["Left Arm"] = 1,
        ["Right Arm"] = 1,
        ["Left Leg"] = 1,
        ["Right Leg"] = 1,
    }

    local function clearCache()
        table.clear(pathCache)
        table.clear(lastGood)
        table.clear(scanCursor)
        table.clear(methodScore)
        table.clear(shotCache)
        table.clear(serverRaySkipCache)
        table.clear(rayBudget.Scans)
        rayBudget.Scan = nil
        rayBudget.Last = nil
    end

    local function pace()
        local scan = rayBudget.Scan
        if scan and os.clock() > rayBudget.Deadline and coroutine.running() == scan.Thread then
            coroutine.yield()
        end
    end

    local function getHitRadius()
        return math.clamp(tonumber(ragebotFlags.path_Target_Shift_Range) or 3, 0.1, hitRadiusMax)
    end

    -- // лид по пингу
    local function getLead(targetCharacter)
        local targetRoot = ragebotFlags.lead_Enabled and targetCharacter
            and targetCharacter:FindFirstChild("HumanoidRootPart")
        if not targetRoot then return Vector3.zero end

        local now = os.clock()
        if (now - pingTime) >= 0.25 then
            pingTime = now
            local ok, value = pcall(function()
                return stats2.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
            end)
            pingValue = (ok and type(value) == "number") and math.clamp(value, 0, 1) or 0
        end

        local velocity = targetRoot.AssemblyLinearVelocity
        if pingValue <= 0 or velocity.Magnitude <= 0.1 then return Vector3.zero end
        return velocity * (pingValue * (ragebotFlags.lead_Scale / 100))
    end

    local function scoreMethod(targetCharacter, methodName, success)
        if not methodRank[methodName] then return end

        local store = methodScore[targetCharacter]
        if not store then
            store = {}
            methodScore[targetCharacter] = store
        end

        local value = store[methodName] or 0
        if success then
            store[methodName] = math.min(12, value + 3)
        else
            store[methodName] = math.max(-6, value - 1)
        end
    end

    local function noteShot(targetCharacter)
        local limit = math.floor(tonumber(ragebotFlags.path_Max_Miss) or 0)
        if limit <= 0 then return end

        local store = lastGood[targetCharacter]
        local entry = store and store[1]
        if not entry then return end

        entry.Shots = (entry.Shots or 0) + 1
        if entry.Shots <= limit then return end

        table.remove(store, 1)
        if #store == 0 then lastGood[targetCharacter] = nil end
        pathCache[targetCharacter] = nil
    end

    local function rememberLine(targetCharacter, entry)
        local store = lastGood[targetCharacter]
        if not store then
            store = {}
            lastGood[targetCharacter] = store
        end

        for index = #store, 1, -1 do
            if store[index].Method == entry.Method then
                table.remove(store, index)
            end
        end

        table.insert(store, 1, entry)

        for index = #store, seedLimit + 1, -1 do
            store[index] = nil
        end
    end

    local function getCursor(targetCharacter, key, total)
        local store = scanCursor[targetCharacter]
        if not store then return 0 end
        local saved = store[key]
        if not saved or saved < 0 or saved >= total then return 0 end
        return saved
    end

    local function setCursor(targetCharacter, key, value)
        local store = scanCursor[targetCharacter]
        if not store then
            store = {}
            scanCursor[targetCharacter] = store
        end
        store[key] = value
    end

    local function getPriorityParts(targetCharacter)
        local parts = {}
        local weights = {}
        local selected = ragebotFlags.hitbox_Parts

        for _, name in ipairs(boneOrder) do
            if selected[name] then
                local part = targetCharacter:FindFirstChild(name)
                if part then
                    parts[#parts + 1] = part
                    weights[#weights + 1] = boneWeights[name] or 1
                end
            end
        end

        return parts, weights
    end

    local isPathClear = LPH_NO_VIRTUALIZE(function(fromPosition, toPosition, allowSlack)
        local direction = toPosition - fromPosition
        if direction.Magnitude <= 0.0001 then return true end

        local blocked
        if ragebotFlags.server_Ray_Rules then
            blocked = serverCast(fromPosition, direction)
            if not blocked then return true end
        else
            local hit = workspace:Raycast(fromPosition, direction, rayParams)
            if not hit then return true end
            blocked = hit.Position
        end

        local gap = (toPosition - blocked).Magnitude
        if allowSlack and gap < slackLimit then return true, gap end

        return false, gap
    end)

    local measureBlock = LPH_NO_VIRTUALIZE(function(fromPosition, toPosition, maxWalls)
        local delta = toPosition - fromPosition
        local span = delta.Magnitude
        if span <= 0.0001 then return 0, 0, nil, nil end

        local direction = delta / span

        table.clear(wallScratch)
        for _, instance in ipairs(rayBudget.Base) do
            wallScratch[#wallScratch + 1] = instance
        end
        wallParams.FilterDescendantsInstances = wallScratch

        local travelled = 0
        local thickness = 0
        local walls = 0
        local material = nil
        local blockerName = nil

        while true do
            local remaining = span - travelled
            if remaining <= 0.0001 then break end

            local hit = workspace:Raycast(
                fromPosition + direction * travelled, direction * remaining, wallParams
            )
            if not hit then break end

            walls += 1
            if not material then
                material = hit.Material
                blockerName = hit.Instance and hit.Instance.Name or nil
            end
            if walls > maxWalls then return math.huge, walls, material, blockerName end

            exitScratch[1] = hit.Instance
            exitParams.FilterDescendantsInstances = exitScratch

            local back = workspace:Raycast(toPosition, -direction * span, exitParams)
            local entryDistance = (hit.Position - fromPosition).Magnitude
            local exitDistance = back and (back.Position - fromPosition).Magnitude or span
            if exitDistance < entryDistance then exitDistance = entryDistance end

            thickness += exitDistance - entryDistance

            wallScratch[#wallScratch + 1] = hit.Instance
            wallParams.FilterDescendantsInstances = wallScratch

            travelled = exitDistance + 0.05
        end

        return thickness, walls, material, blockerName
    end)

    local function getScanInterval()
        local percent = math.clamp(tonumber(ragebotFlags.path_Scanning_Rate) or 50, 5, 100)
        local hz = math.max(1, 60 * (percent / 100))
        return 1 / hz
    end

    local function getEnabledMethods(preferred, targetCharacter)
        local enabled = {}
        local selected = ragebotFlags.path_Scan_Types or {}
        for _, name in ipairs(methodOrder) do
            if selected[name] then enabled[#enabled + 1] = name end
        end

        local scores = methodScore[targetCharacter]
        if scores and #enabled > 1 then
            table.sort(enabled, function(left, right)
                local leftScore = scores[left] or 0
                local rightScore = scores[right] or 0
                if leftScore ~= rightScore then return leftScore > rightScore end
                return methodRank[left] < methodRank[right]
            end)
        end

        if preferred and #enabled > 1 then
            local index = table.find(enabled, preferred)
            if index and index > 1 then
                table.remove(enabled, index)
                table.insert(enabled, 1, preferred)
            end
        end

        return enabled
    end

    local function getFixedPositions(center, target, radius)
        if not radius or radius <= 0 then return { center } end
        local positions = { center }
        local frame = CFrame.new(center, target) * CFrame.Angles(0, 0, math.rad(math.random(1, 90)))
        for _, vector in ipairs(fixedVectors) do
            positions[#positions + 1] = frame * (vector * radius)
        end
        return positions
    end

    local function getHemiPositions(center, poleDirection, radius, count)
        if not radius or radius <= 0 or count <= 0 then return { center } end
        local positions = { center }
        local phi2 = 0.6180339887
        local pole = poleDirection
        if pole.Magnitude <= 0.001 then pole = Vector3.new(0, 0, -1) else pole = pole.Unit end

        local arbitrary = math.abs(pole.X) < 0.9 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
        local tangent1 = pole:Cross(arbitrary).Unit
        local tangent2 = pole:Cross(tangent1).Unit

        for index = 0, count - 1 do
            local phi = index * phi2 * 2 * math.pi
            local cosTheta = 1 - (index + 0.5) / count
            local sinTheta = math.sqrt(math.max(0, 1 - cosTheta * cosTheta))
            local distance = radius * (math.random() ^ (1 / 3))
            local direction = tangent1 * (sinTheta * math.cos(phi))
                + tangent2 * (sinTheta * math.sin(phi))
                + pole * cosTheta
            positions[#positions + 1] = center + direction * distance
        end

        return positions
    end

    local function getRandomOffsets(count, radius)
        local offsets = {}
        local twoPi = math.pi * 2
        for index = 1, count do
            local distance = radius * (math.random() ^ (1 / 3))
            local cosine = math.random() * 2 - 1
            local sineComponent = distance * math.sqrt(math.max(0, 1 - cosine * cosine))
            local theta = math.random() * twoPi
            offsets[index] = Vector3.new(
                sineComponent * math.cos(theta),
                sineComponent * math.sin(theta),
                distance * cosine
            )
        end
        return offsets
    end

    local function getCardinalOffsets(count, radius)
        local offsets = {}
        local total = #cardinalDirections
        local cycles = math.max(1, math.ceil(count / total))
        for index = 1, count do
            local cycle = math.floor((index - 1) / total)
            local direction = cardinalDirections[(index - 1) % total + 1]
            offsets[index] = direction * (radius * (1 - cycle / cycles))
        end
        return offsets
    end

    local function getHammersleyOffsets(count, radius)
        local offsets = { Vector3.new(0, 0, 0) }
        local twoPi = math.pi * 2
        for index = 1, count do
            local base = 0.5
            local radical = 0
            local value = index
            while value > 0 do
                if value % 2 == 1 then radical += base end
                value = math.floor(value / 2)
                base *= 0.5
            end

            local u = index / count
            local theta = twoPi * radical
            local phi = math.acos(1 - 2 * u)
            local sinPhi = math.sin(phi)
            offsets[#offsets + 1] = Vector3.new(
                radius * sinPhi * math.cos(theta),
                radius * math.cos(phi),
                radius * sinPhi * math.sin(theta)
            )
        end
        return offsets
    end

    local function getVectorOffsets(count, radius)
        local offsets = {}
        for index = 1, count do
            offsets[index] = Vector3.new(
                (math.random() * 2 - 1) * radius,
                (math.random() * 2 - 1) * radius,
                (math.random() * 2 - 1) * radius
            )
        end
        return offsets
    end

    local function getFemboyOffsets(count, radius)
        local offsets = {}
        local phi = (1 + math.sqrt(5)) / 2
        local angleIncrement = math.pi * 2 * phi
        for index = 0, count - 1 do
            local progress = index / math.max(count, 1)
            local inclination = math.acos(1 - 2 * progress)
            local azimuth = angleIncrement * index
            local x = math.sin(inclination) * math.cos(azimuth)
            local y = math.sin(inclination) * math.sin(azimuth)
            local z = math.cos(inclination)
            offsets[#offsets + 1] = Vector3.new(x * radius, y * radius, z * radius)
        end
        return offsets
    end

    local function getShellOffsets(count, radius)
        local offsets = {}
        for index = 1, #cardinalDirections do
            offsets[index] = cardinalDirections[index] * radius
        end

        local twoPi = math.pi * 2
        for _ = 1, count do
            local cosine = math.random() * 2 - 1
            local ring = radius * math.sqrt(math.max(0, 1 - cosine * cosine))
            local theta = math.random() * twoPi
            offsets[#offsets + 1] = Vector3.new(
                ring * math.cos(theta),
                ring * math.sin(theta),
                radius * cosine
            )
        end

        return offsets
    end

    local function offsetsToPositions(center, offsets, addCenter, addTop, radius)
        local positions = {}
        if addCenter then positions[#positions + 1] = center end
        if addTop then positions[#positions + 1] = center + Vector3.new(0, radius, 0) end
        for _, offset in ipairs(offsets) do
            local length = offset.Magnitude
            if length > radius then offset = offset * (radius / length) end
            positions[#positions + 1] = center + offset
        end
        return positions
    end

    local function getHaloOffsets(count, radius, axis)
        local right = axis:Cross(Vector3.new(0, 1, 0))
        if right.Magnitude <= 0.001 then right = axis:Cross(Vector3.new(1, 0, 0)) end
        if right.Magnitude <= 0.001 then return { Vector3.zero } end
        right = right.Unit

        local up = axis:Cross(right)
        if up.Magnitude <= 0.001 then return { Vector3.zero } end
        up = up.Unit

        local offsets = {}
        local twoPi = math.pi * 2
        for index = 1, count do
            local angle = twoPi * (index - 1) / count
            local scale = index % 2 == 0 and 0.55 or 1
            offsets[index] = right * (math.cos(angle) * radius * scale)
                + up * (math.sin(angle) * radius * scale)
        end
        return offsets
    end

    local function getCylinderOffsets(count, radius)
        local offsets = {}
        local twoPi = math.pi * 2
        local height = radius * 0.5
        for index = 1, count do
            local angle = twoPi * (index - 1) / count
            local band = 0.5 + (index % 3) * 0.25
            local level = ((index % 5) - 2) / 2
            offsets[index] = Vector3.new(
                math.cos(angle) * radius * band,
                level * height,
                math.sin(angle) * radius * band
            )
        end
        return offsets
    end

    local bounceOriginRatio = 0.8

    local function getMethodPositions(methodName, center, reference, radius, count)
        if radius <= 0 or count <= 0 then return { center } end

        if methodName == "Fixed" then
            return getFixedPositions(center, reference, radius)

        elseif methodName == "Hemi" then
            local pole = reference - center
            if pole.Magnitude <= 0.001 then return { center } end
            return getHemiPositions(center, pole.Unit, radius, count)

        elseif methodName == "Femboy" then
            local offsets = getFemboyOffsets(count, radius)
            table.insert(offsets, 1, Vector3.zero)
            return offsetsToPositions(center, offsets, false, false, radius)

        elseif methodName == "Bounce" then
            return offsetsToPositions(center, getRandomOffsets(count, radius), true, false, radius)

        elseif methodName == "Random" then
            return offsetsToPositions(center, getRandomOffsets(count, radius), true, true, radius)

        elseif methodName == "Cardinals" then
            return offsetsToPositions(center, getCardinalOffsets(count, radius), true, false, radius)

        elseif methodName == "Vector" then
            return offsetsToPositions(center, getVectorOffsets(count, radius), true, false, radius)

        elseif methodName == "Hammersley" then
            return offsetsToPositions(center, getHammersleyOffsets(count, radius), true, false, radius)

        elseif methodName == "Halo" then
            local axis = reference - center
            if axis.Magnitude <= 0.001 then return { center } end
            return offsetsToPositions(center, getHaloOffsets(count, radius, axis.Unit), true, false, radius)

        elseif methodName == "Cylinder" then
            return offsetsToPositions(center, getCylinderOffsets(count, radius), true, false, radius)

        elseif methodName == "Shell" then
            return offsetsToPositions(center, getShellOffsets(count, radius), true, false, radius)
        end

        return { center }
    end

    local function searchPath(localRoot, targetCharacter, priorityParts, partWeights, preferredMethod)
        local methodBudget = math.max(1, math.floor(tonumber(ragebotFlags.path_Candidates) or 120))

        local fallback = { Gap = math.huge }
        local lead = leadOffset

        for _, part in ipairs(priorityParts) do
            pace()
            rayBudget.Left -= 1
            local aim = part.Position + lead
            local clear, gap = isPathClear(localRoot.Position, aim, true)
            if clear then
                return localRoot.Position, aim, part, "Direct"
            end
            if gap and gap < fallback.Gap then
                fallback.Gap = gap
                fallback.From = localRoot.Position
                fallback.To = aim
                fallback.BestPart = part
                fallback.BestMethod = "Direct"
            end
        end

        local methods = getEnabledMethods(preferredMethod, targetCharacter)
        if #methods == 0 then return nil end

        local originRadius = math.clamp(tonumber(ragebotFlags.path_Origin_Shift_Range) or 19.00, 0.1, 19.50)
        local hitRadius = getHitRadius()
        local originScans = math.max(1, math.floor(tonumber(ragebotFlags.path_Origin_Scans) or 20))
        local hitScans = math.max(1, math.floor(tonumber(ragebotFlags.path_Hit_Scans) or 20))

        local partCount = #priorityParts
        local bias = math.clamp(tonumber(ragebotFlags.hitbox_Bias) or 100, 0, 100) / 100
        local weightTotal = 0
        for index = 1, partCount do
            weightTotal += partWeights[index]
        end

        local methodUsed = 0
        local budgetCap = methodBudget
        local function tryMethod(fromPosition, toPosition, allowSlack)
            if methodUsed >= budgetCap or rayBudget.Left <= 0 then return false, true end
            pace()
            methodUsed += 1
            rayBudget.Left -= 1

            local clear, gap = isPathClear(fromPosition, toPosition, allowSlack)
            if not clear and fallback.Part and gap and gap < fallback.Gap then
                fallback.Gap = gap
                fallback.From = fromPosition
                fallback.To = toPosition
                fallback.BestPart = fallback.Part
                fallback.BestMethod = fallback.Method
            end

            return clear, methodUsed >= budgetCap or rayBudget.Left <= 0
        end

        local anchorPosition = priorityParts[1].Position + lead

        for _, methodName in ipairs(methods) do
            methodUsed = 0
            budgetCap = methodBudget

            if rayBudget.Left <= 0 then break end

            if methodName == "Bounce" then
                local bounceTotal = #bounceDirections
                local bounceStart = getCursor(targetCharacter, "Bounce", bounceTotal)
                local bounceStep = 0

                while bounceStep < bounceTotal do
                    local bounceIndex = (bounceStart + bounceStep) % bounceTotal
                    local direction = bounceDirections[bounceIndex + 1]
                    bounceStep += 1

                    local bouncePosition = localRoot.Position + direction * (originRadius * bounceOriginRatio)
                    local firstClear, exhausted = tryMethod(localRoot.Position, bouncePosition)

                    if firstClear then
                        for _, part in ipairs(priorityParts) do
                            local hits = getMethodPositions(
                                methodName, part.Position + lead, bouncePosition, hitRadius, hitScans
                            )

                            fallback.Part = part
                            fallback.Method = methodName

                            for _, hitPosition in ipairs(hits) do
                                local secondClear, secondExhausted = tryMethod(bouncePosition, hitPosition, true)
                                if secondClear then
                                    setCursor(targetCharacter, "Bounce", bounceIndex)
                                    scoreMethod(targetCharacter, methodName, true)
                                    return bouncePosition, hitPosition, part, methodName
                                end
                                if secondExhausted then break end
                            end

                            fallback.Part = nil

                            if methodUsed >= budgetCap then break end
                        end
                    end

                    if exhausted or methodUsed >= budgetCap then break end
                end

                setCursor(targetCharacter, "Bounce", (bounceStart + bounceStep) % bounceTotal)

            else
                local origins = getMethodPositions(
                    methodName, localRoot.Position, anchorPosition, originRadius, originScans
                )

                local weightRunning = 0

                for partIndex, part in ipairs(priorityParts) do
                    weightRunning += partWeights[partIndex]

                    if partIndex == partCount then
                        budgetCap = methodBudget
                    else
                        local evenShare = partIndex / partCount
                        local weightedShare = weightRunning / weightTotal
                        local share = evenShare + (weightedShare - evenShare) * bias
                        budgetCap = math.clamp(
                            math.floor(methodBudget * share + 0.5),
                            partIndex,
                            methodBudget
                        )
                    end

                    local hits = getMethodPositions(
                        methodName, part.Position + lead, localRoot.Position, hitRadius, hitScans
                    )

                    local originCount = #origins
                    local pairTotal = #hits * originCount

                    if pairTotal > 0 then
                        local cursorKey = methodName .. part.Name
                        local cursorStart = getCursor(targetCharacter, cursorKey, pairTotal)
                        local walked = 0

                        fallback.Part = part
                        fallback.Method = methodName

                        while walked < pairTotal do
                            local linear = (cursorStart + walked) % pairTotal
                            local hitPosition = hits[math.floor(linear / originCount) + 1]
                            local originPosition = origins[linear % originCount + 1]
                            walked += 1

                            local clear, exhausted = tryMethod(originPosition, hitPosition, true)
                            if clear then
                                setCursor(targetCharacter, cursorKey, linear)
                                scoreMethod(targetCharacter, methodName, true)
                                return originPosition, hitPosition, part, methodName
                            end
                            if exhausted then break end
                        end

                        setCursor(targetCharacter, cursorKey, (cursorStart + walked) % pairTotal)
                        fallback.Part = nil
                    end

                    if methodUsed >= methodBudget then break end
                end
            end

            if methodUsed > 0 then
                scoreMethod(targetCharacter, methodName, false)
            end
        end

        return nil, nil, nil, nil, fallback
    end

    local function computePath(localRoot, targetCharacter)
        local priorityParts, partWeights = getPriorityParts(targetCharacter)
        if #priorityParts == 0 then return nil end

        local base = { cam2, lp2.Character, targetCharacter }
        local scratch = {}
        for index, instance in ipairs(base) do
            scratch[index] = instance
        end
        rayBudget.Base = base
        rayBudget.ServerScratch = scratch
        rayParams.FilterDescendantsInstances = base
        serverRayParams.FilterDescendantsInstances = scratch

        local targetRoot = targetCharacter:FindFirstChild("HumanoidRootPart")

        slackLimit = 0
        if ragebotFlags.hit_Slack then
            local slack = math.max(0, tonumber(ragebotFlags.hit_Slack_Range) or 25)
            if ragebotFlags.hit_Slack_Velocity and targetRoot then
                slack += targetRoot.AssemblyLinearVelocity.Magnitude
            end
            slackLimit = slack
        end

        leadOffset = getLead(targetCharacter)

        local scan = rayBudget.Scan
        if scan then
            scan.Base = base
            scan.Scratch = scratch
            scan.Slack = slackLimit
            scan.Lead = leadOffset
        end

        local wallEnabled = ragebotFlags.wall_Bang == true
        local wallLimit = math.max(0.1, tonumber(ragebotFlags.wall_Thickness) or 4)
        local wallCount = math.max(1, math.floor(tonumber(ragebotFlags.wall_Count) or 1))

        local store = lastGood[targetCharacter]
        if store then
            local index = 1
            while index <= #store do
                local entry = store[index]
                local entryPart = entry.Part

                if not entryPart
                    or not entryPart.Parent
                    or not table.find(priorityParts, entryPart)
                    or (entry.Wall and not wallEnabled) then
                    table.remove(store, index)
                else
                    pace()
                    local seedOrigin = localRoot.Position + entry.OriginOffset
                    local seedHit = entryPart.Position + leadOffset + entry.HitOffset
                    local passed

                    if entry.Wall then
                        local thickness, walls, material, blockerName =
                            measureBlock(seedOrigin, seedHit, wallCount)
                        rayBudget.Left -= walls * 2 + 1

                        local limit, learned = wallLimit, false
                        if wallLearnLimit then
                            limit, learned = wallLearnLimit(
                                material and material.Name or nil, blockerName, wallLimit
                            )
                        end

                        passed = walls > 0 and thickness <= limit
                        if passed then
                            wallInfo.Thickness = thickness
                            wallInfo.Walls = walls
                            wallInfo.Material = material and material.Name or "Unknown"
                            wallInfo.Name = blockerName or "Unknown"
                            wallInfo.Learned = learned
                        end
                    else
                        rayBudget.Left -= 1
                        passed = isPathClear(seedOrigin, seedHit, true)
                    end

                    if passed then
                        entry.Fails = 0
                        if index > 1 then
                            table.remove(store, index)
                            table.insert(store, 1, entry)
                        end
                        return seedOrigin, seedHit, entryPart, entry.Method, true, false, entry.Wall == true
                    end

                    entry.Fails = (entry.Fails or 0) + 1
                    if entry.Fails >= seedFailLimit then
                        table.remove(store, index)
                    else
                        index += 1
                    end
                end
            end

            if #store == 0 then lastGood[targetCharacter] = nil end
        end

        local history = ragebotFlags.shot_Cache and shotCache[targetCharacter] or nil
        if history then
            local tolerance = math.max(0, tonumber(ragebotFlags.shot_Cache_Tolerance) or 0.6)
            local originLimit = math.clamp(tonumber(ragebotFlags.path_Origin_Shift_Range) or 19, 0.1, 19.5) + tolerance
            local hitLimit = getHitRadius() + tolerance
            local index = 1

            while index <= #history do
                local entry = history[index]
                local entryPart = entry.Part

                if not entryPart or not entryPart.Parent or not table.find(priorityParts, entryPart) then
                    table.remove(history, index)
                else
                    pace()
                    local aim = entryPart.Position + leadOffset

                    if rayBudget.Left > 0
                        and (localRoot.Position - entry.Origin).Magnitude <= originLimit
                        and (aim - entry.Goal).Magnitude <= hitLimit then
                        rayBudget.Left -= 1
                        if isPathClear(entry.Origin, entry.Goal, true) then
                            return entry.Origin, entry.Goal, entryPart, entry.Method, true, false, false
                        end
                    end

                    index += 1
                end
            end

            if #history == 0 then shotCache[targetCharacter] = nil end
        end

        if rayBudget.Left <= 0 then return nil, nil, nil, nil, false, true end

        local shootPosition, hitPosition, hitPart, methodName, fallback = searchPath(
            localRoot, targetCharacter, priorityParts, partWeights,
            store and store[1] and store[1].Method
        )

        local throughWall = false

        if not shootPosition
            and wallEnabled
            and fallback
            and fallback.BestPart
            and fallback.BestPart.Parent then
            pace()
            local thickness, walls, material, blockerName =
                measureBlock(fallback.From, fallback.To, wallCount)
            rayBudget.Left -= walls * 2 + 1

            local limit, learned = wallLimit, false
            if wallLearnLimit then
                limit, learned = wallLearnLimit(
                    material and material.Name or nil, blockerName, wallLimit
                )
            end

            if walls > 0 and thickness <= limit then
                shootPosition = fallback.From
                hitPosition = fallback.To
                hitPart = fallback.BestPart
                methodName = fallback.BestMethod
                throughWall = true

                wallInfo.Thickness = thickness
                wallInfo.Walls = walls
                wallInfo.Material = material and material.Name or "Unknown"
                wallInfo.Name = blockerName or "Unknown"
                wallInfo.Learned = learned
            end
        end

        if shootPosition then
            rememberLine(targetCharacter, {
                OriginOffset = shootPosition - localRoot.Position,
                HitOffset = hitPosition - (hitPart.Position + leadOffset),
                Part = hitPart,
                Method = methodName,
                Wall = throughWall,
                Fails = 0,
                Shots = 0,
            })

            if ragebotFlags.shot_Cache and not throughWall then
                local history = shotCache[targetCharacter]
                if not history then
                    history = {}
                    shotCache[targetCharacter] = history
                end

                table.insert(history, 1, {
                    Origin = shootPosition,
                    Goal = hitPosition,
                    Part = hitPart,
                    Method = methodName,
                })

                local size = math.max(1, math.floor(tonumber(ragebotFlags.shot_Cache_Size) or 5))
                for index = #history, size + 1, -1 do
                    history[index] = nil
                end
            end
        end

        return shootPosition, hitPosition, hitPart, methodName, false, false, throughWall
    end

    local function findPath(localRoot, targetCharacter)
        local now = os.clock()
        local targetRoot = targetCharacter and targetCharacter:FindFirstChild("HumanoidRootPart")
        if not targetRoot then return nil end

        local cached = pathCache[targetCharacter]
        local interval = getScanInterval()

        if (now - rayBudget.Time) >= interval then
            rayBudget.Time = now
            rayBudget.Left = math.max(1, math.floor(tonumber(ragebotFlags.path_Ray_Budget) or 1500))
        end

        if cached and (now - cached.Time) < interval then
            if not cached.Found then return nil end
            if not cached.HitPart or not cached.HitPart.Parent then return nil end

            local localDrift = localRoot.Position - cached.LocalPosition
            local targetDrift = targetRoot.Position - cached.TargetPosition

            if localDrift.Magnitude > cacheDriftLimit
                or targetDrift.Magnitude > cacheDriftLimit then
                return nil
            end

            if cached.Wall then
                wallInfo.Thickness = cached.WallThickness or 0
                wallInfo.Walls = cached.WallCount or 0
                wallInfo.Material = cached.WallMaterial or "Unknown"
                wallInfo.Name = cached.WallName or "Unknown"
                wallInfo.Learned = cached.WallLearned == true
            end

            return cached.ShootPosition + localDrift,
                cached.HitPosition + targetDrift,
                cached.HitPart,
                cached.Method,
                true,
                cached.Wall
        end

        local scans = rayBudget.Scans
        local scan = scans[targetCharacter]
        if scan and (scan.Root ~= localRoot or now - scan.Time > 0.25) then
            scans[targetCharacter] = nil
            scan = nil
        end
        if now > rayBudget.Deadline then return nil end

        if not scan then
            scan = { Root = localRoot, Thread = coroutine.create(computePath) }
            scans[targetCharacter] = scan
        end
        scan.Time = now

        rayBudget.Scan = scan
        if scan.Base and rayBudget.Last ~= scan then
            rayBudget.Base = scan.Base
            rayBudget.ServerScratch = scan.Scratch
            rayParams.FilterDescendantsInstances = scan.Base
            serverRayParams.FilterDescendantsInstances = scan.Scratch
            slackLimit = scan.Slack
            leadOffset = scan.Lead
        end
        rayBudget.Last = scan

        local ok, shootPosition, hitPosition, hitPart, methodName, fromSeed, starved, throughWall =
            coroutine.resume(scan.Thread, localRoot, targetCharacter)
        rayBudget.Scan = nil
        if coroutine.status(scan.Thread) ~= "dead" then return nil end
        if scans[targetCharacter] == scan then scans[targetCharacter] = nil end
        if not ok or starved then return nil end

        pathCache[targetCharacter] = {
            Time = now,
            LocalPosition = localRoot.Position,
            TargetPosition = targetRoot.Position,
            Found = shootPosition ~= nil,
            ShootPosition = shootPosition,
            HitPosition = hitPosition,
            HitPart = hitPart,
            Method = methodName,
            Wall = throughWall,
            WallThickness = throughWall and wallInfo.Thickness or nil,
            WallCount = throughWall and wallInfo.Walls or nil,
            WallMaterial = throughWall and wallInfo.Material or nil,
            WallName = throughWall and wallInfo.Name or nil,
            WallLearned = throughWall and wallInfo.Learned or nil,
        }

        return shootPosition, hitPosition, hitPart, methodName, fromSeed, throughWall
    end

    return {
        ClearCache = clearCache,
        Find = findPath,
        NoteShot = noteShot,
        Frame = function()
            local now = os.clock()
            local limit = math.clamp(tonumber(ragebotFlags.path_Frame_Time) or 4, 1, 16)
            rayBudget.Deadline = now + limit / 1000

            for target, scan in pairs(rayBudget.Scans) do
                if now - scan.Time > 0.25 then rayBudget.Scans[target] = nil end
            end
        end,
        Lead = getLead,
        HitRadius = getHitRadius,
        Parts = getPriorityParts,
        Bones = boneOrder,
        WallInfo = wallInfo,
    }
end)()
drainBootLog("ragebot built")

local hitLog = {
    Enabled = false,
    ShowMethod = true,
    ShowCache = true,
    Lifetime = 4,
    Window = 0.9,
    WallColor = Color3.fromRGB(255, 200, 0),
    Pending = {},
    Health = setmetatable({}, { __mode = "k" }),
}

local wallLearn = {
    Enabled = false,
    Adaptive = false,
    Http = game:GetService("HttpService"),
    Path = "drain.solutions/Wallbang/wallbang.json",
    Version = 2,
    Buckets = {},
    Samples = {},
    SampleLimit = 400,
    BucketLimit = 600,
    MinSamples = 12,
    NameSamples = 6,
    Explore = 10,
    RiseRate = 0.35,
    FallRate = 0.15,
    RateFloor = 0.25,
    RateDecay = 0.97,
    SaveInterval = 30,
    SavedAt = 0,
    Dirty = false,
    Loaded = false,
    Capable = (writefile and readfile and isfile) and true or false,
}

wallLearn.Load = function()
    if wallLearn.Loaded or not wallLearn.Capable then return end
    wallLearn.Loaded = true

    local ok, raw = pcall(readfile, wallLearn.Path)
    if not ok or type(raw) ~= "string" or raw == "" then return end

    local decoded
    ok, decoded = pcall(wallLearn.Http.JSONDecode, wallLearn.Http, raw)
    if not ok or type(decoded) ~= "table" then return end

    if type(decoded.Buckets) == "table" then wallLearn.Buckets = decoded.Buckets end
    if decoded.Version == wallLearn.Version and type(decoded.Samples) == "table" then
        wallLearn.Samples = decoded.Samples
    end
end

wallLearn.Save = function()
    if not wallLearn.Capable then return end

    if isfolder and makefolder and not isfolder("drain.solutions") then
        pcall(makefolder, "drain.solutions")
    end

    local ok, encoded = pcall(wallLearn.Http.JSONEncode, wallLearn.Http, {
        Version = wallLearn.Version,
        Columns = "weapon,wall,material,name,thickness,walls,distance,method,learned,registered",
        Buckets = wallLearn.Buckets,
        Samples = wallLearn.Samples,
    })
    if not ok then return end

    pcall(writefile, wallLearn.Path, encoded)
    wallLearn.Dirty = false
end

wallLearn.KeyFor = function(material)
    local character = lp2.Character
    local tool = character and character:FindFirstChildOfClass("Tool")
    return (tool and tool.Name or "None") .. "|" .. (material or "Unknown")
end

wallLearn.Update = function(key, thickness, registered, allowNew)
    local bucket = wallLearn.Buckets[key]

    if not bucket then
        if not allowNew then return end

        local count = 0
        for _ in pairs(wallLearn.Buckets) do count += 1 end
        if count >= wallLearn.BucketLimit then return end

        bucket = {
            Shots = 0,
            Hits = 0,
            Limit = registered and thickness or thickness * 0.6,
            HitMax = 0,
            MissMin = -1,
        }
        wallLearn.Buckets[key] = bucket
    end

    bucket.Shots += 1

    if registered then
        bucket.Hits += 1
        if thickness > bucket.HitMax then bucket.HitMax = thickness end
        if thickness > bucket.Limit then
            bucket.Limit += (thickness - bucket.Limit) * wallLearn.RiseRate
        end
    else
        if bucket.MissMin < 0 or thickness < bucket.MissMin then
            bucket.MissMin = thickness
        end
        if thickness < bucket.Limit then
            bucket.Limit -= (bucket.Limit - thickness) * wallLearn.FallRate
        end
        if bucket.Shots >= wallLearn.MinSamples
            and (bucket.Hits / bucket.Shots) < wallLearn.RateFloor then
            bucket.Limit *= wallLearn.RateDecay
        end
    end
end

wallLearn.Observe = function(entry, registered)
    if not wallLearn.Enabled or not entry then return end

    if entry.Wall then
        local base = (entry.Weapon or "None") .. "|" .. (entry.Material or "Unknown")
        wallLearn.Update(base, entry.Thickness, registered, true)
        wallLearn.Update(
            base .. "|" .. (entry.Name or "Unknown"), entry.Thickness, registered, true
        )
    end

    wallLearn.Samples[#wallLearn.Samples + 1] = {
        entry.Weapon or "None",
        entry.Wall and 1 or 0,
        entry.Material or "-",
        entry.Name or "-",
        math.floor((entry.Thickness or 0) * 100 + 0.5) / 100,
        entry.Walls or 0,
        math.floor((entry.Distance or 0) * 10 + 0.5) / 10,
        entry.Method or "-",
        entry.Learned and 1 or 0,
        registered and 1 or 0,
    }

    local overflow = #wallLearn.Samples - wallLearn.SampleLimit
    if overflow > 0 then
        for _ = 1, overflow do
            table.remove(wallLearn.Samples, 1)
        end
    end

    wallLearn.Dirty = true
end

wallLearnLimit = function(material, blockerName, fallback)
    if not wallLearn.Adaptive then return fallback, false end

    local base = wallLearn.KeyFor(material)
    local bucket = wallLearn.Buckets[base .. "|" .. (blockerName or "Unknown")]

    if not bucket or bucket.Shots < wallLearn.NameSamples then
        bucket = wallLearn.Buckets[base]
        if not bucket or bucket.Shots < wallLearn.MinSamples then return fallback, false end
    end

    local limit = bucket.Limit
    if math.random(1, 100) <= wallLearn.Explore then
        limit *= 1.4
    end

    return limit, true
end

hitLog.Report = function(player, damage, entry)
    if not hitLog.Enabled then return end

    local segments = {
        { "Hit ", "FontColor" },
        { player.Name, "AccentColor" },
        { " for ", "FontColor" },
        { tostring(math.floor(damage + 0.5)), "RiskColor" },
        { " damage", "FontColor" },
    }

    if hitLog.ShowMethod and entry and entry.Method then
        segments[#segments + 1] = { " using ", "FontColor" }
        segments[#segments + 1] = { entry.Method, "AccentColor" }
    end

    if entry and entry.Wall then
        local label = " [wall"

        if entry.Material and entry.Material ~= "Unknown" then
            label ..= " " .. entry.Material
        end

        if entry.Thickness then
            label ..= string.format(" %.1fst", entry.Thickness)
        end

        segments[#segments + 1] = { label .. "]", hitLog.WallColor }
    end

    if hitLog.ShowCache and entry then
        segments[#segments + 1] = { entry.Cached and " [cache]" or " [fresh]", "OutlineColor" }
    end

    library2:NotifyRich(segments, hitLog.Lifetime)
end

hitLog.Track = function(player, method, cached, throughWall, weapon, distance)
    if not player then return end
    if not hitLog.Enabled and not wallLearn.Enabled then return end

    local info = ragePathFinding.WallInfo

    hitLog.Pending[player] = {
        Time = os.clock(),
        Method = method,
        Cached = cached == true,
        Wall = throughWall == true,
        Weapon = weapon,
        Distance = distance,
        Material = throughWall and info.Material or nil,
        Name = throughWall and info.Name or nil,
        Thickness = throughWall and info.Thickness or nil,
        Walls = throughWall and info.Walls or nil,
        Learned = throughWall and info.Learned or nil,
    }
end

library2:GiveSignal(rs2.Heartbeat:Connect(function()
    if not hitLog.Enabled and not wallLearn.Enabled then return end

    local now = os.clock()

    for _, player in ipairs(plrs:GetPlayers()) do
        if player ~= lp2 then
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")

            if humanoid then
                local record = hitLog.Health[player]

                if not record or record.Character ~= character then
                    hitLog.Health[player] = { Character = character, Last = humanoid.Health }
                else
                    local previous = record.Last
                    local current = humanoid.Health
                    record.Last = current

                    if current < previous then
                        local entry = hitLog.Pending[player]
                        if entry and (now - entry.Time) <= hitLog.Window then
                            hitLog.Pending[player] = nil
                            wallLearn.Observe(entry, true)
                            hitLog.Report(player, previous - current, entry)
                        end
                    end
                end
            end
        end
    end

    for player, entry in pairs(hitLog.Pending) do
        if (now - entry.Time) > hitLog.Window then
            hitLog.Pending[player] = nil
            wallLearn.Observe(entry, false)
        end
    end

    if wallLearn.Dirty and (now - wallLearn.SavedAt) >= wallLearn.SaveInterval then
        wallLearn.SavedAt = now
        wallLearn.Save()
    end
end))

