rageProto.UnknownGap = 0.125
rageProto.Configs = setmetatable({}, { __mode = "k" })

rageProto.Info = function(tool)
    local cached = rageProto.Configs[tool]
    if cached ~= nil then return cached end

    local info = false
    local module = tool:FindFirstChild("Config")

    if module and module:IsA("ModuleScript") then
        local ok, config = pcall(require, module)
        if ok and type(config) == "table" then
            local rate = tonumber(config.FireRate) or 0
            local modes = config.FireModeSettings

            if type(modes) == "table" and modes.CanSwitch then
                if modes.SwitchTo == "Burst" then
                    rate = tonumber(modes.BurstRate) or rate
                end
                local semi = tonumber(modes.SemiRate)
                if semi and semi > rate then rate = semi end
            end

            local shotgun = config.ShotgunSettings
            local shell = type(shotgun) == "table"

            info = {
                Rate = rate,
                MagSize = tonumber(config.MagSize) or 0,
                ReloadTime = tonumber(config.ReloadTime) or 2,
                ShellReload = shell and shotgun.ShotgunReload == true,
                ShellTime = math.max(shell and tonumber(shotgun.ShellInTime) or 0, 0.25),
            }
        end
    end

    rageProto.Configs[tool] = info
    return info
end

rageProto.Rate = function(tool)
    local info = rageProto.Info(tool)
    if info and info.Rate > 0 then return info.Rate end
    return rageWeaponFireRates[tool.Name] or 0
end

rageProto.FireGap = function(tool)
    local rate = rageProto.Rate(tool)
    if rate <= 0 then return rageProto.UnknownGap end

    if ragebotFlags.fire_Rate_Per_Weapon then
        return 1 / rate
    end

    return math.max(1 / rate - 0.04, 0)
end

local rageSurfaceSides = { "Front", "Back", "Left", "Right", "Top", "Bottom" }

local function buildRageSurface(hitPart, hitPosition, shootPosition)
    if ragebotFlags.surface_mode == "None" then return nil end

    if ragebotFlags.surface_mode ~= "Direct" then
        return {
            rageSurfaceSides[math.random(1, 6)],
            UDim2.new(math.random() * 0.9 + 0.05, -3, math.random() * 0.9 + 0.05, -3),
            Vector2.new(10, 20),
        }
    end

    local delta = hitPosition - shootPosition
    if delta.Magnitude <= 1e-6 then delta = Vector3.new(0, 0, -1) end

    local frame = hitPart.CFrame
    local dir = frame:VectorToObjectSpace(delta.Unit)
    local size = hitPart.Size
    local half = size * 0.5
    local point = frame:PointToObjectSpace(hitPosition)

    local ax, ay, az = math.abs(dir.X), math.abs(dir.Y), math.abs(dir.Z)
    local side, u, v

    if az >= ax and az >= ay then
        side = dir.Z > 0 and "Front" or "Back"
        u = (point.X + half.X) / size.X
        v = (half.Y - point.Y) / size.Y
    elseif ax >= ay then
        side = dir.X > 0 and "Left" or "Right"
        u = (point.Z + half.Z) / size.Z
        v = (half.Y - point.Y) / size.Y
    else
        side = dir.Y > 0 and "Bottom" or "Top"
        u = (point.X + half.X) / size.X
        v = (point.Z + half.Z) / size.Z
    end

    return {
        side,
        UDim2.new(math.clamp(u, 0, 1), -3, math.clamp(v, 0, 1), -3),
        Vector2.new(10, 20),
    }
end

local function pingRageShotCheck(tool)
    if not rageSilentAimCheck then return end

    local values = repSt:FindFirstChild("Values")
    local serverTick = values and values:FindFirstChild("ServerTick")
    if not serverTick then return end

    local payload = {}
    for _ = 1, math.random(2, 5) do
        payload[string.format("%x", math.random(256, 4095))] = math.random() * 2 - 1
    end

    pcall(
        rageSilentAimCheck.FireServer, rageSilentAimCheck,
        tool, serverTick.Value * 2 - 91873, payload
    )
end

rageProto.ReloadOpen = function(tool, values, now)
    if (now - ragebotController.ReloadDone) < 0.6 then
        return
    end

    ragebotController.ReloadTool = tool
    ragebotController.ReloadSent = now
    ragebotController.ReloadAck = 0
    ragebotController.ReloadTick = rageProto.ClientTick()
    rageReloadEvent:FireServer(rageProto.SecurityCode(), rageReloadToken, tool, math.random(), nil)
end

rageProto.Reload = function(tool)
    local now = os.clock()
    if (now - ragebotController.LastReload) < 0.1 then return end
    ragebotController.LastReload = now

    local info = rageProto.Info(tool)
    local values = tool:FindFirstChild("Values")

    if ragebotController.ReloadTool ~= tool then
        ragebotController.ReloadTool = nil
        ragebotController.ReloadSent = 0
        ragebotController.ReloadTick = nil
        ragebotController.ReloadAck = 0
    end

    if not ragebotController.ReloadTool then
        rageProto.ReloadOpen(tool, values, now)
        return
    end

    if ragebotController.ReloadAck == 0 then
        local marked = ragebotController.ReloadTick
        if marked ~= nil and rageProto.ClientTick() == marked then
            if (now - ragebotController.ReloadSent) < 1 then return end
        else
        end
        ragebotController.ReloadAck = now
    end

    local serverAmmo = values and values:FindFirstChild("SERVER_Ammo")
    local storedAmmo = values and values:FindFirstChild("SERVER_StoredAmmo")
    local clientAmmo = values and values:FindFirstChild("Ammo")
    local clientStored = values and values:FindFirstChild("StoredAmmo")
    local magSize = (info and tonumber(info.MagSize)) or 0

    if info and info.ShellReload then
        local magNow = serverAmmo and serverAmmo.Value or 0
        if clientAmmo and clientAmmo.Value < magNow then magNow = clientAmmo.Value end

        local reserveNow = storedAmmo and storedAmmo.Value or 0
        if clientStored and clientStored.Value > reserveNow then reserveNow = clientStored.Value end

        if (magSize > 0 and magNow >= magSize) or reserveNow <= 0 then
            ragebotController.ReloadTool = nil
            ragebotController.ReloadSent = 0
            ragebotController.ReloadTick = nil
            ragebotController.ReloadAck = 0
            ragebotController.ReloadDone = now
            return
        end

        if (now - ragebotController.LastShell) < ((info and tonumber(info.ShellTime)) or 0.4) then return end
        ragebotController.LastShell = now
        rageReloadEvent:FireServer(rageProto.SecurityCode(), rageProto.ShellToken, tool, nil, nil)
        return
    end

    if ragebotFlags.reload_Mode == "Spam" then
        if (now - (ragebotController.SpamAt or 0)) < 0.1 then return end
        ragebotController.SpamAt = now
        rageReloadEvent:FireServer(rageProto.SecurityCode(), rageProto.ShellToken, tool, nil, nil)
        return
    end

    if (now - ragebotController.ReloadAck) < rageProto.ReloadSpan(info) then return end

    ragebotController.ReloadTool = nil
    ragebotController.ReloadSent = 0
    ragebotController.ReloadTick = nil
    ragebotController.ReloadAck = 0
    ragebotController.ReloadDone = now
    rageReloadEvent:FireServer(rageProto.SecurityCode(), rageProto.ShellToken, tool, nil, nil)
end

local function fireRageShot()
    local localCharacter = lp2.Character
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    local tool = localCharacter and localCharacter:FindFirstChildOfClass("Tool")
    if not localRoot or not tool then return end

    local values = tool:FindFirstChild("Values")
    local hitmarker = tool:FindFirstChild("Hitmarker")
    local serverAmmo = values and values:FindFirstChild("SERVER_Ammo")
    local storedAmmo = values and values:FindFirstChild("SERVER_StoredAmmo")
    local clientAmmo = values and values:FindFirstChild("Ammo")
    local clientStored = values and values:FindFirstChild("StoredAmmo")
    if not serverAmmo or not storedAmmo then return end

    local magNow = clientAmmo and clientAmmo.Value or serverAmmo.Value
    local reserveNow = clientStored and clientStored.Value or storedAmmo.Value

    if magNow <= 0 then
        if reserveNow > 0 and tool.Parent and not ragebotController.Unloaded then
            rageProto.Reload(tool)
        end
        return
    end

    local fireGap = rageProto.FireGap(tool)
    if fireGap > 0 and (os.clock() - ragebotController.LastFire) < fireGap then return end

    local shellInfo = rageProto.Info(tool)
    if shellInfo and shellInfo.ShellReload
        and shellInfo.MagSize > 0
        and magNow < shellInfo.MagSize
        and reserveNow > 0 then
        rageProto.Reload(tool)
    end

    local targets = getSortedRageTargets()
    if #targets == 0 then return end

    ragePathFinding.Frame()

    local targetCharacter
    local shootPosition, hitPosition, hitPart
    local pathMethod, pathCached, pathWall

    for _, target in ipairs(targets) do
        local character = target.Character
        if character and (
            not ragebotFlags.check_ForceField
            or not character:FindFirstChildOfClass("ForceField")
        ) then
            shootPosition, hitPosition, hitPart, pathMethod, pathCached, pathWall =
                ragePathFinding.Find(localRoot, character)
            if shootPosition then
                targetCharacter = character
                if getPlayerStatus(target.Player) == "Enemy" then
                    ragebotFlags.locked_Target = target.Player
                end
                break
            end
        end
    end
    if not shootPosition then return end

    if not targetCharacter
        or (ragebotFlags.check_ForceField and targetCharacter:FindFirstChildOfClass("ForceField")) then
        return
    end


    local rageTargetPlayer = plrs:GetPlayerFromCharacter(targetCharacter)
    if rageTargetPlayer then
        ragebotController.LastShotTarget = rageTargetPlayer
        ragebotController.LastShotTargetCharacter = targetCharacter
        ragebotController.LastShotTargetTime = os.clock()
        ragebotController.StickyTarget = rageTargetPlayer
        hitChamsTrackPlayer(rageTargetPlayer, "Ragebot")
        hitLog.Track(
            rageTargetPlayer, pathMethod, pathCached, pathWall,
            tool.Name, (hitPosition - shootPosition).Magnitude
        )
    end

    local delta = hitPosition - shootPosition
    if delta.Magnitude <= 0.0001 then return end

    local direction = delta.Unit
    local hitOffset = hitPosition - (hitPart.Position + ragePathFinding.Lead(targetCharacter))
    local shotId = rageProto.ShotId()

    ragebotController.ShotInProgress = true
    environment.drain_rage_shooting = true
    ragebotController.LastFire = os.clock()

    rageStartShootEvent:FireServer(
        rageProto.SecurityCode(), shotId, tool, rageShotToken, shootPosition, { direction }, false, nil
    )
    if bb.On then
        crTracer(shootPosition, hitPosition, bb.Col)
    end

    local fireRate = math.clamp(tonumber(ragebotFlags.fire_Rate) or 50, 0, 100)

    task.wait((1 - fireRate / 100) * 0.2)

    local targetHumanoid = targetCharacter:FindFirstChildOfClass("Humanoid")

    local aborted = ragebotController.Unloaded
        or not ragebotFlags.enabled
        or lp2.Character ~= localCharacter
        or tool.Parent == nil
        or hitPart == nil
        or hitPart.Parent == nil
        or targetCharacter.Parent == nil
        or (targetHumanoid ~= nil and targetHumanoid.Health <= 0)

    if not aborted then
        local hitLimit = ragePathFinding.HitRadius()
        if hitOffset.Magnitude > hitLimit then
            hitOffset = hitOffset.Unit * hitLimit
        end

        local finalHit = hitPart.Position + ragePathFinding.Lead(targetCharacter) + hitOffset
        local finalDelta = finalHit - shootPosition

        if finalDelta.Magnitude > 0.0001 then
            hitPosition = finalHit
            direction = finalDelta.Unit
        end

        rageFinishShootEvent:FireServer(rageHitMarker, tool, shotId, 1, hitPart, hitPosition, direction,
            nil, buildRageSurface(hitPart, hitPosition, shootPosition), nil, nil)

        pingRageShotCheck(tool)
        ragePathFinding.NoteShot(targetCharacter)
        if clientAmmo and clientAmmo.Parent then
            clientAmmo.Value = math.max(clientAmmo.Value - 1, 0)
        end
        if clientStored and clientStored.Parent and storedAmmo.Parent then
            clientStored.Value = storedAmmo.Value
        end
        if ragebotFlags.show_Hitmarker
            and hitmarker
            and hitmarker.Parent
            and hitmarker:IsA("BindableEvent") then
            hitmarker:Fire(hitPart)
        end
    end

    ragebotController.ShotInProgress = false
    environment.drain_rage_shooting = false
end

task.spawn(function()
    while not ragebotController.Unloaded do
        if ragebotFlags.enabled and rageStartShootEvent and rageFinishShootEvent and rageReloadEvent then
            pcall(fireRageShot)

            ragebotController.ShotInProgress = false
            environment.drain_rage_shooting = false
        end
        rs2.RenderStepped:Wait()
    end
end)

ragebotController.FovConnection = rs2.RenderStepped:Connect(function()
    if ragebotFlags.enabled and ragebotFlags.show_Fov and ragebotFlags.fov_Limit
        and (library2.IsMobile or library2.WindowFocused ~= false) then
        if not ragebotController.FovCircle then
            ragebotController.FovCircle = createFovCircle("RagebotFov", false, 10)
        end

        local circle = ragebotController.FovCircle
        local center = getAimScreenPosition()
        if library2.IsMobile then
            updateMobileFovCircle(circle, center, ragebotFlags.fov_Radius, ragebotFlags.fov_Color, true)
        else
            circle.Position = center
            circle.Radius = ragebotFlags.fov_Radius
            circle.Color = ragebotFlags.fov_Color
            circle.Visible = true
        end
    elseif ragebotController.FovCircle then
        removeFovCircle(ragebotController.FovCircle)
        ragebotController.FovCircle = nil
    end

    if ragebotFlags.enabled and ragebotFlags.show_Target_Line then
        local _, targetCharacter, targetRoot = findRageTarget()
        local targetPart = targetCharacter and (targetCharacter:FindFirstChild("Head") or targetRoot)
        local screenPosition, onScreen

        if targetPart then
            screenPosition, onScreen = cam2:WorldToViewportPoint(targetPart.Position)
        end

        if targetPart and onScreen and screenPosition.Z > 0 then
            if not ragebotController.TargetLine then
                local line = Drawing.new("Line")
                line.Thickness = 1
                line.Transparency = 1
                ragebotController.TargetLine = line
            end

            local line = ragebotController.TargetLine
            line.From = getAimScreenPosition()
            line.To = Vector2.new(screenPosition.X, screenPosition.Y)
            line.Color = ragebotFlags.target_Line_Color
            line.Visible = true
        elseif ragebotController.TargetLine then
            ragebotController.TargetLine.Visible = false
        end
    elseif ragebotController.TargetLine then
        ragebotController.TargetLine:Remove()
        ragebotController.TargetLine = nil
    end
end)
library2:GiveSignal(ragebotController.FovConnection)

function ragebotController:Unload()
    if self.Unloaded then return end

    self.Unloaded = true
    self.ShotInProgress = false
    environment.drain_rage_shooting = false
    self.StickyTarget = nil
    ragebotFlags.enabled = false
    resetRageTargetCache()
    hitChamsCleanup()

    cleanupRageHitsound()

    if self.FovConnection then
        self.FovConnection:Disconnect()
        self.FovConnection = nil
    end
    if self.FovCircle then
        removeFovCircle(self.FovCircle)
        self.FovCircle = nil
    end
    if self.TargetLine then
        self.TargetLine:Remove()
        self.TargetLine = nil
    end


    environment.DrainRagebotCleanup = nil
end

environment.DrainRagebotCleanup = function()
    ragebotController:Unload()
end

library2:OnUnload(function()
    ragebotController:Unload()
end)

