;(function()
local gunAdjustSection = miscPage:AddLeftGroupbox("Gun Adjustment")

local nr = {
    Enabled      = false,
    Mode         = "Remove Recoil & Spread",
    ReducePct    = 100,

    weapons      = setmetatable({}, { __mode = "k" }),
    originals    = setmetatable({}, { __mode = "k" }),
    knownToolNames = {},
    connections  = {},
    CFHook       = nil,
    Scanning     = false,
    ScanPending  = false,
    LastScan     = -math.huge,
    ScanCooldown = 3,
    ScanGeneration = 0,
    CacheInitialized = false,
    CacheDirty = false,
    CacheRevision = 0,
}

local function nrMarkCacheDirty()
    nr.CacheDirty = true
    nr.CacheRevision += 1
end

local function nrRegisterWeapon(weapon)
    if nr.weapons[weapon] then return false end
    nr.weapons[weapon] = true
    nr.originals[weapon] = {
        Recoil                 = weapon.Recoil,
        CameraRecoilingEnabled = weapon.CameraRecoilingEnabled,
        AngleX_Min             = weapon.AngleX_Min,
        AngleX_Max             = weapon.AngleX_Max,
        AngleY_Min             = weapon.AngleY_Min,
        AngleY_Max             = weapon.AngleY_Max,
        AngleZ_Min             = weapon.AngleZ_Min,
        AngleZ_Max             = weapon.AngleZ_Max,
        Spread                 = weapon.Spread,
    }
    return true
end

local function nrScan(generation)
    if type(getgc) ~= "function" then return false end
    local success, objects = pcall(getgc, true)
    if not success or type(objects) ~= "table" then return false end

    local processed = 0
    for _, value in pairs(objects) do
        if generation ~= nr.ScanGeneration or not nr.Enabled then return false end
        if type(value) == "table" and rawget(value, "EquipTime") then
            nrRegisterWeapon(value)
        end
        processed += 1
        if processed % 1000 == 0 then task.wait() end
    end
    return true
end

local function nrApply()
    for w in pairs(nr.weapons) do
        pcall(function()
            if nr.Mode == "Remove Recoil & Spread" then
                w.Recoil               = 0
                w.CameraRecoilingEnabled = false
                w.AngleX_Min           = 0
                w.AngleX_Max           = 0
                w.AngleY_Min           = 0
                w.AngleY_Max           = 0
                w.AngleZ_Min           = 0
                w.AngleZ_Max           = 0
                w.Spread               = 0

            elseif nr.Mode == "Reduce Recoil" then
                local orig = nr.originals[w]
                if orig then
                    local mult = (100 - nr.ReducePct) / 100
                    w.Recoil               = (orig.Recoil or 0)     * mult
                    w.AngleX_Min           = (orig.AngleX_Min or 0) * mult
                    w.AngleX_Max           = (orig.AngleX_Max or 0) * mult
                    w.AngleY_Min           = (orig.AngleY_Min or 0) * mult
                    w.AngleY_Max           = (orig.AngleY_Max or 0) * mult
                    w.AngleZ_Min           = (orig.AngleZ_Min or 0) * mult
                    w.AngleZ_Max           = (orig.AngleZ_Max or 0) * mult
                    w.Spread               = (orig.Spread or 0)     * mult
                    w.CameraRecoilingEnabled = mult > 0.01
                end
            end
        end)
    end
end

local function nrRequestScan(delaySeconds, ignoreCooldown)
    if not nr.Enabled or nr.Scanning or nr.ScanPending then return end

    local delay = math.max(delaySeconds or 0, 0)
    if not ignoreCooldown then
        delay = math.max(delay, nr.ScanCooldown - (os.clock() - nr.LastScan))
    end

    nr.ScanPending = true
    local generation = nr.ScanGeneration
    task.delay(delay, function()
        if generation ~= nr.ScanGeneration then return end
        nr.ScanPending = false
        if not nr.Enabled or nr.Scanning then return end

        nr.Scanning = true
        local scanRevision = nr.CacheRevision
        local completed = nrScan(generation)
        nr.Scanning = false
        if generation == nr.ScanGeneration then
            nr.LastScan = os.clock()
            if completed then
                nr.CacheInitialized = true
                nr.CacheDirty = nr.CacheRevision ~= scanRevision
                if nr.Enabled then nrApply() end
                if nr.CacheDirty and nr.Enabled then
                    task.defer(function()
                        nrRequestScan(0, false)
                    end)
                end
            end
        elseif nr.Enabled and nr.CacheDirty then
            task.defer(function()
                nrRequestScan(0, true)
            end)
        end
    end)
end

local function nrRestore()
    for w, orig in pairs(nr.originals) do
        pcall(function()
            w.Recoil               = orig.Recoil
            w.CameraRecoilingEnabled = orig.CameraRecoilingEnabled
            w.AngleX_Min           = orig.AngleX_Min
            w.AngleX_Max           = orig.AngleX_Max
            w.AngleY_Min           = orig.AngleY_Min
            w.AngleY_Max           = orig.AngleY_Max
            w.AngleZ_Min           = orig.AngleZ_Min
            w.AngleZ_Max           = orig.AngleZ_Max
            w.Spread               = orig.Spread
        end)
    end
end

local function nrRecordToolName(tool)
    if not tool:IsA("Tool") then return false end
    local name = tool.Name
    if nr.knownToolNames[name] then return false end
    nr.knownToolNames[name] = true
    return true
end

local function nrRecordCurrentToolNames()
    local foundNew = false
    local backpack = lp2:FindFirstChildOfClass("Backpack")
    if backpack then
        for _, child in ipairs(backpack:GetChildren()) do
            if child:IsA("Tool") and nrRecordToolName(child) then foundNew = true end
        end
    end

    local character = lp2.Character
    if character then
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("Tool") and nrRecordToolName(child) then foundNew = true end
        end
    end
    return foundNew
end

local function nrHandleTool(tool)
    if not tool:IsA("Tool") then return end
    local isNewWeapon = nrRecordToolName(tool)
    if not nr.Enabled then
        if isNewWeapon then nrMarkCacheDirty() end
        return
    end
    if isNewWeapon then nrMarkCacheDirty() end

    task.delay(0.15, function()
        if not nr.Enabled or not tool.Parent then return end
        nrApply()
        if isNewWeapon then nrRequestScan(0.1, false) end
    end)
end

local function nrHookChar(ch)
    local hasTool = false
    local hasNewWeapon = false
    for _, c in ipairs(ch:GetChildren()) do
        if c:IsA("Tool") then
            hasTool = true
            if nrRecordToolName(c) then hasNewWeapon = true end
        end
    end
    if hasNewWeapon then nrMarkCacheDirty() end
    if hasTool and nr.Enabled then
        task.delay(0.15, function()
            if not nr.Enabled then return end
            nrApply()
            if hasNewWeapon then nrRequestScan(0.1, false) end
        end)
    end
    table.insert(nr.connections, ch.ChildAdded:Connect(function(c)
        nrHandleTool(c)
    end))
    local hum = ch:WaitForChild("Humanoid", 3)
    if hum then
        table.insert(nr.connections, hum.Died:Connect(function()
            if nr.Enabled then
                task.wait(2)
                nrApply()
            end
        end))
    end
end

nrRecordCurrentToolNames()
table.insert(nr.connections, lp2.CharacterAdded:Connect(function(ch)
    task.wait(0.5)
    nrHookChar(ch)
end))
if lp2.Character then nrHookChar(lp2.Character) end


local function nrApplyCf()
    if nr.CFHook then return end
    nr.CFHook = hookmetamethod(game, "__newindex", LPH_NO_VIRTUALIZE(function(self, key, value, ...)
        if type(checkcaller) == "function" and checkcaller() then
            return nr.CFHook(self, key, value)
        end
        if nr.Enabled and nr.Mode == "Remove Recoil & Spread"
            and self == cam2 and (key == "CoordinateFrame" or key == "coordinateFrame") then
            return nr.CFHook(self, key, cam2.CFrame)
        end
        return nr.CFHook(self, key, value)
    end))
end

local nrReduceSection = miscPage:AddLeftGroupbox("Reduce Settings")
nrReduceSection.Holder.Visible = false

gunAdjustSection:AddToggle('GunNoRecoil', {
    Text = "No Recoil",
    Default  = false,
    Warn     = true,
    Callback = function(state)
        nr.Enabled = state
        if state then
            if nrRecordCurrentToolNames() then nrMarkCacheDirty() end
            nrApply()
            if not nr.CacheInitialized or nr.CacheDirty then
                nrRequestScan(0, not nr.CacheInitialized)
            end
            if nr.Mode == "Remove Recoil & Spread" then nrApplyCf() end
        else
            nr.ScanGeneration += 1
            nr.ScanPending = false
            nrRestore()
        end
    end,
})

gunAdjustSection:AddDropdown('GunNoRecoilMode', {
    Text = "Mode",
    Values = {"Remove Recoil & Spread", "Reduce Recoil"},
    Default  = "Remove Recoil & Spread",
    Multi    = false,
    Callback = function(v)
        nr.Mode = v
        nrReduceSection.Holder.Visible = (v == "Reduce Recoil")
        if nr.Enabled then nrApply() end
        if nr.Enabled and v == "Remove Recoil & Spread" then nrApplyCf() end
    end,
})

nrReduceSection:AddSlider('GunReducePct', {
    Text = "Reduce %",
    Min      = 0,
    Max      = 100,
    Default  = 100,
    Rounding = 0,
    Suffix   = "%",
    Callback = function(v)
        nr.ReducePct = v
        if nr.Enabled and nr.Mode == "Reduce Recoil" then nrApply() end
    end,
})
end)()

