local sensoryChams = visualsPage:AddRightGroupbox('Player Chams')
local molotovEspSection = viewPage:AddLeftGroupbox('Molotov ESP')

local molotovEsp = {
    Enabled = false,
    Color = Color3.fromRGB(255, 85, 25),
    Transparency = 0.78,
    ZIndex = 5,
    Visuals = setmetatable({}, { __mode = "k" }),
    Connections = {},
    DebrisFolder = nil,
}

local function molotovEspIsTarget(instance)
    return instance
        and instance:IsA("BasePart")
        and instance.Name == "MolotovExplosion"
end

local function molotovEspRemove(part)
    local data = molotovEsp.Visuals[part]
    if not data then return end

    if data.SizeConnection then
        pcall(function() data.SizeConnection:Disconnect() end)
    end
    if data.DestroyConnection then
        pcall(function() data.DestroyConnection:Disconnect() end)
    end
    if data.Adornment then
        pcall(function() data.Adornment:Destroy() end)
    end

    molotovEsp.Visuals[part] = nil
end

local function molotovEspApplyStyle(data)
    local adornment = data and data.Adornment
    if not adornment then return end

    adornment.Color3 = molotovEsp.Color
    adornment.Transparency = molotovEsp.Transparency
    adornment.AlwaysOnTop = true
    adornment.ZIndex = molotovEsp.ZIndex
end

local function molotovEspAdd(part)
    if not molotovEsp.Enabled or not molotovEspIsTarget(part) then
        return
    end

    if molotovEsp.Visuals[part] then
        local data = molotovEsp.Visuals[part]
        if data.Adornment then
            data.Adornment.Size = part.Size
            molotovEspApplyStyle(data)
        end
        return
    end

    local adornment = Instance.new("BoxHandleAdornment")
    adornment.Name = "DrainMolotovRadius"
    adornment.Adornee = part
    adornment.Size = part.Size
    adornment.CFrame = CFrame.identity
    adornment.AlwaysOnTop = true
    adornment.ZIndex = molotovEsp.ZIndex
    adornment.Color3 = molotovEsp.Color
    adornment.Transparency = molotovEsp.Transparency
    adornment.Parent = part

    local data = {
        Adornment = adornment,
    }

    data.SizeConnection = part:GetPropertyChangedSignal("Size"):Connect(function()
        if adornment.Parent and part.Parent then
            adornment.Size = part.Size
        end
    end)

    data.DestroyConnection = part.Destroying:Connect(function()
        molotovEspRemove(part)
    end)

    molotovEsp.Visuals[part] = data
end

local function molotovEspClear()
    local parts = {}
    for part in next, molotovEsp.Visuals do
        parts[#parts + 1] = part
    end
    for _, part in ipairs(parts) do
        molotovEspRemove(part)
    end
end

local function molotovEspScan(folder)
    if not molotovEsp.Enabled or not folder then return end

    for _, object in ipairs(folder:GetDescendants()) do
        if molotovEspIsTarget(object) then
            molotovEspAdd(object)
        end
    end

    for _, object in ipairs(folder:GetChildren()) do
        if molotovEspIsTarget(object) then
            molotovEspAdd(object)
        end
    end
end

local function molotovEspDisconnectFolder()
    if molotovEsp.DescendantAddedConnection then
        molotovEsp.DescendantAddedConnection:Disconnect()
        molotovEsp.DescendantAddedConnection = nil
    end

    if molotovEsp.FolderDestroyConnection then
        molotovEsp.FolderDestroyConnection:Disconnect()
        molotovEsp.FolderDestroyConnection = nil
    end

    molotovEsp.DebrisFolder = nil
end

local function molotovEspBindFolder(folder)
    if molotovEsp.DebrisFolder == folder then
        molotovEspScan(folder)
        return
    end

    molotovEspDisconnectFolder()
    molotovEsp.DebrisFolder = folder

    if not folder then return end

    molotovEsp.DescendantAddedConnection = folder.DescendantAdded:Connect(function(object)
        if molotovEspIsTarget(object) then
            molotovEspAdd(object)
        end
    end)

    molotovEsp.FolderDestroyConnection = folder.Destroying:Connect(function()
        molotovEspDisconnectFolder()
        molotovEspClear()
    end)

    molotovEspScan(folder)
end

local function molotovEspRefresh()
    if not molotovEsp.Enabled then
        molotovEspClear()
        return
    end

    local debrisFolder = workspace:FindFirstChild("Debris")
    if debrisFolder then
        molotovEspBindFolder(debrisFolder)
    end
end

molotovEsp.WorkspaceChildConnection = workspace.ChildAdded:Connect(function(object)
    if object.Name == "Debris" then
        molotovEspBindFolder(object)
    end
end)

local molotovToggle = molotovEspSection:AddToggle('MolotovESPEnabled', {
