    Title = 'Radius color',
    Callback = function(color, transparency)
        molotovEsp.Color = color

        if transparency ~= nil then
            molotovEsp.Transparency = transparency
        end

        for _, data in next, molotovEsp.Visuals do
            molotovEspApplyStyle(data)
        end
    end,
})


