local localSection = viewPage:AddCenterGroupbox("FOV")

local localCfg = {
    CustomFovEnabled   = false,
    CustomFovValue     = 90,
    CustomAimingFov    = false,
    AimingFovValue     = 40,
    DisableOnAim       = false,
    SmoothTransition   = true,
    TransitionTime     = 500,
    ZoomEnabled        = false,
    ZoomMultiplier     = 1,
    _zoomActive        = false,
    _aimDownConn       = nil,
    _currentInternalFov = 70,
    _isForcing         = false,
    _savedGameFov      = 70,
    _transitionFrom    = 70,
    _transitionTarget  = nil,
    _transitionElapsed = 0,
}

local function localFovIsAiming()
    local char = lp2.Character
    local tool = char and char:FindFirstChildOfClass("Tool")
    local vals = tool and tool:FindFirstChild("Values")
    local aimDown = vals and vals:FindFirstChild("AimDown")
    return aimDown ~= nil and aimDown.Value == true
end

local function localFovStop()
    if localCfg._aimDownConn then
        localCfg._aimDownConn:Disconnect()
        localCfg._aimDownConn = nil
    end
    if localCfg._isForcing then
        cam2.FieldOfView = localCfg._savedGameFov
    end
    localCfg._isForcing = false
    localCfg._currentInternalFov = cam2.FieldOfView
    localCfg._transitionTarget = nil
    localCfg._transitionElapsed = 0
end

local function localFovUpdate()
    if not localCfg.CustomFovEnabled and not localCfg._zoomActive then
        localFovStop()
        return
    end

    if not localCfg._aimDownConn then
        localCfg._currentInternalFov = cam2.FieldOfView
        localCfg._aimDownConn = rs2.RenderStepped:Connect(function(dt)
            local targetFov = nil
            local shouldForce = false
            local isAiming = localFovIsAiming()

            if localCfg._zoomActive then
                targetFov = 20 / localCfg.ZoomMultiplier
                shouldForce = true
            elseif localCfg.CustomFovEnabled then
                if isAiming and localCfg.CustomAimingFov then
                    targetFov = localCfg.AimingFovValue
                    shouldForce = true
                elseif not isAiming or not localCfg.DisableOnAim then
                    targetFov = localCfg.CustomFovValue
                    shouldForce = true
                end
            end

            if not shouldForce then
                if isAiming then
                    localCfg._isForcing = false
                    localCfg._currentInternalFov = cam2.FieldOfView
                    localCfg._transitionTarget = nil
                    localCfg._transitionElapsed = 0
                    return
                end

                if localCfg._isForcing then
                    if math.abs(localCfg._currentInternalFov - localCfg._savedGameFov) > 0.5 then
                        targetFov = localCfg._savedGameFov
                    else
                        localCfg._isForcing = false
                        localCfg._currentInternalFov = cam2.FieldOfView
                        return
                    end
                else
                    localCfg._currentInternalFov = cam2.FieldOfView
                    return
                end
            else
                if not localCfg._isForcing then
                    localCfg._savedGameFov = cam2.FieldOfView
                    localCfg._isForcing = true
                end
            end

            if targetFov then
                if localCfg.SmoothTransition and localCfg.TransitionTime > 0 then
                    if localCfg._transitionTarget == nil
                        or math.abs(localCfg._transitionTarget - targetFov) > 0.001 then
                        localCfg._transitionFrom = localCfg._currentInternalFov
                        localCfg._transitionTarget = targetFov
                        localCfg._transitionElapsed = 0
                    end

                    localCfg._transitionElapsed = localCfg._transitionElapsed + dt
                    local duration = localCfg.TransitionTime / 1000
                    local alpha = math.clamp(localCfg._transitionElapsed / duration, 0, 1)
                    local easedAlpha = alpha * alpha * (3 - 2 * alpha)
                    localCfg._currentInternalFov = localCfg._transitionFrom
                        + (targetFov - localCfg._transitionFrom) * easedAlpha
                else
                    localCfg._currentInternalFov = targetFov
                    localCfg._transitionFrom = targetFov
                    localCfg._transitionTarget = targetFov
                    localCfg._transitionElapsed = 0
                end

                cam2.FieldOfView = localCfg._currentInternalFov
            end
        end)
    end
end

local function localFovToggle(state)
    localCfg.CustomFovEnabled = state
    localFovUpdate()
end

local function localZoomApply(active)
    localCfg._zoomActive = active
    localFovUpdate()
end

local customFovToggle = localSection:AddToggle('LocalCustomFov', {
    Text = "Custom Camera FOV",
    Default  = false,
    Callback = function(state)
        localFovToggle(state)
    end,
})

localSection:AddToggle('LocalFovDisableOnAim', {
    Text = "Disable On Aim",
    Default = localCfg.DisableOnAim,
    Callback = function(state)
        localCfg.DisableOnAim = state
    end,
})

localSection:AddToggle('LocalCustomAimingFov', {
    Text = "Custom Aiming FOV",
    Default = false,
    Tooltip = "Overrides Disable On Aim while aiming.",
    Callback = function(state)
        localCfg.CustomAimingFov = state
    end,
})

localSection:AddSlider('LocalAimingFovValue', {
