        localCfg.AimingFovValue = value
    end,
})

localSection:AddToggle('LocalFovSmooth', {
    Text = "Smooth FOV Transition",
    Default = false,
    Callback = function(state)
        localCfg.SmoothTransition = state
    end,
})

localSection:AddSlider('LocalFovTransitionTime', {
    Text = "Transition Time",
    Min      = 0,
    Max      = 3000,
    Default  = 500,
    Rounding = 0,
    Suffix   = "ms",
    Callback = function(value)
        localCfg.TransitionTime = value
    end,
})

localSection:AddSlider('LocalFovValue', {
    Text = "FOV",
    Min      = 50,
    Max      = 120,
    Default  = 90,
    Rounding = 0,
    Suffix   = "°",
    Callback = function(v)
        localCfg.CustomFovValue = v
    end,
})

local zoomToggle = localSection:AddToggle('LocalZoom', {
    Text = "Zoom",
    Default  = false,
    Callback = function(state)
        localZoomApply(state)
    end,
})

zoomToggle:AddKeyPicker('LocalZoomKey', {
    Default = 'None',
    Mode     = "Hold",
    Text = 'Zoom',
    Callback = function(active)
        zoomToggle:SetValue(active)
    end,
})

localSection:AddSlider('LocalZoomMultiplier', {
    Text = "Zoom Multiplier",
    Min      = 1,
    Max      = 20,
    Default  = 1,
    Rounding = 1,
    Suffix   = "x",
    Callback = function(v)
        localCfg.ZoomMultiplier = v
    end,
})

lp2.CharacterAdded:Connect(function()
    task.wait(1)
    if localCfg.CustomFovEnabled or localCfg._zoomActive then
        localFovUpdate()
    end
end)

library2:OnUnload(localFovStop)

