        Enabled = true,
        Size = 4,
        Color = Color3.fromRGB(255, 255, 255),
        Transparency = 1,
        Outline = true,
        OutlineColor = Color3.fromRGB(0, 0, 0),
        OutlineTransparency = 1,
        OutlineThickness = 1,
    },
    Lines = {
        Enabled = true,
        Length = 12,
        Thickness = 2,
        Gap = 6,
        Angle = 0,
        Color = Color3.fromRGB(0, 255, 150),
        Transparency = 1,
        Outline = true,
        OutlineColor = Color3.fromRGB(0, 0, 0),
        OutlineTransparency = 1,
        OutlineThickness = 1,
    },
    Animation = {
        Spin = false,
        SpinSpeed = 1,
        SpinStyle = Enum.EasingStyle.Linear,
        SpinDirection = Enum.EasingDirection.InOut,
        Pulse = false,
        PulseSpeed = 2,
        PulseMin = 3,
        PulseMax = 15,
        PulseStyle = Enum.EasingStyle.Linear,
        PulseDirection = Enum.EasingDirection.InOut,
    },
}

local scopeDrawing = {
    DotOutline = Drawing.new('Square'),
    Dot = Drawing.new('Square'),
    Lines = {},
    Outlines = {},
}

scopeDrawing.DotOutline.Visible = false
scopeDrawing.Dot.Visible = false

for index = 1, 4 do
    local outline = Drawing.new('Line')
    outline.Visible = false
    scopeDrawing.Outlines[index] = outline

    local line = Drawing.new('Line')
    line.Visible = false
    scopeDrawing.Lines[index] = line
end

local scopeState = {
    AimValue = nil,
    Aiming = false,
    AimAlpha = 0,
    SpinProgress = 0,
    PulseTime = 0,
    RenderFailed = false,
    Unloaded = false,
}

local nativeScopeStates = setmetatable({}, { __mode = 'k' })
local scopeBlurStates = setmetatable({}, { __mode = 'k' })

local function hideScopeDrawing()
    scopeDrawing.Dot.Visible = false
    scopeDrawing.DotOutline.Visible = false
    for index = 1, 4 do
        scopeDrawing.Lines[index].Visible = false
        scopeDrawing.Outlines[index].Visible = false
    end
end

local function restoreNativeScope()
    for object, visible in pairs(nativeScopeStates) do
        if object.Parent then object.Visible = visible end
        nativeScopeStates[object] = nil
    end
end

local function restoreScopeBlur()
    for blur, size in pairs(scopeBlurStates) do
        if blur.Parent then blur.Size = size end
        scopeBlurStates[blur] = nil
    end
end

local function applyScopeOverrides()
    if scopeConfig.Enabled then
        local playerGui = lp2:FindFirstChildOfClass('PlayerGui')
        local gunGui = playerGui and playerGui:FindFirstChild('GunGUI')
        local nativeScope = gunGui and gunGui:FindFirstChild('Scope', true)
        if nativeScope and nativeScope:IsA('GuiObject') then
            if nativeScopeStates[nativeScope] == nil then
                nativeScopeStates[nativeScope] = nativeScope.Visible
            end
            nativeScope.Visible = false
        end
    else
        restoreNativeScope()
    end

    if scopeConfig.RemoveBlur then
        local camera = workspace.CurrentCamera
        local blur = camera and camera:FindFirstChild('sniper_Blur')
        if blur and blur:IsA('BlurEffect') then
            if scopeBlurStates[blur] == nil then
                scopeBlurStates[blur] = blur.Size
            end
            blur.Size = 0
        end
    else
        restoreScopeBlur()
    end
end

local function findScopeAimValue()
    local characters = workspace:FindFirstChild('Characters')
    local character = characters and characters:FindFirstChild(lp2.Name) or lp2.Character
    if not character then return nil end

    local equippedTool = character:FindFirstChildOfClass('Tool')
    if equippedTool then
        local values = equippedTool:FindFirstChild('Values')
        local aimDown = values and values:FindFirstChild('AimDown')
        local ok, value = pcall(function() return aimDown and aimDown.Value end)
        if ok and type(value) == 'boolean' then return aimDown end
    end

    for _, object in ipairs(character:GetChildren()) do
        local values = object:FindFirstChild('Values')
        local aimDown = values and values:FindFirstChild('AimDown')
        local ok, value = pcall(function() return aimDown and aimDown.Value end)
        if ok and type(value) == 'boolean' then return aimDown end
    end

    return nil
end

local function updateScopeAimAlpha(deltaTime)
    local aimValue = findScopeAimValue()
    local valueOk, aimState = pcall(function() return aimValue and aimValue.Value end)
    local aiming = valueOk and aimState == true
    scopeState.AimValue = aimValue
    scopeState.Aiming = aiming

    local targetAlpha = aiming and 1 or 0
    if scopeConfig.FadeTime <= 0 then
        scopeState.AimAlpha = targetAlpha
    else
        local alphaStep = deltaTime / (scopeConfig.FadeTime / 1000)
        if scopeState.AimAlpha < targetAlpha then
            scopeState.AimAlpha = math.min(scopeState.AimAlpha + alphaStep, targetAlpha)
        elseif scopeState.AimAlpha > targetAlpha then
            scopeState.AimAlpha = math.max(scopeState.AimAlpha - alphaStep, targetAlpha)
        end
    end

    return scopeState.AimAlpha
end

local function rotateScopeVector(vector, angle)
    local cosine = math.cos(angle)
    local sine = math.sin(angle)
    return Vector2.new(
        vector.X * cosine - vector.Y * sine,
        vector.X * sine + vector.Y * cosine
    )
end

local function renderCustomScope(deltaTime)
    applyScopeOverrides()

    if not scopeConfig.Enabled then
        scopeState.AimAlpha = 0
        hideScopeDrawing()
        return
    end

    local scopeAlpha = updateScopeAimAlpha(deltaTime)
    if scopeAlpha <= 0.001 then
        hideScopeDrawing()
        return
    end

    local camera = workspace.CurrentCamera
    if not camera then
        hideScopeDrawing()
        return
    end

    local center = camera.ViewportSize / 2
    local totalAngle = scopeConfig.Lines.Angle
    if scopeConfig.Animation.Spin then
        scopeState.SpinProgress = scopeState.SpinProgress + deltaTime * scopeConfig.Animation.SpinSpeed
        local cycle = scopeState.SpinProgress % 1
        if cycle < 0 then cycle = cycle + 1 end
        local turns = math.floor(scopeState.SpinProgress)
        local eased = scopeTweenService:GetValue(cycle, scopeConfig.Animation.SpinStyle, scopeConfig.Animation.SpinDirection)
        totalAngle = (scopeConfig.Lines.Angle + (turns + eased) * 360) % 360
    end

    local currentGap = scopeConfig.Lines.Gap
    if scopeConfig.Animation.Pulse then
        scopeState.PulseTime = scopeState.PulseTime + deltaTime * scopeConfig.Animation.PulseSpeed
        local alpha = (math.sin(scopeState.PulseTime) + 1) * 0.5
        local eased = scopeTweenService:GetValue(alpha, scopeConfig.Animation.PulseStyle, scopeConfig.Animation.PulseDirection)
        currentGap = scopeConfig.Animation.PulseMin
            + (scopeConfig.Animation.PulseMax - scopeConfig.Animation.PulseMin) * eased
    end

    if scopeConfig.Dot.Enabled then
        local dotSize = scopeConfig.Dot.Size
        local outlineThickness = scopeConfig.Dot.OutlineThickness
        if scopeConfig.Dot.Outline then
            local outlineSize = dotSize + outlineThickness * 2
            scopeDrawing.DotOutline.Size = Vector2.new(outlineSize, outlineSize)
            scopeDrawing.DotOutline.Position = center - Vector2.new(outlineSize / 2, outlineSize / 2)
            scopeDrawing.DotOutline.Color = scopeConfig.Dot.OutlineColor
            scopeDrawing.DotOutline.Transparency = scopeConfig.Dot.OutlineTransparency * scopeAlpha
            scopeDrawing.DotOutline.Filled = true
            scopeDrawing.DotOutline.Visible = true
        else
            scopeDrawing.DotOutline.Visible = false
        end

        scopeDrawing.Dot.Size = Vector2.new(dotSize, dotSize)
        scopeDrawing.Dot.Position = center - Vector2.new(dotSize / 2, dotSize / 2)
        scopeDrawing.Dot.Color = scopeConfig.Dot.Color
        scopeDrawing.Dot.Transparency = scopeConfig.Dot.Transparency * scopeAlpha
        scopeDrawing.Dot.Filled = true
        scopeDrawing.Dot.Visible = true
    else
        scopeDrawing.Dot.Visible = false
        scopeDrawing.DotOutline.Visible = false
    end

    if scopeConfig.Lines.Enabled then
        local baseAngles = { 0, 90, 180, 270 }
        for index = 1, 4 do
            local direction = rotateScopeVector(Vector2.new(0, -1), math.rad(baseAngles[index] + totalAngle))
            local startPosition = center + direction * currentGap
            local endPosition = center + direction * (currentGap + scopeConfig.Lines.Length)
            local line = scopeDrawing.Lines[index]
            local outline = scopeDrawing.Outlines[index]

            if scopeConfig.Lines.Outline then
                local outlineThickness = scopeConfig.Lines.OutlineThickness
                outline.From = center + direction * (currentGap - outlineThickness)
                outline.To = center + direction * (currentGap + scopeConfig.Lines.Length + outlineThickness)
                outline.Thickness = scopeConfig.Lines.Thickness + outlineThickness * 2
                outline.Color = scopeConfig.Lines.OutlineColor
                outline.Transparency = scopeConfig.Lines.OutlineTransparency * scopeAlpha
                outline.Visible = true
            else
                outline.Visible = false
            end

            line.From = startPosition
            line.To = endPosition
            line.Thickness = scopeConfig.Lines.Thickness
            line.Color = scopeConfig.Lines.Color
            line.Transparency = scopeConfig.Lines.Transparency * scopeAlpha
            line.Visible = true
        end
    else
        for index = 1, 4 do
            scopeDrawing.Lines[index].Visible = false
            scopeDrawing.Outlines[index].Visible = false
        end
    end
end

