library2:GiveSignal(rs2.RenderStepped:Connect(function(deltaTime)
    if scopeState.Unloaded or scopeState.RenderFailed then return end
    if not scopeConfig.Enabled and not scopeConfig.RemoveBlur then return end
    local ok, err = pcall(renderCustomScope, deltaTime)
    if not ok then
        scopeState.RenderFailed = true
        hideScopeDrawing()
        restoreNativeScope()
        restoreScopeBlur()
        library2:Notify(library2:TranslateFormat('Custom scope: %s', tostring(err)), 5)
    end
end))

library2:OnUnload(function()
    scopeState.Unloaded = true
    scopeConfig.Enabled = false
    scopeConfig.RemoveBlur = false
    restoreNativeScope()
    restoreScopeBlur()
    hideScopeDrawing()
    pcall(function() scopeDrawing.Dot:Remove() end)
    pcall(function() scopeDrawing.DotOutline:Remove() end)
    for index = 1, 4 do
        pcall(function() scopeDrawing.Lines[index]:Remove() end)
        pcall(function() scopeDrawing.Outlines[index]:Remove() end)
    end
end)
end)()
