;(function()
local viewModelSection = viewPage:AddCenterGroupbox("Custom ViewModel")

local vmcfg = {
    Enabled = false,
    SelectedState = "Default",
    Speed = 0.3,
    States = {
        Default = { X = 0, Y = 0, Z = 0, Pitch = 0, Yaw = 0, Roll = 0 },
        Aiming  = { X = 0, Y = 0, Z = 0, Pitch = 0, Yaw = 0, Roll = 0 }
    },
    Current = { X = 0, Y = 0, Z = 0, Pitch = 0, Yaw = 0, Roll = 0 }
}

viewModelSection:AddToggle('VM_Enabled', {
    Text = "Enabled",
    Default = false,
    Callback = function(v) vmcfg.Enabled = v end
})

local vmSliders = {}

viewModelSection:AddDropdown('VM_State', {
    Text = "State",
    Values = {"Default", "Aiming"},
    Default = "Default",
    Multi = false,
    Callback = function(v)
        vmcfg.SelectedState = v
        local s = vmcfg.States[v]
        if vmSliders.X then
            vmSliders.X:SetValue(s.X)
            vmSliders.Y:SetValue(s.Y)
            vmSliders.Z:SetValue(s.Z)
            vmSliders.Pitch:SetValue(s.Pitch)
            vmSliders.Yaw:SetValue(s.Yaw)
            vmSliders.Roll:SetValue(s.Roll)
        end
    end
})

vmSliders.X = viewModelSection:AddSlider('VM_X', { Text = "Offset X", Min = -5, Max = 5, Default = 0, Rounding = 1, Callback = function(v) vmcfg.States[vmcfg.SelectedState].X = v end })
vmSliders.Y = viewModelSection:AddSlider('VM_Y', { Text = "Offset Y", Min = -5, Max = 5, Default = 0, Rounding = 1, Callback = function(v) vmcfg.States[vmcfg.SelectedState].Y = v end })
vmSliders.Z = viewModelSection:AddSlider('VM_Z', { Text = "Offset Z", Min = -5, Max = 5, Default = 0, Rounding = 1, Callback = function(v) vmcfg.States[vmcfg.SelectedState].Z = v end })
vmSliders.Pitch = viewModelSection:AddSlider('VM_Pitch', { Text = "Pitch", Min = -180, Max = 180, Default = 0, Rounding = 0, Callback = function(v) vmcfg.States[vmcfg.SelectedState].Pitch = v end })
vmSliders.Yaw = viewModelSection:AddSlider('VM_Yaw', { Text = "Yaw", Min = -180, Max = 180, Default = 0, Rounding = 0, Callback = function(v) vmcfg.States[vmcfg.SelectedState].Yaw = v end })
vmSliders.Roll = viewModelSection:AddSlider('VM_Roll', { Text = "Roll", Min = -180, Max = 180, Default = 0, Rounding = 0, Callback = function(v) vmcfg.States[vmcfg.SelectedState].Roll = v end })

local savedPureCframe = nil
local savedPureViewmodel = nil

rs2:BindToRenderStep("ViewModel_Restore", 100, function()
    if not savedPureCframe then
        return
    end

    local cam = workspace.CurrentCamera
    local vm = cam and cam:FindFirstChild("ViewModel")
    local restoredCustomBase = false

    if savedPureCframe then
        if vm and vm == savedPureViewmodel then
            vm:PivotTo(savedPureCframe)
            restoredCustomBase = true
        end
        savedPureCframe = nil
        savedPureViewmodel = nil
    end

end)

rs2:BindToRenderStep("ViewModel_Custom", 3000, function(dt)
    if vmcfg.Enabled then
        local char = lp2.Character
        local tool = char and char:FindFirstChildOfClass("Tool")
                local isAiming = false
        if tool then
            local vals = tool:FindFirstChild("Values")
            local aimDown = vals and vals:FindFirstChild("AimDown")
            if aimDown and aimDown.Value == true then
                isAiming = true
            end
        end

        local targetState = isAiming and vmcfg.States.Aiming or vmcfg.States.Default

        local factor = 1
        if vmcfg.Speed > 0 then
            factor = 1 - math.pow(0.001, dt / vmcfg.Speed)
        end

        vmcfg.Current.X = vmcfg.Current.X + (targetState.X - vmcfg.Current.X) * factor
        vmcfg.Current.Y = vmcfg.Current.Y + (targetState.Y - vmcfg.Current.Y) * factor
        vmcfg.Current.Z = vmcfg.Current.Z + (targetState.Z - vmcfg.Current.Z) * factor
        vmcfg.Current.Pitch = vmcfg.Current.Pitch + (targetState.Pitch - vmcfg.Current.Pitch) * factor
        vmcfg.Current.Yaw = vmcfg.Current.Yaw + (targetState.Yaw - vmcfg.Current.Yaw) * factor
        vmcfg.Current.Roll = vmcfg.Current.Roll + (targetState.Roll - vmcfg.Current.Roll) * factor

        local camera = workspace.CurrentCamera
        local vm = camera and camera:FindFirstChild("ViewModel")
        if vm then
            savedPureCframe = vm:GetPivot()
            savedPureViewmodel = vm
            local camCf = workspace.CurrentCamera.CFrame
            local offset = CFrame.new(vmcfg.Current.X, vmcfg.Current.Y, vmcfg.Current.Z) * CFrame.Angles(math.rad(vmcfg.Current.Pitch), math.rad(vmcfg.Current.Yaw), math.rad(vmcfg.Current.Roll))
            local newPivot = camCf * offset * camCf:ToObjectSpace(savedPureCframe)
            vm:PivotTo(newPivot)
        end
    else
        savedPureCframe = nil
        savedPureViewmodel = nil
    end
end)


library2:OnUnload(function()
    vmcfg.Enabled = false
    savedPureCframe = nil
    savedPureViewmodel = nil
    pcall(function() rs2:UnbindFromRenderStep("ViewModel_Custom") end)
    pcall(function() rs2:UnbindFromRenderStep("ViewModel_Restore") end)
end)

end)()


