;(function()
local lighting = game:GetService("Lighting")
local worldEnvironment = getgenv()

if type(worldEnvironment.DrainLightingCleanup) == "function" then
    pcall(worldEnvironment.DrainLightingCleanup)
    worldEnvironment.DrainLightingCleanup = nil
end


if type(getconnections) == "function" and debug and type(debug.info) == "function" then
    local legacyNames = {
        fb_ambient_cb = true,
        ca_ambient_cb = true,
        ca_outdoor_ambient_cb = true,
    }
    for _, property in ipairs({ "Ambient", "OutdoorAmbient" }) do
        local ok, connections = pcall(getconnections, lighting:GetPropertyChangedSignal(property))
        if ok and type(connections) == "table" then
            for _, connection in ipairs(connections) do
                local callbackName
                pcall(function()
                    if connection.Function then callbackName = debug.info(connection.Function, "n") end
                end)
                if callbackName and legacyNames[callbackName] then
                    pcall(function()
                        if connection.Disconnect then connection:Disconnect()
                        elseif connection.Disable then connection:Disable() end
                    end)
                end
            end
        end
    end
end

local worldOrig  = {}
local worldConns = {}

local function worldSaveOrig()
    if worldOrig.saved then return end
    worldOrig.saved              = true
    worldOrig.ClockTime          = lighting.ClockTime
    worldOrig.Brightness         = lighting.Brightness
    worldOrig.GlobalShadows      = lighting.GlobalShadows
    worldOrig.Ambient            = lighting.Ambient
    worldOrig.OutdoorAmbient     = lighting.OutdoorAmbient
    worldOrig.ColorShift_Top     = lighting.ColorShift_Top
    worldOrig.ColorShift_Bottom  = lighting.ColorShift_Bottom
    worldOrig.ExposureCompensation = lighting.ExposureCompensation
    pcall(function() worldOrig.Technology = lighting.Technology end)
end

worldSaveOrig()

local function worldConn(key, fn)
    if worldConns[key] then worldConns[key]:Disconnect(); worldConns[key] = nil end
    local prop = key:match("^([^_]+)")
    local ok, sig = pcall(lighting.GetPropertyChangedSignal, lighting, prop)
    if ok and sig then
        worldConns[key] = sig:Connect(fn)
    end
end
local function worldDisconn(key)
    if worldConns[key] then worldConns[key]:Disconnect(); worldConns[key] = nil end
end

local shadowsEnabled = false
local fb = { Enabled = false, Active = false, PostEffects = {} }
local ca = { Enabled = false, Top = Color3.fromRGB(128, 128, 128), Bot = Color3.fromRGB(80, 80, 80) }
local worldApplying = {}

local function worldSet(property, value)
    if value == nil or worldApplying[property] or lighting[property] == value then return end
    worldApplying[property] = true
    pcall(function() lighting[property] = value end)
    worldApplying[property] = nil
end

local function worldApplyAmbient()
    local value
    if ca.Enabled then
        value = ca.Top
    elseif fb.Enabled then
        value = Color3.fromRGB(178, 178, 178)
    else
        value = worldOrig.Ambient
    end
    worldSet("Ambient", value)
end

local function worldApplyOutdoorAmbient()
    worldSet("OutdoorAmbient", ca.Enabled and ca.Bot or worldOrig.OutdoorAmbient)
end

local function fbClocktimeCb()     if fb.Enabled then worldSet("ClockTime", 14) end end
local function fbBrightnessCb()    if fb.Enabled then worldSet("Brightness", 5) end end
local function fbGlobalshadowsCb() if fb.Enabled then worldSet("GlobalShadows", false) end end
local function fbAmbientCb()       if fb.Enabled then worldApplyAmbient() end end

local function fbEnable()
    if fb.Active then return end
    worldSaveOrig()
    fb.Active = true
    fb.PostEffects = {}
    worldSet("ClockTime", 14)
    worldSet("Brightness", 5)
    worldSet("GlobalShadows", false)
    worldApplyAmbient()
    for _, e in ipairs(lighting:GetChildren()) do
        if e:IsA("PostEffect") then
            fb.PostEffects[e] = e.Enabled
            pcall(function() e.Enabled = false end)
        end
    end
    worldConn("ClockTime_fb",     fbClocktimeCb)
    worldConn("Brightness_fb",    fbBrightnessCb)
    worldConn("GlobalShadows_fb", fbGlobalshadowsCb)
    worldConn("Ambient_fb",       fbAmbientCb)
end

local function fbDisable()
    worldDisconn("ClockTime_fb"); worldDisconn("Brightness_fb")
    worldDisconn("GlobalShadows_fb"); worldDisconn("Ambient_fb")
    if not fb.Active then return end
    fb.Active = false
    worldSet("ClockTime", worldOrig.ClockTime)
    worldSet("Brightness", worldOrig.Brightness)
    worldSet("GlobalShadows", if shadowsEnabled then false else worldOrig.GlobalShadows)
    worldApplyAmbient()
    for effect, wasEnabled2 in pairs(fb.PostEffects) do
        if effect and effect.Parent then
            pcall(function() effect.Enabled = wasEnabled2 end)
        end
    end
    fb.PostEffects = {}
end

