local currentSky = nil
local skyboxEnabled = false
local skyboxCurrent = "Peaceful"
local skyboxSpinEnabled = false
local skyboxSpinSpeed = 15
local skyboxSpinAngle = 0

local staleSky = lighting:FindFirstChild("DrainCustomSkybox")
if staleSky and staleSky:IsA("Sky") then staleSky:Destroy() end

local function applySkybox(name)
    local data = skyBoxes[name]
    if not data then return end
    if not currentSky or not currentSky.Parent then
        currentSky = Instance.new("Sky")
        currentSky.Name = "DrainCustomSkybox"
        currentSky.Parent = lighting
    end
    for prop, id in pairs(data) do
        pcall(function() currentSky[prop] = id end)
    end
    pcall(function()
        currentSky.SkyboxOrientation = Vector3.new(0, skyboxSpinAngle, 0)
    end)
end

local function removeSkybox()
    if currentSky then currentSky:Destroy(); currentSky = nil end
end

local skyboxToggle = worldSection2:AddToggle('WorldSkyboxEnabled', {
    Text = "Custom Skybox", Default = false,
    Callback = function(state)
        skyboxEnabled = state
        if state then
            applySkybox(skyboxCurrent)
        else
            removeSkybox()
        end
    end,
})
worldSection2:AddDropdown('WorldSkyboxSelect', {
    Text = "Skybox",
    Values = {"Default","Nebula","Blue Nebula","Setting Hills","Blue Aurora","Red Aurora","Pink Vision","Twilight","Distopia","Peaceful"},
    Default = "Peaceful", Multi = false,
    Callback = function(v)
        skyboxCurrent = v
        if skyboxEnabled then applySkybox(v) end
    end,
})

worldSection2:AddToggle('WorldSkyboxSpin', {
    Text = "Skybox Spin", Default = false,
    Tooltip = "Continuously rotates the custom skybox around the vertical axis.",
    Callback = function(state)
        skyboxSpinEnabled = state

        if state and not skyboxToggle.Value then
            skyboxToggle:SetValue(true)
        end

        if state and not worldConns.SkyboxSpin then
            worldConns.SkyboxSpin = rs2.RenderStepped:Connect(function(delta)
                if not skyboxSpinEnabled or not currentSky or not currentSky.Parent then return end
                skyboxSpinAngle = (skyboxSpinAngle + delta * skyboxSpinSpeed) % 360
                pcall(function()
                    currentSky.SkyboxOrientation = Vector3.new(0, skyboxSpinAngle, 0)
                end)
            end)
        elseif not state then
            worldDisconn("SkyboxSpin")
            skyboxSpinAngle = 0
            if currentSky and currentSky.Parent then
                pcall(function() currentSky.SkyboxOrientation = Vector3.zero end)
            end
        end
    end,
})

worldSection2:AddSlider('WorldSkyboxSpinSpeed', {
    Text = "Spin Speed",
    Min = 1, Max = 180, Default = 15, Rounding = 0, Suffix = "°/s",
    Tooltip = "Sets how fast the custom skybox rotates.",
    Callback = function(value)
        skyboxSpinSpeed = value
    end,
})

