local function fogGetOrCreate()
    if _fogAtmo and _fogAtmo.Parent then return _fogAtmo end
    _fogAtmo = Instance.new("Atmosphere")
    _fogAtmo.Name   = "CustomFog"
    _fogAtmo.Parent = lighting
    return _fogAtmo
end

local function fogApply()
    local atmo = fogGetOrCreate()
    atmo.Density = fogDensity
    atmo.Offset  = fogOffset
    atmo.Color   = fogColor
    atmo.Decay   = fogDecay
    atmo.Glare   = fogGlare
    atmo.Haze    = fogHaze
end

local function fogRemove()
    if _fogAtmo and _fogAtmo.Parent then
        _fogAtmo:Destroy()
        _fogAtmo = nil
    end
end

