worldEnvironment.DrainLightingCleanup = function()
    skyboxSpinEnabled = false
    removeSkybox()
    shadowsEnabled = false
    shadowsOriginal = nil
    fb.Enabled = false
    fbDisable()
    worldSet("GlobalShadows", worldOrig.GlobalShadows)

    fogEnabled = false
    fogRemove()
    if _fogOrigAtmo then
        pcall(function()
            if not _fogOrigAtmo.Parent then _fogOrigAtmo.Parent = lighting end
        end)
    end

    if worldOrig.Technology then
        pcall(function() lighting.Technology = worldOrig.Technology end)
    end
    if _bloomObj then
        _bloomObj:Destroy()
        _bloomObj = nil
    end
    for key, connection in pairs(worldConns) do
        pcall(function() connection:Disconnect() end)
        worldConns[key] = nil
    end
end

end)()

;(function()
local gunChamsSection  = viewPage:AddLeftGroupbox("Gun Chams")

local gc = {
    Enabled      = false,
    Color        = Color3.fromRGB(100, 149, 237),
    TargetColor  = Color3.fromRGB(100, 149, 237),
    Alpha        = 0,
    TargetAlpha  = 0,
    Material     = "Neon",
    ForceFieldAnimation = "Off",
    NoTexture    = true,
    Mode         = "Material",
    HighlightOutlineColor = Color3.fromRGB(255, 255, 255),
    HighlightOutlineEnabled = false,
    HighlightOutlineAlpha = 0,
    HighlightInstance = nil,

    originals    = {},
    parts        = {},
    roots        = {},
    rootOrder    = {},
    sourceConnections = {},
    refreshQueued = false,
    tweenConn    = nil,
    assertConn   = nil,
    lastAssert   = 0,
    AssertInterval = 1 / 15,

    SkipTransparencyThreshold = 0.99,


    ColorLerpSpeed = 0.12,
}

local materials = {
    "Neon", "ForceField", "Glass", "SmoothPlastic", "Plastic",
    "Metal", "DiamondPlate", "Foil", "Ice", "Custom", "Reflective",
}

local function gcIsVisual(instance)
    return instance and (instance:IsA("BasePart") or instance:IsA("SpecialMesh"))
end

local function gcSave(part)
    if gc.originals[part] then return end

    local success, original = pcall(function()
        local origTransparency = nil
        local skipTransparency = false
        if part:IsA("BasePart") then
            origTransparency = part.Transparency
            skipTransparency = origTransparency >= gc.SkipTransparencyThreshold
        end

        return {
            Color         = part:IsA("BasePart") and part.Color       or nil,
            BrickColor    = part:IsA("BasePart") and part.BrickColor  or nil,
            Material      = part:IsA("BasePart") and part.Material    or nil,
            TextureID     = (part:IsA("MeshPart") and part.TextureID) or
                            (part:IsA("SpecialMesh") and part.TextureId) or nil,
            Transparency  = origTransparency,
            SkipTransparency = skipTransparency,
        }
    end)
    if success then gc.originals[part] = original end
end

local function gcApplyPart(part, forceInvisible)
    gcSave(part)
    local orig = gc.originals[part]

    pcall(function()
        if part:IsA("BasePart") then
            local material = resolveVisualMaterial(gc.Material, Enum.Material.Neon)
            if part.Color ~= gc.Color then part.Color = gc.Color end
            if part.Material ~= material then part.Material = material end

            if not (orig and orig.SkipTransparency) then
                local transparency = forceInvisible and 1 or gc.Alpha
                if part.Transparency ~= transparency then part.Transparency = transparency end
            end
        end

        local texture = gc.Material == "ForceField"
            and forcefieldAnimationTexture(gc.ForceFieldAnimation)
            or nil
        if part:IsA("MeshPart") then
            if texture and part.TextureID ~= texture then
                part.TextureID = texture
            elseif not texture and gc.NoTexture and part.TextureID ~= "" then
                part.TextureID = ""
            end
        elseif part:IsA("SpecialMesh") then
            if texture and part.TextureId ~= texture then
                part.TextureId = texture
            elseif not texture and gc.NoTexture and part.TextureId ~= "" then
                part.TextureId = ""
            end
        end
    end)
end

local function gcStartColorTween()

end

local function gcStopColorTween()
    if gc.tweenConn then gc.tweenConn:Disconnect(); gc.tweenConn = nil end
end

local function gcRestorePart(part)
    local orig = gc.originals[part]
    if not orig then return end
    pcall(function()
        if part:IsA("BasePart") or part:IsA("MeshPart") then
            if orig.Color    then part.Color    = orig.Color    end
            if orig.Material then part.Material = orig.Material end
            if orig.Transparency ~= nil and not orig.SkipTransparency then
                part.Transparency = orig.Transparency
            end
        end
        if orig.TextureID then
            if part:IsA("MeshPart")    then part.TextureID = orig.TextureID end
            if part:IsA("SpecialMesh") then part.TextureId = orig.TextureID end
        end
    end)
    gc.originals[part] = nil
end

local function gcRecalculateForce(partEntry)
    local forceInvisible = false
    for _, ownerForce in pairs(partEntry.owners) do
        if ownerForce then
            forceInvisible = true
            break
        end
    end
    partEntry.forceInvisible = forceInvisible
end

local function gcRegisterPart(rootData, part)
    if not gcIsVisual(part) or rootData.parts[part] then return end

    rootData.parts[part] = true
    local partEntry = gc.parts[part]
    if not partEntry then
        partEntry = { owners = {}, forceInvisible = false }
        gc.parts[part] = partEntry
    end
    partEntry.owners[rootData.root] = rootData.forceInvisible
    gcRecalculateForce(partEntry)

    if gc.Enabled and gc.Mode == "Material" then
        gcApplyPart(part, partEntry.forceInvisible)
    end
end

local function gcUnregisterPart(rootData, part)
    if not rootData.parts[part] then return end
    rootData.parts[part] = nil

    local partEntry = gc.parts[part]
    if not partEntry then return end
    partEntry.owners[rootData.root] = nil
    if next(partEntry.owners) == nil then
        gcRestorePart(part)
        gc.parts[part] = nil
    else
        gcRecalculateForce(partEntry)
        if gc.Enabled and gc.Mode == "Material" then
            gcApplyPart(part, partEntry.forceInvisible)
        end
    end
end

local gcScheduleRefresh

local function gcDisconnectList(list)
    for index = #list, 1, -1 do
        local connection = table.remove(list, index)
        pcall(function() connection:Disconnect() end)
    end
end

local function gcRegisterRoot(root, forceInvisible)
    local rootData = {
        root = root,
        forceInvisible = forceInvisible == true,
        parts = {},
        connections = {},
    }
    gc.roots[root] = rootData

    gcRegisterPart(rootData, root)
    for _, descendant in ipairs(root:GetDescendants()) do
        gcRegisterPart(rootData, descendant)
    end

    table.insert(rootData.connections, root.DescendantAdded:Connect(function(descendant)
        local current = gc.roots[root]
        if current then gcRegisterPart(current, descendant) end
    end))
    table.insert(rootData.connections, root.DescendantRemoving:Connect(function(descendant)
        local current = gc.roots[root]
        if current then gcUnregisterPart(current, descendant) end
        if gcScheduleRefresh then gcScheduleRefresh() end
    end))
    table.insert(rootData.connections, root.AncestryChanged:Connect(function()
        if gcScheduleRefresh then gcScheduleRefresh() end
    end))
    table.insert(rootData.connections, root:GetPropertyChangedSignal("Name"):Connect(function()
        if gcScheduleRefresh then gcScheduleRefresh() end
    end))

    return rootData
end

local function gcUnregisterRoot(root)
    local rootData = gc.roots[root]
    if not rootData then return end

    gcDisconnectList(rootData.connections)
    local parts = {}
    for part in pairs(rootData.parts) do
        table.insert(parts, part)
    end
    for _, part in ipairs(parts) do
        gcUnregisterPart(rootData, part)
    end
    gc.roots[root] = nil
end

local function gcCollectRoots()
    local desired = {}
    local order = {}

    local function addRoot(root, forceInvisible)
        if root and desired[root] == nil then
            desired[root] = forceInvisible == true
            table.insert(order, root)
        end
    end

    local camera = workspace.CurrentCamera
    local viewModel = camera and camera:FindFirstChild("ViewModel")
    local viewModelTool = viewModel and (viewModel:FindFirstChild("Tool") or viewModel:FindFirstChild("Tool", true))
    addRoot(viewModelTool, false)

    local char = lp2.Character
    if not char then return desired, order end


    local equippedNames = {}
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Tool") then
            addRoot(child, false)
            equippedNames[child.Name] = true
        end
    end


    local di = char:FindFirstChild("DisplayItems")
    if di then
        for _, weaponFolder in ipairs(di:GetChildren()) do
            local partsFolder = weaponFolder:FindFirstChild("Parts")
            if partsFolder then
                for _, partGroup in ipairs(partsFolder:GetChildren()) do
                    local model = partGroup:FindFirstChild("Model")
                    if model then
                        local handle = model:FindFirstChild("Handle", true)
                            or model:FindFirstChildWhichIsA("BasePart", true)
                            or model:FindFirstChildWhichIsA("SpecialMesh", true)
                        if handle then
                            local root = model
                            local isEquipped = equippedNames[weaponFolder.Name] == true
                            addRoot(root, isEquipped)
                        end
                    end
                end
            end
        end
    end

    return desired, order
end

local function gcRestoreAll()
    for part in pairs(gc.originals) do
        gcRestorePart(part)
    end
    gc.originals = {}
end

local function gcRefreshRoots()
    local desired, order = gcCollectRoots()

    local removed = {}
    for root in pairs(gc.roots) do
        if desired[root] == nil then table.insert(removed, root) end
    end
    for _, root in ipairs(removed) do
        gcUnregisterRoot(root)
    end

    for _, root in ipairs(order) do
        local forceInvisible = desired[root]
        local rootData = gc.roots[root]
        if not rootData then
            gcRegisterRoot(root, forceInvisible)
        elseif rootData.forceInvisible ~= forceInvisible then
            rootData.forceInvisible = forceInvisible
            for part in pairs(rootData.parts) do
                local partEntry = gc.parts[part]
                if partEntry then
                    partEntry.owners[root] = forceInvisible
                    gcRecalculateForce(partEntry)
                    if gc.Enabled and gc.Mode == "Material" then
                        gcApplyPart(part, partEntry.forceInvisible)
                    end
                end
            end
        end
    end
    gc.rootOrder = order
end

local function gcDestroyHighlight()
    if gc.HighlightInstance then
        pcall(function() gc.HighlightInstance:Destroy() end)
        gc.HighlightInstance = nil
    end
end

local function gcApplyStyle()
    if gc.Mode == "Material" and gc.Enabled then
        gcDestroyHighlight()
        for part, partEntry in pairs(gc.parts) do
            if part.Parent then gcApplyPart(part, partEntry.forceInvisible) end
        end
    else
        gcRestoreAll()
    end

    if gc.Mode == "Highlight" and gc.Enabled then
        if gc.HighlightInstance and not gc.HighlightInstance.Parent then
            gcDestroyHighlight()
        end
        if not gc.HighlightInstance then
            gc.HighlightInstance = Instance.new("Highlight")
            gc.HighlightInstance.Name = "GunHighlight"
        end
        local h = gc.HighlightInstance
        local outlineTransparency = gc.HighlightOutlineEnabled and gc.HighlightOutlineAlpha or 1
        if h.FillColor ~= gc.Color then h.FillColor = gc.Color end
        if h.FillTransparency ~= gc.Alpha then h.FillTransparency = gc.Alpha end
        if h.OutlineColor ~= gc.HighlightOutlineColor then h.OutlineColor = gc.HighlightOutlineColor end
        if h.OutlineTransparency ~= outlineTransparency then h.OutlineTransparency = outlineTransparency end
        if h.DepthMode ~= Enum.HighlightDepthMode.AlwaysOnTop then
            h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        end

        local target = gc.rootOrder[1]
        if target then
            pcall(function()
                if h.Adornee ~= target then h.Adornee = target end
                if h.Parent ~= target then h.Parent = target end
            end)
        else
            gcDestroyHighlight()
        end
    else
        gcDestroyHighlight()
    end
end

local function gcApplyAll()
    if not gc.Enabled then return end
    gcRefreshRoots()
    gcApplyStyle()
end

gcScheduleRefresh = function()
    if not gc.Enabled or gc.refreshQueued then return end
    gc.refreshQueued = true
    task.defer(function()
        gc.refreshQueued = false
        if gc.Enabled then gcApplyAll() end
    end)
end

local function gcBindSources()
    gcDisconnectList(gc.sourceConnections)

    local function rebind()
        task.defer(function()
            if not gc.Enabled then return end
            gcBindSources()
            gcScheduleRefresh()
        end)
    end
    table.insert(gc.sourceConnections, workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(rebind))
    table.insert(gc.sourceConnections, lp2.CharacterAdded:Connect(rebind))

    local camera = workspace.CurrentCamera
    if camera then
        local function cameraChildChanged(child)
            if child.Name == "ViewModel" then rebind() end
        end
        table.insert(gc.sourceConnections, camera.ChildAdded:Connect(cameraChildChanged))
        table.insert(gc.sourceConnections, camera.ChildRemoved:Connect(cameraChildChanged))

        local viewModel = camera:FindFirstChild("ViewModel")
        if viewModel then
            table.insert(gc.sourceConnections, viewModel.DescendantAdded:Connect(gcScheduleRefresh))
            table.insert(gc.sourceConnections, viewModel.DescendantRemoving:Connect(gcScheduleRefresh))
        end
    end

    local char = lp2.Character
    if char then
        local function characterChildChanged(child)
            if child:IsA("Tool") then
                gcScheduleRefresh()
            elseif child.Name == "DisplayItems" then
                rebind()
            end
        end
        table.insert(gc.sourceConnections, char.ChildAdded:Connect(characterChildChanged))
        table.insert(gc.sourceConnections, char.ChildRemoved:Connect(characterChildChanged))

        local displayItems = char:FindFirstChild("DisplayItems")
        if displayItems then
            table.insert(gc.sourceConnections, displayItems.DescendantAdded:Connect(gcScheduleRefresh))
            table.insert(gc.sourceConnections, displayItems.DescendantRemoving:Connect(gcScheduleRefresh))
        end
    end
end

local function gcStart()
    gcBindSources()
    gcApplyAll()
    gcStartColorTween()

    if not gc.assertConn then
        gc.assertConn = rs2.RenderStepped:Connect(function()
            if not gc.Enabled then return end

            local now = os.clock()
            if (now - gc.lastAssert) < gc.AssertInterval then return end
            gc.lastAssert = now

            gcApplyStyle()
        end)
    end
end

local function gcStop()
    gc.Enabled = false
    gc.refreshQueued = false
    gcDisconnectList(gc.sourceConnections)
    gcStopColorTween()

    if gc.assertConn then
        gc.assertConn:Disconnect()
        gc.assertConn = nil
    end

    local roots = {}
    for root in pairs(gc.roots) do table.insert(roots, root) end
    for _, root in ipairs(roots) do
        gcUnregisterRoot(root)
    end
    gc.rootOrder = {}
    gc.parts = {}
    gcDestroyHighlight()
    gcRestoreAll()
end
library2:OnUnload(gcStop)
local gunChamsHighlightSection = nil

gunChamsSection:AddToggle('GunChamsEnabled', {
