;(function()
local armsSection = viewPage:AddLeftGroupbox("Arms")

local armsMaterials = {
    "Neon", "ForceField", "Glass", "SmoothPlastic", "Plastic",
    "Metal", "DiamondPlate", "Foil", "Ice", "Custom", "Reflective",
}

local ac = {
    Left  = {
        Enabled     = false,
        Color       = Color3.fromRGB(255, 200, 150),
        TargetColor = Color3.fromRGB(255, 200, 150),
        Alpha       = 0,
        TargetAlpha = 0,
        Material    = "SmoothPlastic",
        ForceFieldAnimation = "Off",
        partName    = "Left Arm",
        vmPart      = nil,
        charPart    = nil,
        originals   = setmetatable({}, { __mode = "k" }),
    },
    Right = {
        Enabled     = false,
        Color       = Color3.fromRGB(255, 200, 150),
        TargetColor = Color3.fromRGB(255, 200, 150),
        Alpha       = 0,
        TargetAlpha = 0,
        Material    = "SmoothPlastic",
        ForceFieldAnimation = "Off",
        partName    = "Right Arm",
        vmPart      = nil,
        charPart    = nil,
        originals   = setmetatable({}, { __mode = "k" }),
    },
}

local acConn     = nil
local acLerpConn = nil
local acSourceConnections = {}
local acRefreshQueued = false
local acLastThirdPerson = nil
local acLastAssert = 0
local acAssertInterval = 1 / 15

local acViewmodelClothingOriginals = setmetatable({}, { __mode = "k" })

local function acRestoreClothingObject(object, data)
    if not object or not data then return end
    pcall(function()
        if data.Kind == "Shirt" then
            object.ShirtTemplate = data.Value
        elseif data.Kind == "Pants" then
            object.PantsTemplate = data.Value
        elseif data.Kind == "ShirtGraphic" then
            object.Graphic = data.Value
        elseif data.Kind == "CharacterMesh" then
            if data.BaseTextureId ~= nil then object.BaseTextureId = data.BaseTextureId end
            if data.OverlayTextureId ~= nil then object.OverlayTextureId = data.OverlayTextureId end
        end
    end)
end

local function acRestoreViewmodelClothing()
    for object, data in pairs(acViewmodelClothingOriginals) do
        acRestoreClothingObject(object, data)
        acViewmodelClothingOriginals[object] = nil
    end
end

local function acUpdateViewmodelClothing()
    local needsForceFieldTexture = false
    for _, cfg in pairs(ac) do
        if cfg.Enabled and cfg.Material == "ForceField" then
            needsForceFieldTexture = true
            break
        end
    end

    local camera = workspace.CurrentCamera
    local viewModel = camera and camera:FindFirstChild("ViewModel")
    if not needsForceFieldTexture or not viewModel then
        acRestoreViewmodelClothing()
        return
    end

    for object, data in pairs(acViewmodelClothingOriginals) do
        if not object.Parent or not object:IsDescendantOf(viewModel) then
            acRestoreClothingObject(object, data)
            acViewmodelClothingOriginals[object] = nil
        end
    end

    for _, object in ipairs(viewModel:GetDescendants()) do
        if object:IsA("Shirt") then
            if not acViewmodelClothingOriginals[object] then
                acViewmodelClothingOriginals[object] = { Kind = "Shirt", Value = object.ShirtTemplate }
            end
            object.ShirtTemplate = ""
        elseif object:IsA("Pants") then
            if not acViewmodelClothingOriginals[object] then
                acViewmodelClothingOriginals[object] = { Kind = "Pants", Value = object.PantsTemplate }
            end
            object.PantsTemplate = ""
        elseif object:IsA("ShirtGraphic") then
            if not acViewmodelClothingOriginals[object] then
                acViewmodelClothingOriginals[object] = { Kind = "ShirtGraphic", Value = object.Graphic }
            end
            object.Graphic = ""
        elseif object:IsA("CharacterMesh") then
            if not acViewmodelClothingOriginals[object] then
                local data = { Kind = "CharacterMesh" }
                pcall(function() data.BaseTextureId = object.BaseTextureId end)
                pcall(function() data.OverlayTextureId = object.OverlayTextureId end)
                acViewmodelClothingOriginals[object] = data
            end
            pcall(function() object.BaseTextureId = 0 end)
            pcall(function() object.OverlayTextureId = 0 end)
        end
    end
end


local function acDisconnectList(list)
    for index = #list, 1, -1 do
        local connection = table.remove(list, index)
        pcall(function() connection:Disconnect() end)
    end
end

local function acSave(cfg, part)
    if not part or cfg.originals[part] then return end
    local success, original = pcall(function()
        local mesh = part:FindFirstChildOfClass("SpecialMesh")
        local overlays = {}
        for _, object in ipairs(part:GetDescendants()) do
            if object:IsA("Decal") or object:IsA("Texture") then
                overlays[#overlays + 1] = {
                    Instance = object,
                    Kind = "Texture",
                    Transparency = object.Transparency,
                }
            elseif object:IsA("SurfaceAppearance") then
                overlays[#overlays + 1] = {
                    Instance = object,
                    Kind = "SurfaceAppearance",
                    Parent = object.Parent,
                }
            end
        end
        return {
            Color = part.Color,
            Material = part.Material,
            Transparency = part.Transparency,
            LocalTransparencyModifier = part.LocalTransparencyModifier,
            TextureID = part:IsA("MeshPart") and part.TextureID or nil,
            Mesh = mesh,
            MeshTextureID = mesh and mesh.TextureId or nil,
            Overlays = overlays,
        }
    end)
    if success then cfg.originals[part] = original end
end

local function acIsThirdPerson()
    local hrp = lp2.Character and lp2.Character:FindFirstChild("HumanoidRootPart")
    local camera = workspace.CurrentCamera
    if not hrp or not camera then return false end
    local camPos  = camera.CFrame.Position
    local hrpPos  = hrp.Position
    local dist    = (camPos - hrpPos).Magnitude
    return dist > 3
end

local function acRestoreInstance(cfg, part)
    local original = part and cfg.originals[part]
    if not original then return end
    pcall(function()
        if part.Color ~= original.Color then part.Color = original.Color end
        if part.Material ~= original.Material then part.Material = original.Material end
        if part.Transparency ~= original.Transparency then part.Transparency = original.Transparency end
        if part.LocalTransparencyModifier ~= original.LocalTransparencyModifier then
            part.LocalTransparencyModifier = original.LocalTransparencyModifier
        end
        if part:IsA("MeshPart") and original.TextureID ~= nil and part.TextureID ~= original.TextureID then
            part.TextureID = original.TextureID
        end
        if original.Mesh and original.Mesh.Parent and original.MeshTextureID ~= nil
            and original.Mesh.TextureId ~= original.MeshTextureID then
            original.Mesh.TextureId = original.MeshTextureID
        end
        for _, overlay in ipairs(original.Overlays or {}) do
            local object = overlay.Instance
            if object then
                if overlay.Kind == "Texture" and object.Parent then
                    object.Transparency = overlay.Transparency
                elseif overlay.Kind == "SurfaceAppearance" and overlay.Parent and not object.Parent then
                    object.Parent = overlay.Parent
                end
            end
        end
    end)
    cfg.originals[part] = nil
end

local function acApplyInstance(cfg, part, styled, localTransparency)
    if not part then return end
    acSave(cfg, part)
    local original = cfg.originals[part]
    if not original then return end

    pcall(function()
        if part.LocalTransparencyModifier ~= localTransparency then
            part.LocalTransparencyModifier = localTransparency
        end

        if styled then
            local material = resolveVisualMaterial(cfg.Material, Enum.Material.SmoothPlastic)
            if part.Color ~= cfg.Color then part.Color = cfg.Color end
            if part.Material ~= material then part.Material = material end
            if part.Transparency ~= cfg.Alpha then part.Transparency = cfg.Alpha end

            local texture = cfg.Material == "ForceField"
                and forcefieldAnimationTexture(cfg.ForceFieldAnimation)
                or ""
            if part:IsA("MeshPart") and part.TextureID ~= texture then
                part.TextureID = texture
            end
            if original.Mesh and original.Mesh.Parent and original.Mesh.TextureId ~= texture then
                original.Mesh.TextureId = texture
            end
            for _, overlay in ipairs(original.Overlays or {}) do
                local object = overlay.Instance
                if object then
                    if overlay.Kind == "Texture" and object.Parent then
                        object.Transparency = 1
                    elseif overlay.Kind == "SurfaceAppearance" and object.Parent then
                        object.Parent = nil
                    end
                end
            end
        else
            if part.Color ~= original.Color then part.Color = original.Color end
            if part.Material ~= original.Material then part.Material = original.Material end
            if part.Transparency ~= original.Transparency then part.Transparency = original.Transparency end
            if part:IsA("MeshPart") and original.TextureID ~= nil then part.TextureID = original.TextureID end
            if original.Mesh and original.Mesh.Parent and original.MeshTextureID ~= nil then
                original.Mesh.TextureId = original.MeshTextureID
            end
            for _, overlay in ipairs(original.Overlays or {}) do
                local object = overlay.Instance
                if object then
                    if overlay.Kind == "Texture" and object.Parent then
                        object.Transparency = overlay.Transparency
                    elseif overlay.Kind == "SurfaceAppearance" and overlay.Parent and not object.Parent then
                        object.Parent = overlay.Parent
                    end
                end
            end
        end
    end)
end

local function acFindParts(cfg)
    local camera = workspace.CurrentCamera
    local vm = camera and camera:FindFirstChild("ViewModel")
    local vmPart = vm and vm:FindFirstChild(cfg.partName, true) or nil
    if vmPart and not vmPart:IsA("BasePart") then vmPart = nil end

    local char = lp2.Character
    local charPart = char and char:FindFirstChild(cfg.partName, true) or nil
    if charPart and not charPart:IsA("BasePart") then charPart = nil end
    return vmPart, charPart
end

local function acRefreshCfg(cfg)
    local vmPart, charPart = acFindParts(cfg)
    if cfg.vmPart and cfg.vmPart ~= vmPart then
        acRestoreInstance(cfg, cfg.vmPart)
    end
    if cfg.charPart and cfg.charPart ~= charPart then
        acRestoreInstance(cfg, cfg.charPart)
    end
    cfg.vmPart = vmPart
    cfg.charPart = charPart
end

local function acApplyCfg(cfg, thirdPerson)
    if not cfg.Enabled then return end
    acApplyInstance(cfg, cfg.vmPart, not thirdPerson, thirdPerson and 1 or 0)
    acApplyInstance(cfg, cfg.charPart, thirdPerson, thirdPerson and 0 or 1)
end

local function acApply(cfg)
    acRefreshCfg(cfg)
    acUpdateViewmodelClothing()
    local thirdPerson = acIsThirdPerson()
    acLastThirdPerson = thirdPerson
    acApplyCfg(cfg, thirdPerson)
end

local function acApplyAll(refreshParts)
    acUpdateViewmodelClothing()
    local thirdPerson = acIsThirdPerson()
    acLastThirdPerson = thirdPerson
    for _, cfg in pairs(ac) do
        if cfg.Enabled and refreshParts then acRefreshCfg(cfg) end
        acApplyCfg(cfg, thirdPerson)
    end
end

local function acRestore(cfg)
    local parts = {}
    for part in pairs(cfg.originals) do table.insert(parts, part) end
    for _, part in ipairs(parts) do acRestoreInstance(cfg, part) end
    cfg.vmPart = nil
    cfg.charPart = nil
end

local acBindSources
local function acScheduleRefresh()
    if acRefreshQueued or (not ac.Left.Enabled and not ac.Right.Enabled) then return end
    acRefreshQueued = true
    task.defer(function()
        acRefreshQueued = false
        if ac.Left.Enabled or ac.Right.Enabled then acApplyAll(true) end
    end)
end

acBindSources = function()
    acDisconnectList(acSourceConnections)

    local function rebind()
        task.defer(function()
            if not ac.Left.Enabled and not ac.Right.Enabled then return end
            acBindSources()
            acScheduleRefresh()
        end)
    end

    table.insert(acSourceConnections, workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(rebind))
    table.insert(acSourceConnections, lp2.CharacterAdded:Connect(rebind))

    local camera = workspace.CurrentCamera
    if camera then
        local function cameraChildChanged(child)
            if child.Name == "ViewModel" then rebind() end
        end
        table.insert(acSourceConnections, camera.ChildAdded:Connect(cameraChildChanged))
        table.insert(acSourceConnections, camera.ChildRemoved:Connect(cameraChildChanged))

        local viewModel = camera:FindFirstChild("ViewModel")
        if viewModel then
            local function viewModelChanged(descendant)
                if descendant.Name == "Left Arm" or descendant.Name == "Right Arm" then
                    acScheduleRefresh()
                end
            end
            table.insert(acSourceConnections, viewModel.DescendantAdded:Connect(viewModelChanged))
            table.insert(acSourceConnections, viewModel.DescendantRemoving:Connect(viewModelChanged))
        end
    end

    local char = lp2.Character
    if char then
        local function characterChanged(descendant)
            if descendant.Name == "Left Arm"
                or descendant.Name == "Right Arm"
                or descendant.Name == "HumanoidRootPart" then
                acScheduleRefresh()
            end
        end
        table.insert(acSourceConnections, char.DescendantAdded:Connect(characterChanged))
        table.insert(acSourceConnections, char.DescendantRemoving:Connect(characterChanged))
    end
end

local function acStart()
    if not acConn then
        acBindSources()
        acApplyAll(true)
        acConn = rs2.RenderStepped:Connect(function()
            if not (ac.Left.Enabled or ac.Right.Enabled) then return end

            local now = os.clock()
            local thirdPerson = acIsThirdPerson()

            if thirdPerson == acLastThirdPerson
                and (now - acLastAssert) < acAssertInterval then
                return
            end

            acLastThirdPerson = thirdPerson
            acLastAssert = now
            for _, cfg in pairs(ac) do acApplyCfg(cfg, thirdPerson) end
        end)
    else
        acApplyAll(true)
    end
end

local function acStopIfNone()
    if not ac.Left.Enabled and not ac.Right.Enabled then
        if acConn then acConn:Disconnect(); acConn = nil end
        acDisconnectList(acSourceConnections)
        acRefreshQueued = false
        acLastThirdPerson = nil
    end
end

library2:OnUnload(function()
    ac.Left.Enabled = false
    ac.Right.Enabled = false
    if acConn then acConn:Disconnect(); acConn = nil end
    if acLerpConn then acLerpConn:Disconnect(); acLerpConn = nil end
    acDisconnectList(acSourceConnections)
    acRestoreViewmodelClothing()
    for _, cfg in pairs(ac) do acRestore(cfg) end
end)


armsSection:AddToggle('ArmsLeftEnabled', {
    Text = "Left Arm",
    Default  = false,
    Callback = function(state)
        ac.Left.Enabled = state
        if state then
            acStart()
        else
            acRestore(ac.Left)
            acUpdateViewmodelClothing()
            acStopIfNone()
        end
    end,
}):AddColorPicker('ArmsLeftColor', {
    Title = "Left Arm Color",
    Default = Color3.fromRGB(255, 200, 150),
    Transparency = 0,
    Callback = function(c, a)
        ac.Left.TargetColor = c
        ac.Left.Color       = c
        ac.Left.TargetAlpha = a or ac.Left.TargetAlpha
        ac.Left.Alpha       = a or ac.Left.Alpha
        if ac.Left.Enabled then acApply(ac.Left) end
