;(function()

local ammoSection = viewPage:AddColumnGroupbox(3, "Ammo UI")

local ammoFontFaces = environment.DrainESPFontFaces or {}
local ammoFontMap = environment.DrainESPFontMap or {}
local ammoFontNames = {
    "Proggy Clean", "Smallest Pixel-7", "Tahoma", "Minecraftia", "Tahoma Modern Bold",
}

local ammoAnchors = {
    "Magazine", "Screen Center",
    "Top Left", "Top Center", "Top Right",
    "Bottom Left", "Bottom Center", "Bottom Right",
}

local ammoTextSpots = { "Above", "Below", "Inside", "Left", "Right" }

local ammoHud = {
    Enabled = false,
    Anchor = "Magazine",
    OffsetX = 0,
    OffsetY = 0,
    Width = 110,
    Height = 8,
    Rounded = true,
    Outline = true,
    BackColor = Color3.fromRGB(12, 12, 12),
    BackTransparency = 0.45,
    LowColor = Color3.fromRGB(215, 45, 45),
    HighColor = Color3.fromRGB(70, 160, 255),
    Gradient = true,
    GradientRotation = 0,
    ShowText = true,
    ShowReserve = true,
    TextSpot = "Above",
    TextColor = Color3.fromRGB(255, 255, 255),
    TextSize = 14,
    FontName = "Smallest Pixel-7",

    Gui = nil,
    Bar = nil,
    Fill = nil,
    Grad = nil,
    Label = nil,
    Conn = nil,
    MagCache = setmetatable({}, { __mode = "k" }),
    LastText = nil,
    LastPercent = -1,
}

local function ammoDestroy()
    if ammoHud.Conn then
        ammoHud.Conn:Disconnect()
        ammoHud.Conn = nil
    end
    if ammoHud.Gui then
        pcall(function() ammoHud.Gui:Destroy() end)
    end
    ammoHud.Gui, ammoHud.Bar, ammoHud.Fill, ammoHud.Grad, ammoHud.Label = nil, nil, nil, nil, nil
    ammoHud.LastText, ammoHud.LastPercent = nil, -1
    table.clear(ammoHud.MagCache)
end

local function ammoStyle()
    local bar, fill, label = ammoHud.Bar, ammoHud.Fill, ammoHud.Label
    if not bar then return end

    bar.Size = UDim2.fromOffset(ammoHud.Width, ammoHud.Height)
    bar.BackgroundColor3 = ammoHud.BackColor
    bar.BackgroundTransparency = ammoHud.BackTransparency

    local corner = bar:FindFirstChildOfClass("UICorner")
    if corner then
        corner.CornerRadius = UDim.new(0, ammoHud.Rounded and math.max(2, ammoHud.Height // 2) or 0)
    end
    local stroke = bar:FindFirstChildOfClass("UIStroke")
    if stroke then
        stroke.Enabled = ammoHud.Outline
        stroke.Thickness = ammoHud.OutlineThickness or 1
    end

    local fillCorner = fill and fill:FindFirstChildOfClass("UICorner")
    if fillCorner then
        fillCorner.CornerRadius = UDim.new(0, ammoHud.Rounded and math.max(2, ammoHud.Height // 2) or 0)
    end

    if label then
        label.TextColor3 = ammoHud.TextColor
        label.TextSize = ammoHud.TextSize
        label.Font = ammoFontMap[ammoHud.FontName] or Enum.Font.SourceSans
        local face = ammoFontFaces[ammoHud.FontName]
        if face then
            pcall(function() label.FontFace = face end)
        end

        local spot = ammoHud.TextSpot
        if spot == "Below" then
            label.AnchorPoint = Vector2.new(0.5, 0)
            label.Position = UDim2.new(0.5, 0, 1, 3)
        elseif spot == "Inside" then
            label.AnchorPoint = Vector2.new(0.5, 0.5)
            label.Position = UDim2.new(0.5, 0, 0.5, 0)
        elseif spot == "Left" then
            label.AnchorPoint = Vector2.new(1, 0.5)
            label.Position = UDim2.new(0, -5, 0.5, 0)
        elseif spot == "Right" then
            label.AnchorPoint = Vector2.new(0, 0.5)
            label.Position = UDim2.new(1, 5, 0.5, 0)
        else
            label.AnchorPoint = Vector2.new(0.5, 1)
            label.Position = UDim2.new(0.5, 0, 0, -3)
        end
    end

    ammoHud.LastPercent = -1
end

local function ammoBuild()
    if ammoHud.Gui then return true end

    local gui = Instance.new("ScreenGui")
    gui.Name = "DrainAmmoHud"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = false
    gui.DisplayOrder = 998
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Global

    local parented = false
    local playerGui = lp2:FindFirstChildOfClass("PlayerGui")
    if playerGui then
        parented = pcall(function() gui.Parent = playerGui end)
    end
    if not parented then
        parented = pcall(function() gui.Parent = game:GetService("CoreGui") end)
    end
    if not parented then
        gui:Destroy()
        return false
    end

    local bar = Instance.new("Frame")
    bar.Name = "Bar"
    bar.AnchorPoint = Vector2.new(0.5, 0.5)
    bar.BorderSizePixel = 0
    bar.Visible = false
    bar.ZIndex = 10
    bar.Parent = gui

    Instance.new("UICorner").Parent = bar

    local stroke = Instance.new("UIStroke")
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Color = Color3.new(0, 0, 0)
    stroke.Thickness = 1
    stroke.Transparency = 0.25
    stroke.Parent = bar

    local fill = Instance.new("Frame")
    fill.Name = "Fill"
    fill.BorderSizePixel = 0
    fill.Position = UDim2.fromScale(0, 0)
    fill.Size = UDim2.fromScale(1, 1)
    fill.BackgroundColor3 = Color3.new(1, 1, 1)
    fill.ZIndex = 11
    fill.Parent = bar

    Instance.new("UICorner").Parent = fill

    local grad = Instance.new("UIGradient")
    grad.Rotation = 0

    local label = Instance.new("TextLabel")
    label.Name = "Readout"
    label.AutomaticSize = Enum.AutomaticSize.XY
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromOffset(0, 0)
    label.Text = ""
    label.RichText = false
    label.ZIndex = 12
    label.Parent = bar

    local labelStroke = Instance.new("UIStroke")
    labelStroke.Color = Color3.new(0, 0, 0)
    labelStroke.Thickness = 1
    labelStroke.Transparency = 0.25
    labelStroke.Parent = label

    ammoHud.Gui, ammoHud.Bar, ammoHud.Fill, ammoHud.Grad, ammoHud.Label = gui, bar, fill, grad, label
    ammoStyle()
    return true
end

local ammoMagPart = LPH_NO_VIRTUALIZE(function(tool)
    local camera = workspace.CurrentCamera or cam2
    local viewModel = camera and camera:FindFirstChild("ViewModel")
    local mag = viewModel and viewModel:FindFirstChild("MagPart", true)
    if mag then return mag, true end

    local cached = ammoHud.MagCache[tool]
    if cached and cached.Parent then return cached, false end

    local handle = tool:FindFirstChild("Handle")
    local parts = handle and handle:FindFirstChild("Parts")
    mag = parts and parts:FindFirstChild("MagPart") or handle

    if mag then ammoHud.MagCache[tool] = mag end
    return mag, false
end)

local ammoAnchorPoint = LPH_NO_VIRTUALIZE(function(viewport, tool)
    local ox, oy = ammoHud.OffsetX, ammoHud.OffsetY
    local anchor = ammoHud.Anchor
    local pad = 60

    if anchor == "Magazine" and tool then
        local mag, firstPerson = ammoMagPart(tool)
        local camera = workspace.CurrentCamera or cam2

        if mag and camera and firstPerson then
            local screen, onScreen = camera:WorldToViewportPoint(mag.Position)
            if onScreen and screen.Z > 0
                and screen.X >= 0 and screen.X <= viewport.X
                and screen.Y >= 0 and screen.Y <= viewport.Y then
                return screen.X + ox, screen.Y + oy
            end
        end

        return viewport.X * 0.5 + ox, viewport.Y * 0.5 + oy
    end

    if anchor == "Top Left" then
        return pad + ox, pad + oy
    elseif anchor == "Top Center" then
        return viewport.X * 0.5 + ox, pad + oy
    elseif anchor == "Top Right" then
        return viewport.X - pad + ox, pad + oy
    elseif anchor == "Bottom Left" then
        return pad + ox, viewport.Y - pad + oy
    elseif anchor == "Bottom Center" then
        return viewport.X * 0.5 + ox, viewport.Y - pad + oy
    elseif anchor == "Bottom Right" then
        return viewport.X - pad + ox, viewport.Y - pad + oy
    end

    return viewport.X * 0.5 + ox, viewport.Y * 0.5 + oy
end)

local ammoStep = LPH_NO_VIRTUALIZE(function()
    local bar = ammoHud.Bar
    if not bar then return end

    if not ammoHud.Enabled then
        if bar.Visible then bar.Visible = false end
        return
    end

    local character = lp2.Character
    local tool = character and character:FindFirstChildOfClass("Tool")
    local values = tool and tool:FindFirstChild("Values")
    local ammo = values and (values:FindFirstChild("Ammo") or values:FindFirstChild("SERVER_Ammo"))
    local stored = values and (values:FindFirstChild("StoredAmmo") or values:FindFirstChild("SERVER_StoredAmmo"))

    if not ammo then
        if bar.Visible then bar.Visible = false end
        return
    end

    local current = ammo.Value
    local maximum = ammo.MaxValue
    if not maximum or maximum <= 0 then maximum = math.max(current, 1) end
    local percent = math.clamp(current / maximum, 0, 1)

    local camera = workspace.CurrentCamera or cam2
    local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
    local x, y = ammoAnchorPoint(viewport, tool)
    bar.Position = UDim2.fromOffset(math.floor(x + 0.5), math.floor(y + 0.5))

    if percent ~= ammoHud.LastPercent then
        ammoHud.LastPercent = percent
        ammoHud.Fill.Size = UDim2.new(percent, 0, 1, 0)

        if ammoHud.Gradient then
            ammoHud.Grad.Parent = ammoHud.Fill
            ammoHud.Grad.Rotation = ammoHud.GradientRotation
            ammoHud.Grad.Color = ColorSequence.new(ammoHud.LowColor, ammoHud.HighColor)
            ammoHud.Fill.BackgroundColor3 = Color3.new(1, 1, 1)
        else
            ammoHud.Grad.Parent = nil
            ammoHud.Fill.BackgroundColor3 = ammoHud.LowColor:Lerp(ammoHud.HighColor, percent)
        end
    end

    local label = ammoHud.Label
    if ammoHud.ShowText or ammoHud.ShowReserve then
        local reserve = stored and stored.Value or 0
        local text
        if ammoHud.ShowText and ammoHud.ShowReserve then
            text = string.format("%d/%d (%d)", current, maximum, reserve)
        elseif ammoHud.ShowText then
            text = string.format("%d/%d", current, maximum)
        else
            text = string.format("(%d)", reserve)
        end

        if text ~= ammoHud.LastText then
            ammoHud.LastText = text
            label.Text = text
        end
        if not label.Visible then label.Visible = true end
    elseif label.Visible then
        label.Visible = false
    end

    if not bar.Visible then bar.Visible = true end
end)

local function ammoSetEnabled(state)
    ammoHud.Enabled = state

    if not state then
        if ammoHud.Bar then ammoHud.Bar.Visible = false end
        return
    end

    if not ammoBuild() then
        ammoHud.Enabled = false
        library2:Notify(library2:Translate("Ammo HUD: could not create the overlay"), 4)
        return
    end

    if not ammoHud.Conn then
        ammoHud.Conn = rs2.RenderStepped:Connect(ammoStep)
        library2:GiveSignal(ammoHud.Conn)
    end
end

if type(environment.DrainAmmoHudCleanup) == "function" then
    pcall(environment.DrainAmmoHudCleanup)
end
