local function drainSafeStage(stage, func)
	local ok, err = pcall(func)
	if not ok then
		local text = tostring(err)
		print(string.format("[drain] %s failed: %s", stage, text))
		warn(string.format("[drain] %s failed: %s", stage, text))
		drainBootDump(string.format("FAIL %s: %s", stage, text))
	end
	drainBootLog(stage)
	return ok
end

