local function initAdonisBypass()
    if not getreg or not getgc or not isfunctionhooked then return false end

    for _, thread in getreg() do
        if typeof(thread) ~= "thread" then continue end
        local src = debug.info(thread, 1, "s")
        if src and (src:match(".Core.Anti") or src:match(".Plugins.Anti_Cheat")) then
            pcall(coroutine.close, thread)
        end
    end

    local adonisTables = {}
    if filtergc then
        local candidates = filtergc("table", { Keys = { "Detected", "RLocked" } }, false)
        for _, t in candidates do
            if typeof(rawget(t, "Detected")) == "function" then
                table.insert(adonisTables, t)
            end
        end
    else
        for _, t in getgc(true) do
            if typeof(t) == "table"
                and typeof(rawget(t, "Detected")) == "function"
                and rawget(t, "RLocked") then
                table.insert(adonisTables, t)
            end
        end
    end

    for _, tbl in adonisTables do
        for _, fn in tbl do
            if typeof(fn) == "function" and not isfunctionhooked(fn) then
                hookfunction(fn, function()
                    coroutine.yield()
                    return task.wait(9e9)
                end)
            end
        end
    end

    return true
end

pcall(initAdonisBypass)
